window.HARDTRP.receive("167805",[[167806,"2026-08-22T15:01:25",9,"Начало темы.\n\n@Ashenchampion — Дм этой темы.",167805,null],[167807,"2026-08-22T15:08:34",11,"@sweetkittywitch @elsio28 Сергей \n\nПривет-привет, кому когда удобно будет начать? Примерно денёк прикинуть хотя бы. Ну и может к этому времени найдется ещё желающий кто присоединиться",167805,null],[167809,"2026-08-22T16:25:13",11,"@lady_godzilla и твое мнение:)",167805,null],[167810,"2026-08-22T16:26:35",22,"У меня отпуск, так что я пока свободна всегда - только тегайте :)\nпо прайм тайму примерно с 10 до 20 по мск",167805,null],[167811,"2026-08-22T17:15:10",41,"( Давайте начнем потихоньку",167805,null],[167812,"2026-08-22T17:15:25",41,"( фильм еще идет, но у нас люди рано ложатся",167805,null],[167813,"2026-08-22T17:19:18",11,"// я сегодня занята, завтра смогу точно хоть с утра, но напишу вступление ночью сегодня как освобожусь",167805,null],[167835,"2026-08-22T18:26:23",17,"/ мест нет?",167805,null],[167840,"2026-08-22T18:30:16",41,"@Ashenchampion примешь Колю?",167805,null],[167845,"2026-08-22T18:36:49",11,"// хмм... Много вас, тяжело будет, ну можно попробовать главное чтоб время у всех было собраться \n\nНу и спойлер на не основной сюжет не обязательно всем вместе ходить будет",167840,null],[167846,"2026-08-22T18:42:30",17,"/ А вы тут все 1 уровня?",167805,null],[167847,"2026-08-22T18:42:41",17,"/ Я наверное не буду мешать лучше. Играйте",167805,null],[167848,"2026-08-22T18:42:42",22,"я 3/",167805,null],[167851,"2026-08-22T18:44:48",11,"// ну да сбалансить трудно будет, но К'варсио тоже 4. В общем я не против твоей компании, но честно да думаю бои мне тяжело дадуться':) лучше все же 4 игрока",167847,null],[167856,"2026-08-22T18:46:11",17,"/ Хорошо. Давайте попробуем. Если будет тяжело я спокойненько вас оставлю. Спасибо",167805,null],[167861,"2026-08-22T18:49:18",5,"/ 3",167851,null],[167874,"2026-08-22T19:00:17",17,"/ У меня персонаж 4 лвла. Фауст. Вот ссылка\n\nhttps://t.me/c/3239766844/3459",167805,null],[167895,"2026-08-22T19:26:56",11,"// в этом и проблема что спокойно оставить не получится:D впрочем вывести я тебя смогу при определенных условиях. В общем да давайте попробуем пока",167856,null],[167899,"2026-08-22T19:28:59",17,"/ Выпнешь под зад магическим сапогом)",167805,null],[167901,"2026-08-22T19:30:35",41,"( и я на обывателе 3го левела:",167874,null],[168040,"2026-08-22T20:26:54",53,"//в магические моря среди моих владений :3",167899,null],[168072,"2026-08-22T20:37:39",11,"К'варсио\nhttps://t.me/c/3239766844/733\nКД: 16 (в доспехах) без брони 12\n\nВенус:\nhttps://t.me/c/3239766844/4969\n13+щит=15\n\nЦет:\nhttps://t.me/c/3239766844/6171\nКД: 10\n\nЭто я для себя напоминалку что бы проще найти было в будущем",167805,null],[168118,"2026-08-22T21:22:36",11,"Вся группа приходит в себя крепко выспавшись. Тело чувствуется легче чем раньше и его наполняет энергия (+6 тхп для всех, кроме Фауста) Первое что каждый здесь ощущает — это тепло, возможно даже для кого-то — жару, и влажный воздух. Вас окружают знакомые и незнакомые запахи растений.\n\nОткрыв глаза вы обнаруживаете над собой листья небольших кустов с тонкими, почти витыми стеблями. В случае эладрина это крупные овальные листья. Сквозь них пробивается золотистый солнечный свет. \n\nЛежат все на небольшой поляне, окружённой джунглями. Первой приходит в себя друидка, чуткая флорен даже сквозь сон ощутила на себе пристальный взгляд, но как только она открыла глаза — рядом, на первый взгляд, никого не было. А затем она услышали сонное кваканье, которое пробудило ото сна и всех остальных. Красный грунг сидел в кустарнике. \n\nРядом, за деревом, просыпался крупный фирболг, а из под высокой травы, посреди поляны, выглянула голова тритона. Не слышно было лишь эладрина который почему-то оказался на ветке дерева и мог наблюдать всю картину с высоты 20 футов. \n\nРядом с вами нет ни домов, ни дорог. Только звуки леса.",167805,null],[168227,"2026-08-22T22:56:13",41,"Златовласый фирболг легонько приоткрыл глаза. Теплый воздух и высокая трава окружали его, он потянул руки к облачкам, наслаждаясь невинным и спокойным моментов. \n\n— А ведь мне казалось нет ничего лучше той кроватки в таверне… хо\n\nПриподнявшись он осмотрелся по сторонам\n\n— Кажется ещё вчера я строил домик для маленькой серенады , а сегодня судьба приподнесла мне такое красивое место, хохо\n\nОднако внезапно его нос учуял сладковатый запах, за которым тот прошел огибая осторожно огибая траву и кусты. Первым он заметил флорен, что только пробуждалась ото сна и отошел чуть дальше чтоб не пугать её\n\n— Извините пожалуйста, не хотел вас беспокоить… я найду кого-то ещё \n\nОднако осмотревшись снова, он обнаружил сонных незнакомцев и задумчиво почесал бороду\n\n— Хмхмхм",167805,null],[168228,"2026-08-22T23:01:35",41,"Дед Мороз и Лето",167805,null],[168229,"2026-08-22T23:04:11",17,"Фауст открыл глаза.\n\nКак он здесь оказался не имело значения. Что делать, вот вопрос. Первым делом он осмотрелся раз находился высоко. Заметил остальных неподалеку флорен, грунг, тоитон и фирболрг\n\n\"Ну и ну. Чудеса.\"\n\nПодумал он про себя. А после фирболргу телепатически передал\n\n\"Эй.. там внизу... Я на ветке дерева, где это мы находимся?\"",167805,null],[168230,"2026-08-22T23:10:46",41,"Хвост Освальда от неожиданности дернулся и тот поднял взгляд на ветку. \n\n— Ух ты, добрый день вам. Ну как ответить на ваш вопрос… всё что я знаю — мы на поляне. А вы кем будете? Меня зовут Освальд.\n\nСлегка хрипло произнес добродушный фирболг, присаживаясь на траву, около дерева\n\n— Должно быть какие-то лесные феи нас сюда позвали.",167805,null],[168231,"2026-08-22T23:17:50",17,"\"Меня зовут Фауст. Я наемник-авантюрист. Ладно я сейчас попробую разглядеть что то. Может поселение или ещё чего. Раз ты тоже не местный.\"",168230,null],[168232,"2026-08-22T23:18:05",17,"/r +3 Смотрим по сторонам",167805,null],[168234,"2026-08-22T23:20:15",41,"— Хохо. Это дело благое, а я просто резчик по дереву. Делаю замечательные игрушки и домики для зверей)",168231,null],[168235,"2026-08-22T23:21:15",53,"*после пары мгновений глаза тритона резко раскрываются и его тело за пару мгновений обрастает броней*",168118,null],[168236,"2026-08-22T23:21:53",11,"Ветки и листья сильно загораживают обзор. Но на горизонте голубое небо становится немного темнее и с той стороны дует приятный прохладный ветерок. Трава же внизу высокая, местами ее рост останавливают корни джунглей что вырвались из под земли, однако и они тонут в ее глубине. А где-то впереди и немного справа от вас виднеются камни и журчит вода. Никаких признаков разумных рас вокруг. Лишь незнакомого вида птицы в небе.",167805,null],[168237,"2026-08-22T23:22:01",53,"оххх.. где это я..\n*осматревшись по сторонам приполнимаюсь на локтях*",167805,null],[168238,"2026-08-22T23:22:09",11,"// тебе ответ",168232,null],[168239,"2026-08-22T23:24:17",41,"( а тебя я не помню :0",168237,null],[168240,"2026-08-22T23:25:22",53,"//тритончик",168239,null],[168241,"2026-08-22T23:25:32",53,"//оть",168235,null],[168242,"2026-08-22T23:25:39",41,"( аааа",168240,null],[168243,"2026-08-22T23:28:15",53,"люд добрый, нужна ль кому помощь?",167805,null],[168244,"2026-08-22T23:28:59",53,"*оглядываю людей наконец поднимаясь на ноги и проверяя свои вещи на их наличие или отсутствие*",168243,null],[168245,"2026-08-22T23:31:23",11,"Тритон открывает сумку и обнаруживает.. что там всё на месте:3\n\n\n// смотрите какой, по себе судит))",167805,null],[168246,"2026-08-22T23:32:27",17,"В голове Тритон слышит телепатическое \n\n\"Привет. Фауст меня звать. Ты понимаешь где мы и как сюда попали? Я в замешательстве\"\n\nПотом фирболргу в голову прилетает\n\n\"Вокруг нет следов цивилизации\n Дикая местность. Я спускаюсь\"\n\nВнизу под деревом из воздуха в вихре снежинок создаётся ледяной клон эладрина и тут же на его месте возникает сам оригинал из плоти и крови, а ледяной уже на ветке\n\n/ создал эхо и поменялся местами с ним\n\nЛедяной клон спрыгивает с ветки разбиваясь в дребезги около Фауста. Но очень быстро снова его силуэт вырастает из ледяных обломков",168243,null],[168247,"2026-08-22T23:32:58",11,"// я на это и рассчитывала хехе:3 рада что ты понял",167805,null],[168248,"2026-08-22T23:34:53",53,"экие чудеса...\n*оглядываюсь по сторонам услышав голоса в голове, а следом увидев и фокусы с эхом*\nвсе чудесатее и чудесатие...\nимя мне Цет.",168246,null],[168249,"2026-08-22T23:34:56",41,"— Какая дивная магия. Ни у кого нет карты, которая сама себя нарисует? (футляр картографа) \n\nОсмотрелся и Освальд, после взглянул на солнце чтоб определить запад и восток",168246,null],[168250,"2026-08-22T23:35:56",53,"*с некоторой опаской, но в то же время с полной увереностью в чем то подхожу к клону и достав небольшую сумочку начинаю осматривать его на предмет травм*",168246,null],[168251,"2026-08-22T23:39:20",53,"(травмы у эха есть?)//",168250,null],[168252,"2026-08-22T23:39:44",17,"\"Что ты ищешь?\"",167805,null],[168253,"2026-08-22T23:40:17",41,"( минус хп минус хп минус хп",168252,null],[168254,"2026-08-22T23:41:13",17,"\"Он из тонкого но прочного льда. Магия эладринов зимы. Я могу создавать таких клонов снова и снова. Они не являются живыми. Скорее как предмет. Ты можешь спрятаться за ним если в тебя летят стрелы например. Можешь пользоваться.\"",167805,null],[168255,"2026-08-22T23:41:20",17,"/ Забыл))",168253,null],[168256,"2026-08-22T23:41:23",53,"раны на духе войны. аль нет их на теле его?",168252,null],[168257,"2026-08-22T23:41:56",17,"Ран нет он полый внутри",168256,null],[168258,"2026-08-22T23:42:01",53,"хм..",168254,null],[168259,"2026-08-22T23:42:03",17,"Тонкая оболочка из льда",167805,null],[168260,"2026-08-22T23:42:31",53,"*аккуратно прикосаюсь к эху*",168257,null],[168261,"2026-08-22T23:43:04",17,"Твоя рука встречает сопротивление это твердый объект",167805,null],[168263,"2026-08-22T23:43:14",53,"//холодный?",168261,null],[168264,"2026-08-22T23:43:18",17,"\"Занятно, что тебя так заинтересовало?\"",167805,null],[168265,"2026-08-22T23:43:30",17,"Да, это лед",168263,null],[168266,"2026-08-22T23:44:15",41,"Пока тритон и Фауст болтали, Освальд тихонько уложил флорен на подушку, чтоб ей было удобнее",167805,null],[168267,"2026-08-22T23:44:17",53,"мне впервой созерцать такие чудеса.\nсам я чудотворством еще не овладел в мере дорожной.",168261,null],[168268,"2026-08-22T23:45:21",53,"*резко переключившись с чудесатого льда на чудесатого чудотворца начинаю проверять уже его на наличие травм*\n\nа вы сами не ранены?",168262,null],[168269,"2026-08-22T23:45:43",17,"\"А очень жаль\"\n\nФауст достал свою книгу заклинаний\n\n\"Мне бы найти ментора по магическим наукам, я открыл в себе дар управлять потоками арканы, но без учителя не могу прогрессировать\"",168267,null],[168270,"2026-08-22T23:46:38",53,"понимаю вас. мне тоже крайне недостает наставника.",168269,null],[168271,"2026-08-22T23:46:40",17,"\"Я в полном порядке. Что то перенесло меня на ветку, но бережно, без повреждений. А ты тоже интересный, у тебя от природы такая броня? Хитин или панцирь?\"",168268,null],[168272,"2026-08-22T23:47:20",41,"Закончив с Флорен, Освальд шевельнул ухом, но не спешил отвечать",168269,null],[168273,"2026-08-22T23:47:56",36,"//вы чо... Моих собратов убиваете?????",168272,null],[168274,"2026-08-22T23:48:13",41,"( д а",168273,null],[168275,"2026-08-22T23:48:13",36,"//я их по Лору спрятала в жопе мира\nА вы их нашли и пиздите?????",167805,null],[168276,"2026-08-22T23:48:28",36,"//а со мной согласовать мою расу?",167805,null],[168279,"2026-08-22T23:48:45",36,"//хард сказал что я за неё отвечаю",168276,null],[168280,"2026-08-22T23:48:45",53,"это одежды ордена. наш долг исцелять страждущих. \n\n*передвигаюсь к двум другим существам и так же осматриваю их*",168271,null],[168283,"2026-08-22T23:49:35",6,"//даже бог вас не спасет",167805,null],[168288,"2026-08-22T23:51:23",41,"— Простите, вы не знакомы с феями? Нас Будто бы выбрали из нашего вида..",168280,null],[168289,"2026-08-22T23:52:39",53,"//ростение, человек, фея, рыба?",168288,null],[168290,"2026-08-22T23:53:33",41,"( я фирболг",167805,null],[168291,"2026-08-22T23:53:39",41,"( ты рыба",167805,null],[168292,"2026-08-22T23:54:27",53,"до меня доходили слухи о столь диковенных созданиях. но многого я о них не знаю.",168288,null],[168293,"2026-08-22T23:55:46",17,"\"И так, часть случайных встречных ещё в отключке или спят. Ну..\n Будить не вежливо. Давайте пока с вами побеседуем. Кто вы и откуда? Например ты, фирлборг. Расскажи что нибудь о себе, что считаешь нам нужно знать. И давайте на ты сразу господа товарищи общаться \"",168288,null],[168294,"2026-08-22T23:58:17",53,"*начав осматривать флорена я слегка присаживаюсь и мой доспех обращается в вот такой костюм (красное это вышитые кресты красного цвета :3)*\n\nвы целы?",167805,null],[168295,"2026-08-22T23:58:18",41,"— Ох, с чего бы начать... Я хорошо выполняю свою работу и это все, что нужно обо мне знать. Делаю поделки, игрушки, угощаю детей печеньем... Много чего Делаю. Откуда я... Я не с этого континента, но я путишествую здесь и изучаю этот мир",168293,null],[168296,"2026-08-22T23:58:44",41,"( могу кинуть историю на кресты?",168294,null],[168297,"2026-08-22T23:59:53",41,"/r d20-1",167805,null],[168299,"2026-08-23T00:00:00",17,"\"Здорово... Если мы найдем детей в джунглях ты сможешь им сделать поделку и немного успокоить\n Ну а защиту от плотоядных растений и хищников я могу взять на себя\"",168295,null],[168300,"2026-08-23T00:00:02",41,"( ой",167805,null],[168301,"2026-08-23T00:00:04",53,"*не получив ответа начинаю прощупывать тело удивленно и опечалено поднимаюсь*\n\nкажется этому существу уже не помочь.",168294,null],[168302,"2026-08-23T00:00:36",53,"какой то крест, ничего осоього не напоминает//",168298,null],[168303,"2026-08-23T00:00:50",41,"— Еще я немного занимаюсь врачевательством, но наш друг вероятно умеет это лучше)",168299,null],[168304,"2026-08-23T00:01:09",41,"( ну да, я же с ней закончила)))))",168301,null],[168305,"2026-08-23T00:01:36",17,"\"Целителей много не бывает. Чтож предлагаю вам тогда держаться чуть за мной. Чтобы первый удар я принял на себя, как вам план? Удар я держать умею\"",167805,null],[168306,"2026-08-23T00:02:46",41,"— Спасибо вам, так и поступим.",167805,null],[168307,"2026-08-23T00:03:40",11,"// сказал он, а сам будет стоять позади и бить эхом хд\n\nШучу шучу",168305,null],[168308,"2026-08-23T00:04:47",17,"/ Ну по сути да) эхо потом я потом целители )",167805,null],[168309,"2026-08-23T00:05:43",53,"имя мне Цет. наречен я был великим паладином ордена красного креста.\nнаш долг исцелять умирающих и очищать мир от последствий воин, буйства чудовищ и скверны.\nя лишь ученик, но мне было дозволено направится на великую миссию.\nежели вы ощутиье тяжесть, иль иной недуг, а быть может и ранение получите, можете обратится ко мне, я дарую вам любую посильную помощь.",168293,null],[168310,"2026-08-23T00:06:03",11,"// ну я все таки надеюсь что флорен наш не такой как Кью.. меня пугает дк",167805,null],[168311,"2026-08-23T00:06:36",41,"— однако лучше сражаться тогда, когда сражение неизбежно. У меня на всех магии не хватит...",167805,null],[168312,"2026-08-23T00:06:38",53,"//а что там с кью?",168310,null],[168313,"2026-08-23T00:07:48",53,"чем больше способных рук, тем труднее ошибиться исцеляя тех, кому это необходимо.",168305,null],[168314,"2026-08-23T00:07:53",17,"\"Про меня вам нужно знать, что по давней причине я не могу говорить нормально голосом. Но телепатически вы меня прекрасно услышите на приличном расстоянии. Орудую клинком. А ледяной клон не только чтобы меняться с ним местами и прятаться от стрел. Он может прекрасно и сам убивать врагов, правда требуется много концентрации. Думаю сработаемся и выживем. \n\nКак на счёт развести костер?\"",167805,null],[168315,"2026-08-23T00:08:56",53,"*достаю топорик из под плащика*\nкак паладин ордена я владею не одним лишь исцелением, но и искусством боя.",168305,null],[168316,"2026-08-23T00:09:26",41,"— Давайте. Кто соберет хворост а кто камни?",168314,null],[168317,"2026-08-23T00:09:31",17,"\"Прекрасно. А ещё топориком удобно делить сухие ветви для костра. Чтож приступим\"",168315,null],[168318,"2026-08-23T00:09:39",53,"*киваю и достаю еще 3 топорика*",168317,null],[168319,"2026-08-23T00:10:14",41,"— у меня есть небольшой кремень...где же он? \n\nТот ООООХ НИХУЯ Как глубоко сунул руку в мешок",167805,null],[168320,"2026-08-23T00:10:18",17,"\"Пойдёмте пока все вместе поищем хворост или думаете лучше остаться с этими спящими, от греха подальше?\"",167805,null],[168321,"2026-08-23T00:11:01",41,"Вытащил деревянную лошадку. \n\nПоложил.\n\nЗа ней флейту детскую.\n\nПоложил рядом \n\nИ так еще раз 5",167805,null],[168322,"2026-08-23T00:11:22",41,"— я останусь, вы пойдите",167805,null],[168323,"2026-08-23T00:12:05",53,"//у нас же там лягушка и кусок мха лежат, да? 😅",167805,null],[168324,"2026-08-23T00:12:20",41,"— хотя...я не так хорошо могу защитить. Может кто-то из вас?",167805,null],[168325,"2026-08-23T00:12:33",17,"\"Все это отлично горит, но вдруг дети в джунглях. Лучше оставить\"\n\nФауст чуть усмехается под маской прикрывающей нижнюю часть лица, нити зашитого рта больно натягиваются и режут губы. Ну уж больно его повеселили своя же постиронияная шутка",168321,null],[168326,"2026-08-23T00:13:05",41,"( Поляяя",167805,null],[168327,"2026-08-23T00:13:28",41,"( я тебе подушечку положила",167805,null],[168328,"2026-08-23T00:13:35",53,"быть может мы перенесем тела?",168324,null],[168329,"2026-08-23T00:13:39",41,"( ты у нас спишь крепко крепко",167805,null],[168330,"2026-08-23T00:14:02",11,"// когда они успели стать телами :D",168328,null],[168331,"2026-08-23T00:14:04",17,"\"Думаю все будет нормально. Мы быстро найдем что нужно.\"\n\nФауст взял топорик у паладина",167805,null],[168332,"2026-08-23T00:14:19",53,"//мертвым сном",168329,null],[168333,"2026-08-23T00:14:56",41,"— что же, Если что, я подам знак.",168331,null],[168334,"2026-08-23T00:15:03",53,"//ну флорен не выглядит для меня живым ^^ там трупик заросший мхом. а лягушка даже если живая все еще имеет телесную форму :3",168330,null],[168335,"2026-08-23T00:15:17",41,"— не будем их беспокоить",168328,null],[168336,"2026-08-23T00:15:49",53,"тоже верно.",168335,null],[168337,"2026-08-23T00:16:05",53,"//не дело беспокоить тела павших ^^",168336,null],[168338,"2026-08-23T00:17:16",22,"Проснувшись от плотного влажного тепла и аромата незнакомой тропической зелени, Венус на мгновение замерла. Ветви и распустившиеся бутоны на ее голове чуть затрепетали. По телу разлилась бодрящая, чистая энергия, оставившая легкое чувство невесомости, но расслабляться флорен не собиралась. Едва открыв глаза, она чутко ощутила на себе чей-то пристальный взгляд, напоминающий взгляд ее Госпожи.\n\nПриподнявшись и рефлекторно выставив перед собой щит, Венус оглядела поляну. Вокруг, казалось, никого не было, лишь плотное кольцо джунглей и звуки дикой природы. \n\nУбедившись, что непосредственной опасности нет, Венус успокоилась и убрала щит. Она посмотрела на других существ и нервно улыбнулась.\n\n- Ну и ну...Не знаю, чей это магический фокус и куда меня занесло на этот раз, но воздух тут точно получше вонючей канализации. Все целы, компания? Кто-нибудь узнает эти кусты, или мне опять придется пробовать всё на вкус? Я Венус. \n\n- О, подушка! Такая мягкая, словно облако. Её приятно трогать. Вам всем дали подушки?",167805,null],[168343,"2026-08-23T00:18:18",22,"// впервые слышу что расу, представленную на dnd.su нужно согласовывать. Анкета есть давно, в ней прописано как существо появилось. Какие-то проблемы?\n\n@Professor_3M653",167805,null],[168344,"2026-08-23T00:18:39",22,"//я проиграла турнир в лоле и очень зла",167805,null],[168346,"2026-08-23T00:18:50",41,"( Давайте во флуд с этим",168343,null],[168347,"2026-08-23T00:18:50",53,"*повернувшись на звук вижу движение трупа и слегка дернувшись медленно начинаю приближатся*\n\nвы.. живы? вы не ранены?",168338,null],[168348,"2026-08-23T00:19:03",53,"//пиздес, труп встал",168347,null],[168349,"2026-08-23T00:19:37",36,"//ну вообще да... Проблем полно... Ладушки, отметь анку мне пожалуйста",168343,null],[168350,"2026-08-23T00:19:46",41,"— О, вы проснулись. Меня зовут Освальд. Мы не враги...Мы тут хотим костер разжечь, вы не против?",167805,null],[168351,"2026-08-23T00:20:58",11,"// да, Эля права, если есть вопросы лучше во флуд и к Харду, он все таки анкету одобрял",168349,null],[168352,"2026-08-23T00:21:14",17,"\"Отлично, с пробуждением. Я Фауст. Мы тут все очутились внезапно и пытаемся разобраться.\"\n\nУ Венус телепатический безэмоциальный голос",168338,null],[168353,"2026-08-23T00:22:37",22,"- Я.. Жива. Я в порядке, спасибо. \nКостёр это хорошо. Тепло приятно согревает.\n\nВенус кивнула.",167805,null],[168354,"2026-08-23T00:23:29",36,"//пиздец какой-та...",168351,null],[168355,"2026-08-23T00:24:43",53,"вы не ощуещаете болей в теле аль какой звон в ушах слышите? иль рябь в очах ваших?",168353,null],[168357,"2026-08-23T00:25:10",11,"Кто может ощущать температуру явно ощущает что тут и так тепло и жарко",168353,null],[168358,"2026-08-23T00:27:09",41,"— у вас есть какие-то предпочтения в еде? Я приготовлю завтрак. Есть яйца… и другое",168353,null],[168359,"2026-08-23T00:27:51",53,"я предпочитаю водоросли в любом их виде.",168358,null],[168360,"2026-08-23T00:28:11",11,"// морской капусты этому господину",168359,null],[168361,"2026-08-23T00:28:16",41,"— Хм, тогда возможно вам понравится «сочный» десерт",168359,null],[168362,"2026-08-23T00:29:21",17,"\"Я ем свое. Запасы на месте\"",168358,null],[168364,"2026-08-23T00:29:54",53,"сочный десерт?",168361,null],[168365,"2026-08-23T00:30:12",41,"— Хорошо. Но я всегда рад поделиться.",168362,null],[168366,"2026-08-23T00:30:42",41,"— у меня есть разное…печенье. Например с кусочками алоэ, его я и хотел предложить)",168364,null],[168367,"2026-08-23T00:31:10",41,"— ребенок или взрослый, все могут поесть немного печенья)",167805,null],[168368,"2026-08-23T00:31:58",53,"предпочту отказатся.\n\n*достаю из под плаща коробочку, при открытии которой становится виден плотно сжатый пучек водорослей*",168366,null],[168369,"2026-08-23T00:32:29",17,"\"Кстате Освальд. Тебе не жарко в шубе? Может начаться перегрев, гипертермия и солнечный удар\"",167805,null],[168370,"2026-08-23T00:34:29",41,"— Хм, здесь и правда жарко. Спасибо, что напомнил. Обычно в глубинных городах я с ней не расстаюсь. \n\nОсвальд расстегнул пояс и снял тяжелую шубу",168369,null],[168371,"2026-08-23T00:34:37",53,"гипертермия.",168369,null],[168372,"2026-08-23T00:34:57",53,"не желаете воды?",168370,null],[168373,"2026-08-23T00:34:58",17,"Фауст достает бурдюк воды и плескает его вверх. Вода выплёскивается. Сделав быстро печать в воздухе на ладонь Фаусту падают кубики льда.\n\n\"Вот можно охладиться слегка\"\n\n/ формирование воды заговор",167805,null],[168374,"2026-08-23T00:35:29",11,"Как раз к этому времени солнце начало понемногу выходить из тени освещая поляну и оставляя на ней все меньше тени. Вы действительно чувствуете что вам жарко",168369,null],[168375,"2026-08-23T00:35:42",41,"— Спасибо большое, я и не заметил совсем. Очень вовремя. \n\nОн взял лёд и приложил к щечкам",167805,null],[168376,"2026-08-23T00:36:09",22,"- О, я всеядна. Но я пока не голодна, благодарю за предложение,  мне очень приятно.\n\nФлорен улыбнулась и из ее рогов появились грибы, создающие тусклое мерцание",167805,null],[168377,"2026-08-23T00:36:31",41,"За это время Освальд приготовил завтрак. Видимо только себе и тритончику",168374,null],[168379,"2026-08-23T00:37:54",53,"господин фауст, вы можете без конца формировать ледяных воев?",168374,null],[168380,"2026-08-23T00:37:55",41,"( запишешь себе 1 временное хп, хд",167805,null],[168381,"2026-08-23T00:38:14",11,"// а у вас и так по 6 есть у всех кроме Фауста",167805,null],[168384,"2026-08-23T00:39:00",53,"//тритончик отказався",168377,null],[168385,"2026-08-23T00:39:03",41,"( да, прост у меня черта",168381,null],[168386,"2026-08-23T00:39:10",53,"//",168368,null],[168387,"2026-08-23T00:39:13",41,"(\u003c:(",168384,null],[168388,"2026-08-23T00:39:37",53,"//не гоже тратить чужую еду раньше времени.",168387,null],[168389,"2026-08-23T00:39:41",41,"В таком случае печеньки уберёт",167805,null],[168390,"2026-08-23T00:40:00",11,"// не хотят кушать вкусняшки.. хмм",168389,null],[168391,"2026-08-23T00:40:06",53,"//а какого он росту?",168378,null],[168392,"2026-08-23T00:40:27",53,"//экономлю.",168390,null],[168393,"2026-08-23T00:40:38",17,"\"Когда идёт бой это сложнее. От концентрации у меня часто идёт кровь из носа. Но я стараюсь развивать эту силу. Так что когда нибудь я смогу создавать их бесконечно\"",168379,null],[168394,"2026-08-23T00:40:44",41,"( 2 м +",168391,null],[168395,"2026-08-23T00:41:03",41,"( 2.30 наверное",167805,null],[168396,"2026-08-23T00:41:18",22,"- Только не выкидывай! Не нужно мусорить в чужом доме. Хочешь, я уберу к себе?\n\nСпросила девушка. Её платье раскрылось, словно живое, демонстрируя под собой деревянный ящик с дверцей.",168387,null],[168397,"2026-08-23T00:41:19",53,"можем ли мы использовать ваших воев для охлаждения ежели будет таковая необходимость?",168393,null],[168398,"2026-08-23T00:41:47",17,"\"Да. Можете использовать как хотите.\"",168397,null],[168399,"2026-08-23T00:42:02",11,"Не успел Освальд спрятать печенье как к нему подлетело юркое создание и вырвало угощение из рук \n\n// Минутку..",167805,null],[168400,"2026-08-23T00:42:03",41,"— простите, леди. Я и не думал выкидывать свою еду. Смотрите, у меня удобный мешок!",168396,null],[168401,"2026-08-23T00:42:09",53,"//а трупики ледяных исчезают сразу иль нет?",168398,null],[168402,"2026-08-23T00:42:14",41,"И тут…",167805,null],[168403,"2026-08-23T00:42:25",17,"/ Да. Сразу пропадают",168401,null],[168404,"2026-08-23T00:48:48",17,"\"Кажется нашлись таки голодные ценители печенья. Хочешь схвачу птичку?\"",167805,null],[168405,"2026-08-23T00:48:52",11,"На вид подобное на чайку создание, но явно крупнее чем она размером схватив сладость уселось на ветку с которой ранее спустился элдарин и поглотило печенье. Выглядит оно явно довольным",167805,null],[168406,"2026-08-23T00:51:04",53,"*осматриваю птичку на предмет явных болезней и ран, а так же на предмет опасности*\n\nптица.",168405,null],[168407,"2026-08-23T00:51:07",22,"Флорен посмотрела на создание и подошла к ближайшему дереву. Обняв его она стала ему что-то нашептывать и показывать на подушку в своих руках.\n\n//покидаю вас, режим сна, все дела. Завтра все прочитаю и отреагирую.",167805,null],[168408,"2026-08-23T00:51:37",41,"— хохо! Нашлись ценители моего печенья. Даже не думай)",168404,null],[168409,"2026-08-23T00:51:43",11,"// давай природу",168406,null],[168410,"2026-08-23T00:51:57",53,"//ибо если у птички коготки-лезвия, клюв такой же и лазеры из глаз то стоит ее избегат ^^",168406,null],[168412,"2026-08-23T00:52:15",53,"+0//",168411,null],[168413,"2026-08-23T00:52:20",11,"ты веришь что это простая птица",168411,null],[168414,"2026-08-23T00:52:28",53,"а болезни?//",168413,null],[168415,"2026-08-23T00:52:34",11,"здоровая",167805,null],[168420,"2026-08-23T00:53:27",41,"( могу тоже кинуть ?",167805,null],[168421,"2026-08-23T00:53:46",41,"/r d20-1",167805,null],[168423,"2026-08-23T00:53:49",53,"птица.....",168413,null],[168424,"2026-08-23T00:53:55",41,"( наманая птица",167805,null],[168425,"2026-08-23T00:54:14",11,"Птенец издал звук не особо похожий на чириканье, скорее потрескивание, стук клюва. И через несколько секунд над вами вновь появились тени. В этот раз в воздухе, вместо листьев деревьев, повисли ещё 2 такие птички. Голодные",168408,null],[168426,"2026-08-23T00:54:33",11,"// абсолютно нормальная",168424,null],[168427,"2026-08-23T00:56:31",11,"Птицы с метр размером и огромным размахом крыльев сели на соседние ветки с любопытством следя за самым высоким членом группы",167805,null],[168428,"2026-08-23T00:57:06",11,"// Вот такие милашки",167805,null],[168429,"2026-08-23T00:57:33",41,"( баба динозавр",167805,null],[168430,"2026-08-23T00:58:03",53,"чудится мне, что их станет лишь больше.",168425,null],[168431,"2026-08-23T00:58:22",53,"//абсолюьно безопасные ^^",168428,null],[168432,"2026-08-23T01:02:08",11,"// лады, раз все спать ушли завтра с птичками решите что делать, спокойной ночи:3",167805,null],[168433,"2026-08-23T01:02:31",17,"\"Спроси у ясеня, где моя любимая?\"",168407,null],[168434,"2026-08-23T01:03:08",53,"//спокойной ночи",168432,null],[168435,"2026-08-23T01:03:56",17,"/r +1 Природа на птичек",167805,null],[168437,"2026-08-23T01:04:37",53,"//никто из нас птиц не видел раньше ^^",168436,null],[168438,"2026-08-23T01:04:45",17,"\"Таких зубастых особей не видел. Зачем им зубы если не жевать мясо? Предлагаю напрячься ибо их становится больше... А печенья закончатся когда нибудь\"",167805,null],[168448,"2026-08-23T06:02:07",5,"// поспать не дают, сразу несут хоронить",168328,null],[168449,"2026-08-23T06:09:44",5,"/ этим я воспользуюсь",168373,null],[168450,"2026-08-23T06:28:55",5,"Большая красная совсем-не-лягушка, а именно грунг, сонно сидит в кустах. Дремля, он всё сидит и квакает. \n\nУслышав представления других, грунг открывает глаза.\n\n— Ква-ква-ква-к'варсио. А я К'варсио! И мне жарко!",167805,null],[168451,"2026-08-23T06:32:23",5,"Увидев водяной фонтан, грунг быстрыми прыжками метнулся под него. Часть капель долетела в виде воды, а часть превратилась в льдинки и поцарапала кожу К'варсио. Он смотрит на Фауста и возмущённо квакает.\n\n— Эй, ты квачем воду превратил в лёд? Исквортил мне дождь!",168373,null],[168452,"2026-08-23T06:42:04",5,"К'варсио нюхает воздух и чувствует что-то аппетитное рядом. \n\n— Вкуснво пахнет!\n\nОн уже скачет к тарелке с печеньками, как ту опустошает странная птица. Грунг замирает и смотрит на неё. А потом кричит на чистом птичьем.\n\n// да, сразу использую разговор с животными \n\n— Отдай печеньки, летун зубастый! Мои печеньки!",167805,null],[168453,"2026-08-23T09:11:25",17,"\"О, извини.  Изначально хотел сделать немного льда. Воды не то чтобы много для того чтобы дождик устраивать. Но если найдем водоем я могу его сделать магией. Я Фауст, Квасио.  \"",168451,null],[168454,"2026-08-23T09:31:03",5,"К'варсио успокаивается и растирает воду по коже.\n\n— Кварошо! Сделаешь мне дождик из водоёма. Квастлив познакомиться с тобой, Фауст!",168453,null],[168457,"2026-08-23T09:48:15",22,"Пока Венус болтала и обнималась с деревом она даже не заметила, что сползла по стволу и задремала под ним. Её разбудил шум птичьего клекота и обсуждение товарищей.\n\nДевушка привстала, держась за голову.\n\n- Это точно птица? Может это белочка? Да нет, точно птица я тебе говорю. - доносилось обсуждение спутников.",167805,null],[168458,"2026-08-23T09:55:27",22,"Венус услышала птичью трель, что издало странное существо, похожее на лягушку, и с интересом повернула голову в его сторону.\n\nДевушка никогда раньше не страдала подобную расу и принюхалась. Кварсио пах корицей, пах домом. От нахлынувшего чувства, в глазах флорен защипало. Она протерла их руками и, неожиданно для себя, обнаружила их влажными.\n\n Венус растерялась и, шмыгнув носом, быстро вытерла руки о траву.",168452,null],[168484,"2026-08-23T10:39:41",17,"\"Может быть зубастая белка летяга с клювом\"",168457,null],[168507,"2026-08-23T10:46:28",41,"— О, у нас последний, кто проснулся это доблестный рыцарь. Я Освальд, очень приятно ) \n\nОн вновь осмотрелся\n\n— Я тут задумался, а здесь ли мой верный скакун? Птички нам пока не вредят, а вот за него я волнуюсь",168454,null],[168508,"2026-08-23T10:47:41",53,"думается мне, окрас белок имеет несколько другой оттенок. может ли это быть барсук? цвет соответствует.. но мне казалось они несколько меньше размером.",168484,null],[168509,"2026-08-23T10:50:56",5,"Грунг уставился почти в небо, чтобы посмотреть на лицо огромного фирболга.\n\n— Привет, Освальд! Я и правда рыцарь, служу своей кваролеве! А у тебя есть конь?",168507,null],[168511,"2026-08-23T10:52:51",41,"— у меня есть мой олень. Его зовут Рудольф, будет приятно вас с ним познакомить. Надо его поискать, согласны? Он хорошо отзывается на своё имя.",167805,null],[168512,"2026-08-23T10:53:16",41,"С этими словами он раскрошит для птичек немного печенья и будет готов отправиться в путь",167805,null],[168513,"2026-08-23T10:54:07",53,"скакун? вы имеете своего скакуна?\n\n*звуки хруста шеи при повороте в поисках вероятно раненого скакуна*",168507,null],[168514,"2026-08-23T10:55:52",5,"— Квалень! Я хочу посмотреть на Рудольфа, пойдём искать его\n\nГрунг заметил нецелевое расходование печенья.\n\n— А можно мне печенье? Я тоже хочу кушать!",168511,null],[168515,"2026-08-23T10:57:16",41,"— Конечно! Я очень ждал этого вопроса. Какое печенье вы любите? У меня с собой самое разное! )",168514,null],[168516,"2026-08-23T10:58:06",5,"— Я не знаю... Квакое самое вкусное?",168515,null],[168522,"2026-08-23T11:02:51",41,"— Ох, у меня есть такое! Я их всех очень люблю, но самое большое и сочное называется «Освальдова радость»! \n\nОн довольный достает большооое печенье с разными ингредиентами . Орехами, шоколадом и алоэ. Вместе с ним протягивает лягушонку стакан молока",167805,null],[168524,"2026-08-23T11:07:11",5,"Лягушонок смущается, увидев такой невероятный десерт посреди леса. Он осторожно берёт печенье и стакан молока и опасливо смотрит на птиц на ветках.\n\n(Освальду)\n— Выглядит чудесно... Сквасибо, Освальд!\n\n(Грозно на языке животных птицам)\n— Это моё печенье! Только попробуйте тронуть!",168522,null],[168525,"2026-08-23T11:09:54",41,"— Хохохохоу! Не тронут, не волнуйся. Я им их печенье уже насыпал)",167805,null],[168526,"2026-08-23T11:10:13",41,"( думаю подождем мастера. Авось нас щас заклюют",167805,null],[168527,"2026-08-23T11:10:23",5,"// да, думаю ещё как тронут",167805,null],[168528,"2026-08-23T11:10:47",5,"// вот если что пытался установить контакт с птицами",168452,null],[168566,"2026-08-23T12:05:07",11,"//К'варсио понял что трещанием птица звала сородичей (совсем не очевидно хд)",168452,null],[168585,"2026-08-23T12:10:05",11,"**Из веток показывается целая свора подобных большим птичек, но поменьше, и сметает крошки с пола. К'варсио только и слышит:\n\n— Вкусно-вкусно. Звуки клювов по земле, а затем вновь крыльев",168512,null],[168587,"2026-08-23T12:10:52",53,"//доброе утро",167805,null],[168592,"2026-08-23T12:12:11",11,"Птицы начинают трещать между собой\n\n— Лягушка выглядит ярко.\n— Опасно\n\nНикто из них не решается воровать у грунга",168524,null],[168593,"2026-08-23T12:12:24",53,"*оглядываю остальных птице-барсуко-белок на наличие ранений*\n\nвам не кажется что их становится слишком много?",168585,null],[168595,"2026-08-23T12:12:43",22,"- Давайте пойдем в ту сторону, откуда они прилетели?",167805,null],[168600,"2026-08-23T12:13:25",5,"Довольный грунг неторопливо ест печенье и запивает молоком.\n\n— Ух, вкуснятина... И птицам нравится! Отличные у тебя закуски, Освальд!",168592,null],[168604,"2026-08-23T12:13:43",41,"— Я думаю, Мой олень где-то в лесу, в тени",168595,null],[168607,"2026-08-23T12:14:15",41,"— Рад слышать)",168600,null],[168613,"2026-08-23T12:15:13",11,"— У лягушки есть еда, дать мне? — смелый птенец поменьше подлетает к грунгу, а с ним ещё несколько молодых особей. Остальные пристально смотрят",168600,null],[168614,"2026-08-23T12:15:27",5,"— Они меня кваятся, не волнуйся",168593,null],[168615,"2026-08-23T12:15:49",53,"ты их понимаешь?",168614,null],[168618,"2026-08-23T12:16:13",53,"*достаю из под плаща свой комплект целителя*",167805,null],[168619,"2026-08-23T12:16:40",5,"— Вежливый птиц! Лягушка дать еду\n\nГрунг отламывает кусок печенья и протягивает птенцу.\n\n— Где ты живёшь?",168613,null],[168621,"2026-08-23T12:17:18",5,"*кивает, говоря с птенцом*",168615,null],[168623,"2026-08-23T12:18:20",53,"прошу дознатся, нет ли у этих творений травм.",168621,null],[168625,"2026-08-23T12:20:17",5,"Лягушонок непонимающе посмотрел на Цета и моргнул.\n\n— Дознкваться? Зачем дознкваться?",168623,null],[168627,"2026-08-23T12:23:03",53,"ежели они имеют травмы, я должен помочь им их исцелить.",168625,null],[168628,"2026-08-23T12:24:59",11,"Птенец мгновенно хватает печенье и уносится обратно на ветку. Стая голодных глаз все так же смотрит на тебя\n\n— Жить? \n— Мы летать здесь, искать еду.\n— Обитать на побережье \n\nНесколько птенцов разом отвечают, а взрослые следят за источником печеньев, фирболгом",168619,null],[168629,"2026-08-23T12:26:26",11,"// ежели хотите искать оленя, действуйте:3",167805,null],[168630,"2026-08-23T12:27:44",5,"— Освальд, у тебя же есть ещё печенье?\n\nЛягушонок с надеждой смотрит на него, а потом вновь спрашивает птиц.\n\n— Рядом есть двуногие, как он? *указал на фирболга*",168628,null],[168631,"2026-08-23T12:28:24",17,"\"Осмальд,  могу поискать следы твоего оленя. Я умею их читать. На базовом уровне.\"\n\nФауст пошел и в стороне присел расчищая траву в поисках следов оленя или кого то опаснее",167805,null],[168632,"2026-08-23T12:28:36",17,"/r +3 Выживание",167805,null],[168634,"2026-08-23T12:28:56",41,"— найдется. Этим голодным птичкам тем более. Только вот я хотел оставить на случай, если мы встретим ещё любителей печенья. У вас есть то, что не жалко оставить?",168630,null],[168636,"2026-08-23T12:29:17",41,"— Спасибо, Фауст. Я помогу ( помощь)",168631,null],[168638,"2026-08-23T12:29:58",41,"— у него очень аккуратные копытца, точь в точь кругленькие с прорезью. Отличить можно, не думаю, что здесь много оленей",167805,null],[168640,"2026-08-23T12:30:58",53,"*чуть приближаюсь к птицам дабы можно было легче рассмотреть их*",167805,null],[168645,"2026-08-23T12:32:59",5,"— У меня есть только кворожная еда. Сушёные мухи, квясо и сухари. Птички хотят печенья. Дай печенья, пожалуйста!",168634,null],[168650,"2026-08-23T12:33:57",11,"// что-то кубы не на вашей стороне. Кстати, давайте договоримся. Все броски в рп формате касающиеся мира можно делать только раз (c помощью конечно же ) так что сами решите у кого статы лучше, кому выгоднее или нарративнее",168633,null],[168653,"2026-08-23T12:34:24",17,"/ Да хорошо. Ниже перекинули за помощь так можно же?",167805,null],[168654,"2026-08-23T12:35:23",41,"— Хм, так и быть\n\nНаверное он не умеет говорить нет",168645,null],[168655,"2026-08-23T12:35:58",41,"Дает по одному печенью каждого вкуса",167805,null],[168656,"2026-08-23T12:36:06",41,"( -2 рациона",167805,null],[168657,"2026-08-23T12:36:21",11,"Фауст какое-то время оглядывается стоя на месте. Его внимание привлекает примятая трава в месте где они не топтались. Он точно помнит что когда смотрел сверху трава там была целой.",168644,null],[168658,"2026-08-23T12:36:58",41,"— Это Рудольф?",167805,null],[168660,"2026-08-23T12:37:20",11,"А вот Освальд, в другой стороне, находит следы примятую траву, но следы в ней для него знакомы — копытца оленя. Но только его, больше ничьих",168644,null],[168661,"2026-08-23T12:37:37",17,"\"Тут кто то прошмыгнул недалеко от нас. Может хищник приглядывается. Вот на том месте трава примята, хотя мы там не топтались, и сверху я видел что там было все ровненько. Невидимка?\"",168657,null],[168663,"2026-08-23T12:38:30",11,"// следы что вы нашли ведут в разные стороны, те что нашла Эля — в глубь леса, те что Коля — к месту где была слышна вода",167805,null],[168664,"2026-08-23T12:39:05",53,"чтож. вы видитесь здравыми.\n*напоследок еще раз оглядев птиц возвращаюсь к попутчикам*",168640,null],[168665,"2026-08-23T12:39:23",5,"Лягушонок берёт печенье и собирается понемногу скармливать птенцам. Он подманивает самого смелого из них.\n\n— Птиц, иди ко мне! Лягушка дать печенье. Хочешь пойти со мной? Лягушка кормить печеньем всегда.",168655,null],[168666,"2026-08-23T12:41:14",11,"Несколько мгновений и фирболга окружает пара стаек, через те же мгновения они вздымаются вверх вновь закрывая вас своими тенями, а затем улетают восвояси",168655,null],[168673,"2026-08-23T12:42:09",11,"За такую смелость один птенец на последок щипнул тебя за палец",168664,null],[168678,"2026-08-23T12:43:49",11,"Довольные птички, одна с кровью тритона на клюве, летят донимать кого-то ещё\n\n// Ну и 2 урона",167805,null],[168683,"2026-08-23T12:45:31",53,"*быстро перебинтовав палец непонимающе смотрю в сторону птиц*",168678,null],[168684,"2026-08-23T12:45:54",41,"— Ох! Ох!",168666,null],[168686,"2026-08-23T12:46:16",5,"/ будет что-то?",168665,null],[168689,"2026-08-23T12:46:49",41,"( Они меня клюнкли и улетели",168686,null],[168690,"2026-08-23T12:46:52",17,"\"Пойдем по следам оленя, то что нашел я, не очень понятно чьих рук дело. Просто остаёмся на чеку\"",167805,null],[168691,"2026-08-23T12:46:52",5,"— Квахоже, творение сделало травму тебе",168683,null],[168692,"2026-08-23T12:47:08",11,"// попробуй дружбу с животными. Только ты",168686,null],[168693,"2026-08-23T12:47:24",41,"( а не, не меня",167805,null],[168694,"2026-08-23T12:47:45",5,"/r +1",168692,null],[168696,"2026-08-23T12:47:49",41,"— Да, он очень чувствителен к жаре, Точно пошел в лес",168690,null],[168697,"2026-08-23T12:47:49",53,"такова воля великого.",168691,null],[168699,"2026-08-23T12:49:11",5,"— Какого квеликого?",168697,null],[168700,"2026-08-23T12:49:26",11,"Маленькие и юркие птенцы кружат вокруг тебя после того как отобрали печенье с рук фирболга. Они недовольны тем что ты их обманул и дарят тебе тоже пару прощальных поцелуев",168695,null],[168701,"2026-08-23T12:49:30",53,"великого.",168699,null],[168703,"2026-08-23T12:49:48",5,"— Квеликого!",168701,null],[168704,"2026-08-23T12:50:01",53,"да. великого.",168703,null],[168705,"2026-08-23T12:50:05",11,"Мелкие клювики не попадают по тебе и улетают вслед за собратьями",167805,null],[168706,"2026-08-23T12:50:23",11,"// такс, извините.. щас буду за всеми следить в темпе. Ищете оленя?",167805,null],[168707,"2026-08-23T12:51:05",41,"( да",167805,null],[168709,"2026-08-23T12:51:31",5,"— Ай! Чуть не уквусили! \n\nГрунг отпрыгивает от уже улетающих птиц. И продолжает задавать вопрос Цету\n\n— Ктво такой квеликий?",168705,null],[168716,"2026-08-23T12:52:57",53,"великий это величайший из всех великих, что ниспослало нам милость свою и даровало силы врачевать раненых, да болезных.",168709,null],[168717,"2026-08-23T12:53:42",11,"Освальд видит что следы ведут в чащу, их хорошо видно, олень точно ушел не так давно",167805,null],[168718,"2026-08-23T12:53:46",5,"— Квеличайший квеликий? Не понимаю! Ква-ква!",168716,null],[168719,"2026-08-23T12:55:24",53,"не всегда нам дано понять сути его и планов его, но должно нам придерживатся заветов его.",168718,null],[168723,"2026-08-23T12:58:24",22,"- Я же говорила, давайте пойдем, осмотримся. Сейчас нас поклевали маленькие пташки, вдруг выйдет кто-то опаснее? Здесь слишком хорошо и это.. Пугает.\n\nВенус хочет пойти в сторону джунглей и покинуть полянку.",167805,null],[168726,"2026-08-23T12:59:43",17,"\"Посмотрю сверху\"\n\nЛедяной клон создаётся на ветке над вами. Фауст в вихре снежинок меняется с ним местами. А после передвигается по деревьям таким же способом. Ледяной клон на соседнем дереве и вихрь для перемещения на его место.",167805,null],[168727,"2026-08-23T13:00:19",17,"/ нужно кинуть внимание?",167805,null],[168728,"2026-08-23T13:00:30",11,"// как далеко так движешься? И идут ли остальные за тобой?",167805,null],[168731,"2026-08-23T13:01:18",17,"/ Я стараюсь держаться не далее чем в 30 футах от группы впереди",167805,null],[168732,"2026-08-23T13:01:26",5,"— Они неопасные, просто голодные.\n\nГрунг внимательно осматривает Венус и что-то вспоминает.\n\n— Я уже квидел таких, как ты",168723,null],[168733,"2026-08-23T13:01:40",53,"здесь и вправду благодатно, пусть и жар черезмерен, но почему же это пугает тебя?",168723,null],[168734,"2026-08-23T13:01:43",41,"Освальд хотел попросить звать Рудольфа по имени, но передумал \n\n– Рудольф! Рудольф! Где ты???",167805,null],[168739,"2026-08-23T13:02:36",5,"К'варсио будет прыгать за остальными, если они идут",167805,null],[168742,"2026-08-23T13:03:13",11,"Ветки баньянов здесь достаточно крепкие и крупные что бы выдержать на себе вес взрослого эладрина. Ты делаешь пару таких прыжков вперёд и всё ещё видишь следы Рудольфа, но не его самого. Под тобой всё те же корни и трава, местами знакомые и незнакомые цветы, пока что ничего примечательного",168731,null],[168747,"2026-08-23T13:04:21",17,"\"Ничего не видно, можете спокойно идти\"",167805,null],[168748,"2026-08-23T13:04:25",53,"*пока мы плутаем проверяю не ходим ли мы кругами оставив пометку зеленой пахучей(с крайне неприятным запахом) травой на одном из деревьев*",168742,null],[168750,"2026-08-23T13:05:25",53,"путники, коли увидите эту метку - то будет знак, что мы бредем по кругу.",167805,null],[168752,"2026-08-23T13:05:52",41,"— Спасибо",167805,null],[168753,"2026-08-23T13:05:56",11,"Лес отвечает лишь звуками птиц и шумом листьев",168734,null],[168757,"2026-08-23T13:07:03",53,"//а далеко шум птиц?",168753,null],[168759,"2026-08-23T13:07:49",11,"// везде и понемногу. Просто звуки леса",168757,null],[168760,"2026-08-23T13:07:51",41,"Освальд достал из глубины мешка маленький колокольчик и начал в него звенеть, привлекая внимание своего оленя",167805,null],[168763,"2026-08-23T13:09:51",53,"*не видя ничего необычного возвращаюс к разговору с лягухом*\n\nжелаешь ли ты узнать больше о великом?",167805,null],[168764,"2026-08-23T13:10:08",11,"Олень всё так же не появляется, а следы продолжают вести вглубь.\n\nЦет не видит своих следов на деревьях, они не ходят кругами, а идут вперёд\n\nПройдя какое-то время, сперва Фауст, а затем и остальные, понимают что лес меняется. Деревья в глубине другие",167805,null],[168766,"2026-08-23T13:10:23",11,"// что за свидетели Иеговы в днд",168763,null],[168767,"2026-08-23T13:10:59",5,"К'варсио немного недовольно квакает.\n\n— Ква! Желаю, если ты скажешь что-то кроме \"квеликий квеликий\"",168763,null],[168768,"2026-08-23T13:12:05",53,"*понемногу разглядываю новые деревья и пытаюсь понять в чем их отличие от старых*",168764,null],[168769,"2026-08-23T13:12:23",53,"что же ты желаешь знать?",168767,null],[168778,"2026-08-23T13:13:50",5,"— Где живёт твой квеликий?",168769,null],[168783,"2026-08-23T13:15:12",5,"К'варсио старается идти всегда в тенях, чтобы греться поменьше. А по пути вдыхает воздух, пытаясь заметить изменения влажности",168764,null],[168784,"2026-08-23T13:15:13",53,"в глубине дальних морей, на границе земли, у великого водопада.",168778,null],[168785,"2026-08-23T13:16:02",5,"— Кводопада? Звучит приятно. Мне нравятся кводопады. А бассейн у него есть?",168784,null],[168786,"2026-08-23T13:16:33",53,"весь океан дальних морей - боссейн для великого",168785,null],[168787,"2026-08-23T13:17:37",5,"— Не понимаю...\n\nЛягушонок расстроился.\n\n— Я хочу посидеть под кводопадом. Твой квеликий может это устроить?",168786,null],[168799,"2026-08-23T13:18:58",53,"конечно, но для того надобно быть верным последователем его. все верные последователи удостаиваются получить этот дар.",168787,null],[168801,"2026-08-23T13:19:35",41,"— Надеюсь, Рудольф не пострадал... Он точно заблудился...",167805,null],[168803,"2026-08-23T13:21:01",11,"И ещё немного погодя, передвигаясь по уже менее удобных ветках, некоторые из которых местами кажутся слишком тонкими что бы выдержать его..\n\nВсе видят что фауна здесь становится другой. Однако теперь вам не так жарко, кроны деревьев здесь создают тень везде..? А Венус обращает внимание на розы?\n\nА затем Фауст останавливается, понимая что следы ведут к новой поляне. Перед ним открывается вид: \n\nУединенное место, окутанное туманом, сквозь который тяжело рассмотреть что-то, лишь мерцающие огоньки в нем, а вокруг вековые деревья образуют идеальный купол из ветвей. \nНо что ещё странно, на поляне стоит абсолютная тишина — здесь не слышно ни пения птиц, ни жужжания насекомых, будто сама природа замерла в ожидании вас.",168764,null],[168805,"2026-08-23T13:21:57",5,"— Правда?\n\nГрунг задумался \n\n— Я могу стать квоследователем, если кводопад будет. А квеликий добрый? Моя госпожа архифея не одобрит, если он злой.",168799,null],[168806,"2026-08-23T13:22:05",17,"Фауст останавливается и спускается с дерева. Дожидаясь остальных\n\n\"Дальше некая аномалия. Смотрите\"",167805,null],[168808,"2026-08-23T13:22:57",53,"великий невероятно добр. именно поэтому и свществует наш орден, что врачует нуждающихся.",168805,null],[168814,"2026-08-23T13:24:09",22,"- Видел? где? Какие они были?",168732,null],[168815,"2026-08-23T13:24:18",5,"— Аномалия? Ква-квакая?",168806,null],[168816,"2026-08-23T13:24:49",5,"— Тогда я помогу квеликому. Отведешь меня к нему? Хочу посмотреть на водопад, ква!",168808,null],[168817,"2026-08-23T13:24:53",53,"*оборачиваюсь к фаусту*\nаномалия?",168806,null],[168818,"2026-08-23T13:25:02",41,"— Не знаю, затянуло ли Рудольфа туда. Он крайне любопытный...",167805,null],[168821,"2026-08-23T13:25:20",53,"сделаю все что в моих силах.",168816,null],[168823,"2026-08-23T13:26:45",5,"— Видел...\n\nПо лицу грунга видно, что это неприятные воспоминания.\n\n— Такой куст как ты. Она убила волка и сразу ела по кускам. Прямо в крови. Отквратительно!\n\nК'варсио посмотрел на неё.\n\n— А ты... Ты тоже такая?",168814,null],[168832,"2026-08-23T13:30:05",11,"Ни пения птиц, ни шелеста листьев и травы, ни ветра, ничего не слышно кроме разговоров остальных членов группы. Но стоит тебе пошевелиться, а твоему колокольчику издать звук как из тумана придёт ответ знакомым голосом. Лесную тишину прорезал пронзительный, чистый свист, переходящий в трубный призыв",168818,null],[168835,"2026-08-23T13:32:37",41,"— Давайте попытаем удачу в том куполе?",167805,null],[168840,"2026-08-23T13:34:13",53,"но для того тебе надобно будет также и врачевать раненых что есть силы.\n\n*протягиваю два комплекта целителя*",168816,null],[168846,"2026-08-23T13:35:56",5,"— Это звук от Рудольфа? Пойдём у нему скорее!",168835,null],[168848,"2026-08-23T13:36:45",41,"— Это точно он!",168846,null],[168850,"2026-08-23T13:37:10",5,"— Кврачевать? Я попробую! Только... Касание моей кожи заставляет других слабеть. Как мне лечить раненных?",168840,null],[168857,"2026-08-23T13:38:10",5,"// касание кожи грунга накладывает отравление",167805,null],[168858,"2026-08-23T13:38:46",53,"*вытаскиваю из сумки плотные кожанные перчатки и даю грунгу*\nэто должно помочь.",168850,null],[168859,"2026-08-23T13:39:00",22,"- Фе... Свежее мясо невкусное. Я предпочитаю ферментированное. А лучше помидоры.. О... помидоры...\n\nВенус задумалась, шумно втягивая слюну.\n\n\n- Я переживаю за Рудольфа, давайте пойдем к нему скорее, это хорошая идея.",168823,null],[168861,"2026-08-23T13:39:06",11,"Звук явно знакомый тебе\n\n// пыталась описать звук оленя вапити",168848,null],[168863,"2026-08-23T13:39:37",11,"// шагаете в туман?",167805,null],[168864,"2026-08-23T13:39:52",5,"— Спасибо. Буду кврачевать \n\nЛягушонок взял перчатки и надел их. А потом принял комплекты целителя",168858,null],[168865,"2026-08-23T13:39:58",41,"( а, тогда поменяю",167805,null],[168872,"2026-08-23T13:42:42",5,"— Свежее мясо в крови отквратительно. А кверментированное вкусное?",168859,null],[168878,"2026-08-23T13:45:21",5,"— Рудольф! Рудольф! Ква!\n\nЗаквакал грунг и поскакал в туман. Серебряная тиара на голове грунга засияла и звук вышел удивительно громким для такого лягушонка.\n\n// Чудотворство утроило громкость",168848,null],[168884,"2026-08-23T13:46:30",11,"Все остальные видят как грунг вошёл в туман с громким кваканьем которое внезапно затихло, а сам лягух исчез",167805,null],[168885,"2026-08-23T13:46:51",41,"Освальд с ним",167805,null],[168886,"2026-08-23T13:46:53",53,"*завидев это начинаю идти за лягухом*",168884,null],[168887,"2026-08-23T13:47:25",17,"Фауст тоже входит в туман",167805,null],[168888,"2026-08-23T13:47:30",11,"Освальд так же растворяется в тумане",168885,null],[168889,"2026-08-23T13:49:02",11,"Цет и Фауст пытаются сделать шаг, но понимают что что-то остановило их. Опустив взгляд вы оба замечаете как ваши ноги оплетает шипастая лоза, которая растёт от.. Венус",167805,null],[168891,"2026-08-23T13:49:33",11,"Вокруг друида распускаются алые розы, а ее собственные ноги будто пустили корни и не дают сдвинуться. Как будто бы что-то не хочет что бы она входила.",167805,null],[168893,"2026-08-23T13:50:27",53,"что это? \n*оьорачиваюсь на фауста и пытаюсь вырвать ногу из пут*",168891,null],[168895,"2026-08-23T13:51:02",17,"\"Не знаю. Венус ты это... Заканчивай. Убери лозы.\"",168893,null],[168896,"2026-08-23T13:51:25",17,"Ледяной клон рядом молча наблюдает",167805,null],[168897,"2026-08-23T13:51:31",11,"От того что ты брыкаешься шипы ранее не доставляющие тебе дискомфорта начинают понемногу впиваться в кожу, а лоза только сильнее оплетает тебя подымаясь все выше",168893,null],[168898,"2026-08-23T13:52:13",22,"- Да, все верно. Я люблю и мясо и овощи. Что-то не так?",168872,null],[168900,"2026-08-23T13:53:38",22,"Венус попыталась сделать шаг, но ее ноги не слушались. \n\n- Ч...что происходит?\n\nДевушка в ужасе пытается осознать происходящее. Все напоминало сон... страшный сон... Который был явью, пока она жила в мире фей.",168891,null],[168902,"2026-08-23T13:55:39",5,"Грунг с подозрением посмотрел на тебя, прежде чем попрыгать и скрыться в туманп",168898,null],[168904,"2026-08-23T13:57:51",11,"Тем временем сперва К'варсио, а затем и Освальд, который войдя услышал звенящий в ухе квакающий звук, видят перед собой:\n\nПоляну, что застыла в бесконечном полудне. Солнечный свет заливает изумрудную траву золотым потоком, а воздух пересыщен сладким ароматом клевера и смолы. Птичий щебет звучит так слаженно, будто невидимый хор празднует триумф. Вся поляна пульсирует безудержной, радостной жизнью, заставляя забыть обо всем на свете.Но в самом центре этой идиллии природа замирает, подчиняясь идеальной геометрии.Там высится безупречное кольцо из разнообразных грибных шляпок. Внутри него, на коленях бледного каменного изваяния прелестной девы, покрытого цветами под стать ее красоте, спит Рудольф. Пространство над ними прорезают ослепительно яркие, крупные искры. Они хаотично чертят в воздухе изумрудные дуги, а сквозь их гудение изредка прорывается хрустальный, дразнящий перезвон, похожий на далекий смех.",167805,null],[168905,"2026-08-23T13:58:16",17,"Фауст перемещает клона от подальше Венус и меняется с ним местами \n\n/ На 30 футов \n\n\"Ты видать это не контролируешь? Тобой управляют?\"\n\nЗвучит у Венус в голове",167805,null],[168907,"2026-08-23T13:59:02",11,"// в туман клона послать пытаешься или в сторону откуда пришли?",168905,null],[168908,"2026-08-23T13:59:17",41,"— Рудольф, милый мой, пойдем! \n\nОкликнул его Освальд",168904,null],[168909,"2026-08-23T13:59:41",17,"А тумане пусть",168907,null],[168910,"2026-08-23T14:00:24",5,"— Квак красиво!\n\nГрунг медленно идёт к изваянию, восторженно смотря на поляну",168904,null],[168911,"2026-08-23T14:01:30",11,"Олень грациозно поднимает голову услышав знакомый голос и в этот момент застывшая статуя начинает двигаться, убирая руку с тела животного и давая тому свободу. Он делает несколько прыжков к хозяину, под провожающий взгляд статуи, а затем она переводит свой взор на К'варсио",168908,null],[168912,"2026-08-23T14:01:37",11,"Клон тает",168909,null],[168914,"2026-08-23T14:03:11",17,"\"Ладно, Венус прости. Наверное тебе будет неприятно, но хватать меня не позволю.\"\n\nФауст достает свой клинок и рубит лозы чтобы освободить ноги себе и Цету",167805,null],[168920,"2026-08-23T14:04:19",5,"— Ты видел? Стватуя двигается! \n\nГрунг вопросительно смотрит на статую и спрашивает.\n\n— Ква?",168911,null],[168922,"2026-08-23T14:04:44",11,"Веренестра протягивает руку идущему ей на встречу лягушенку и издает приятный ушам звук — звон маленьких колокольчиков, совсем как тот которым Освальд звал своего друга. Олень реагирует на это оглядываясь, но она лишь качает головой и говорит ему\n\n— Иди — а вы понимаете что так звучал ее смех",167805,null],[168924,"2026-08-23T14:05:13",53,"*переворачиваю часы висящие внутри плаща и смотрю что происходит если не сопроивлятся, а так же что будет с товарищем что решил рубить лозы*",168914,null],[168925,"2026-08-23T14:05:25",41,"( А ХЕ РЕТЬ",168922,null],[168926,"2026-08-23T14:05:36",11,"//спас силы против ее сл",168914,null],[168927,"2026-08-23T14:05:55",41,"( Я ВЕРЕНЕСТРА ТЫ ВЕРЕНЕСТРА",167805,null],[168930,"2026-08-23T14:06:23",41,"( я думала её никто не выберет афигеть бро . Круто!",167805,null],[168931,"2026-08-23T14:06:27",17,"/r -1 О да спасы силы",168926,null],[168933,"2026-08-23T14:06:37",41,"( только именно она архифея грунга…",167805,null],[168934,"2026-08-23T14:06:40",11,"Венус понимает кто именно не хочет что бы она и остальная часть группы двигались",168900,null],[168935,"2026-08-23T14:07:01",5,"// лягушонок узнает её полагаю",168922,null],[168936,"2026-08-23T14:07:07",11,"Лоза оказывается крепче чем тебе казалось и опутывает уже твой клинок",168932,null],[168937,"2026-08-23T14:07:16",41,"— Спасибо вам, что приглядели за моим другом. Добрая леди",168922,null],[168938,"2026-08-23T14:07:48",53,"фауст, думаю это подойдет лучше.\n*кидаю фаусту ручной топор и сам беру такой же*",168936,null],[168940,"2026-08-23T14:09:03",11,"— Грациозное создание — отвечает она. А ты видишь на шее оленя венок из цветов, которые так же вплетены в его гриву, вокруг которой суетятся маленькие создания похожие на светлячков\n\nСтоило каменной девушке махнуть рукой как они вмиг разлетелись по сторонам",168937,null],[168942,"2026-08-23T14:09:17",17,"Поймал топорик и взял его в левую руку \n\n\"Магические, не могу прорубить\"",168938,null],[168943,"2026-08-23T14:09:26",11,"— Маленькие баловницы привели его ко мне, но теперь ему пора возвращаться к хозяину",167805,null],[168944,"2026-08-23T14:09:40",5,"К'варсио узнаёт свою покровительницу-архифею и спешит к ней.\n\n— Моя кваспожа! Я счастлив вновь встретить вас! Вы охраняли Рудольфа?",168922,null],[168945,"2026-08-23T14:09:57",41,"— Простите, милая леди. Вы знаете, почему мы оказались здесь?",167805,null],[168946,"2026-08-23T14:11:03",17,"\"Освальд и Кварсио пропали в тумане, может им помощь нужна. Нужно скорее догонять. Вдруг ранены.\"\n\nФауст делает фейский шаг\n\nРассыпаясь на вихрь снега он проходит сквозь ледяные пустоши зимнего двора фейлвинда и оказывается в 30 футах от точки в которой был. Ледяной холод пронзает все в месте его появления.",167805,null],[168947,"2026-08-23T14:11:21",53,"//я могу попытатся проанализировать путы?",168942,null],[168958,"2026-08-23T14:13:03",11,"Она вновь отрицательно качает головой\n\n— Но я знаю что лес здесь пробудился. Возможно дело в этом. — Затем она вновь улыбаясь смотрит на К'варсио — Ты ведь разберешься для меня, а затем расскажешь мне сказки о своих приключениях, мой рыцарь?",167805,null],[168959,"2026-08-23T14:13:11",53,"*киваю на его слова*",168946,null],[168965,"2026-08-23T14:14:45",11,"**И ты действительно оказываешься на поляне, но.. // пройди ка спас мудрости",168946,null],[168969,"2026-08-23T14:15:13",17,"/r +1 Спас мудрости",167805,null],[168971,"2026-08-23T14:15:15",5,"Лягушонок тянется лапкой к руке архифеи.\n\n— Клянусь, я разберусь, что здесь произошло! Моя кваспожа, я каждый раз не успеваю спросить, как ваше имя?",168958,null],[168975,"2026-08-23T14:16:09",41,"— Большое спасибо вам, мы все поможем вам)\n\nОсвальд отвечал так, будто знал её… возможно и она знала его, но это было не точно",167805,null],[168979,"2026-08-23T14:17:17",11,"Маленькие пикси окружают тебя сразу же как ты появляешься на поляне, но ты ловко рассеиваешь их пыльцу и они издавая писки возмущения покидают тебя\n\n— Заботливое дитя из зимнего двора, как любопытно — произносит архифея",168970,null],[168980,"2026-08-23T14:17:44",41,"( Фауст оказался не там не с той феей)))",167805,null],[168981,"2026-08-23T14:17:57",41,"( мухаха",167805,null],[168982,"2026-08-23T14:18:13",17,"\"Ты Мэб? Архифея зимнего двора?\"",168979,null],[168983,"2026-08-23T14:18:14",11,"// да ему повезло спас пройти😢\n\nБалованья не будет",167805,null],[168988,"2026-08-23T14:18:31",53,"*видя что еще один мой товарищ исчез пытаюсь высвободить ноги отодрав или срубив путы при помощи топора*",168965,null],[168989,"2026-08-23T14:18:40",41,"— Нет, Фауст. Но я не стану называть её имя без разрешения",168982,null],[168992,"2026-08-23T14:18:58",17,"\"Тогда мы не враги.\"",168989,null],[169009,"2026-08-23T14:23:15",11,"Статуя прищурила глаза в улыбке и наклонила голову\n\n— Может быть в следующий раз, мой К'варсио, если соберёшь для меня интересных сказок — ответила она и исчезла.\n\nВместе с ней исчезла и добрая часть магии: поляна вновь стала обычной, солнечные лучи больше не пробивались в эту чащу, а туман закрывающий обзор друиду и тритону исчез. Теперь все видели лишь странный светящийся грибной круг на земле и смешки, место происхождения которых нельзя было определить.\n\nЛозы исходящие от Венус сами вернулись к ней давая ей и Цету возможность ходить. А на ее теле расцвели алые розы",167805,null],[169011,"2026-08-23T14:24:13",11,"Олень ткнулся мордой в руку Освальда",167805,null],[169012,"2026-08-23T14:24:33",41,"Освальд зацеловал Рудольфа",167805,null],[169014,"2026-08-23T14:26:37",53,"*увидев исчезнувших товарищей отряхиваю ногу и подбегаю ближе к нимосматривая их на наличие ран*\n\nживы? не ранены?\nчто с вами произошло? \nощущаете болезность аль боль в теле?",169009,null],[169015,"2026-08-23T14:26:51",5,"— Теперь я обязан выяснить, что с этим лесом. Кваспожа сказала, он пробудился. Я должен узнать, что это значит!",167805,null],[169018,"2026-08-23T14:27:31",5,"Грунг гладит Рудольфа лапкой в перчатке",169012,null],[169020,"2026-08-23T14:28:15",5,"— Всё кварошо! Тут была моя кваспожа, она дала мне поручение. И она охраняла Рудольфа",169014,null],[169021,"2026-08-23T14:28:22",53,"*рудольфа так же осматриваю на наличие травм*",169018,null],[169022,"2026-08-23T14:29:11",53,"*услышав это киваю и подходя к товарищу что был опутан осматриваю его ноги*",169020,null],[169023,"2026-08-23T14:30:12",11,"Рудольфу сегодня досталось ещё больше любви чем обычно. Довольный олень благоухающий цветами оборачивается в сторону откуда вы пришли и издает громкий свист",167805,null],[169024,"2026-08-23T14:30:44",11,"https://youtube.com/shorts/eJ7Klefa2OA?si=P4FZwJf3wvW1A389\n\n// Я примерно так это представляю",167805,null],[169025,"2026-08-23T14:31:15",11,"И флорен и эладрин выглядят здоровыми",169022,null],[169026,"2026-08-23T14:32:23",53,"//ран от лоз не осталось?",169025,null],[169027,"2026-08-23T14:32:43",53,"*после этого осматриваю уже свои ноги*",169026,null],[169028,"2026-08-23T14:33:34",53,"//ну на счет флорена не сказал бы. все еще не понимаю почему и как заросший корнями труп ходит и говорит ^^",169025,null],[169029,"2026-08-23T14:34:31",11,"Все выглядят вполне себе здоровыми, даже не уставшими, а от Венус пахнет розами",169028,null],[169031,"2026-08-23T14:35:39",53,"*смотрю на время на часах и переворачиваю их обратно, а после сьедаю половину своего перекуса*",167805,null],[169032,"2026-08-23T14:36:03",11,"Олень указывает туда откуда вы пришли, но в то же время вы замечаете как глубже в лесу мерцают светлячки как будто бы указывая путь\n\n// Что будете делать",167805,null],[169033,"2026-08-23T14:37:47",5,"— Рудольф, ты видел что-то странное в лесу? Пойдём туда!",169032,null],[169034,"2026-08-23T14:38:01",53,"раз уж все... *хадумчиво посмотоел на флорена* целы, то нам стоит отправлятся туда?",169032,null],[169035,"2026-08-23T14:38:05",11,"// он как раз в другую сторону показывает",169033,null],[169037,"2026-08-23T14:38:43",11,"// ну и отдаю оленя под управление хозяину",167805,null],[169038,"2026-08-23T14:39:12",41,"— ты можешь поговорить с Рудольфом ?",169033,null],[169039,"2026-08-23T14:40:07",5,"— Ква! Я могу\n\nК'варсио произносит какие-то слова и делает взмахи лапками\n\n/ Кастую разговор с животными",169038,null],[169040,"2026-08-23T14:40:28",5,"А затем обращается к оленю, подражая его крику.\n\n— Привет, Рудольф!",167805,null],[169041,"2026-08-23T14:41:27",53,"*нахожу меч фауста и возвращаю ему забирая свой топорик*",167805,null],[169042,"2026-08-23T14:42:07",11,"// ну или пока не отдаю\n\n— Ты говоришь на моем языке? — Рудольф удивлён — Привет!",167805,null],[169043,"2026-08-23T14:42:38",11,"Остальные видят как олень свистит лягушке, а лягушка в ответ",167805,null],[169044,"2026-08-23T14:42:48",17,"\"Ладно. Я так понимаю это знакомая вам архифея. Если опасности нет, я спокоен.\"\n\n\nЭладрин убрал клинок на пояс\n\n\"Так, что теперь? Надо бы выбираться из джунглей, архифея не сказал вам куда идти?\"",167805,null],[169045,"2026-08-23T14:43:22",5,"— Могу, Рудольф. Куда ты указывал? Что там такое в лесу?",169042,null],[169046,"2026-08-23T14:43:22",17,"\"Спасибо Цет.\"",169041,null],[169048,"2026-08-23T14:44:16",53,"нет нужды благодарить. такова воля великого.",169046,null],[169051,"2026-08-23T14:46:39",11,"— Лучше не идти за светлячками, я следовал за ними очень долго, но так никуда и не пришёл, лишь зря растратив силы, а затем я услышал звон колокольчиков, как у Освальда.. он привел меня сюда к живому камню, она накормила меня сочной травой и дала отдохнуть, а затем появились вы",169045,null],[169053,"2026-08-23T14:49:43",5,"— Спасибо, Рудольф. А ты не видел больше ничего странного в лесу?\n\nК'варсио гладит оленя лапкой",169051,null],[169054,"2026-08-23T14:50:07",11,"// ээ лапу то убери..",169053,null],[169055,"2026-08-23T14:50:16",5,"— Рудольф говорит, что не надо ходить за светлячками, они никуда не приведут. Надо искать другой путь",167805,null],[169057,"2026-08-23T14:51:10",11,"Смех вокруг затих, а светлячки померкли",167805,null],[169058,"2026-08-23T14:51:39",11,"— Нет, все вокруг было одинаковым пока я ходил за светлячками",169053,null],[169059,"2026-08-23T14:51:42",22,"- Госпожа не хочет, чтобы мы туда шли..\n\n\"Госпожа? Вы меня.. Простили? Я могу вернуться домой?\"\n\nС надеждой Венус попыталась связаться с королевой. С удивлением, Венус заметила, что на ней расцвели алые розы. Как красиво! \n\n\"Я прощена? Это ваш дар, моя королева?! Спасибо, спасибо!\"\n\nВенус стояла на месте не двигаясь и просто наслаждалась моментом.",168934,null],[169060,"2026-08-23T14:51:43",41,"— Хм, ясно. Давайте поищем еще что-то примечательное",167805,null],[169062,"2026-08-23T14:53:46",11,"Только Венус видит как розы расцветают и увядают подле грибов, оплетая круг своими лозами с шипами",169059,null],[169063,"2026-08-23T14:53:46",5,"— Надо бы узнать, что значит \"лес пробудился\"",169060,null],[169064,"2026-08-23T14:54:11",11,"— Я покажу путь обратно — говорит олень",167805,null],[169065,"2026-08-23T14:54:41",11,"// тащемта Венус или Фауст может кинуть историю или природу",167805,null],[169067,"2026-08-23T14:55:34",41,"— у подобных лесов обычно есть \"Сердце\". Но Оно обычно скрыто",169063,null],[169068,"2026-08-23T14:57:39",5,"— Ква! Веди нас!\n\nГрунг обернулся к остальным\n\n— Рудольф знает путь обратно",169064,null],[169069,"2026-08-23T14:58:41",41,"— Молодец, Рудольф! Позволишь милой леди Венус прокатиться на тебе? Кажется, она устала",167805,null],[169070,"2026-08-23T14:59:12",11,"// Олень в твоём распоряжение, я только говорить за него буду если приходится",169069,null],[169071,"2026-08-23T14:59:51",41,"( Спасибо",169070,null],[169072,"2026-08-23T15:00:21",41,"Олень присел чтоб Венус забралась на него, за это получил сухофрукт",167805,null],[169073,"2026-08-23T15:00:32",41,"@lady_godzilla на борт, королева",167805,null],[169075,"2026-08-23T15:02:10",11,"// чисто сестра терновника:D",167805,null],[169080,"2026-08-23T15:02:54",11,"// Ну в общем никто не против идти за оленем?",167805,null],[169081,"2026-08-23T15:03:02",41,"Мы идем",167805,null],[169082,"2026-08-23T15:03:11",41,"( хотя",167805,null],[169084,"2026-08-23T15:03:28",41,"( Фауст и Венус мб чето сделают",167805,null],[169126,"2026-08-23T15:45:37",11,"// @lady_godzilla \n@dunchev \n\nЖдём вас\nИ скажите мне есть ли у кого кроме Цета слепое зрение заранее пожалуйста",169065,null],[169130,"2026-08-23T15:46:29",17,"/r +1 Фауст решил попробовать вспомнить что он читал",167805,null],[169135,"2026-08-23T15:46:57",17,"\"Есои олень нас выведет, из джунглей ч готов следовать\"",167805,null],[169139,"2026-08-23T15:47:50",11,"Эладрин без труда понимает что это древний перекресток миров — живой портал, связывающий Материальный план и Страну Фей, который коренные фейри используют как транспортную сеть. Для вашего народа это священное место силы и нейтральная зона, где любая клятва скрепляется магией самой природы, а нарушение договора карается мгновенным проклятием",169130,null],[169150,"2026-08-23T15:53:50",17,"\"Это перекресток миров, портал между миром фей и материальным. Тут лучше не разбрасываться словами попусту. Пойдёмте за оленем\"",169139,null],[169151,"2026-08-23T15:54:45",41,"— Спасибо, Фауст. Пойдем",167805,null],[169154,"2026-08-23T15:55:35",53,"*киваю*",169150,null],[169155,"2026-08-23T15:55:41",5,"— Значит, мир фей здесь близко... Кваспожа рядом, я не могу подвести её!",169150,null],[169158,"2026-08-23T15:59:24",11,"Вы спокойно идёте обратно. Путь занимает какое-то время, но без происшествий, разве что вы немного начали уставать к этому времени. Вернувшись на поляну где вы проснулись Фауст видит всё те же следы, но трава постепенно начала подыматься. А солнце всё так же печет. Все, особенно К'варсио и Цет очень хотят пить. Освальду тоже жарко в его теплой одежде\n\n// Давайте спас тела всем за жару\n\nА звук ручейка и редкий прохладный ветер с той стороны все сильнее манит вас\n\n// Если Полина что-то захочет сказать или сделать в прошлой сцене то отыграем ретроспективно как Коля в квестах писал, мне понравилась идея",167805,null],[169160,"2026-08-23T16:02:17",53,"+0",169159,null],[169161,"2026-08-23T16:02:19",41,"/r d20+2 спас теплого деда",167805,null],[169163,"2026-08-23T16:02:30",41,"( дед горячий",167805,null],[169164,"2026-08-23T16:02:42",17,"/r +5 Спас телосложения Фауста",167805,null],[169167,"2026-08-23T16:03:18",5,"/r +3",167805,null],[169174,"2026-08-23T16:05:06",53,"//когда вселенная начала жарить деда он благоразумно позволит ей это. у остальных 15",169163,null],[169177,"2026-08-23T16:05:25",53,"//хотя еще остался флорен 🤔",169174,null],[169184,"2026-08-23T16:07:33",11,"//кидай помеху за средний доспех\n\nУ Фауста лёгкий если не ошибаюсь так что не надо",169167,null],[169186,"2026-08-23T16:09:34",11,"Освальду слишком душно из-за его теплой одежды, К'варсио уже иссыхает без воды, ещё и чешуйчатый доспех\n\n1 степень истощения обоим",167805,null],[169188,"2026-08-23T16:11:20",5,"Грунг достаёт свой бурдюк и выливает половину содержимого на себя, надеясь облегчить страдания.\n\n— Жарко, квак жарко!",167805,null],[169193,"2026-08-23T16:12:36",22,"/r +2 Венус пытается понять, что такое пробуждение леса. А после запрыгивает на оленя, как ей предложили.",169065,null],[169195,"2026-08-23T16:13:01",11,"Кожа лягушонка впитывает влагу, но этого недостаточно. Его тянет к воде",167805,null],[169196,"2026-08-23T16:13:04",22,"//я буду чуть медленнее отвечать, сегодня дел много, но я все читаю, очень интересно!",167805,null],[169199,"2026-08-23T16:13:29",11,"// если что в ретроспективе все доиграем, я про тебя не забуду❤️",169196,null],[169200,"2026-08-23T16:13:31",41,"— Точно ли в лесу проблема, если тут такая невыносимая жара?",167805,null],[169201,"2026-08-23T16:13:35",22,"/r +3",169158,null],[169204,"2026-08-23T16:14:38",22,"- Хочу пить... Так жарко.. Я же не кактус, в конце концов! Вы посмотрите!\n\nВенус начала ныть, смотря на то, как иссыхает ее платье и становится некрасиво-коричневым и ломким.",167805,null],[169205,"2026-08-23T16:14:41",11,"Лес вокруг круга фей был прохладнее из-за тени, да и.. более похож на обычный. Сейчас же вы находитесь в джунглях. Солнце в зените и погода здесь соответствует обстановке",169200,null],[169206,"2026-08-23T16:15:28",53,"*вспомнив о существовании бурдюка крупными глотками выпиваю воду из него*",167805,null],[169207,"2026-08-23T16:15:31",11,"Друид понимает что круг ей знаком, а вот что именно он делает ей напомнил Фауст",169193,null],[169208,"2026-08-23T16:16:16",11,"Однако всадница на олене чувствует себя не так и плохо. Впрочем воды выпить хотят все",169204,null],[169209,"2026-08-23T16:16:40",41,"Освальд достанет свою флягу\n\n— Фауст, Будь другом, сделай лед во фляге",169204,null],[169210,"2026-08-23T16:16:52",11,"// и так все хотят воды, а @dunchev  видит что следы начинают понемногу исчезать..\n\nЧто делаете?",167805,null],[169241,"2026-08-23T16:29:24",53,"*подхожу к ледяному клону если таковой сейчас идет с нами и прижимаюсь к нему маской*",169210,null],[169243,"2026-08-23T16:31:53",11,"// интересно, а он реально холодный?",167805,null],[169244,"2026-08-23T16:32:09",41,"( нарратив в студию",169243,null],[169245,"2026-08-23T17:21:58",17,"Фауст делает жест и внутри фляжки Освальда появляются кубики льда\n\nВ бурдюках у остальных тоже самое\n\n\"Всегда пожалуйста\"",169209,null],[169246,"2026-08-23T17:22:23",17,"/ я все таки тут я не прав был. Нарративно ледяной но не холодный механически",169241,null],[169247,"2026-08-23T17:22:59",17,"\"Ребята, слышите? Ручей журчит в той стороне. Пойдёмте наберём воды\"",167805,null],[169248,"2026-08-23T17:23:19",11,"Цет прислоняется к клону, но холода не чувствует",169241,null],[169249,"2026-08-23T17:23:27",41,"— Давайте. Хохоу, так хочется свежей воды",167805,null],[169250,"2026-08-23T17:23:44",11,"// зато может пощупать торс эладрина легально без смс и регистрации",167805,null],[169251,"2026-08-23T17:24:09",5,"— Ручей? Где? Мне до смерти надо искупаться!",169247,null],[169252,"2026-08-23T17:24:48",11,"Звук журчащей воды слышат все где-то спереди и немного вправо",167805,null],[169260,"2026-08-23T17:31:26",53,"*продолжаю идти опершись мосью в клона и прикрыв глаза*",169248,null],[169261,"2026-08-23T17:32:03",5,"Изнемогающий от жажды лягушонок поскакал прямо на звук",169252,null],[169263,"2026-08-23T17:38:46",17,"\"Что вам архифея сказала? Дала какое нибудь задание? Она не объяснила где мы?\"",167805,null],[169264,"2026-08-23T17:43:29",11,"К'варсио прыгает в направление звука который становится всё ближе, а в конце пути его ждёт небольшая живописная река с хрустально-чистой водой. Мелководные участки с гладкой галькой здесь то и дело сменяются невысокими каменными каскадами с которых падает вода. \n\nРека скрывалась под раскидистыми папоротниками и сплетениями лиан. Здесь ты чувствуешь себя лучше, влажный воздух джунглей разбавляется прохладной свежестью и непрерывным, убаюкивающим журчанием.",169261,null],[169265,"2026-08-23T17:44:07",5,"— Моя кваспожа сказала, что лес здесь пробудился. И что я должен разузнать про это больше. Я не знаю, где мы находимся, но буду выполнять поручение кваспожи",169263,null],[169266,"2026-08-23T17:46:01",5,"— Какое замечательное место!\n\nК'варсио торопливо снимает с себя доспех, а затем бежит вприпрыжку к каскадам падающей воды. Чтобы насладиться потоками.",169264,null],[169267,"2026-08-23T17:46:28",11,"// вещи тоже оставляешь? И что делают остальные?",167805,null],[169268,"2026-08-23T17:46:52",5,"// да, кроме пояса с двумя мечами",169267,null],[169269,"2026-08-23T17:46:53",53,"мы добрались до воды?..\n*поднимаюсь с лопатки клона и осматриваюсь вокруг выискивая ростения которые могут помочь в лечении или же охлаждении\nи попутно набираю в флягу воды*\nчто это у нас тут?",169265,null],[169270,"2026-08-23T17:46:55",11,"Под одним из таких маленьких водопадиков лягушонок видит чуть более глубокий участок, падающая вода вымыла землю здесь создав заводь глубиной по грудь среднего человека",169266,null],[169271,"2026-08-23T17:48:01",41,"— только, что лес пробуждается и она не знает причину",169263,null],[169272,"2026-08-23T17:48:09",5,"Туда-то он и становится. А ещё К'варсио захватил бурдюк и наполняет его водой.",169270,null],[169273,"2026-08-23T17:48:12",22,"Венус замерла на краю берега, вода с поеском разбиваласб о камни.\n\nПрохладный влажный воздух, пропитанный свежестью, заставил её бледную зелёную кожу покрыться приятными мурашками. Она не стала спешить, из под ее платья медленно вытянулись корни, погружаясь в хрустальную воду. \n\nПожухлые цветы и листья на ее рогах тут же напитались влагой, вспыхнув мягким зеленым светом.\n-  Ах-х... вот теперь мы снова живем.\n\nТихо прошептала бывший тифлинг, закрыв глаза и с наслаждением впитывая каждую каплю прохлады под убаюкивающее журчание реки.",167805,null],[169274,"2026-08-23T17:48:54",11,"// если хочешь найти полезные травки кидай медицину/природу",169269,null],[169275,"2026-08-23T17:48:58",22,"Спустя время, насладившееся водой девушка, освежила свой бурдюк.",167805,null],[169277,"2026-08-23T17:49:08",53,"+0//",167805,null],[169278,"2026-08-23T17:49:51",11,"Кристально-чистая прохладная вода. Самая обычная, но такая освежающая. Для маленького грунга здесь достаточно глубоко что бы погрузиться с головой",169272,null],[169279,"2026-08-23T17:50:42",17,"\"Пробудился? Как то звучит страшновато. А что нужно делать конкретно?\"",169265,null],[169280,"2026-08-23T17:50:52",22,"Венус посмотрела на то, как странники ищут травы, чтобы охладиться.\n\n\"Глупцы\". - высокомерно подумала она.\n\nФлорен наклонилась, и с горстью зачерпнула речного ила. Ещё и еще, она покрывала себя приятной грязью, которая впитывалась в ее тело и одеяние, слегка изменяя его цвет.",167805,null],[169281,"2026-08-23T17:50:55",11,"Розы на тебе пустили новые побеги, а прошлые слегка увядшие от жары цветки приобрели здоровый вид и цвет и вновь благоухают",169273,null],[169282,"2026-08-23T17:51:24",17,"Магией формирования воды Фауст колдует обещанный дождик над грунгом",169264,null],[169283,"2026-08-23T17:51:53",5,"Выбросив на берег полный бурдюк и скинув вообще всё с себя, грунг возвращается в эту замечательную заводь. Он ныряет с головой и сидит под водой",169278,null],[169284,"2026-08-23T17:52:33",5,"— Спасибо, но здесь и так есть кводопад",169282,null],[169285,"2026-08-23T17:53:07",5,"// ретроспективный разговор\n\n— Кванкретно? Искать причину пробуждения. В лесу",169279,null],[169286,"2026-08-23T17:53:11",11,"Внимание Цета привлек небольшой куст, листья которого похожи на птичьи лапки. Он абсолютно точно не видел его ранее и не знает о его свойствах",169276,null],[169287,"2026-08-23T17:53:46",41,"— Видимо найти причину",169279,null],[169288,"2026-08-23T17:55:00",53,"хмм...\n\n*осматриваю куст подробнее пытаясь понять его примерные свойства и может ли он чем то быть полезен*\n\nэкий куст.\nзнает кто что это такое?",169286,null],[169289,"2026-08-23T17:55:23",5,"/ если бы мы знали что это такое...",169288,null],[169290,"2026-08-23T17:55:46",11,"Почему-то тебе кажется что куст полезный, но чем именно и что с ним делать ты не знаешь, как и остальные",169288,null],[169292,"2026-08-23T17:57:54",11,"Пока остальные наслаждаются водой и ее прохладой, под аккомпанемент из птичьего пения и журчания воды..\n\n«Слишком спокойным» — проносится в голове у Цета. Его слепое зрение помогает заметить как на большом листе, недалеко от него, почти сливаясь с его поверхностью, неподвижно сидит небольшое крылатое существо. Хотя зверёк и не прячется(?) остальные не видят его. Но не успевает Цет сказать о своем наблюдение остальным как каждого из вас, одновременно, пытаются накрыть такие создания. Каждого включая клона и Рудольфа.\n\n// Кидаем иню и враги ходят первые. Имея особенности позволяющие делать такие засады:3\n\nУ лягуха и фирболга помеха на иню ещё",167805,null],[169293,"2026-08-23T17:59:14",11,"// а листики если хочешь можешь собрать",169290,null],[169294,"2026-08-23T17:59:56",5,"/r -d20+2",167805,null],[169296,"2026-08-23T18:00:28",5,"// крылатый под водой охотится на грунга?",167805,null],[169297,"2026-08-23T18:01:04",11,"// а ты головой в этот момент снаружи был",169296,null],[169299,"2026-08-23T18:02:05",11,"// щас пойдет куча бросков не пугайтесь.. атака с преимуществом по всем кроме Цета.",167805,null],[169301,"2026-08-23T18:02:36",53,"//хочу.",169293,null],[169303,"2026-08-23T18:03:33",53,"//артик есь?",169292,null],[169304,"2026-08-23T18:04:27",11,"/roll +d20 К'варсио\n/roll +d20 клон\n/roll +d20 Фауст\n/roll +d20 Освальд \n/roll +d20 Рудольф\n/roll +d20 Венус\n/roll d20 по Цету",167805,null],[169306,"2026-08-23T18:05:10",11,"// ну и говно) щас гляну ваши КД скажу по кому попало",167805,null],[169307,"2026-08-23T18:05:21",5,"// я без доспеха, КД 12",167805,null],[169308,"2026-08-23T18:05:44",53,"10 кд :D//",169305,null],[169309,"2026-08-23T18:09:19",11,"На ваши лица пикируют вот такие птички. Впрочем, разглядеть ее пока что успел только Цет",167805,null],[169311,"2026-08-23T18:10:13",41,"/r -d20-1 иня поджареного деда(",167805,null],[169313,"2026-08-23T18:11:16",53,"//джëлтый аналог птахов что кусьнули пальцу",169309,null],[169315,"2026-08-23T18:12:15",27,"// Так вот как выглядят австралийские гуси...",169309,null],[169316,"2026-08-23T18:13:30",11,"// другие если что:D\nНе те же что были раньше \n\nНа ваши лица пикируют небольшие создания. \n\nКак только К'варсио выглядывает из воды в его лицо цепляется один из таких\nКлона и Венус постигает та же участь. \n\nНа оленя же и его хозяина птички не попали. \n\nЦет был готов так что успел среагировать. Фауст просто слишком ловкий и легко увернулся.\n\n//А теперь урон по тем по кому попало",167805,null],[169318,"2026-08-23T18:18:02",11,"Клон мгновенно исчезает получив 4 единицы урона. Птица что была на нем чуть было не упала на землю от неожиданности, но благодаря своей ловкости парит в воздухе\n\nК'варсио (2 урона колющего) же и Венус (4) получают царапины и лицехвата которого нужно скидывать действием // спас силы или спас силы от товарищей что бы помочь",167805,null],[169319,"2026-08-23T18:20:49",11,"// и так как все были застаты врасплох кроме Цета, ходи сперва ты Серёг, потом по порядку уже:3",167805,null],[169320,"2026-08-23T18:20:56",17,"/ если что у клона КД 14+БМ сейчас 16. Так что не пробивают. У меня КД 19.",167805,null],[169321,"2026-08-23T18:21:04",5,"Крылатая птица, вонзившая коготки в лицо красной лягушки, чувствует что-то неприятное, как будто ее кровь жжется внутри.\n\n// Кидай спас тела 12 против отравления",167805,null],[169322,"2026-08-23T18:21:13",17,"/r +4 Ини",167805,null],[169324,"2026-08-23T18:21:33",11,"// да, я знаю ваше КД и КД клона, у птиц есть + просто его не дописывала. По клону попали",169320,null],[169326,"2026-08-23T18:23:14",11,"Иня:\nПтицы \nЦет 18\nК'варсио 15\nВенус 13\nФауст 10\nОсвальд: 1",167805,null],[169327,"2026-08-23T18:24:51",11,"А ещё Цет и Фауст видят что помимо атаковавших вас птиц были ещё и они суют наглые мордашки в ваши сумки. Фауст пропускающий ход видит как его ограбили на минус пайки, а Цет может что-то с этим сделать",167805,null],[169328,"2026-08-23T18:25:34",53,"*быстро оценив обстановку я подбегаю к лягуху и пытаюсь сорвать с него птаху опустив ее в воду*\n\nныне я отдеру это с тебя, помоги лишь что есть сил тяни это от себя!",169319,null],[169329,"2026-08-23T18:25:44",41,"Вы видите как Освальд очень боится за здоровье оленя и первым делом попробует защитить его",167805,null],[169330,"2026-08-23T18:25:47",11,"// стой стой я щас спас кину",169328,null],[169331,"2026-08-23T18:25:52",5,"— Квааааа! — вопит лягуха",169328,null],[169333,"2026-08-23T18:26:27",11,"// кидай урон, Эл",167805,null],[169334,"2026-08-23T18:26:43",5,"// там не урон. Отравление = помеха на броски и проверки",167805,null],[169335,"2026-08-23T18:28:49",11,"// ну если хочешь помочь ему кидай силу",169328,null],[169336,"2026-08-23T18:29:08",5,"// не, я просто кричу",169331,null],[169338,"2026-08-23T18:30:18",53,"//я на это потратил действие, если верно понимаю?",169337,null],[169339,"2026-08-23T18:30:46",11,"Тебе с трудом, но удалось оттянуть птицу от лягуха, она вырвалась из твоих рук и с пьяным видом от отравления предпочла ретироваться от греха подальше",167805,null],[169340,"2026-08-23T18:31:39",53,"*после этого на остаток скорости бегу к сумкам с припасами*",169339,null],[169341,"2026-08-23T18:32:07",5,"// ретироваться в смысле улететь?",169339,null],[169342,"2026-08-23T18:33:01",11,"Осталась только птичка на лице Венус. Наглые создания за ход стащили вашу еду и улетают. Большая часть из них успешно скрылась в зарослях, но парочку вы ещё можете видеть (в 30ф, но в полу укрытие)",167805,null],[169343,"2026-08-23T18:33:18",11,"// угу",169341,null],[169344,"2026-08-23T18:33:25",5,"// провоцированную можно?",167805,null],[169345,"2026-08-23T18:34:09",11,"// неа, умение такое у нее, не провоцирует\nДа и у тебя оружия нет сейчас",169344,null],[169346,"2026-08-23T18:34:31",5,"// буря яростных лапок",169345,null],[169348,"2026-08-23T18:34:52",11,"// суммарно Венус получает 6 колющего урона \n\nНу и тут уже ваш ход",167805,null],[169349,"2026-08-23T18:34:57",41,"( а моя еда в мешке. Выйдет ли?",167805,null],[169351,"2026-08-23T18:35:24",53,"//опять я?..",169326,null],[169352,"2026-08-23T18:35:29",11,"// всех грабим, замка же не было:D",169349,null],[169353,"2026-08-23T18:35:58",11,"// ну справедливости ради сцена пусть и не серьезная, но боевая, а Венус так и не кидала иню так что правильнее будет подождать ее",169351,null],[169354,"2026-08-23T18:35:58",53,"//поблизости есть еще не улетевшие птицы что жарятся в мешках?",167805,null],[169355,"2026-08-23T18:36:16",53,"эт да//",169353,null],[169356,"2026-08-23T18:41:50",53,"*быстро оглядевшись кричу лягуху*\nпомоги поймать последнюю! она не должна уйти.",167805,null],[169357,"2026-08-23T18:42:27",5,"— Ква-а! Где?",169356,null],[169358,"2026-08-23T18:42:50",53,"*указываю на птаху на лице друида*",169357,null],[169359,"2026-08-23T18:43:22",5,"— Кварошо!",169358,null],[169671,"2026-08-23T21:44:39",22,"/r +2",169292,null],[169674,"2026-08-23T21:46:49",22,"Венус в ярости рычит. Опять какие-то голуби хотят сделать с ее рогами всякие непотребства!\n\nЗеленый сок вперемешку с кровью сочится из-под когтей птиц, а пара цветов были оторваны и течение реки уже уносило прекрасные окровавленные розы.\n\n- Ненавижу птиц! Вредители!",167805,null],[169676,"2026-08-23T21:49:04",22,"//простите, что так долго, куча дел",167805,null],[169677,"2026-08-23T21:49:48",11,"// Сергей ну тащемта всё равно твой ход да",167805,null],[169681,"2026-08-23T21:53:06",53,"*подбегаю к друиду и пытаюсь схватить птицу за горло и сорвать так что бы она осталась в руках, ожидая при этом прибытия товарища, что поможет обезвредить птицу* \n3... 2... сейчас!",167805,null],[169682,"2026-08-23T21:53:43",11,"// силу опять",169681,null],[169685,"2026-08-23T21:55:28",11,"Стянуть с лица Флорена птицу получилось, а вот удержать сил не хватило. Птичка вырвалась из твоих рук оставаясь парить на месте в пяти футах от вас",167805,null],[169686,"2026-08-23T21:56:35",53,"а вот теперь время кварсио и венуса которве идут как раз после меня ^^\\\\",169685,null],[169688,"2026-08-23T21:58:26",11,"// а Эл спать ушел",167805,null],[169689,"2026-08-23T21:59:06",53,"//это печально",169688,null],[169785,"2026-08-24T01:26:48",11,"Разобравшись с птицами и лишившись всей (или почти всей) своей провизии группа ощущает что направление с которого дует ветер изменилось. \nТеперь он доносит до вас новый запах, соли и водорослей.\n\nПосмотрев в сторону, откуда дует ветер, вы видите как сквозь густые переплетения лиан и гигантских папоротников пробиваются непривычные цвета — синий и жёлтый.\n\n// Я думаю вы разберётесь с ситуацией пока я спать буду, так что вот вам заранее описание\n\nНу а Серёга залутал 4 веточки растения с неизвестным эффектом, который ещё предстоит узнать",167805,null],[169787,"2026-08-24T07:35:12",5,"— Ловлю! — проквакал подбежавший к Венус К'варсио. В его руках уже был меч и... набор целителя. Он высоко подпрыгнул и резанул птицу по крылу. А затем, не дожидаясь исхода, бросил меч и взял бинты.\n\n— Кве-венус, ты ранена! Я перевяжу, пусть квеликий запоминает!\n\nГрунг принялся неуклюже обматывать голову флорен бинтом.",167805,null],[169788,"2026-08-24T07:35:35",5,"// а что записать про рационы?",169785,null],[169789,"2026-08-24T07:45:44",53,"//птаха вроде еще не улетела",169787,null],[169790,"2026-08-24T07:46:45",5,"// отпусти её с богом",169789,null],[169791,"2026-08-24T07:47:00",53,"//я хотев ее допросит и за едой сходить ^^",169790,null],[169792,"2026-08-24T07:48:28",5,"// идея хорошая...",169791,null],[169794,"2026-08-24T07:51:51",5,"/r +5 по птице",167805,null],[169796,"2026-08-24T07:52:22",5,"/r d6+3+d4 если попал",167805,null],[169798,"2026-08-24T07:53:37",5,"/ нелетальная",167805,null],[169803,"2026-08-24T10:28:02",22,"К'варсио напрыгнул так стремительно, что Венус едва успела убрать щит, чтобы не сшибить маленького грунга. Не успела она опомниться от его точного удара по птице, как на её голову уже опустились слои бинтов. Венус застыла, хлопая глазами.\n\n-Спасибо за заботу, мой маленький герой.\n\nЦветы на голове флорен вспыхнули ярким светом, а на лице появилась добрая и тёплая улыбка. Венус опустилась на одно колено прямо на гальку, чтобы оказаться на одном уровне с К'варсио, и ласково сжала его лапку.",167805,null],[169824,"2026-08-24T12:08:21",11,"// хотя ладно, чтоб не затягивать..\n\nНе летальная так не летальная, делайте как нравится",167805,null],[169825,"2026-08-24T12:09:36",11,"Птица смотрела в другую сторону и не увидела как отважный лягушонок занёс над ней свое лезвие",167805,null],[169829,"2026-08-24T12:57:59",5,"// а в итоге что с ней?",169825,null],[169830,"2026-08-24T13:01:34",11,"Птица падает на пол без сознания, ты явно переусердствовал с уроном, но если присмотреться оно ещё дышит",169829,null],[169831,"2026-08-24T13:08:38",5,"— Я? Герой?\n\nЛягушонок засмущался и смотрит на свою лапку в руках Венус. На лапке перчатка, размером несколько больше, чем подходит грунгу.\n\n— Я всего лишь учусь... врачевать!",169803,null],[169833,"2026-08-24T13:24:07",53,"*достав комплект целителя и веревку связываю существо и залечиваю его рану, а после, проверив надежность связки и на всякий случай окликнув квасио и поудобнее перехватив птаху провожу пахучей травой у лица птицы дабы разбудить ее*\n\nкварсио, ты сможешь поговорить с этим созданием? и я бы хотел осмотреть твои раны и помочь чем смогу.",169830,null],[169835,"2026-08-24T13:26:36",11,"// происходит трата ячеек следопыта",167805,null],[169836,"2026-08-24T13:26:41",41,"освальд позовет оленя в свой мешок, от чего тот послушно уйдет. После предложит раненой птице еще печенья",167805,null],[169837,"2026-08-24T13:26:53",41,"( ритуалом вроде можно",169835,null],[169838,"2026-08-24T13:27:18",5,"/ у следопыта нет ритуалов",167805,null],[169839,"2026-08-24T13:27:48",5,"// так ведь?..",167805,null],[169840,"2026-08-24T13:28:20",11,"// в 14 да",167805,null],[169841,"2026-08-24T13:30:02",11,"После манипуляций Цета птица продолжает лежать без сознания, но запах печенья действует как нашатырь и оно открывает глаза\n\n// Кстати, а откуда у вас печенье если его украли? \nВыпишите у себя пайки",169836,null],[169844,"2026-08-24T13:33:02",41,"( а, всеее?",167805,null],[169845,"2026-08-24T13:33:03",5,"К'варсио подошёл к связанной \"птице\".\n\n— Я поговорю с ней. Что ты квочешь узнать?\n\nНа голове грунга остались царапины от когтей птички.",169833,null],[169846,"2026-08-24T13:33:17",41,"( окей, еды нет",167805,null],[169847,"2026-08-24T13:33:29",41,"( спрятал последнее печенье за щекой",167805,null],[169852,"2026-08-24T13:39:14",53,"куда улетели другие.",169845,null],[169853,"2026-08-24T13:39:40",53,"*передав птицу грунгу аккуратно обрабатываю его раны*",169845,null],[169854,"2026-08-24T13:44:24",5,"Лягушонок взял птицу в лапки, заглянул ей в глаза и спросил, подражая голосу этих птиц.\n\n— Куда улетели другие?\n\n// Кастую разговор",167805,null],[169855,"2026-08-24T13:44:58",5,"// ты в перчатках?",169853,null],[169856,"2026-08-24T13:46:23",11,"Птенец молчит и моргает смотря на печенье",169854,null],[169857,"2026-08-24T13:47:13",5,"Грунг молчит и моргает, смотря на печенье",169856,null],[169862,"2026-08-24T13:51:21",11,"— Я отвечу если двуногие дадут еды мне",167805,null],[169864,"2026-08-24T13:54:13",53,"//да.",169855,null],[169865,"2026-08-24T13:54:24",5,"(на общем)\n— Ква! Печенье такое вкусное... Надо съесть, пока ещё осталось\n\nК'варсио умоляюще смотрит на Освальда с печеньем.\n\n— Дай мне печенье, пожалуйста!",169836,null],[169866,"2026-08-24T13:54:53",5,"// тогда не отравлен 😶",169864,null],[169867,"2026-08-24T13:55:52",41,"— Я хотел дать его раненой птице, но могу поделить. Кстати об этом, мы остались без еды почти что",169865,null],[169869,"2026-08-24T13:57:47",22,"- У меня с собой немного вяленых помидоров в специях. Эльфы называют это \"снеком\".\n\nВенус открыла деревянный ящик в своем теле и показала несколько упаковок из листьев.\n\n//у Венуса 7 пайков, она вроде больше не давала никому",169867,null],[169870,"2026-08-24T13:58:07",53,"//нас ограбили птицы",169869,null],[169871,"2026-08-24T13:58:11",41,"— Только у меня остались припасы. В Мой мешок заглянуть могу лишь я \n\nОн открыл мешок",167805,null],[169872,"2026-08-24T13:58:30",22,"/птицы выгребли вообще все? мне казалось что лишь частично мы лишились",169870,null],[169875,"2026-08-24T13:59:04",41,"( вообще",169872,null],[169876,"2026-08-24T13:59:16",41,"( нас раздели",167805,null],[169877,"2026-08-24T13:59:26",53,"нас обьели//",169876,null],[169878,"2026-08-24T13:59:41",22,"Венус открыла один из травяных конвертов и с ужасом обнаружила там лишь крошки.\n\n- МОИ ТОМАТЫ! НЕЕЕТ!",167805,null],[169879,"2026-08-24T13:59:58",41,"— Не волнуйтесь, леди. Найдем еще",169878,null],[169880,"2026-08-24T14:01:01",22,"Венус грустно шмыгнула носом и улыбнулась.\n\n- Хорошо.",167805,null],[169881,"2026-08-24T14:01:28",5,"— Но я хочу печенья... Ква!\n\nК'варсио посмотрел на птицу.\n\n— Кварошо, птица тоже хочет еды. Подели печенье пожалуйста, Освальд!",169867,null],[169882,"2026-08-24T14:03:09",11,"Испуганный птерозаврик смотрит как двуногие разговаривают между собой и не хотят давать печенье",167805,null],[169883,"2026-08-24T14:03:32",11,"Свисая в руках лягушки",167805,null],[169885,"2026-08-24T14:07:47",41,"Освальд решает достать еще печенье, ему как раз не помешает сбросить вес. Печенье получает Венус с кокосом, птица с орехами, К'Васирио получает радость.",169881,null],[169886,"2026-08-24T14:08:59",5,"// как много у тебя за щекой",167805,null],[169887,"2026-08-24T14:09:40",11,"Птенец грызет угощение из рук Фирболга\n\n— Ладно, я скажу. Еду отнесли в гнёзда. Гнёзда на утёсе",169885,null],[169891,"2026-08-24T14:10:01",11,"// у нее сумка маг предмет с доступом через кольцо, так что с него не выгребли",169886,null],[169892,"2026-08-24T14:13:03",5,"— Где утес? Покажи",169887,null],[169893,"2026-08-24T14:13:21",5,"Грунг говорит, хрустя печеньем",167805,null],[169896,"2026-08-24T14:17:28",11,"— У бескрайней воды — отвечает птиц и смотрит в сторону синевы откуда на вас дует ветер",169785,null],[169897,"2026-08-24T14:17:57",11,"— Как я тебе покажу если ты меня держишь?",167805,null],[169898,"2026-08-24T14:19:11",5,"— У кводы. Видел ещё двуногих в лесу?",169896,null],[169899,"2026-08-24T14:19:45",5,"(на общем)\n— Птица кваворит, еду унесли в гнезда на утёсе, утес у бесквайней квады",167805,null],[169900,"2026-08-24T14:20:02",11,"— Много двуногих, но здесь впервые ходят.",167805,null],[169903,"2026-08-24T14:21:12",5,"— Где другие двуногие ходят?",169900,null],[169906,"2026-08-24T14:22:05",41,"— На утесе их гнезда? Еду быстро съедят, лучше найдем новую",167805,null],[169910,"2026-08-24T14:24:15",11,"— На западе. Иногда выходят к большой воде",169903,null],[169911,"2026-08-24T14:25:05",11,"птенец висит в руках К'варсио напротив самого лягушенка\n\n// Запад от его позиции\n\nВ этой стороне знакомая вам река и скалистый берег",167805,null],[169912,"2026-08-24T14:26:03",5,"Остальным:\n— Птица квоворит, двуногие есть на западе.\n\n*показывает остальным направление*",167805,null],[169913,"2026-08-24T14:26:26",41,"— спасибо тебе и ей. Пойдем туда!",167805,null],[169915,"2026-08-24T14:30:27",41,"( подождем Николая?",167805,null],[169916,"2026-08-24T14:33:51",11,"Птенец видит в какую сторону вы смотрите и добавляет\n\n— Двуногие здесь не ходят, и четырехлапые тоже. Только крылатые, здесь тоже утёс, но каменный",167805,null],[169919,"2026-08-24T14:36:30",11,"Перед вами простираются джунгли. Камни вокруг реки создают не самую удобную, скользкую, но дорогу. Впереди — заросли, которые если постараться, можно срубить. Есть ли там утёс, не видно, растительность закрывает обзор",167805,null],[169922,"2026-08-24T14:39:29",5,"— Квуда мы пойдём? Что с делать птицей?\n\nГрунг крутит птерозавра в руках",167805,null],[169923,"2026-08-24T14:40:26",11,"// можно и подождать, но он в принципе может в ретроспективе говорить",169915,null],[169924,"2026-08-24T14:40:56",41,"— возьмем, пока не оправится",167805,null],[169925,"2026-08-24T14:41:06",22,"- Давайте идти, будем рубить растительность, что мешает двигаться. Потихоньку двинемся в сторону утеса, о котором говорит птица.\n\nЯ бы забрала его с собой. Он ранен, если мы его оставим - он умрет. Но что он сам думает на этот счет?",167805,null],[169927,"2026-08-24T14:41:48",5,"Лягушонок поднял птицу и спросил её.\n\n— Птица, что нам с тобой сделать?",167805,null],[169928,"2026-08-24T14:42:14",11,"— Отпустить — смело чирикает он",167805,null],[169930,"2026-08-24T14:43:13",5,"Остальным:\n— Кварит отпустить",169925,null],[169931,"2026-08-24T14:43:40",41,"— тогда...",167805,null],[169932,"2026-08-24T14:44:31",41,"Освальд прикладывает руку к птице и от неё исходит золотой свет",167805,null],[169934,"2026-08-24T14:44:46",41,"/r d8+2",167805,null],[169936,"2026-08-24T14:45:01",41,"Он Её исцелил",167805,null],[169937,"2026-08-24T14:47:51",5,"К'варсио вручает птерозавра Освальду",167805,null],[169938,"2026-08-24T14:48:04",41,"— обычно я делаю это в опасной ситуации, но раз он ждать не хочет. Можно отпустить",167805,null],[169939,"2026-08-24T14:48:24",11,"Вряд ли птица знает слова благодарности, но его взгляд говорит сам за себя. Крупный двуногий точно запомнится ему другом пахнущим вкусной едой и избавляющим от боли",167805,null],[169940,"2026-08-24T14:48:29",41,"Крыло как новое. Освальд поднимает птицу На руке",167805,null],[169941,"2026-08-24T14:51:34",11,"Он осторожно цепляется когтистыми лапами за руку Освальда\n\n— Большой двуногий не вредит мне хотя мои сородичи отобрали у вас еду, взамен я скажу вам что и у большой воды и у скал обитают хищники, вот почему тут нету других двуногих",167805,null],[169942,"2026-08-24T14:54:40",5,"Грунг переводит для остальных.\n\n— Освальд, ты ему нравишься! Кварит, там хищники обитают у скал и квады. Ква!",169941,null],[169943,"2026-08-24T14:55:21",41,"— мы поищем способ их обойти. Что за хищники?",167805,null],[169944,"2026-08-24T14:55:21",11,"— Мы не вьем гнезда у скал потому что там обитают огромные крылатые собратья.. они охотятся на всех кто меньше их",167805,null],[169945,"2026-08-24T14:56:11",5,"— Огромные крылатые сокватья, охотятся на мелких",169943,null],[169946,"2026-08-24T14:58:03",41,"— ясно, тогда нам нужна будет маскировка",167805,null],[169948,"2026-08-24T15:00:23",5,"— Маскировка?.. Я очень шумный, у меня не получится!\n\nЛягушонок посмотрел на птерозавра и спросил:\n— Скажи, как нам спрятаться от огромных птиц?",169946,null],[169951,"2026-08-24T15:01:56",53,"согласен. мы должны помогать раненым созданиям.",169925,null],[169954,"2026-08-24T15:03:38",22,"-Я предлагаю пока выдвинуться в ту сторону, а дальше мы что-нибудь придумаем. Посмотрим, что их привлекает, а что пугает. Может получится сделать приманку, которая их отвлечет.",167805,null],[169955,"2026-08-24T15:05:04",53,"*подхожу к птенцу и осматриваю его раны, если они есть*",167805,null],[169956,"2026-08-24T15:06:04",11,"— Большие братья высоко летают и видят всё-всё внизу, но деревья хорошо скрывают нас",169948,null],[169957,"2026-08-24T15:06:30",11,"Птенец сидит цел здоров на руке фирболга и отстраняется от тебя телом когда ты подходишь",169955,null],[169958,"2026-08-24T15:07:06",5,"— Давайте. Птица кварит, под деревьями нас не увидят",169954,null],[169959,"2026-08-24T15:07:29",53,"раз он исцелен, стоит снять лишние повязки.",169957,null],[169960,"2026-08-24T15:09:06",5,"// если все согласны, то\n\nГрунг двигается в сторону берега, прорубает кусты своими мечами, чтобы сделать свободный путь остальным",167805,null],[169961,"2026-08-24T15:10:21",11,"Он сам ощущает от них неудобство и стряхивает бинты с себя",169959,null],[169962,"2026-08-24T15:10:27",53,"*иду за грунгом*\nкак твои раны?",169960,null],[169963,"2026-08-24T15:10:30",11,"// все идут за ним?",169960,null],[169964,"2026-08-24T15:12:14",5,"— Спасибо, это лишь царапины. Таким не остановить рыцаря!",169962,null],[169965,"2026-08-24T15:14:42",41,"Идем",169960,null],[169967,"2026-08-24T15:15:34",11,"// В общем опишите как идете \n\n@lady_godzilla @dunchev вы тоже",167805,null],[169968,"2026-08-24T15:17:32",5,"К'варсио усердно рубит колючки. А сам посматривает наверх, чтобы случайно не выйти из-под защиты деревьев",167805,null],[169971,"2026-08-24T15:24:27",53,"*прохожу след в след за грунгом внимательно осмативая окружение, особенно внимательно ветви деревьев и небо, в одной из рук ручной топорик которым расчищаю ростительность до которой не достает лягух и готовлюсь блокировать им любую угрозу что окажется поблизости и попытается нас атаковать*",169967,null],[169985,"2026-08-24T16:57:15",22,"Венус убрала щит за спину, чтобы он не мешался и шла со скимитаром в руках. Она старалась срубать только самые крепкие и непослушные лианы. В груди немного кольнуло, ей было больно причинять вред природе, но выбора у нее было не много.\n\n\"Выживает сильнейший\".\n\nРешила для себя девушка и, стиснув зубы, продолжила путь. Будь она одна, то превратилась бы в лесную кошку или лемура и причинять боль природе бы не пришлось, однако за спиной флорен шли ее союзники, которые выглядят очень потеряно и беспомощно, словно слепые котята.",167805,null],[169986,"2026-08-24T17:31:28",17,"Фауст особо не понял что произошло и с птицами не заговаривал, так что он просто дождавшись, что все разрешилось пошел за остальными вместе с ледяным клоном.\n\nОн так и не обнажил меч, может и к лучшему.",167805,null],[170004,"2026-08-24T18:16:22",11,"Перед вами густая стена влажных зарослей: широкие трёхлопастные листья переплелись так плотно, что пройти дальше невозможно. Вы решаете прорываться силой.\n\nХрясь\n\nВетки поддаются вашему напору, но вместе с треском древесины из свежих срезов вырываются тонкие бледно-розовые волоски, похожие на пушистую пыльцу. Они кружатся в неподвижном влажном воздухе и мгновенно прилипают к лицу и одежде.\n\nКаждому из вас, кроме Фауста, чье лицо закрыто маской, внезапно щекочет нос.. так и хочется чихнуть\n\n// Кидайте спас мудрости",167805,null],[170006,"2026-08-24T18:19:56",5,"/r +2",167805,null],[170013,"2026-08-24T18:25:32",22,"/r +5",170004,null],[170017,"2026-08-24T18:29:08",11,"// жду от Эли и от Серёги ещё, а пока..",167805,null],[170018,"2026-08-24T18:29:23",41,"( надо доработать сори",167805,null],[170039,"2026-08-24T18:35:32",11,"Стоит К'варсио квахнуть как наваждение проходит, только нос немного щекочет",170007,null],[170683,"2026-08-24T20:13:00",22,"@sweetkittywitch Сергей /",167805,null],[171927,"2026-08-24T23:00:50",41,"/r d20+3",167805,null],[172057,"2026-08-24T23:37:52",11,"Освальд вовремя соображает поднять свободные руки и закрыть ими рот и нос\n\nВ это же время Венус чувствует странное, щекочущее тепло, которое поднимается от груди к носу. Она судорожно вдыхает, чихает и зажмуривает глаза.\n\nОткрыв их, мгновение спустя, она обнаруживает что мир вокруг нее изменился? Земля очутилась прямо перед самым носом, а камни у ее ног теперь стали преградой. Флорен испуганно оглядывается и замечает, что ее друзья теперь возвышаются над ней.",167805,null],[172100,"2026-08-25T00:34:06",53,"//у меня тоже лицо закрыто",170004,null],[172104,"2026-08-25T03:06:03",11,"Мерцающая пыльца лениво оседает на землю и открыв глаза вы оглядываетесь, но не видите Венус. \n\nПтица что сидела на руке у Освальда вспорхнула когда тот поднял руку что бы прикрыть глаза и сейчас вы видите её (?) на земле.",167805,null],[172107,"2026-08-25T11:00:50",22,"- Я здесь! Не наступите! АААПЧИ! \n\nПищало маленькое зелёное существо",167805,null],[172108,"2026-08-25T11:16:00",11,"Вместо собственного голоса ты слышишь как из твоего рта(?) вырываются стрекочущие звуки. Осмотрев собственные руки ты обнаруживаешь маленькие лапки.\n\nА всех остальных привлекает шум который создаёт маленькая птица с земли",172107,null],[172156,"2026-08-25T11:52:27",22,"Венус осматривает себя. Что я такое? Думает девушка",167805,null],[172179,"2026-08-25T12:03:19",5,"// можно мне такого домой?",167805,null],[172181,"2026-08-25T12:03:56",41,"/r d20+2 дед слышит ?",172107,null],[172184,"2026-08-25T12:04:11",41,"— О боже, лежи! Вы совсем кроха!",167805,null],[172185,"2026-08-25T12:04:18",22,"\"Я не хочу становиться девочкой обратно! Я такая красивая!\"\n\n*радостный клекот-стрекот*\n\nВенус начала махать крыльями. Она всегда мечтала научиться летать!",167805,null],[172206,"2026-08-25T12:14:52",17,"\"Что происходит?\"\n\nФауст выглядит растерянным глядя на то что произошло с Венус \n\n\"Освальд это что то в воздухе? Нельзя вдыхать?\"",172057,null],[172207,"2026-08-25T12:15:32",41,"— Да, будь осторожен. Нужно отойти отсюда!",167805,null],[172217,"2026-08-25T12:18:00",17,"Эладрин решил забраться выше и спустить верёвку вниз для остальных\nОглянулся в поисках высокого дерева.",167805,null],[172222,"2026-08-25T12:22:10",11,"Вокруг полно деревьев разных размеров, включая действительно высоких",172217,null],[172244,"2026-08-25T12:26:54",5,"Грунг отвлёкся от прорезания зарослей.\n\n— Отойти? Зачем? Куда? Нам надо на берег!",172207,null],[172246,"2026-08-25T12:27:33",41,"— тут пыльца. Она сделала с Венус это…\n\nОна показал на маленькое существо",172244,null],[172248,"2026-08-25T12:29:42",5,"— Венус стала такой милой птичкой!? Я тоже хочу! Ква!",172246,null],[172256,"2026-08-25T12:34:44",11,"// а не надо было спас проходить:3\n\nИ так у вас нету друида, но есть маленькая ящерица ака белка летяга и рядом достаточно высоких деревьев. Вы так же всё ещё видите что каменные пороги служат не заросшей дорогой к пляжу",172248,null],[172257,"2026-08-25T12:35:52",5,"К'варсио показал на пороги.\n\n— До пляжа совсем недалеко!",167805,null],[172477,"2026-08-25T15:13:09",41,"( ась?",167805,null],[172483,"2026-08-25T15:51:26",11,"// ну я жду пока вы предпримете какие-то действия или путь выберете",167805,null],[172484,"2026-08-25T15:55:29",41,"Освальд берет ящерку\n\n— Слушай, Венус, а ты хочешь полететь и посмотреть краткий путь нам? Будет очень кстати, раз тебе так нравится",167805,null],[172891,"2026-08-25T18:56:49",17,"\"А что на пляже?\"",172257,null],[172911,"2026-08-25T19:03:23",11,"// птичка говорила что там ходили двуногие",172891,null],[172993,"2026-08-25T19:18:08",17,"\"Я следую за тобой Кварсио. Пока идем, хотел узнать твою историю, ты знаком с этой архифеей?\"",167805,null],[173067,"2026-08-25T19:41:39",5,"// завтра отвечу",172993,null],[173139,"2026-08-26T00:10:22",22,"Пиу пиу пиу!!!\n\nВенус активно машет крылышками на ладони Освальда, пытаясь взлететь.",172484,null],[173143,"2026-08-26T00:42:07",11,"Крылышки у Венус на лапках, подняться самой в воздух она не сможет, но сможет парить в воздухе как белка летяга прыгнув с любой высоты не получая урон",173139,null],[173210,"2026-08-26T12:09:47",22,"Хлоп хлоп хлоп\nВенус изящно спланировала с руки Освальда на землю.\n\nПотом она жалобно подняла лапки вверх, просясь на ручки.",167805,null],[173216,"2026-08-26T12:39:18",5,"— Кванечно знаком! Я служу архифее, моей кваспоже. Она всегда рядом, направляет меня, квагда я сбился с пути. \n\nГрунг указывает на медальон из чёрного дерева на шее.\n\n— Прислушайся!\n\nЛягушонок открывает его и голос встреченной ранее архифеи шепчет: «Обещаю... Всегда...»",172993,null],[173217,"2026-08-26T12:56:30",17,"\"Да... Слышу. Значит она оберегает тебя? А что ты для нее делаешь?\"",173216,null],[173219,"2026-08-26T12:58:02",5,"— Она... даёт мне поручения. Они всегда непонятные, но я стараюсь, как могу!",173217,null],[173220,"2026-08-26T12:59:25",17,"\"Ага. Как разобраться в причинах пробуждения этого леса. Хорошо когда есть какой-то ментор, у вас прямо таки симбиоз. И много таких, кто служит ей? Или, нет, служит, наверное не правильное слово. Скорее у вас взаимопомощь и взаимовыручка. \"",173219,null],[173222,"2026-08-26T13:02:01",5,"— Да, квак сейчас!\n\nГрунг немного задумался.\n\n— Я не видел никого ещё, кто служит моей кваспоже. Но я — её рыцарь, и служу!",173220,null],[173223,"2026-08-26T13:03:34",17,"\"Рыцарь, ну да. Похож. Ладно, помогу вам разобраться, все равно не понятно как из леса выбраться. А там где двуногие, там и весь кипиш, веди.\"",167805,null],[173224,"2026-08-26T13:06:05",5,"— Я и сам не знаю, куда идти. Лишь надеюсь, что местные знают больше. Поэтому идём к ним!\n\nК'варсио поскакал по каменным порогам, ведущим к пляжу",173223,null],[173240,"2026-08-26T14:29:33",11,"// что на счёт остальных? Идёте с ним?",167805,null],[173245,"2026-08-26T16:31:15",22,"Венус хотела бы пойти с ними. Если ее кто-то посадит себе на плечо",167805,null],[173283,"2026-08-26T17:02:26",17,"\"Освальд, Цет, Кварсио, кто то возьмёт птичку с собой? Кажется Венус может быть полезна, если расколдуем, я видел на ней растут съедобные грибы, как минимум\"",167805,null],[173304,"2026-08-26T17:10:51",41,"— Ох, очень необычно. Я позабочусь о ней. Венус, можешь посидеть у меня в мешке, если хочешь. Там безопасно",167805,null],[173326,"2026-08-26T17:29:02",11,"Оставляя позади джунгли и скользкие, покрытые мхом, камни речного русла вы делаете последние шаги по каменистому берегу, и ступаете на мелкий рассыпчатый золотистый песок.\n\nРека которая вела вас сквозь чащу, здесь наконец находит свободу, резко расширяясь, и впадает в бескрайнюю морскую синеву, смешивая пресную воду с соленой пеной прибоя.\n\nЯркое полуденное солнце обрушивается на вас всей своей мощью, заставляя зажмуриться от слепящих бликов на воде. Но приятный морской бриз сильно спасает ситуацию. Он треплет ваши волосы и одежду, принося с собой бодрящую прохладу, резкий запах соли и выброшенных на берег, подсохших на солнце водорослей.",167805,null],[173348,"2026-08-26T17:36:29",22,"Венус в ужасе покачала головой. Она не хотела бы сидеть в мешке, ее же красивые пёрышки никто не увидит!",173304,null],[173350,"2026-08-26T17:37:46",22,"//вопрос к мастеру, в этой форме, я так понимаю, я не могу использовать заклинания с вербальным компонентом. Но могу ли я облик зверя использовать?",167805,null],[173352,"2026-08-26T17:38:42",17,"Фауст обращает внимание на водоросли может там есть съедобные",173326,null],[173353,"2026-08-26T17:38:52",17,"/r +1 Выживание",167805,null],[173357,"2026-08-26T17:40:00",5,"// сильно ли кварсио страдает от жары?",167805,null],[173359,"2026-08-26T17:41:27",11,"// нет, если интересно можно будет потом этот вопрос во флуде обсудить, как вернёшь свою форму что бы без метаразговоров сейчас",173350,null],[173360,"2026-08-26T17:42:23",11,"Фаусту приходит отличная идея, жаль что он совсем не разбирается в водорослях, однако у нас есть их ценитель который может помочь Сергей",173352,null],[173361,"2026-08-26T17:43:50",11,"После освежающего купания К'варсио какое-то время иммунен к воздействию жаркой погоды",173357,null],[173362,"2026-08-26T17:44:05",17,"\"Цет, ты морской житель? Знаешь какие нибудь целебные или съедобные водоросли?",173360,null],[173367,"2026-08-26T17:48:55",53,"*задумался перебирая знакомые варианты* \nнекоторые знаю, но не могу быть уверен, что здесь есть такие. \n//могу прокинуть на поиск или дать ттоварищу помощь? ^^",173362,null],[173374,"2026-08-26T17:50:54",11,"Оглядываясь вы так же можете увидеть вдалеке тот самый утёс о котором говорил птицезверь. Высотой около 100 футов (30м). Подобные ему летают там",167805,null],[173376,"2026-08-26T17:51:30",11,"// кидай выживание или просто опиши интересно, как знатоку водорослей за описание и так дам",173367,null],[173430,"2026-08-26T18:00:05",53,"*подождав несколько мгновений вы видите как одежда рыбки принимает новый вид, более удобной для купания, но маска все еще остается на лице*\n\nчто же. настал час когда я вернусь обратно к глубинам.  и покуда есть силы у нас, великий будет вести нас вперед.\n\n*с этими словами я слегка проведя по воде рукой ныряю в нее и начинаю плавать в воде, двигаясь ближе ко дну в поисках растений и рыбов(есть ростения и рыбовы?)*",173376,null],[173439,"2026-08-26T18:02:46",11,"Перед тобой уйма водорослей разных видов, но большинство знакомы тебе, а так же чистейший песочек на дне и плавающие местами медузы, но что странно — ни одной рыбы",173430,null],[173445,"2026-08-26T18:05:01",17,"Фауст решает набрать песка для грязного приема. В обрывок ткани он заворачивает горсть песка. \n\n\"Хм, можете пригодиться пустить пыль в глаза. Точнее песок.\"",167805,null],[173449,"2026-08-26T18:05:25",17,"Осматривается на берегу ближе к утесу скалы в поисках двуногих",167805,null],[173450,"2026-08-26T18:05:28",17,"/r +3",167805,null],[173459,"2026-08-26T18:09:05",53,"*плаваю вокруг осторожно ища нужные водоросли и стараясь не издавать лишних звуков и не приближаясь к медузам(если приблизятся аккуратно обплываю)*",173439,null],[173461,"2026-08-26T18:09:19",53,"//выживание",173460,null],[173462,"2026-08-26T18:09:33",53,"//+0.",167805,null],[173469,"2026-08-26T18:10:27",5,"Увидев маневры Цета, К'варсио немедленно поскакал за ним. Он плавает в воде за воином, совершенно никак не помогая",167805,null],[173475,"2026-08-26T18:11:01",53,"видишь рыб?",173469,null],[173480,"2026-08-26T18:12:04",53,"и я не вижу. а то оьозначает, что здесь вероятно есть что то голодное.",173475,null],[173481,"2026-08-26T18:12:09",53,"(все шопотом)",167805,null],[173482,"2026-08-26T18:12:17",53,"и вероятно опасное.",173480,null],[173483,"2026-08-26T18:12:28",53,"(тоже шопотом)",173482,null],[173484,"2026-08-26T18:13:18",5,"— Ква! Да, тут над нами летает большая птица. Зубастая. Так сказала маленькая птица. Ква!",173482,null],[173489,"2026-08-26T18:16:49",22,"- Пиу пиу пиу!\n\nОдной лапкой Венус крепко ухватилась за бороду Освальда, чтобы не упасть, а второй сделала чёткий жест в сторону утёса. \n\nУбедившись, что на скалу смотрят, она упёрлась передними лапами в бороду Освальда и начала имитировать быстрый подъём вверх, активно переставляя лапки одна за другой, после чего подпрыгнула и с требовательным писком замахала перепонками в направлении вершины.",167805,null],[173490,"2026-08-26T18:16:55",53,"я думаю это что то в воде. ведь не могла птица переесть всех...",173484,null],[173491,"2026-08-26T18:17:05",53,"(шептаемь ^^}",173490,null],[173497,"2026-08-26T18:19:09",5,"— Птицы умеют нырять. И птиц здесь много. Целый утес голодных ртов",173490,null],[173504,"2026-08-26T18:26:16",53,"//ты рассказывал нам о том что птица сожрала всех двуногих и четвероногих или нет?",173497,null],[173505,"2026-08-26T18:26:42",5,"// рассказывал",173504,null],[173506,"2026-08-26T18:27:03",5,"// только она просто хищная, неизвестно кого съела",167805,null],[173510,"2026-08-26T18:29:56",11,"// извините щас исправлю нормально опишу кринжи навалила",167805,null],[173511,"2026-08-26T18:30:13",53,"//а может там вообще два вида птиц. но я все равно за рыбкозавра ^^",173506,null],[173514,"2026-08-26T18:32:01",11,"Воин опустился на одно колено, аккуратно коснувшись пальцами зыбкого песка. Следы большого создания привлекли его внимание. По всей видимости животное было довольно тяжёлым потому что ветер еще не успел сгладить их острые края, но было видно что они начали засыпаться. Внимательнее присмотревшись Фауст так же заметил что чуть в стороне от цепочки этих грубых ям тянулась более легкая, прерывистая полоса — следы характерные человеческой обуви, их почти замело песком.\n\nШли эти двое от джунглей — к морю и наоборот. Там куда уходили следы была видна тропа.",167805,null],[173516,"2026-08-26T18:33:00",11,"К'варсио ощущает что вода как-то отличается от привычной ему.. она солёная",173469,null],[173519,"2026-08-26T18:34:39",11,"У Цета получается собрать 5 пайков добротных морских вкусностей, но будучи увлечённым разговором, растениями и опасностью с неба вы совсем не заметили тех кто съел всю рыбу до вас..",173461,null],[173520,"2026-08-26T18:34:42",5,"— Квода другая, соленая. Немного неприятно. Лучше вернусь под водопад.\n\nК'варсио вылез из моря и пошел к Фаусту",167805,null],[173521,"2026-08-26T18:34:53",11,"// неть не успел",173520,null],[173524,"2026-08-26T18:40:56",17,"\"Тут крупные следы двоих, кто то большой и обычный гуманоид двуногий. Шли рядом. И ушли вон туда, видно тропу. Давайте пойдем следом, это было относительно незадолго до нас. Но и прям недавно\"",167805,null],[173525,"2026-08-26T18:41:26",11,"Изящные большие ящеры плавно скользят сквозь толщу прозрачной морской воды, напоминая грациозного подводного левиафана в миниатюре. Вода легко удерживает их поджарые тела, пока они неторопливо перебирают мощными лапами среди колышущихся изумрудных лесов из гигантских водорослей. Длинные бурые ленты растений мягко огибают их гладкую, зеленовато-серую чешую с костными бляшками на спине, а маленькие головы на гибкой шее то и дело погружается вглубь зарослей в поисках лакомства. В лучах солнца, прошивающих океан, молодые ящеры выглядит безмятежными и величественными хозяевами своего уединенного подводного мира. \n\nЗаметив их первыми вы собираетесь ринуться к берегу, но они успевают нагнать вас как только ваши головы показываются товарищам",167805,null],[173526,"2026-08-26T18:42:28",53,"//артик есть?",173525,null],[173532,"2026-08-26T18:46:08",11,"И так \nБелая точка - Освальд. Зелёная с ним - Венус птичка \nБирюзовая - Фауст \nКрасная - К'варсио \nСиняя - Цет\n\nКрупные точки - аризонозавр 1 и 2. Жёлтое 3 который так и не показался из воды.\n\nКидаем инициативу",167805,null],[173534,"2026-08-26T18:47:07",17,"/r +4 Ини Фауст",167805,null],[173537,"2026-08-26T18:47:21",53,"+0//",173535,null],[173539,"2026-08-26T18:47:38",5,"/r +2",167805,null],[173541,"2026-08-26T18:48:09",41,"/r d20-1 аааа драца",167805,null],[173551,"2026-08-26T18:50:40",11,"Иня:\nФауст 24\nАризонозавр 1 и 2 - 12\nВенус - 12\nК'варсио - 7\nАризонозавр 3 - 5\nЦет - 3\nОсвальд - 2",167805,null],[173559,"2026-08-26T18:57:07",17,"Фауст обернулся на звуки плеска воды, на морской глади он явно заметил зубастую угрозу\n\nМысль о том что двое из их отряда в воде промелькнула мгновенно и ударила как электрошок\n\nНе теряя времени эладрин сорвался с места он пробежал прямо до берега. \n\nЗавидев что всё ещё далеко от ящеров обернулся назад на своего клона, махнув свободной рукой клон взорвался на месте где стоял облаком осколков. Они быстро растворились в воздухе.\n\nРазвернувшись снова к угрозе, Фауст воссоздал клона над водой и толкнул его вперёд прямо к ящеру, клон очутился между Цетом и смертоносным зверем.\n\nФауст обнажил клинок и рубанул воздух, клон повторил взмах, оружия у него не было, но невидимый клинок рядом рассек монстра. \n\nПосле этого струйка крови пошла из носа Фауста. Он мысленно представил как клон вонзает свои ледяные когти в глаз существа и клон совершил эту атаку в то же мгновение",167805,null],[173560,"2026-08-26T18:57:23",11,"Венус чувствует что силы понемногу начинают возвращаться к ней, но на это потребуется ещё несколько секунд\n// Грубо говоря первый ход  @lady_godzilla будет птичкой (+2 к ине), затем бонус добавишь свой",173532,null],[173565,"2026-08-26T18:57:56",17,"/подошёл на 30. Переставил клона в 15 от себя бонусным действием. Двинул его ещё на 15. \n\nУдар через клона. \n\nСпособность высвобождение потенциала ещё один удар через клона.",167805,null],[173569,"2026-08-26T18:58:37",17,"/r +6 q +6 q На попадание\n\nd8+6 Рубящий если первый попал \n\nd8+6 Рубящий удар два если попал",167805,null],[173574,"2026-08-26T18:58:53",17,"/r d8 Рубящий к первому за крит",167805,null],[173576,"2026-08-26T18:59:12",17,"/ 27 рубящего урона",167805,null],[173584,"2026-08-26T19:00:27",11,"Ящер пошатнулся на месте, точные движения клона попадали в самые болезненные места. Его зелёная чешуя померкла от полученных ранений",167805,null],[173594,"2026-08-26T19:06:14",11,"// Ладно, Венус в обличие птички не достанет точно первый ход, так что если захочет подлететь может озвучить это позже. Между вами примерно 50ф расстояние как правильно посчитал Коля.",167805,null],[173596,"2026-08-26T19:06:53",11,"Раненый зверь пытается атаковать раздражитель вместо тритона",167805,null],[173600,"2026-08-26T19:07:47",11,"Раненый, но злой ящер пытается ухватить клона зубами, но тот растворяется получив урон",167805,null],[173603,"2026-08-26T19:08:18",11,"Второй же ящер все ещё сосредоточен на К'варсио и пытается поймать его",167805,null],[173607,"2026-08-26T19:09:15",22,"/r +2",173551,null],[173614,"2026-08-26T19:10:29",22,"//не ожидала что так быстро и резко бой начнется. Можно инфу по теле птички? какие атаки есть и пр",167805,null],[173615,"2026-08-26T19:10:45",11,"Хищник хватает свою добычу в виде алой лягушки нанося ей 12 колющего урона\n\n// К'варсио, спас силы на высвобождение",167805,null],[173624,"2026-08-26T19:12:06",11,"// статы, атака +4, но урон всего 1",173614,null],[173625,"2026-08-26T19:12:10",5,"/r +6",173615,null],[173628,"2026-08-26T19:12:57",11,"К'варсио трепыхается в пасти ящера получая ещё 6 урона",167805,null],[173629,"2026-08-26T19:13:06",11,"// отравление будет? Или как там",167805,null],[173630,"2026-08-26T19:13:23",5,"/ спас тела 12",173629,null],[173632,"2026-08-26T19:13:43",11,"// прошёл\nХод Венус",167805,null],[173633,"2026-08-26T19:14:18",41,"( лети птичка",167805,null],[173642,"2026-08-26T19:16:25",22,"Птичка летит в бой, она явно не успевает кого-то клюнуть, но смело летит к врагам, громко стрекоча и маша крыльями, стараясь их отвлечь от товарищей.",167805,null],[173646,"2026-08-26T19:17:19",22,"- Я тебе все плавники повырываю! Ты кто такой? А? А ну иди сюда, я тебе жабры на хвост натяну!\n\nРугается Венус.\n\nВсе остальные же слышат чирик трик трик стрекко ко",167805,null],[173647,"2026-08-26T19:17:30",11,"// выступление:D",167805,null],[173650,"2026-08-26T19:18:18",22,"/r d20-3 ругается на птичьем",167805,null],[173654,"2026-08-26T19:18:45",11,"Ящер что схватил лягушку выплюнул ее скалясь на птицу, но двигаться не стал",167805,null],[173655,"2026-08-26T19:18:53",11,"// ход К'варсио",167805,null],[173656,"2026-08-26T19:18:56",5,"Грунг квакает от боли, тут же выхватывает клинок и режет по ноге хищной рыбины.",167805,null],[173657,"2026-08-26T19:19:05",5,"/r +5",167805,null],[173660,"2026-08-26T19:19:23",5,"/ спас тела 12",167805,null],[173663,"2026-08-26T19:20:13",5,"/r d6+3",167805,null],[173670,"2026-08-26T19:21:47",5,"— Цет, ты был крав! Уплывай отсюда скорее! Архифея защити нас!\n\nК'варсио растворяется в воздухе, а затем снова появляется, но на 30 футов ближе к берегу. И плывет дальше со всех лапок\n\n/ Туманный шаг и ещё 25 футов",167805,null],[173673,"2026-08-26T19:22:15",5,"/ и ход",167805,null],[173676,"2026-08-26T19:22:54",11,"К'варсио не сильно, но ранит динозавра, тот немного шипит, но скорее растерян тем как ты исчез и оказался возле Освальда и Фауста (полагаю)",167805,null],[173679,"2026-08-26T19:23:46",11,"Внезапно из воды выскакивает ещё один, чуть поменьше на вид, он прыгает на Цета",167805,null],[173681,"2026-08-26T19:23:59",11,"// Серёга, отдыхать..",167805,null],[173684,"2026-08-26T19:24:14",53,"//живь ^^",167805,null],[173685,"2026-08-26T19:24:18",11,"// спас силы",167805,null],[173687,"2026-08-26T19:24:27",53,"//+1",173686,null],[173688,"2026-08-26T19:24:31",11,"// ёлки макарошки",167805,null],[173690,"2026-08-26T19:24:49",53,"//рыба в воде есь рыба в воде ^^",167805,null],[173691,"2026-08-26T19:25:16",11,"Хрупкий, но стойкий обыватель вырывается из пасти твари, та рычит на него с запахом тухлой рыбы",167805,null],[173692,"2026-08-26T19:25:29",11,"// и твой ход",167805,null],[173736,"2026-08-26T19:35:59",53,"*выскальзывая из пасти отталкиваю, а так же в его морду ударяется неслабый энергетический всплеск(спас силы от ящерки) верхнюю челюсть твари ногами и обращаясь в вид рыцаря и доставая свое длинное рубило я отхожу(действие отход) к товарищам(к рецарю эха в ближайшей точке от лягуха не выходя из зоны поражения эхо-рыцаря)*\n\nдруже, умеешь пользоваться таким оружием? (рыцарю) \n\n\nя есмь посланник твой, я есмь проволник твой, о великий даруй моему орудию силу твою, что разит врагов твоих.(шепотом)\n\n*оружие заполняет сила молнии и оно начинает сиять от эллектрических искорок пробегающих по нему искрорками(цветная инфузия) и если рыцарь согласен то передаю ему электро-алебарду*",167805,null],[173740,"2026-08-26T19:36:55",53,"//на этом мои полномочия все",167805,null],[173749,"2026-08-26T19:38:37",11,"// ничего не понял но очень интересно:D\n\nЕщё раз сколько футов и куда идёшь?",167805,null],[173750,"2026-08-26T19:38:49",53,"//от ящерки нужон спас силы ^^",173749,null],[173752,"2026-08-26T19:39:07",53,"//прошла",173751,null],[173753,"2026-08-26T19:39:29",11,"Ящер не понимает что произошло и продолжает на тебя рычать",167805,null],[173754,"2026-08-26T19:39:45",53,"//иду используя действие отход к эхо рыцарю, так что бы оказатся в пределах его досяганмости и при этом быть поближе к лягуху",173749,null],[173759,"2026-08-26T19:42:22",53,"//а по поводу зарядки орудия алебарда теперь на носит не 1к10+сила рубящего, а 1к10+сила рубящего +1к4 электричества",173754,null],[173765,"2026-08-26T19:43:09",11,"// ну если Серёга свой ход закончил, то ход Освальда",167805,null],[173766,"2026-08-26T19:43:18",53,"//дя",173765,null],[173768,"2026-08-26T19:43:56",11,"Тем временем мир глазами Венус вновь становится нормальным, а песок больше не закрывает обзор",167805,null],[173771,"2026-08-26T19:45:23",53,"//а пока он рычит диктор на фоне рассказывает о том как сверкали пятки лекаря когда он покидал область боя",173753,null],[173772,"2026-08-26T19:46:06",11,"// @sweetkittywitch",173765,null],[173774,"2026-08-26T19:46:58",41,"( кто ранен , напомните",167805,null],[173775,"2026-08-26T19:47:12",53,"//я и лягух.",173774,null],[173776,"2026-08-26T19:47:48",53,"//и эхо разложившееся на воздух и липовый лед",167805,null],[173778,"2026-08-26T19:47:57",53,"//ну ему уже не помочь ^^",173776,null],[173780,"2026-08-26T19:48:05",11,"Освальд видит раненого грунга возле себя с следами от зубов на теле, а так же тритона стоящего в 15ф от тебя рядом с Эладрином",167805,null],[173784,"2026-08-26T19:49:13",41,"Поможет грунгу",167805,null],[173785,"2026-08-26T19:49:22",41,"/r d8+2 исцеление",167805,null],[173787,"2026-08-26T19:49:29",41,"( уы",167805,null],[173791,"2026-08-26T19:51:51",5,"Места укуса теперь кровоточат чуть меньше.\n\n— Квасибо, Освальд!",167805,null],[173793,"2026-08-26T19:53:25",41,"— Пожалуйста, но увы… \n\nОн достанет свой посох\n\n— придется покипеть",173791,null],[173794,"2026-08-26T19:54:20",53,"//ну и я ее пытаюсь передать @dunchev",173759,null],[173797,"2026-08-26T19:54:53",11,"// новое расположение если правильно вас поняла",167805,null],[173799,"2026-08-26T19:55:21",11,"// и полагаю ход переходит к Коле",167805,null],[173801,"2026-08-26T19:55:53",17,"/ Мне не надо)) ты чего я от ловкости с дуэлянтом",173794,null],[173803,"2026-08-26T19:56:56",17,"\"Алебарда мне только помешает, спасибо\"",167805,null],[173804,"2026-08-26T19:57:19",53,"*понимающе киваю перехватывая алебарду поудобнее*",173803,null],[173806,"2026-08-26T19:58:10",17,"\"Ну что ж. Вставайте я в авангарде приму удар. Готовимся\"\n\nФауст перед собой создаёт ледяного клона снова\n\nИ готовиться рубить",167805,null],[173809,"2026-08-26T19:58:43",17,"/ Бонуской эхо. Основное атака через эхо. Конец хода. \n\nЕсли пройдут мимо клона будет реакция на атаку по возможности",167805,null],[173811,"2026-08-26T19:59:06",17,"/ Хотя они же ближе чем 30",167805,null],[173812,"2026-08-26T19:59:12",17,"/ сек я чуть переделаю",167805,null],[173814,"2026-08-26T19:59:38",53,"//внезапно вспомненые 5 урона полем по ящерке ибо",173813,null],[173818,"2026-08-26T20:00:43",17,"Фауст снова мягким движением толкнул клона в спину и тот полетел вперёд над водой к уже ранее раненому ящеру\n\nСнова рубанув воздух около клона невидимый клинок рассекает плоть",167805,null],[173819,"2026-08-26T20:00:51",17,"/r +6 q\n\nd8+6 q",167805,null],[173821,"2026-08-26T20:01:13",17,"/Везунчик а трачу",167805,null],[173822,"2026-08-26T20:01:20",17,"/r +6 q",167805,null],[173824,"2026-08-26T20:01:37",11,"// две атаки верно?",173820,null],[173825,"2026-08-26T20:01:40",17,"/ 12 рубящего тому кто получил 27 и наверное что то еще",167805,null],[173826,"2026-08-26T20:01:48",17,"/ Атака одна. Переброс за везунчика",173824,null],[173827,"2026-08-26T20:03:04",11,"Ящер падает у ног эладрина, оставшиеся два лишь скалятся смотря на тебя",167805,null],[173828,"2026-08-26T20:04:07",17,"/ Ну технически. Я так понял ящеры ещё были в воде туда я клона отправил и там рубил через него. Или уже на берегу ящуры?",167805,null],[173829,"2026-08-26T20:05:04",11,"// на мелководье. Там ходить можно\n\n(Тут хз как по правилам, но допустим что для не плавающих двойная мобильность, но атаки нормальные)",167805,null],[173831,"2026-08-26T20:09:00",11,"// так мой ход и ты атаковал клоном, сам стоишь где стоял, верно?",167805,null],[173839,"2026-08-26T20:13:20",17,"/ Да верно",167805,null],[173840,"2026-08-26T20:13:34",17,"/ Чуть перед всеми так сказать",167805,null],[173842,"2026-08-26T20:15:29",11,"«оранжевый» на карте аризонозавр видел как клон растворился в зубах павшего товарища, да и едой от него не пахнет, так что игнорируя эхо он направляется к хозяину",167805,null],[173843,"2026-08-26T20:15:40",11,"// давай провоцированную",167805,null],[173844,"2026-08-26T20:15:47",17,"/r +6 q",167805,null],[173848,"2026-08-26T20:16:04",11,"Эхо промахивается и динозавр даже не замечает его атаки",167805,null],[173849,"2026-08-26T20:16:15",17,"Фауст не успел среагировать и достать спину ящера",167805,null],[173851,"2026-08-26T20:16:37",11,"// опиши как уклонился",167805,null],[173854,"2026-08-26T20:17:44",17,"В бою эладрин использовал стальную перчатку с когтями которой парировал и отбивал удар\n\nЯщер пытался укусить его но получил тыльной стороной перчатки по морде на отскоке",167805,null],[173859,"2026-08-26T20:19:26",11,"//ход Сергей и возле тебя снова ящерица",167805,null],[173860,"2026-08-26T20:20:42",53,"//насколько близко?",173859,null],[173861,"2026-08-26T20:20:55",53,"//перед фаустом или ближе?",167805,null],[173862,"2026-08-26T20:21:06",11,"// он 10х10 футов так что возле вас двоих",173860,null],[173863,"2026-08-26T20:21:24",22,"(венус ход пропускает?",167805,null],[173864,"2026-08-26T20:21:34",11,"// точно я про Полину забыла извини, твой ход!",167805,null],[173867,"2026-08-26T20:21:52",53,"//и про лягуха",173864,null],[173868,"2026-08-26T20:22:08",22,"Они подошли к берегу? сколько фт до них?/",167805,null],[173869,"2026-08-26T20:22:11",11,"// да я в целом почему-то решила что жёлтым хожу сори, моя ошибка",173867,null],[173878,"2026-08-26T20:24:45",11,"Один из ящеров стоит возле эладрина и тритона, тело второго омывает соленая вода забирая с собой его кровь в море, а третий стоит на месте, чуть поодаль от вас. Из-за того что на мелководье в 25 футах от тебя (пешком не дойти)",173868,null],[173891,"2026-08-26T20:28:53",22,"Птичка, полная ярости летела в сторону ящеров. Неожиданно для себя она превратилась обратно в девочку и неуклюже упала в песок.\n\nВенус встала. Злая, растрепанная и поцарапанная песком она попыталась сделать шаг, но ноги вязли в песке  и быстро дойти у нее не получится.\n\nФыркнув и выплюнов изо рта ракушку, флорен вытянула руки вперед и начала заколдовывать водоросли, отращивая у них шипы, заставляя расти гуще и быстрее, больно раня ящеров",167805,null],[173894,"2026-08-26T20:29:19",22,"сл 13 мудрость/внимание",167805,null],[173899,"2026-08-26T20:30:08",11,"// нарисуй на карте где кастуешь их, а то вы там впритык все стоите, вдруг ещё сами на них попадете хд",167805,null],[173909,"2026-08-26T20:31:25",11,"Первый ящер слишком занят боем, второй же увидел твои действия",167805,null],[173926,"2026-08-26T20:33:39",22,"точка на пересечении клеток, я чуть скривила/",167805,null],[173929,"2026-08-26T20:34:01",11,"// только оранжевый ящер уже у Цета и Фауста стоит, вне радиуса, а жёлтый колючки как раз заметил",167805,null],[173935,"2026-08-26T20:34:46",22,"обнови пж карту, я накрываю четко так, чтобы Фауста не цепляло, а ящеров задело/",167805,null],[173944,"2026-08-26T20:36:28",11,"// красный мёртв, жёлтый стоит, оранжевый двинулся туда куда показала",167805,null],[173948,"2026-08-26T20:36:51",53,"//а когда красный помереть успев",167805,null],[173968,"2026-08-26T20:39:14",11,"// двинулась сама как-то или на месте осталась? И если ты закончила то ход К'варсио",167805,null],[173969,"2026-08-26T20:39:26",5,"К'варсио вытащил второй меч и с боевым кваканье надвигается на ящера",167805,null],[173971,"2026-08-26T20:39:33",22,"|на месте пусть будет",167805,null],[173979,"2026-08-26T20:40:03",5,"/r +5 первая +5",167805,null],[173981,"2026-08-26T20:40:14",5,"/ 2 Спаса тела 12",167805,null],[173985,"2026-08-26T20:40:55",5,"/r d6+d4+3 один\nd6+3 два\n2d4 яд",167805,null],[173987,"2026-08-26T20:41:26",5,"— Ква! Ква!\n\nИ режет зверя",167805,null],[173988,"2026-08-26T20:41:28",5,"/ ход",167805,null],[173997,"2026-08-26T20:44:03",11,"/roll 2d4\n/roll 2d4\n/roll 2d4\n/roll 2d4",167805,null],[174007,"2026-08-26T20:45:29",11,"Третий ящер движется вверх видя колючки на земле. Водоросли оплетают его лапы сильно раня, но делают только злее и он атакует лягушонка",167805,null],[174010,"2026-08-26T20:46:16",11,"В последний момент когда ящер пытался сделать рывок к К'варсио водоросль потянул его обратно за хвост",167805,null],[174013,"2026-08-26T20:46:22",11,"// теперь ход Цета",167805,null],[174024,"2026-08-26T20:49:23",53,"//интернет ожив",167805,null],[174025,"2026-08-26T20:49:27",53,"//а, нет, интернет сделал вдох и сдох.",167805,null],[174029,"2026-08-26T20:49:39",53,"//интернет ожив 2.0",167805,null],[174039,"2026-08-26T20:51:56",53,"//он проходит мимо нас?",174007,null],[174040,"2026-08-26T20:51:56",53,"///////ебучий интернет",167805,null],[174045,"2026-08-26T20:53:30",11,"// напротив тебя стоит 10х10 клеток ящерица и проходят напротив неё, а сверху над тобой стоит К'варсио, снизу Фауст\nПровоцированных не будет💅",174039,null],[174049,"2026-08-26T20:54:50",53,"//можешь на карте показать пока описываю что делаю?",174045,null],[174050,"2026-08-26T20:54:56",53,"//заранее спасибо :3",167805,null],[174056,"2026-08-26T20:57:20",53,"*крепко сжав алебарду даю в нос ящерке оранжевой элекро-палкой*",167805,null],[174062,"2026-08-26T20:58:30",11,"// ты кстати как на его клетку встал.. я тебя перемещу немного",173972,null],[174076,"2026-08-26T21:00:21",53,"//а, нет, не укрываюсь",174071,null],[174078,"2026-08-26T21:00:31",53,"//конец хода.",167805,null],[174080,"2026-08-26T21:00:48",11,"Твоя алебарда и близко не касается ящера, они оба даже не смотрят на тебя",174056,null],[174082,"2026-08-26T21:01:10",11,"// @sweetkittywitch ход",167805,null],[174085,"2026-08-26T21:01:56",41,"( кто из врагов ближе ко мне ?",167805,null],[174089,"2026-08-26T21:02:23",41,"( а. Желты й",167805,null],[174091,"2026-08-26T21:03:01",53,"цел ты аль раны еще тревожат?(лягуху)",173988,null],[174092,"2026-08-26T21:03:10",41,"Подбегаю и устрашающе вращаю палкой пытаясь отогнать хищников дальше в воду",167805,null],[174093,"2026-08-26T21:03:18",41,"/r d20 запугивание",167805,null],[174095,"2026-08-26T21:03:25",41,"( Оу ноу",167805,null],[174101,"2026-08-26T21:04:01",41,"/r d20 тогда бонк по башке",167805,null],[174104,"2026-08-26T21:04:08",41,"( конец хода",167805,null],[174105,"2026-08-26T21:04:09",5,"— Болят укусы, но я держусь! Следи, чтобы тебя не достали, ква!",174091,null],[174108,"2026-08-26T21:04:22",41,"( уквусы",167805,null],[174110,"2026-08-26T21:04:48",11,"Ящерицы не пугаются фирболга даже несмотря на то что тот выглядит довольно крупным",167805,null],[174111,"2026-08-26T21:04:51",53,"коли дам алебарду, сможешь с ней обращаться пока я буду тебя целительствовать?",174105,null],[174112,"2026-08-26T21:04:54",11,"// @dunchev ход",167805,null],[174120,"2026-08-26T21:05:58",17,"/ Жёлтый и оранжевый друг от друга в 5 футах?",167805,null],[174124,"2026-08-26T21:06:26",11,"// да рядом стоят",167805,null],[174125,"2026-08-26T21:07:15",5,"— Она...\n\nГрунг посмотрел на алебарду. Алебарда вдвое больше него.\n\n— Слишком тяжёлая для меня",174111,null],[174126,"2026-08-26T21:07:54",17,"Фауст поднимает клинок для очередного цдра\n\nВ этот раз он делает жест и шепчет еле еле слышно заговор\n\nКлинок загорается зелёным пламенем, при столкновении оно перекидывается на соседнюю ящерицу\n\nУдарив так эларин быстро проводит ещё одну таку зелёное пламя вновь вспыхивает и снова кусает соседнего ящера.",167805,null],[174129,"2026-08-26T21:08:20",17,"/ Заговор клинок зелёного плвмени\n\nВсплеск действий \n\nЕщё раз атака клинок зелёного пламени",167805,null],[174131,"2026-08-26T21:08:43",11,"// хм..\n\nДа, все легально \nТолько скажи мне во флуде наверное откуда у тебя заговоры просто интересно) мультикласс?",167805,null],[174134,"2026-08-26T21:08:56",17,"/ Да?",167805,null],[174145,"2026-08-26T21:11:14",17,"/r +6 попадание раз\n\nd8+6 Колющий раз\n\nd8+1 Соседнему огнем\n\n+6 Попадание два\n\nd8+6 Колющий два\n\nd8+1 Соседнему огнем",167805,null],[174147,"2026-08-26T21:11:53",11,"// ну описывай как ящеры горят зелёным пламенем до тла:D",167805,null],[174148,"2026-08-26T21:11:56",17,"/ Итого 15 колющего основной цели и 18 огнем соседнему (хера себе)",167805,null],[174149,"2026-08-26T21:12:36",11,"// И конец боя👌",167805,null],[174150,"2026-08-26T21:13:25",53,"*сбросив оружие и видя что ящеркам уже не помочь молча молюсь о благополцчном путешествии их душ и иду лечить лягуха*",174149,null],[174152,"2026-08-26T21:13:59",53,"+4//",174151,null],[174153,"2026-08-26T21:14:13",53,"и + временные хиты в размере его костей хп если я все верно понял",167805,null],[174154,"2026-08-26T21:14:49",5,"Раны практически целиком затянулись.\n\n— Ох, да и ты правда целитель. Квеликий хорошо тебя научил. Спасибо!",167805,null],[174156,"2026-08-26T21:15:14",53,"//т.е если у него 4 лвл, то 4 временных хита",174153,null],[174158,"2026-08-26T21:15:37",11,"// набором лечишь? Вычитай их не забывай.",174150,null],[174159,"2026-08-26T21:15:43",17,"Пронзенный острым лезвием в глаз ящер падает на берег\n\nВолна захлёстывает кровь на сапоги всех кто рядом. Снова и снова\n\nВторой ящер обуглился в зелёном огне. Пламя выжгло его до черноты\n\n\"Иногда и зима бывает жаркой \"",167805,null],[174160,"2026-08-26T21:15:57",53,"*заканчивая мазать его раны мазью и затягивая бинты осматриваю состояние*\nтак будет лучше, но стоит какое то время отдохнуть.\n*беру алебарду и убираю на место*",174154,null],[174163,"2026-08-26T21:16:13",53,"//у нас есть еще раненые кроме меня?",167805,null],[174169,"2026-08-26T21:17:17",11,"Жара ли это была от сгорающих ящериц, аль от солнца, но всем кроме тритона который покупался в море спас от истощения\n\n// А лягуха соль печет так что тоже",167805,null],[174172,"2026-08-26T21:18:01",53,"*следом обмазываю и перевязываю свои раны выпив настойку из чегото источающего резкий запах похожий на запах сосновых иголок*",174163,null],[174174,"2026-08-26T21:18:15",53,"//ебать я лекарь",174173,null],[174183,"2026-08-26T21:20:02",53,"//помню. у меня сейчас три юза потрачены",174158,null],[174185,"2026-08-26T21:20:53",11,"// сл по чуть-чуть растет, тело все так же",174169,null],[174187,"2026-08-26T21:21:21",53,"*так же набираю флягуводы*",167805,null],[174188,"2026-08-26T21:21:23",5,"/r +4 тело",167805,null],[174190,"2026-08-26T21:21:38",11,"// как жаль что К'варсио в броне..",167805,null],[174195,"2026-08-26T21:22:06",11,"Жарковато, но он держится",167805,null],[174196,"2026-08-26T21:22:33",11,"// @dunchev @sweetkittywitch @lady_godzilla давайте спас тела все\u003c3",167805,null],[174198,"2026-08-26T21:23:00",53,"*после того как полуголый тритон обматався  бинтами на нем вновь выростает костюм дохтура*",174173,null],[174202,"2026-08-26T21:23:32",17,"/r +5 Спас Фауст",174196,null],[174205,"2026-08-26T21:23:49",41,"/r d20+2",167805,null],[174207,"2026-08-26T21:23:50",11,"// Фауста кубы любят прям",167805,null],[174208,"2026-08-26T21:24:20",11,"// такс ну и напоминаю что Фауст видел следы. А Цет набрал пять пайков добрейших водорослей, так что рпшьте:3",167805,null],[174220,"2026-08-26T21:28:41",53,"*оглядев лягуха вновь начинаю расспрашивать его о состоянии постепенно идя к телам трупов*\n\nнет ли мест где ткань давит сильно, аль мест где она сползает?",167805,null],[174232,"2026-08-26T21:29:43",41,"— Кажется, надо устроить привал …",167805,null],[174235,"2026-08-26T21:29:54",5,"— Не, доспех сидит хорошо. Только вот жарко очень в нём, квух...",174220,null],[174240,"2026-08-26T21:30:29",11,"Всем кроме Цета жарковато оставаться на пляжу",167805,null],[174244,"2026-08-26T21:30:34",17,"Фауст выдохнул и стряхнул кровь с клинка резким взмахом в сторону.\n\nПотом он пратер его ещё раз о внутреннюю сторону  согнутой в логте руки и убрал в ножны на поясе \n\n\"Они пришли из воды. Тут следы ведут и к воде и от воды. Похоже что они охотятся в море и возвращаются. Значит скоро найдем их логово. Пойдёмте за мной по следам, я вижу там тропу\"",167805,null],[174245,"2026-08-26T21:31:06",11,"// я видимо плохо описала что там человеческие следы были и следы вьючного животного",167805,null],[174250,"2026-08-26T21:31:33",17,"/ Я думал тираннозавра",167805,null],[174251,"2026-08-26T21:31:37",17,"/ Такой облооом",167805,null],[174252,"2026-08-26T21:31:42",17,"/ Я думал это динотопия",167805,null],[174253,"2026-08-26T21:31:48",17,"/ Люди приручили динозавнов",167805,null],[174255,"2026-08-26T21:32:01",5,"— Фауст, ты квабыл, тут есть ещё хищная птица. Большая.",174244,null],[174256,"2026-08-26T21:32:05",17,"/ Может не поздно ещё.. хоть одного ручного тирекса ...?",167805,null],[174257,"2026-08-26T21:32:06",11,"// всему свое время:3",167805,null],[174259,"2026-08-26T21:32:31",11,"// по 9 приручить?)",174256,null],[174261,"2026-08-26T21:32:58",53,"//я про бинты :D",174235,null],[174262,"2026-08-26T21:33:31",17,"\"Птица подождет. Я сейчас тут натурально растаю в лужицу, на этом палящем солнце, пойдёмте обратно в лесную тень*",167805,null],[174266,"2026-08-26T21:34:16",5,"— Бинты удобные, квасибо. Откуда ты знаешь, как их накладывать?",174261,null],[174269,"2026-08-26T21:34:29",5,"— Пойдём-пойдём поскорее!",174262,null],[174270,"2026-08-26T21:34:36",11,"Следы очень удобно ведут в лес",174262,null],[174273,"2026-08-26T21:35:10",53,"я есмь лекарь, нас обучали этому. и пусть я все еще набираюсь опыта, однако уже сейчас способен исправлять многие травмы.",174266,null],[174275,"2026-08-26T21:35:26",41,"— Голова кружится от жары, надо бы… в тень …",167805,null],[174277,"2026-08-26T21:35:43",17,"Перед уходом Фауст снова обнажает клинок и срезает наспинный гребень ящера\n\nОн использует его как веер опохало и обмахивает себя",167805,null],[174281,"2026-08-26T21:36:21",41,"( и в этот момент Фауст загорается",174277,null],[174282,"2026-08-26T21:36:30",27,"// Брутально",174277,null],[174283,"2026-08-26T21:36:39",11,"// ну если только с морского, остальных ты спалил..",174277,null],[174284,"2026-08-26T21:37:10",17,"/ Давайте больше пафоса",167805,null],[174285,"2026-08-26T21:37:58",17,"Заговором замораживая воду под ногами эладрин быстро бегал до ящера труп которого всплыл неподалеку от берега \n\nС него гребень был неповрежденый огнем",167805,null],[174286,"2026-08-26T21:38:19",41,"( Эльза",174285,null],[174290,"2026-08-26T21:39:01",11,"море абсолютно спокойно омывало замороженные участки воды и тебя тоже",167805,null],[174291,"2026-08-26T21:39:04",53,"нам необходимо отдохнуть после боя. \n*достав какую то маленькую скоянку подходу к фаусту и даю ее ему*\nэто ненадолго поможет от утери крови через нос и ослабит головные боли коли они есть.",167805,null],[174300,"2026-08-26T21:40:19",17,"\"Пригодится. Благодарю. Старайся держаться ближе ко мне. Я приму удар судьбы первым. А тебе оставлю обработать раны и залечить после победы. Договорились?\"",174291,null],[174312,"2026-08-26T21:42:16",5,"Грунг скачет дальше по пляжу, смотря в небо",167805,null],[174313,"2026-08-26T21:42:39",11,"// куда скачешь?",174312,null],[174316,"2026-08-26T21:43:00",5,"По следам",174270,null],[174323,"2026-08-26T21:45:23",53,"*киваю и выпив что то из похожей склянки оглядываю тела*\nдоговорились, вой.  мое дело врачевать. но так же я могу иногда просить великого ралеоить оружие мощью, коего ищначально это оружие не имеет. к сожалению в этом бою я слишком выматался и не смогу сделать так вновь пока нк передохну.\n\n*следом омываю тела трупов морской водой*\n\n\nда примет вас великий у вечного водопада. (глубинный)\n\n*после этого осматриваю тела на предмет сьедобности*\n\nдруже, не знаешь, можно ль таких есть?",174300,null],[174325,"2026-08-26T21:45:31",53,"(фаусту)",174323,null],[174330,"2026-08-26T21:46:28",11,"Следы хорошо видны и ты без труда отслеживаешь их, они ещё какое-то время ведут по пляжу, видно что человек то тут то там подходил к морю по какой-то причине, но возвращался и шел дальше, а затем и вовсе пошел назад. Его следы начались и закончились у лесной тропы",174316,null],[174333,"2026-08-26T21:47:39",5,"Забежал под дерево у следов и сидит-ждёт других",174330,null],[174335,"2026-08-26T21:47:55",17,"\"Если ты можешь усиливать оружее других, только скажи и я передам тебе свой клинок. Так мы быстрее могли бы заканчивать. Что касается мяса ящеров... Думаю да. Знаешь ради выживания в холодных пустошах я и не такое ел. Помню время когда пришлось варить свой кожаный ремень. Так что... Для меня любая еда деликатес.\"",174323,null],[174337,"2026-08-26T21:48:21",11,"В тени комфортнее",174333,null],[174339,"2026-08-26T21:48:36",22,"/r +3",174196,null],[174341,"2026-08-26T21:48:39",53,"некоторые существа полнятся токсинами, да хворью.",174335,null],[174343,"2026-08-26T21:49:09",17,"\"Ты прав. Нужно быть осторожнее. Но может термическая обработка поможет\"",174341,null],[174346,"2026-08-26T21:49:49",53,"*набрав еще одну флягу достаю топорик и промыв топорик начинаб разделку туши*\nне поможешь? я не слишком хорош в таком.",174343,null],[174347,"2026-08-26T21:49:59",22,"- Как же жарко!\n\nВоскликнула Венус. \n\n- Надеюсь тварей больше тут не осталось...\n\nСказала флорен и немного поплескалась на пляже, пытаясь охладиться. Потом она рванула в сторону джунглей, в попытках спрятаться в тенечке.",167805,null],[174348,"2026-08-26T21:50:02",17,"Фауст полил тебе волосы из фгляги водой и щёлкнул пальцами щепнув заговор. чтобы заморозить ее \n\nС такими обледеневшими волосами он шел дальше",167805,null],[174349,"2026-08-26T21:50:37",17,"\"Помогу конечно. Дай мне топорик, у тебя их кажется много\"",174346,null],[174350,"2026-08-26T21:50:46",53,"*даю топорик*",174349,null],[174351,"2026-08-26T21:50:47",17,"Фауст дождавшись топорика помогает разделывать ящера",167805,null],[174352,"2026-08-26T21:50:57",11,"// ты солёную воду набираешь?",174346,null],[174353,"2026-08-26T21:51:05",53,"//да.",174352,null],[174355,"2026-08-26T21:51:36",53,"//можно попытатся выпарить соль чтоб еду посолить, можно ей помытся и хладится, лишней не будет",167805,null],[174356,"2026-08-26T21:51:37",11,"Солнце всё так же жарит, работа вам даётся с трудом\n\n// Давайте выживание",167805,null],[174357,"2026-08-26T21:51:41",17,"\"Соленая вода убьет тебя цветочек. Не рискуй\"",174347,null],[174358,"2026-08-26T21:51:45",22,"Фокусом \"искусство друидов\" Венус кастует легкий бриз",167805,null],[174360,"2026-08-26T21:51:56",11,"// будет, не зря люди после моря моются в душах",174355,null],[174361,"2026-08-26T21:52:02",17,"/r +1 Выживание",167805,null],[174363,"2026-08-26T21:52:27",53,"+0//",174359,null],[174365,"2026-08-26T21:52:35",22,"Потом она подберет палку и попытается сделать из нее зонтик - чтобы раскрылись крупные листья",167805,null],[174367,"2026-08-26T21:52:58",11,"Экспертами в ящерицах ребята не были, как и мясниками, но адекватно выглядящих пару кусков мяса на два пайка у них вырезать удалось",167805,null],[174370,"2026-08-26T21:53:11",11,"// отличная идея",174365,null],[174372,"2026-08-26T21:53:24",53,"//я морепродукт, мне лишней не будет",174360,null],[174377,"2026-08-26T21:54:14",11,"// если совсем голодны будете готовьте его. Сразу соленый, на вкус как рыба",167805,null],[174380,"2026-08-26T21:54:45",17,"/ Лобстер",167805,null],[174386,"2026-08-26T21:55:20",53,"//аксолотлик в картонном панцыре :D",174380,null],[174394,"2026-08-26T21:56:20",41,"Освальд рассмотрел добытую еду и засолил её + засушил чтоб дольше хранилась в такой погоде",167805,null],[174395,"2026-08-26T21:56:27",22,"//еще венус нарежет себе мяса с рапторов, вместо пайков (всеядность)",167805,null],[174398,"2026-08-26T21:57:14",17,"\"Ты будешь есть эти ошметки и потроха Венус? Ты что всеядная?\"",167805,null],[174399,"2026-08-26T21:57:56",53,"и того у нас есть мясо...? рыба?.... ни рыба, ни мясо и рыбомясо.",167805,null],[174400,"2026-08-26T21:58:04",22,"- Вкусьно!",174398,null],[174401,"2026-08-26T21:58:21",11,"Все набирают себе пайки, но жарятся на солнышке, Венус чувствует себя чуть получше в тени собственного зонтика\n\nТем временем сидящий у пальмы К'варсио наблюдает за небом, там летают только относительно небольшие птицезавры, ему надоедает это дело и он смотрит в лес. Тут его внимание привлекает что заросли какие-то.. ссохшиеся как Венус от жары",167805,null],[174406,"2026-08-26T21:59:06",17,"\"Воу ты меня удивляешь, я думал тебе достаточно пресной водички и солнышка.\"",174400,null],[174408,"2026-08-26T21:59:40",11,"// при желании К'варсио может бросить анализ",167805,null],[174424,"2026-08-26T22:01:59",53,"//и тут я задумался, а можно ли из нее сварить лекарство?",174406,null],[174441,"2026-08-26T22:07:33",17,"Фауст создал ледяного клона и пустил его перед собой в паре тройке шагов, чтобы он разведывал тропу по которой все идут",167805,null],[174451,"2026-08-26T22:09:30",11,"// ну дальше чем на 60ф от тебя он не уйдет, да и 7 лвл нужен вроде что бы его глазами смотреть",167805,null],[174452,"2026-08-26T22:09:49",5,"/r -1 обдумал страннность",167805,null],[174460,"2026-08-26T22:10:56",11,"К'варсио понимает что хотя день близится к вечеру жара все не спадает и это как-то связано с усыхающей растительностью. Отдохнуть тут нормально не получится пока не разобраться с причиной",174453,null],[174462,"2026-08-26T22:11:38",5,"— Жара не зависит от времени суток? Странно! Ква!",174460,null],[174471,"2026-08-26T22:13:30",53,"//а какая по температуре вода в море?",174460,null],[174473,"2026-08-26T22:13:55",5,"Грунг решает предпринять что-то против жары. Он снимает свой доспех, кладёт в рюкзак. А сам достаёт свиток и произносит слова на нём.\n\n// могу доспех мага применить?",167805,null],[174474,"2026-08-26T22:14:12",53,"//ну ловить выстрелы лицом это ему не помешает :3",174451,null],[174475,"2026-08-26T22:14:15",11,"// ну если тебе есть с чем сравнить, то теплее чем обычно",174471,null],[174476,"2026-08-26T22:14:44",11,"// там надо бросать что бы кастануть успешно 11сл, а что за бросок я не помню..",174473,null],[174477,"2026-08-26T22:15:20",5,"/ магию?",167805,null],[174478,"2026-08-26T22:16:13",5,"/r +1",167805,null],[174480,"2026-08-26T22:16:32",11,"Свиток без эффекта превращается в прах в твоих лапках",167805,null],[174481,"2026-08-26T22:16:57",5,"— Ну вот!\n\nЛягушонок расстроился и опять надел доспех",167805,null],[174482,"2026-08-26T22:17:28",11,"Эхо идёт вперёд, но ничего не происходит\n\n// Продолжаете идти по следам?",167805,null],[174499,"2026-08-26T22:28:58",11,"// давайте продвигаться, ребятки🥺",167805,null],[174500,"2026-08-26T22:29:37",53,"*следуя за эхом поролжаю оглядывать травку на предмет полезных*",174482,null],[174501,"2026-08-26T22:30:18",11,"Все полезное иссохло, только деревья ещё кое-как держаться",167805,null],[174503,"2026-08-26T22:32:34",5,"Идёт тоже",167805,null],[174505,"2026-08-26T22:33:20",11,"// отдых я вам пока не дам в любом случае, так что что бы не затягивать этот игровой день ещё на пару ирл деньков..",167805,null],[174510,"2026-08-26T22:34:45",17,"/ Да. И там 30 ограничение",174451,null],[174511,"2026-08-26T22:34:48",11,"Вы идете вперёд пока не выходите к.. оазису? Пальмы и другие деревья растут вокруг, но травы меньше чем положено в джунглях и вместо земли песок что идёт волнами и много много следов лап.. след по которому шли вы потерялся здесь. Совсем недалеко от вас небольшое озеро и труп крупного травоядного динозавра",167805,null],[174512,"2026-08-26T22:35:06",11,"// 30ф не исчезает, на 60 можешь передвинуть, но исчезнет да знаю, люблю эхо тоже",174510,null],[174515,"2026-08-26T22:37:20",11,"В моменте клон исчезает, а перед вами стоит ящер подобный тому что вы видели, но сильно крупнее.. а ещё его чешуйки и кожа алые",167805,null],[174516,"2026-08-26T22:37:34",11,"//ну и тут снова иня",167805,null],[174517,"2026-08-26T22:37:59",5,"/r +2",167805,null],[174519,"2026-08-26T22:38:15",17,"Фауст показывает знак согнутая в локте рука и \"ладонь сжалась в кулак\"\n\n\"Свежий труп травоядного, значит хищник рядом или падальщики\"\n\nФауст обнажил меч",174511,null],[174520,"2026-08-26T22:38:23",17,"Внимательно ищет угрозы",167805,null],[174521,"2026-08-26T22:38:29",17,"/r +3 Ищем",167805,null],[174523,"2026-08-26T22:39:00",17,"/r +4 Инициатива",174515,null],[174526,"2026-08-26T22:39:09",17,"/ Не заметил разу что вылез ящур алый",167805,null],[174529,"2026-08-26T22:41:01",41,"( отошла на секунду снова ящеры аааа",167805,null],[174530,"2026-08-26T22:41:36",27,"// Половина Бестиария подтипа \"зверей\", это различные динозавры",174529,null],[174531,"2026-08-26T22:41:52",22,"//меня правда уже напрягает токсичность в сторону моей расы. Давай завязывать",174424,null],[174532,"2026-08-26T22:42:03",53,"//оке",174531,null],[174533,"2026-08-26T22:42:22",53,"//просто реально интересно стало",174532,null],[174534,"2026-08-26T22:43:17",17,"/ Да я как то пытался просто нащупать тему чтоб поролить. Ладно надо копать глубже в характер перса а не во внешние признаки\n\nНо нужен хотябы привал чтоль, чтобы пообщаться",174531,null],[174535,"2026-08-26T22:43:40",22,"// я могу понять один выпад в мою сторону, два. Но фразы про ходячий труп и сварить из неё лекарство- меня уже правда напрягают. Не заставляй меня включать токсичную суку, тебе не понравится, поверь",167805,null],[174536,"2026-08-26T22:43:48",11,"// ну вы во время простоя слабо болтаете, будет вам привал, только общайтесь)",174534,null],[174538,"2026-08-26T22:43:55",22,"/r +2 инициатива",167805,null],[174541,"2026-08-26T22:45:22",22,"Венус лениво осматривалась, но зонтик вырос очень крупный и листья сильно загораживали ей обзор.",167805,null],[174542,"2026-08-26T22:47:00",17,"/ Мастер а клон исчез потому что был разорван внезапно?",174515,null],[174544,"2026-08-26T22:47:37",11,"Иня:\nАризонозавр мутант - 17\nК'варсио 11\nОсвальд - 9\nФауст 8\nВенус 4\nЦет 2\nАризонозавр 1 - 1",167805,null],[174545,"2026-08-26T22:47:46",11,"// скоро узнаешь:3",174542,null],[174548,"2026-08-26T22:48:14",41,"/r d20-1 Бедный Освальд(",167805,null],[174553,"2026-08-26T22:49:34",11,"// кто стоит спереди?",167805,null],[174555,"2026-08-26T22:51:23",17,"/ Я",167805,null],[174556,"2026-08-26T22:52:37",11,"**Группа чувствует как жар накаляется, все кроме Фауста получают 1к6 урона огнем. Фауст к которому бросается ящер 2д6. Без спасов**",167805,null],[174558,"2026-08-26T22:54:28",11,"Ящер в высоту с Фирболга, а весом явно больше движется в сторону эладрина пытаясь поймать его в пасть, но слишком неуклюж из-за размера видимо",167805,null],[174560,"2026-08-26T22:56:09",17,"/ Фауст хиты 32/38",167805,null],[174561,"2026-08-26T22:56:22",5,"/r 1d6",167805,null],[174564,"2026-08-26T22:56:42",11,"// вы урон себе сами кидайте, я кинула на попадание по тебе, очевидно промахнулась) но ты в мили с ним, пока только ты",167805,null],[174565,"2026-08-26T22:57:08",53,"//7 хп осталось",174563,null],[174568,"2026-08-26T22:57:48",17,"/r 2d6 fire",167805,null],[174570,"2026-08-26T22:58:01",17,"/ как чувствовал что 6",167805,null],[174571,"2026-08-26T22:58:43",11,"Такс",167805,null],[174575,"2026-08-26T22:59:55",11,"Внимательная друидка чувствует ещё одну знакомую ящерицу сзади \n\n// Ход К'варсио",167805,null],[174579,"2026-08-26T23:02:14",5,"— Как же печёт! Не хочу к нему подходить!\n\nГрунг достал весьма массивное копьё двумя лапами и кинул в завра",167805,null],[174580,"2026-08-26T23:02:17",5,"/r +5",167805,null],[174582,"2026-08-26T23:04:08",11,"Везение ли, но копьё прилетает в лапу ящеру\n\n// Урон",167805,null],[174585,"2026-08-26T23:06:59",5,"/ cпас тела 12",167805,null],[174586,"2026-08-26T23:07:14",5,"/r d12+3+d4",167805,null],[174589,"2026-08-26T23:07:49",5,"Лапки грунга потянутся к копью, оно само вырвется из раны и вернётся в руки.",167805,null],[174591,"2026-08-26T23:11:35",11,"// не было описания что оно в яде",174579,null],[174592,"2026-08-26T23:11:45",5,"// тогда ход",167805,null],[174593,"2026-08-26T23:12:46",11,"// ход @sweetkittywitch карта вот\nНе забудь кинуть д6 на урон себе",174571,null],[174600,"2026-08-26T23:16:23",41,"( спасибо, сек доубераю и подумаю",167805,null],[174698,"2026-08-27T14:06:29",41,"/r d6",167805,null],[174701,"2026-08-27T14:06:37",41,"( ауч",167805,null],[174709,"2026-08-27T14:09:22",41,"Освальд пытается сбить ящера с ног своим посохом",167805,null],[174712,"2026-08-27T14:09:29",41,"/r d20",167805,null],[174714,"2026-08-27T14:09:41",41,"— извините!",167805,null],[174770,"2026-08-27T14:37:39",17,"Фауст создаёт ледяного клона рядом с ящером который зашел в тыл, подальше от этого огненно алого монстра\n\nВыхватив клинок он рубит воздух, но удар проходит рядом с клоном, а после сфокусировавшись он представляет как когти клона рвут брюхо ящеру и клон незамедлительно воплощает желание в жизнь",167805,null],[174771,"2026-08-27T14:38:06",17,"/ Бонусным поставил эхо, подвинул к тому что сзади. Атака + Атака от Высвобождения потенциала",167805,null],[174772,"2026-08-27T14:38:27",17,"/r +6 q1\n\nd8+6 q1\n\n+6 q2\n\nd8+6 q2",167805,null],[174774,"2026-08-27T14:38:49",17,"/ Трачу везунчика на переброс первой",167805,null],[174775,"2026-08-27T14:38:51",17,"/r +6",167805,null],[174778,"2026-08-27T14:38:58",17,"/Конец хода",167805,null],[174779,"2026-08-27T14:39:15",17,"/ @lady_godzilla Твой ход, жги",167805,null],[174780,"2026-08-27T14:39:57",17,"\"Отойдите от него дальше! Я попробую сдержать этот его жар!\"",167805,null],[174790,"2026-08-27T14:56:41",22,"Венус рычит. Она превращается в медведя и нападает на самого раненного.\n\nХП 26/34\nКБ 11\nМультиатака. Две атаки: одну укусом, и одну когтями.\nУкус. +6, . Попадание: Кол урон 8 (1к8 + 4).\nКогти. +6, Попадание: Руб урон 11 (2к6 + 4).",167805,null],[174791,"2026-08-27T14:58:29",22,"/r +6 укус\n/r d8+4\n/r +6 царап\n/r 2d6+4",167805,null],[174793,"2026-08-27T14:58:36",22,"/ход",167805,null],[174798,"2026-08-27T15:09:27",41,"( Белка отжигает",167805,null],[174812,"2026-08-27T15:20:41",11,"// попал, но подошёл на 5 футов к нему да? Если да то ещё д6 урона..😅",174713,null],[174822,"2026-08-27T15:22:38",11,"Любой кто приближается к красным аризонозаврам на расстояние в пять футов ощущает жар ещё сильнее\n\n//Урон наносится в ваш ход, а не после него, так что клон автоматом отлетает",167805,null],[174827,"2026-08-27T15:23:29",41,"/r d6 ауч",174812,null],[174829,"2026-08-27T15:23:39",41,"( 10 хп у деда",167805,null],[174833,"2026-08-27T15:24:17",11,"Фирболг на морально волевых подходит и заносит посох, но падает без сил",167805,null],[174844,"2026-08-27T15:26:31",11,"Воин растерявшись от исчезновения клона не попадает по ящеру, одна из атак мишки попадает, но сам он так же страдает от жара\n\n//Тоже 2д6 кинь урона себе",174793,null],[174845,"2026-08-27T15:26:44",11,"// ход Сергей",167805,null],[174847,"2026-08-27T15:27:52",22,"/r 2d6",174844,null],[174850,"2026-08-27T15:31:51",11,"Все кроме Цета и К'варсио стоят вокруг крупного красного аризонозавра излучающего жар, от которого Фирболг уже потерял сознание",167805,null],[174853,"2026-08-27T15:33:09",5,"/ у завра с тылу никого нет?",174850,null],[174855,"2026-08-27T15:33:47",11,"// ну брось анализ свободным\nЧисто как следопыт",167805,null],[174856,"2026-08-27T15:33:57",5,"/r -1",167805,null],[174861,"2026-08-27T15:35:29",11,"К'варсио думает что следов там достаточно.. кто знает что там ещё ждёт, но от мыслей про следы его отрывает тень за мертвым травоядным: «Она только что двинулась?» — думает он",167805,null],[174925,"2026-08-27T17:17:10",17,"/ Позади тоже чтоле горячий?",174822,null],[174926,"2026-08-27T17:17:16",53,"*видя падение фирболга срываюсь к нему и залив ему в рот странную настойку, а следом проведя перед его носом пахучей травой чтоб проснулся и поливаю нас из вляги дабы охладится*\nосвальд, сможешь устоять на ногах? \n*слегка придерживаю его помогая поднятся и скрываясь за спину ближайшего товарища*",174833,null],[174927,"2026-08-27T17:17:29",17,"/ ну тогда мой ход получается был невозможен. Что делать? Или урон в конце хода?",167805,null],[174938,"2026-08-27T17:21:57",11,"// почему невозможен? Ты призвал клона, он исчез, своей атакой ты не попал",174927,null],[174939,"2026-08-27T17:22:55",17,"/ Я бил через клона.",174938,null],[174940,"2026-08-27T17:23:13",17,"/ Ну думаю не будем душиться. Скажи как было и так и было.",167805,null],[174941,"2026-08-27T17:23:53",17,"/ клон значит сразу пропал, я подбежал и ударил дальнего, не пробил 14 ну и стою получается у дальнего. Можно по мне провоцирку",167805,null],[174943,"2026-08-27T17:25:53",53,"//у фирболга исцеляется 8 хитов и дается временное равное максимальному количеству его костей хитов",174942,null],[174944,"2026-08-27T17:26:38",53,"//конец хода",167805,null],[174945,"2026-08-27T17:31:27",11,"// Если есть претензии пиши в флуд поговорим",174940,null],[174946,"2026-08-27T17:31:44",17,"/ нету",174945,null],[174947,"2026-08-27T17:38:10",41,"Освальд, измученный жарой приходит в себя \n\n— спасибо, добрый рыцарь...\n\n( 18 хп(?)",167805,null],[174949,"2026-08-27T17:41:13",53,"//не, 8 хп и временные хиты равные максимальному количеству костей хитов того кого лечат (у меня эт 2 :D)",174947,null],[174950,"2026-08-27T17:41:48",41,"( я просто легла с 10 хп",167805,null],[174951,"2026-08-27T17:42:08",41,"( решила, что нарратив",167805,null],[174952,"2026-08-27T17:42:33",53,"//аа",174950,null],[174953,"2026-08-27T17:42:49",53,"//ну тогда да, 18 выходит",174950,null],[174955,"2026-08-27T17:44:20",53,"//у тебя вроде тоже",174949,null],[174956,"2026-08-27T17:44:36",53,"//так что отремонтировав в целое состоянье почти ^^",167805,null],[174958,"2026-08-27T17:51:25",11,"// А, значит ты дальнего бил, извини запуталась. По дальнему Фауст попадает да, тогда бросай урон",174941,null],[174961,"2026-08-27T17:52:46",17,"/ Да ничего. Я сам запутался. Хотел да, именно к дальнему вызвать клона и бить его чтобы мелкого сперва убить",174958,null],[174965,"2026-08-27T17:53:42",17,"/ Тут первая атака 14 после переброса, там чуть ниже везунчиков перебрасывал. Вторая 21\n\nУрон первой атаки 12\n\nУрон второй был 13",174772,null],[174966,"2026-08-27T17:53:43",11,"// ну в общем да если хочешь можешь его бить, попадешь, но провоцированную получишь\n\nВторая атака от клона. Он атаковать не будет так как банально получает урон на спавне",167805,null],[174969,"2026-08-27T17:54:43",17,"/ Хорошо одна атака и я получаю провокацию да теперь понял",167805,null],[174976,"2026-08-27T17:55:23",11,"// промахиваюсь, спокойно отходишь к другому, урон учла 👍",167805,null],[174979,"2026-08-27T17:56:34",11,"Второй ящер атакует цель что подошла к нему",167805,null],[174983,"2026-08-27T17:57:16",11,"// И снова ход @elsio28 карту щас обновлю",167805,null],[174985,"2026-08-27T17:59:24",5,"— Отойдите от них, звери жгутся!\n\nГрунг трёт остриё длинного копья о свою кожу и выбирает цель",167805,null],[174991,"2026-08-27T18:03:24",5,"/r +5 кидает в первого ящера от которого все ушли",167805,null],[174993,"2026-08-27T18:03:33",17,"/ Фауст 22/38",167805,null],[174995,"2026-08-27T18:04:46",5,"/ спас тела 12 и",167805,null],[174996,"2026-08-27T18:04:55",5,"/r 2d12+2d4+3",167805,null],[174998,"2026-08-27T18:06:09",11,"// пупупу запутанно выходит, но в общем Фауст у жёлтого ящера, мишка там же так как выбрала более раненого. Освальд у алого, а Цет возле него\n\nСамка — это вы можете определить по тому что ее гребень не имеет окраса, выглядит ослабшей. Крупный самец выглядит так будто получил только пару царапин. Они оба источают жар и вы прекрасно понимаете что именно они повлияли на местность",167805,null],[175006,"2026-08-27T18:08:17",5,"Грунг идёт на клетку вверх, а копьё само возвращается в его лапки",174998,null],[175008,"2026-08-27T18:08:25",11,"**Копьё попадает ящеру прямо в глаз и он рычит. Игнорируя Цета и Освальда ящер ползет прямо к лягушке \n\n// Эл, в начале хода д6 урона себе не забывай",167805,null],[175012,"2026-08-27T18:08:36",5,"/r d6",167805,null],[175015,"2026-08-27T18:08:52",5,"/ ход",167805,null],[175016,"2026-08-27T18:08:55",11,"// @sweetkittywitch провоцированную кинь",167805,null],[175017,"2026-08-27T18:09:10",17,"Эладрин получает рваную рану на груди от размашистого удара когтистой лапой самки\n\n\"Черт, становится действительно адски жарковато\"",167805,null],[175018,"2026-08-27T18:09:28",5,".",174995,null],[175021,"2026-08-27T18:09:49",11,"// а кстати спас силы, это укус и тебя пытаются взять в пасть",175017,null],[175025,"2026-08-27T18:10:19",17,"/r -1 Спас",175021,null],[175031,"2026-08-27T18:10:34",5,"Яд с острия попал в глаз, но тот моргнул и отрава быстро испарилась",167805,null],[175035,"2026-08-27T18:11:37",11,"Пасть самки крепче сжимается на теле эладрина",167805,null],[175036,"2026-08-27T18:12:02",11,"// жаром сдуло хд",175031,null],[175038,"2026-08-27T18:12:20",41,"/r d20",175016,null],[175040,"2026-08-27T18:12:29",41,"( ноуп",167805,null],[175041,"2026-08-27T18:12:46",11,"Ящер движется к К'варсио, Освальд пытается среагировать, но не попадает, впрочем как и ящерица, ведь ловкая лягушка подпрыгнула прямо перед укусом",167805,null],[175042,"2026-08-27T18:13:05",11,"// Ход Освальда как раз. Д6 урона так как ты больше не в пяти футах от него",167805,null],[175043,"2026-08-27T18:13:07",5,"/ ого, это он реакцией приполз кусать",167805,null],[175044,"2026-08-27T18:13:15",11,"// ого это его ход был:3",175043,null],[175045,"2026-08-27T18:13:36",41,"/r d6",167805,null],[175047,"2026-08-27T18:13:44",41,"( ща подумаю",167805,null],[175048,"2026-08-27T18:13:52",41,"( боевка у меня так себе",167805,null],[175049,"2026-08-27T18:13:55",17,"/Хиты 18/38 Фауст",167805,null],[175050,"2026-08-27T18:14:50",11,"// говорить с союзниками - бесплатно, можешь посоветоваться",175048,null],[175057,"2026-08-27T18:17:01",41,"Освальд стал невидимым и попытался подойти к ближайшему дереву чтоб одним ударом срубить его в нужном направлении на ящера сверху",167805,null],[175058,"2026-08-27T18:17:16",41,"( срубить тоже полным действием, полагаю",167805,null],[175059,"2026-08-27T18:17:24",41,"( если да, то ход",167805,null],[175060,"2026-08-27T18:18:17",11,"// интересно, давай на попадание",167805,null],[175061,"2026-08-27T18:18:32",41,"/r d20",167805,null],[175063,"2026-08-27T18:18:42",41,"( ладно, оно стоит",167805,null],[175065,"2026-08-27T18:18:53",11,"// ну это дерево, так что давай урон",167805,null],[175066,"2026-08-27T18:19:02",41,"/r d6",167805,null],[175068,"2026-08-27T18:19:34",11,"Твое оружие врезалось в пальму, но этого недостаточно что бы она упала",167805,null],[175069,"2026-08-27T18:19:56",11,"// сейчас карту поправлю чтоб не путаться",167805,null],[175070,"2026-08-27T18:20:15",41,"— уф! Старость не радость",167805,null],[175071,"2026-08-27T18:23:32",53,"//невидимость еще на тебе?",175070,null],[175072,"2026-08-27T18:23:48",41,"( думаю нет. Но тут на волю мастера",167805,null],[175074,"2026-08-27T18:26:52",11,"//такс",167805,null],[175076,"2026-08-27T18:26:54",17,"Эладрин взорвался снегом в пасти этого ящера и очутился на спине, перехватив клинок лезвием вниз он нанёс колющий удар в область шеи\n\n/Фейский шаг зимы, спас мудрости СЛ 10",167805,null],[175078,"2026-08-27T18:26:56",53,"*услвшав как товарищ рубит пальму, владыка 7 топоров оборачивается на звук и поняв идею(ибо сам об этом вчера задумывался :D) показывает топорики свисающие под плащом*\n\nколи я могу чем то помояь в этом плане, то хотел бы принять в нем участие. (слегка сбавив голос на всяки случай)",175072,null],[175082,"2026-08-27T18:27:16",17,"/r +6 На попадание\n\nd8+6 На урон колющий",167805,null],[175086,"2026-08-27T18:27:45",11,"// прошел",167805,null],[175089,"2026-08-27T18:28:01",17,"/Нет испуга",167805,null],[175091,"2026-08-27T18:28:27",11,"// 2д6 урона не забывай",167805,null],[175093,"2026-08-27T18:29:36",11,"Злая самка выглядит побитой, но всё ещё стоит на лапах",167805,null],[175096,"2026-08-27T18:30:27",17,"/r 2d6 fire",167805,null],[175098,"2026-08-27T18:30:57",17,"/ 13/38 Фауст. Как остальные живы?",167805,null],[175099,"2026-08-27T18:31:26",11,"// и ход @lady_godzilla сразу брось 2д6 урона огнем себе",167805,null],[175100,"2026-08-27T18:31:48",5,"К'Варсио сидит красный. Не от крови. От жары. Или может потому что он всегда красный.",167805,null],[175156,"2026-08-27T18:54:49",11,"// Ну и сразу для Полины ввод в курс дела, вот актуальная карта \n(Ну кроме Эли, она не уточняла, так что я всё же лучше ее к нижним пальмам перемещу, так как добрый Фирболг увидит что самку уже двое бьют, а К'варсио помощь не помешает) \nНу и не забудь 2д6 урона в начале хода \n\nОба ящера выглядят ранеными, но всё ещё стоят на лапах. А где-то в кустах кряхтит Освальд и доносится стук по дереву",175074,null],[175180,"2026-08-27T19:05:51",22,"/r 2d6",175099,null],[175183,"2026-08-27T19:07:38",22,"Медведь рычит, стараясь привлечь к себе побольше внимания.\n\nИ бьет ближайшего\n\nХп 18/36",167805,null],[175184,"2026-08-27T19:07:40",22,"/r +6 укус\n/r d8+4\n/r +6 царап\n/r 2d6+4",167805,null],[175186,"2026-08-27T19:10:04",11,"Мишка сильный, но не такой меткий, впрочем динозавр тоже не самый ловкий и крепкий так что первая атака когтями попадает. Самка пошатывается, но ещё стоит на лапах",175185,null],[175187,"2026-08-27T19:10:11",11,"//конец хода?",167805,null],[175191,"2026-08-27T19:13:03",11,"// ну полагаю что так, Сергей теперь ты",167805,null],[175193,"2026-08-27T19:13:40",41,"( добей пальму!",167805,null],[175194,"2026-08-27T19:13:56",41,"( ураааа",167805,null],[175220,"2026-08-27T19:23:25",53,"*сорвав секиру изза спины начинаю бежать к пальме и с разбегу наношу удар и подталкиваю пальму в нужную сторону телом*\n\nи... давим.",175191,null],[175224,"2026-08-27T19:24:05",53,"//+1",175223,null],[175226,"2026-08-27T19:24:31",41,"( ы",167805,null],[175227,"2026-08-27T19:24:40",41,"( Кинь преймущество",167805,null],[175228,"2026-08-27T19:24:51",5,"/ делай мультиатаку топором за каждую конечность",175220,null],[175231,"2026-08-27T19:25:56",11,"Совместными усилиями Цет и Освальд рубят пальму. Она понемногу поддается и.. падает прямо на..",167805,null],[175237,"2026-08-27T19:26:40",11,"Ящера который в последний момент замечает это",167805,null],[175239,"2026-08-27T19:26:52",11,"// Давай д10 урона, Серёг",167805,null],[175240,"2026-08-27T19:28:06",11,"Пальма прилетает гиганту на заднюю часть туловища закрепляя того на месте",167805,null],[175247,"2026-08-27T19:32:44",11,"А тем временем яростная самка провоцируется медведем",167805,null],[175256,"2026-08-27T19:35:13",11,"Острые зубы впиваются в кожу мишки, но схватить зверя в пасть ей не получается, она лишь дёргается из-за \"всадника\" и опускает, а затем подымает орошенный кровью гребень прямо под ним. Бонусным\n\nСидеть после такого Фаусту на ней трудно \n\n@dunchev спас ловкости что бы удержаться",167805,null],[175257,"2026-08-27T19:35:41",17,"/r +4 Держимся",167805,null],[175259,"2026-08-27T19:35:50",41,"( приручил",167805,null],[175263,"2026-08-27T19:36:53",11,"// примерно так это и выглядит \n\nСамка брыкается, но Фауст ловко держится на ней",175260,null],[175265,"2026-08-27T19:37:31",17,"/ Раз уж я на спине самки в ее слепой зоне, есть у меня от этого преимущество, мастер?",167805,null],[175267,"2026-08-27T19:37:36",11,"Самец сжатый пальмой делает выпад в сторону К'варсио который всё ещё рядом",167805,null],[175268,"2026-08-27T19:37:51",22,"/шляпу этому всаднику!",175263,null],[175272,"2026-08-27T19:38:56",11,"Большой алый, как сам К'варсио, ящер хватает его в пасть нанося 14 урона",167805,null],[175273,"2026-08-27T19:39:05",11,"// @elsio28 спас силы",167805,null],[175274,"2026-08-27T19:39:37",5,"/r +6",167805,null],[175277,"2026-08-27T19:40:22",11,"// опиши как из пасти выбрался и следом твой ход +2д6 урона огнем в начале",167805,null],[175278,"2026-08-27T19:41:16",11,"// кстати, Сергей ты тоже забыл про 1д6",167805,null],[175280,"2026-08-27T19:41:53",53,"1 хп осталось//",175279,null],[175281,"2026-08-27T19:42:29",53,"*начал пошатыватся от черезмерной жары*",167805,null],[175282,"2026-08-27T19:42:46",5,"Тонкий Квак! раздался, когда завр схватил маленького лягушонка в зубы. Он бессильно дёргался, но силы лапок не хватало. Через секунду яд с кожи грунга уже заполонил рот завтра и он ослабил хватку. К'варсио сделал рывок и внезапным прыжком вылетел изо рта монстра.",167805,null],[175283,"2026-08-27T19:43:08",5,"/r 2d6",167805,null],[175289,"2026-08-27T19:46:41",5,"Прыжок из пасти оказался очень длинным. В воздухе лягушонок сгруппировался, перехватил копьё (острие всё ещё в яде) и полетел прямо на спину самки.\n\n// Это нарративно\n\nМеханически кастую удар зефира чтобы уйти без  провоцированной, добираюсь до самки и атакую",167805,null],[175296,"2026-08-27T19:49:07",5,"/ Кидай тело 12 ему",175277,null],[175303,"2026-08-27T19:52:00",11,"// не прошел",175296,null],[175311,"2026-08-27T19:53:03",5,"/ отравлен, помеха на атаки",175303,null],[175313,"2026-08-27T19:53:42",5,"/r +d20+5 копьём по самке",167805,null],[175316,"2026-08-27T19:53:55",11,"// откуда преимущество?",167805,null],[175320,"2026-08-27T19:54:19",5,"/ удар зефира",167805,null],[175321,"2026-08-27T19:54:29",11,"// давай урон",167805,null],[175323,"2026-08-27T19:55:35",5,"/r d12+d8+d4+3",167805,null],[175325,"2026-08-27T19:56:06",5,"/ и спас тела если жив",167805,null],[175330,"2026-08-27T19:56:49",11,"Самка падает замертво от точного удара лягушки, а отравленный самец смотрит на вас с гневом и обидой, по его состоянию видно что ему самому не долго осталось, ещё и яд сказывается",167805,null],[175334,"2026-08-27T19:57:43",5,"К'варсио становится рядом с Фаустом",167805,null],[175336,"2026-08-27T19:57:49",5,"/ ход",167805,null],[175345,"2026-08-27T19:59:01",11,"А Фауст тем временем ощущает как тело под ним бездыханное падает на землю",167805,null],[175349,"2026-08-27T20:00:29",11,"// ну и ход Освальда.. \n\nМишке и эладрину становится полегче, остальные же все ещё ощущают жар",167805,null],[175353,"2026-08-27T20:02:29",41,"— слишком много боли... Прости нас, природа... \n\nВздыхая, Освальд подходит к прижатому ящеру и пробует нанести смертельный удар палкой через глаз",167805,null],[175354,"2026-08-27T20:02:34",41,"/r d20",167805,null],[175367,"2026-08-27T20:04:25",17,"Фауст спрыгивает в сторону и делает кувырок по траве когда слаженная самка валится на земь",175330,null],[175370,"2026-08-27T20:04:46",17,"\"Отличный удар, рыцарь\"",167805,null],[175372,"2026-08-27T20:05:21",17,"/ Если он ничком то с преимуществом вроде как",175353,null],[175375,"2026-08-27T20:05:34",11,"// мимо и 2д6 тебе😅",175353,null],[175377,"2026-08-27T20:06:01",41,"( не вышло",167805,null],[175378,"2026-08-27T20:06:11",41,"/r 2d6",167805,null],[175380,"2026-08-27T20:06:23",41,"( ура, 6 хп",167805,null],[175381,"2026-08-27T20:06:29",11,"// я не говорила что он ничком. Зависело от броска на внимательность который я кинула",175372,null],[175386,"2026-08-27T20:06:55",11,"// ну и твой, Коля, ход\nЕсли подходишь не забудь урон кинуть",167805,null],[175400,"2026-08-27T20:09:17",17,"Фауст проводит по серебряным нитям сшивающим рот слегка натягивая их и звеня как на струнах\n\nЭто его ритуал.\n\n\"Сжать зубы, притупить боль. Боль не управляет мной, боль не важна\"\n\nЭто придает ему духовного мужества и он бросается на оставшегося ящера\n\n/ второе дыхание воина бонусным побегаю и бью",167805,null],[175403,"2026-08-27T20:09:54",17,"/r d10+3 Лечение\n\n2d6 Урон огнем\n\n+6 Попадание\n\nd8+6 Колющий урон если попал",167805,null],[175415,"2026-08-27T20:12:34",11,"Ящер шипит от боли, алая кожа тускнеет, ему явно очень плохо",175403,null],[175416,"2026-08-27T20:12:51",11,"@lady_godzilla \n\n// Твой ход и тут уже происходит добейте выживших",167805,null],[175587,"2026-08-27T20:53:55",22,"Медведица отворачивается от павшей протвницы и бежит на самца.",167805,null],[175588,"2026-08-27T20:53:57",22,"/r +6 укус\n/r d8+4\n/r +6 царап\n/r 2d6+4",167805,null],[175590,"2026-08-27T20:54:22",22,"/урон жаром ещё будет?",167805,null],[175598,"2026-08-27T20:56:55",22,"/ход",167805,null],[175601,"2026-08-27T20:58:04",11,"// Да, последний раз когда подходишь и затем ты добиваешь его",175590,null],[175604,"2026-08-27T20:59:09",11,"Ящер перестает дышать, а вам всем становится легче дышать\n\n// Конец боя",167805,null],[175610,"2026-08-27T21:01:39",53,"*оглядываю товарищей и подхожу к фаусту*\n\nкак раны твои, вой?",175604,null],[175613,"2026-08-27T21:02:26",53,"*сам я заметно пошаиываюсь и тяжело дышу*",175610,null],[175617,"2026-08-27T21:02:55",5,"— Это было жарко! Ква!\n\nГрунг вытаскивает бурдюк и обливает себя прямо в доспехах",167805,null],[175620,"2026-08-27T21:03:57",17,"Вынимая клинок из туши ящера \n\nФауст опускает его и шумно выдыхает и выдыхает через нос\n\nЗнак крайней усталости\n\nОн делает манипуляции чтобы очистить клинок от крови и убирает оружее на пояс\n\n\"Было тяжело. Рад что вы такие умелые воины и волшебники, тут мой ледяной клон был бесполезен. Но видя, что вы горите решимостью ярче чем пламя этих монстров. Паника отступила\"",167805,null],[175624,"2026-08-27T21:05:13",17,"\"Ран много, выбирай любую.\"\n\nТкань с лица была опущена и видно Фауст улыбнулся кровь потекла по разрезанной нитью губе",175610,null],[175677,"2026-08-27T21:19:45",11,"Совсем рядом манящее озеро",175617,null],[175681,"2026-08-27T21:20:09",5,"Лягушонок заскакивает туда и плещется",175677,null],[175683,"2026-08-27T21:20:51",11,"Пробегая мимо трупа травоядного ты слышишь кряхтение и замечаешь руку что тянется к тебе",175681,null],[175684,"2026-08-27T21:21:23",5,"*быстрый прыжок в высоту*",175683,null],[175685,"2026-08-27T21:21:28",53,"*не прекращая шататся обрабатываю раны и бинтую наиболее серьезные, а в местах где этого мало даже подшиваю, а в конце наношу охлаждающую мазь*\nтеперь должно стать легче..\n*после этого вы все видите как тритон заваливается на спину и лежит повернув голову в сторону медведя, держа в руке набор целителя*",175624,null],[175688,"2026-08-27T21:22:50",53,"//вот столько захилял фаусту, +временное хп по максимальному количеству костей хитов",175686,null],[175689,"2026-08-27T21:23:13",53,"//медведь выглядит раненым или поджаренным?",175685,null],[175690,"2026-08-27T21:23:43",5,"Грунг выглядит раненным и поджаренным",167805,null],[175691,"2026-08-27T21:23:51",11,"// просто прыгаешь в воду?",175684,null],[175692,"2026-08-27T21:24:20",5,"/да\n\nПотом грунг сразу выплывает и смотри в сторону руки",175691,null],[175698,"2026-08-27T21:26:39",11,"// какой же жестокий К'варсио",167805,null],[175699,"2026-08-27T21:26:41",11,"// хм..",167805,null],[175700,"2026-08-27T21:26:49",41,"Освальд даёт печеньку",175690,null],[175703,"2026-08-27T21:27:03",41,"( не дает",167805,null],[175704,"2026-08-27T21:27:09",41,"( кажется",167805,null],[175708,"2026-08-27T21:28:02",11,"Пока К'варсио купался, а остальные даже не видели. Лежащий у тела своего вьючного динозавра гуманоид продолжал истекать кровью",167805,null],[175711,"2026-08-27T21:28:43",11,"Закончив с банными процедурами К'варсио выглядывает на берег и видит что рука тянувшаяся за помощью больше не шевелится",167805,null],[175714,"2026-08-27T21:29:17",5,"/ я же написал, что прыгнул в воду, чтобы посмотреть на руку безопасно, а не чтобы купаться",167805,null],[175724,"2026-08-27T21:32:20",17,"Фауст подходит к озеру и вглядывается в водную гладь\n\nОн садится на корточки и касается воды пальцами",167805,null],[175732,"2026-08-27T21:35:19",11,"Прохладная, приятная вода. Прозрачная, но дна не видно. Похоже что ящеры облюбовали это место именно поэтому",175724,null],[175733,"2026-08-27T21:35:47",11,"// что есть то есть, реагируй",175714,null],[175734,"2026-08-27T21:36:20",5,"— У того тела чья-то рука была",175733,null],[175735,"2026-08-27T21:36:41",17,"\"Только рука?\"",167805,null],[175736,"2026-08-27T21:37:08",5,"— Не увидел больше ничего",167805,null],[175737,"2026-08-27T21:37:52",17,"Эладрин решает проверить\n\nПодойдя к телу травоядного как выглядит гуманоид? Он придавлен или рядом просто?",167805,null],[175739,"2026-08-27T21:38:25",11,"// врёт и не краснеет, а он уже красный:D",175736,null],[175740,"2026-08-27T21:38:40",5,"/ не врёт",175739,null],[175742,"2026-08-27T21:39:14",11,"// ты мимо проходил, видел все прекрасно",167805,null],[175743,"2026-08-27T21:39:22",5,"/ только руку",167805,null],[175747,"2026-08-27T21:46:44",11,"Массивное тело четырехлапого ящера с трубкой на лбу завалилось на бок у самой кромки воды. На нем видны следы от атаки ящеров, а так же рыболовные снасти. Полакомиться им ещё не успели, похоже помешали вы.\n\nПод тяжелым бедром динозавра лежит фигура  темнокожего гуманоида с такими же острыми ушами как у тебя. Многотонная туша ящера прижала его к песчаной косе. Тёмно-древесная рука бессильно вытянута в сторону К'варсио. Его простая одежда из переплетенных зеленых листьев испачкана мокрым песком.",175737,null],[175759,"2026-08-27T21:52:31",53,"*наконец отдышавшись тяжело поднимаюсь и иду тоже глчнуть на то что лежит у воды опираясь на любые возможные опоры*",175747,null],[175760,"2026-08-27T21:53:02",11,"// видишь все то же самое, но эладрина присевшего рядом с тушей и лягушку в воде",167805,null],[175761,"2026-08-27T21:53:11",22,"Медведь стал девочкой.",167805,null],[175762,"2026-08-27T21:53:22",11,"// звучит забавно хд",175761,null],[175763,"2026-08-27T21:53:28",22,"- Ребята, есть раненые? Я могу помочь!\n\nРуки Венус загорелись зелёным",167805,null],[175764,"2026-08-27T21:53:30",17,"\"Нужна помощь, Цет, Освальд, Кварсио подойдите\"\n\nЭладрин разворачивается и найдя крепкую длинную и относительно ровную ветвь срубает ее \n\nОбтесывая от веток\n\n\"Это рычаг, нужно вставить под тушу\"\n\nПосле этого сложив печать из озера поднимается сгусток воды он подлетает к Фаусту и принимает форму капли. Фауст щелкает пальцами и капля замерзает \n\n/ Ледяная капля принца Руперта и ветка для рычага. От эладрина, пробуем?",167805,null],[175765,"2026-08-27T21:54:01",17,"\"Венус, твой медвежий облик тоже кстате, ты в нем такая дикая. Дух захватывает\"",167805,null],[175768,"2026-08-27T21:54:48",11,"// имба, работает",175764,null],[175769,"2026-08-27T21:54:56",41,"Освальд идет чтоб помочь с рычагом. Проверяет палку на прочность как работник по дереву",167805,null],[175770,"2026-08-27T21:55:00",41,"( помощь)",167805,null],[175771,"2026-08-27T21:56:05",41,"— ну и странности же тут творятся, вот. Попробуй так",167805,null],[175772,"2026-08-27T21:56:46",11,"// давайте силу/ловкость от двоих любых ребят кто держится за донкрат ветку",167805,null],[175773,"2026-08-27T21:57:09",41,"/r d20 можно ловкость рук ?",167805,null],[175775,"2026-08-27T21:57:10",17,"/ Я пожалуй посмотрю со стороны",167805,null],[175776,"2026-08-27T21:57:10",53,"*увидев дроу припадаю на одно колено и готовлюсь вытягивать того, паралельно оглядывая его травмы*",175747,null],[175778,"2026-08-27T21:58:02",11,"// Венус, К'варсио кто поможет?",175774,null],[175782,"2026-08-27T22:00:09",22,"- Спасибо.\nВенус смутилась и покрылась розовыми бутонами",167805,null],[175783,"2026-08-27T22:00:12",22,"Я помогу",175778,null],[175784,"2026-08-27T22:00:20",41,"( мишкаааа",167805,null],[175785,"2026-08-27T22:00:41",22,"/r +2",175778,null],[175788,"2026-08-27T22:01:56",11,"Освальду и Венус рычаг не поддаётся, руки ослабшего фирболга соскользают с бревна, а флорен не справляется сама",167805,null],[175789,"2026-08-27T22:02:15",41,"— Уф, ребята. Все вместе!",167805,null],[175790,"2026-08-27T22:02:17",22,"- Если есть раненые, скажите, я умею лечить. У меня это лучше получается... чем колдовать",167805,null],[175791,"2026-08-27T22:03:42",53,"*поднимаю руку все так же сидя на колене у подранка и тяжело дыша*",175790,null],[175792,"2026-08-27T22:04:32",41,"Освальд тоже поднял руку",167805,null],[175793,"2026-08-27T22:05:02",11,"// тело бы тоже руку подняло хд",167805,null],[175794,"2026-08-27T22:06:18",11,"Касаясь руки ты чувствуешь совсем слабый пульс",175776,null],[175795,"2026-08-27T22:09:13",5,"Грунг выплыл из воды и помогает тянуть",167805,null],[175796,"2026-08-27T22:09:14",22,"/r d8+3",175791,null],[175798,"2026-08-27T22:09:29",22,"/r d8+3",175792,null],[175800,"2026-08-27T22:10:53",41,"— спасибо, дорогая. Чтоб мы без тебя делали... А что с этим эльфом?",167805,null],[175801,"2026-08-27T22:11:34",22,"Венус подошла к товарищам. Из-под её пальцев вырывается мягкое изумрудное свечение, и прямо в повреждённую ткань устремляются тонкие живые корешки и мох. Они быстро сплетаются с плотью, затягивая порезы.",167805,null],[175802,"2026-08-27T22:11:43",53,"*резко закашляв и сделав глубокий вдоз начинаю резво ухаживать за полумертвым*\n\nблагодарю. теперь мне легче. вам не требуется медецинская помощь?",175797,null],[175803,"2026-08-27T22:12:07",22,"Венус покачала головой",167805,null],[175805,"2026-08-27T22:12:23",53,"//лечение лежачего",175804,null],[175807,"2026-08-27T22:13:33",11,"Тело все так же без сознания лежит под тушей",167805,null],[175813,"2026-08-27T22:14:53",53,"что же, други, вытащим страдальца? \n*оглядываю товарищей готовясь вытаскивать лежащего когда тело зверя приполнимут, взгляд чуть дольше задерживается на кварсио*",167805,null],[175818,"2026-08-27T22:16:25",17,"Фауст сосредоточился и создал эхо над рычагом в воздухе поднял его ещё выше\n\nСмена позиций и в вихре снежинок всем весом эладрин приземляется ногами и давит на рычаг",167805,null],[175819,"2026-08-27T22:16:40",17,"/r -1",167805,null],[175821,"2026-08-27T22:16:44",41,"Освальд снова помогает *",167805,null],[175822,"2026-08-27T22:16:51",17,"/ Как смог)",167805,null],[175826,"2026-08-27T22:18:11",11,"// что-то никак у вас не идёт:D Но есть и другой способ если так подумать",167805,null],[175828,"2026-08-27T22:18:41",53,"//кстати вспомнив",175826,null],[175829,"2026-08-27T22:18:45",41,"Освальд осмотрится...\n\n— а если Под ним подкопать?",167805,null],[175830,"2026-08-27T22:19:17",53,"//я могу порывом ветра оттолкнуть тушу?",175828,null],[175831,"2026-08-27T22:19:47",22,"- Стойте",167805,null],[175833,"2026-08-27T22:19:55",22,"- Давайте его раскопаем",167805,null],[175834,"2026-08-27T22:20:09",41,"—...хорошая идея!",167805,null],[175835,"2026-08-27T22:20:31",22,"- Сделаем под ним ямку и так мы сможем безопасно его вызволить",167805,null],[175836,"2026-08-27T22:20:44",11,"// слишком тяжёлая, нет, а вот подкоп сработает",175830,null],[175837,"2026-08-27T22:21:01",22,"Венус превращается в роющее существо и роет ямку",167805,null],[175839,"2026-08-27T22:21:14",22,"/простите я в дороге, не могу подсказать название",167805,null],[175840,"2026-08-27T22:21:27",22,"/но у меня круг луны, так что там выбор огромный",167805,null],[175841,"2026-08-27T22:21:27",17,"/ Медоед наверное)",167805,null],[175844,"2026-08-27T22:21:52",11,"Песок сыпется на Цета стоящего позади и немного попадает на всех кто вокруг, но вскоре вы понимаете что достать тело больше не составит труда",167805,null],[175848,"2026-08-27T22:22:09",53,"//гигантский барсук?",175839,null],[175854,"2026-08-27T22:23:16",53,"*как только понимаю это вытягиваю тело и начинаю лечить все ранее не поддававшиеся лечению зоны*",175844,null],[175865,"2026-08-27T22:27:57",11,"Освобожденное из-под туши тело принадлежит девушке дроу.  Её кожа имеет глубокий, благородный оттенок темной древесной коры. Ярким контрастом на фоне этой темной кожи выделяются её длинные, густые желтые волосы. Сейчас они растрепались, частично скрывая лицо, и сильно испачканы песком. Вместо брони на ней надета простая одежда, искусно сшитая из мангровых листьев и скрепленная волокнами лиан.\n\nЦет который вытянул ее чувствует что тело всё ещё теплое, а пульс стабилизировался от его помощи, но в сознание она пока не приходит",175854,null],[175868,"2026-08-27T22:29:00",53,"ей требуется отдых. нам тоже.",175865,null],[175875,"2026-08-27T22:32:35",22,"/r d8+3",175865,null],[175877,"2026-08-27T22:33:01",22,"- Ее тяжело лечить.. тело словно сопротивляется магии. Я согласна, давайте отдохнём",167805,null],[175878,"2026-08-27T22:33:32",41,"Освальд приподнимет ей голову и осторожно напоит прохладным молоком",167805,null],[175879,"2026-08-27T22:33:48",41,"— представьте, каково дроу на этой жаре",167805,null],[175880,"2026-08-27T22:33:49",53,"думаю дело в том что ее раны слишком глубоки.",175877,null],[175881,"2026-08-27T22:34:06",41,"( +1 временное хп ей",175878,null],[175882,"2026-08-27T22:34:07",53,"//еще и лучи натсебя стягивает",175879,null],[175884,"2026-08-27T22:34:25",53,"//жаль не стакаютса..",175881,null],[175886,"2026-08-27T22:34:37",53,"//но лишним не будет :D",167805,null],[175887,"2026-08-27T22:34:38",41,"( Почему?",167805,null],[175888,"2026-08-27T22:34:50",53,"?//",175887,null],[175890,"2026-08-27T22:35:37",41,"( Почему не стакается?",167805,null],[175891,"2026-08-27T22:36:03",11,"// по правилам тхп не стакается, остается только эффект с самым большим кол-вом единиц",167805,null],[175892,"2026-08-27T22:36:17",41,"( а",167805,null],[175894,"2026-08-27T22:37:37",53,"//ну все равно неплохо подлечили хоть у всех и по еденичке выпало на хилл :D  (аж целых 11 хп отхиляли и дали тхпшек немножко)",167805,null],[175895,"2026-08-27T22:38:10",11,"// можете приземляться на отдых",167805,null],[175896,"2026-08-27T22:38:23",53,"//время суток?",175895,null],[175902,"2026-08-27T22:39:25",17,"\"Прикрою ему глаза. Дроу не переносят яркий солнечный свет.\"\n\nФауст снял свой платок и накрыл дроу. Сейчас скрывать свой зашитый рот не имело смысла. Тут все свои.",167805,null],[175905,"2026-08-27T22:39:55",53,"*разоьравшись с ранеными поправляю сначала повязки на квасио, а затем и на себе, после набрав воды проделываю с трупами огненых рыбомясов то же что делал с обычными рыбомясами*\n\nда примет великий ваши души.",167805,null],[175908,"2026-08-27T22:40:31",17,"\"Я помогу разделать туши. Но ты уверен что мясо съедобно?\"",175905,null],[175909,"2026-08-27T22:41:19",11,"Вечер, но ещё не темнеет",175896,null],[175910,"2026-08-27T22:41:22",53,"не могу быть в этом уверен, как и в сьедобности мяса тех кого мы разделывали до этого. от подмоги в работе отказыватся не стано.",175908,null],[175911,"2026-08-27T22:41:46",5,"— Спасибо, Цет. Мне уже легчает, это всё была жара",175905,null],[175913,"2026-08-27T22:42:04",11,"// как говорится не попробуешь не узнаешь..",175908,null],[175916,"2026-08-27T22:42:59",53,"от жары открылись старые раны. стоит быть осторожнее и спокойнее пока не отдохнешь. дальше раны уже не должны сильно беспокоить.",175911,null],[175918,"2026-08-27T22:43:27",5,"— Старые? У меня таких нет, я ещё молодой",175916,null],[175920,"2026-08-27T22:44:18",53,"*призадумался на мгновение подбирая слова*\nстарые есмь полученные в прошлом бою.",175918,null],[175923,"2026-08-27T22:44:56",11,"// на разделку туш кидайте выживание все кто хочет пайков, за качество которых я не ручаюсь есть на свой страх и риск",167805,null],[175924,"2026-08-27T22:45:11",17,"\"Слушайте, вот вопрос, ящеры как то источали ужасный жар, мы чуть не сгорели рядом с ними. Но почему их самих он не убивал? Может дело в шкуре? Она огнепрочная? Мы могли бы сделать пару плащей или хотябы нарезать заготовок, как думаете?\"",167805,null],[175925,"2026-08-27T22:46:01",11,"// хочешь осмотреть прежде чем разделывать?",175924,null],[175926,"2026-08-27T22:46:17",53,"соглашусь. олнако если жар исзодил изнутри них, может так быть что они целиком стойки к жару",175924,null],[175929,"2026-08-27T22:46:41",5,"— Эти есть. Побаливают",175920,null],[175932,"2026-08-27T22:47:13",17,"\"А давай изучим их шкуру поподробнее.\"\n\nФауст сел и с задумчивым видом пялится на шкуру.\n\nОтрезал небольшой кусочек и крутит в руках",175925,null],[175934,"2026-08-27T22:47:56",53,"*киваю*\nнагрузки и жар тому причина.",175929,null],[175935,"2026-08-27T22:48:24",11,"Шкура самца не поддаётся легко, она более тугая чем остальных особей, как будто покрыта хитином насекомых",167805,null],[175936,"2026-08-27T22:48:44",53,"*так же осматриваю шкуры (помошь если потребуется)*",175932,null],[175939,"2026-08-27T22:49:45",11,"// хм.. анализ наверное\nЛюбой из вас двоих кидайте с преимуществом за помощь, ну или если ещё кто захочет поглядеть",167805,null],[175945,"2026-08-27T22:54:47",53,"//лучше пусть фауст кидает",175939,null],[175948,"2026-08-27T23:00:58",17,"/r +d20+1 Анализируем с Цетом шкуру хитиновую",175939,null],[175956,"2026-08-27T23:05:12",11,"Цвет чешуек обоих особей приобрел нормальный вид за это короткое время после их смерти. Самка выглядела в точности как предыдущие особи с пляжа, самец же имел небольшой хитиновый покров и явно выраженный гигантизм, в остальном всё то же. В какой-то момент в твоей голове проносится: «это была магия». Но она покинула тела после смерти.",175949,null],[175960,"2026-08-27T23:06:17",11,"// выживание каждый сам себе на пайки кинуть можете",167805,null],[175963,"2026-08-27T23:07:11",17,"\"Нет, Цет. Тут больше ничего необычного. Их изменила магия и после смерти усиление или магическая мутация пропала. Не видать нам огнеупорных плащей. Что ж давай нарежем лишних стейков. Хоть что то\"",167805,null],[175964,"2026-08-27T23:07:22",22,"- Очень интересно. Мне кажется, что они что-то съели, благодаря чему приобрели такие способности. Вспомните, что я нанюхалась чего-то и стала птичкой! \n\nВесь этот лес странный. Тут ещк многое предстоит изучить",167805,null],[175965,"2026-08-27T23:07:25",17,"/r +3 Выживалити",167805,null],[175967,"2026-08-27T23:07:44",22,"/r +5",175960,null],[175969,"2026-08-27T23:08:04",17,"\"Звучит умно. Наверное так и есть. А что за пыльца там была от растений или откуда?\"",175964,null],[175970,"2026-08-27T23:08:36",41,"— интересно, это перевоплощение связано с пробуждением леса?",167805,null],[175972,"2026-08-27T23:08:47",22,"Помимо нарезки мяса, Венус занялась шалашом.\n\nС помощью магии друидов она просила растения ей помочь и изящно сплетала их воедино, сделав товарищам гамаки и навес над головой",167805,null],[175975,"2026-08-27T23:09:14",22,"//о боги мне так стыдно, это все т9!!",167805,null],[175976,"2026-08-27T23:09:15",11,"// я видела оригинал ахаха",175972,null],[175978,"2026-08-27T23:09:20",17,"/ Прочитал 3 раза и все пытался понять...",175975,null],[175981,"2026-08-27T23:09:52",11,"// по 3 пайка удалось добыть и Венус и Фаусту",167805,null],[175982,"2026-08-27T23:09:52",41,"( а я упустиль (",167805,null],[175985,"2026-08-27T23:10:37",11,"Вы не особо уверены съедобно ли мясо, но вместе с усталостью накатывает и голод..",167805,null],[175988,"2026-08-27T23:10:51",11,"// кто там ближе всего к эльфийке?",167805,null],[175992,"2026-08-27T23:13:30",53,"думается мне, чешуя будет хороша для бронирования.",175963,null],[175994,"2026-08-27T23:13:46",41,"( я",175988,null],[175995,"2026-08-27T23:13:58",41,"( ухажор",167805,null],[175996,"2026-08-27T23:14:04",11,"— Почему тут так темно..? Я умерла? — доносится женский голос из под платка Фауста. \n\nОбернувшись в сторону где лежала девушка без сознания вы видите что она шевелится",167805,null],[175998,"2026-08-27T23:14:13",11,"// а тебе 2 пайка, без чешуи",175993,null],[175999,"2026-08-27T23:14:34",41,"— нет, ты жива, просто на тебе платок. Осторожно снимай, тут солнечно",175996,null],[176003,"2026-08-27T23:15:18",5,"К'варсио тем временем сморило на берегу оазиса. Он спит спокойным лягушачьим сном",167805,null],[176004,"2026-08-27T23:15:53",17,"Фауст отошёл собирать хворост для костра",167805,null],[176005,"2026-08-27T23:15:55",53,"//хоть кто то лечится.",176003,null],[176006,"2026-08-27T23:16:20",11,"— ..? Кто вы? — Услышав незнакомый голос девушка протянула руку к голове, нащупала платок и сняв его шелохнулась увидев огромного фирболга, но его доброжелательный вид заставил ее чуть подуспокоиться.\n\nДевушка попыталась привстать, но застонала от боли",167805,null],[176007,"2026-08-27T23:16:35",17,"\"С голодухи будет сосать под ложечкой, дождись еду, потом все отдыхать пойдем… рыцарь\"",176003,null],[176008,"2026-08-27T23:16:56",53,"//тож верно",176007,null],[176009,"2026-08-27T23:17:04",5,"Красное лягушачье тельце никак не реагирует",176007,null],[176010,"2026-08-27T23:18:14",17,"Фауст шумно вздыхает и подходит к Венус\n\n\"Сделай пожалуйста Кварсио зонтик, кажется от такого палящего солнца у нас будет вареная лягушка, я за хворостом\"",176009,null],[176011,"2026-08-27T23:19:05",22,"Делаю",176010,null],[176012,"2026-08-27T23:20:23",41,"— и то верно",176010,null],[176013,"2026-08-27T23:20:43",41,"— может у меня есть что-то хорошее для навеса ?",167805,null],[176014,"2026-08-27T23:21:11",41,"Он делится с Венус своим посохом и пальто чтоб сделать навес К´Варсио",167805,null],[176016,"2026-08-27T23:22:57",11,"// жду вашей реакции👀",176006,null],[176017,"2026-08-27T23:23:41",41,"— привет :3",176006,null],[176018,"2026-08-27T23:23:58",22,"- Я Венус.\n\nМягко и ласково сказала девушка. \n\n- А как тебя зовут?",176006,null],[176020,"2026-08-27T23:24:25",53,"вам следует отдыхать.\n*разобравшись с тушкой подхожу к дроу*\nвы были тяжело травмированы, наш долг помочь вам в исцелении.*",176006,null],[176024,"2026-08-27T23:27:26",11,"— Вы все такие разные.. — она немного в замешательстве — Я Олани, а это.. \n\nОна вновь пытается подняться, но безрезультатно плюхается обратно в песок, а её отчаянный взгляд смотрит то на одного то на другого в надежде\n\n— А Соната? Они съели её да?",167805,null],[176028,"2026-08-27T23:27:59",53,"*помогаю приподнятся*",176024,null],[176029,"2026-08-27T23:29:58",11,"Эльфийка оглядывается и видит тело, а затем на её глаза накатываются слёзы\n\n— Соната была со мной с детства.. — она шмыгает и вытирает глаза — а где эти аризонозавры..? Судя по тому что здесь больше не так жарко, вы разобрались с ними..?",167805,null],[176030,"2026-08-27T23:30:57",41,"Он протянул ей платочек",167805,null],[176031,"2026-08-27T23:31:27",41,"— Мне жаль, леди Олани. Мы поищем вашу подругу, не теряйте надежду",167805,null],[176032,"2026-08-27T23:32:04",11,"— Нет-нет, спасибо, я в порядке — понимая что встать без помощи Цета она не может Олани исправляется — или не очень..",167805,null],[176033,"2026-08-27T23:32:13",11,"// она про тело травоядного",176031,null],[176034,"2026-08-27T23:33:01",41,"( а, сори",176033,null],[176035,"2026-08-27T23:33:24",17,"/ Поедим* вашу подругу",176031,null],[176036,"2026-08-27T23:33:41",41,"( Соль одобряет",176035,null],[176037,"2026-08-27T23:35:40",11,"— Она защитила меня от них.. собой\n\nДевушка лишь грустно покачала головой и отвела взгляд от тела\n\n— Не могли бы вы провести меня домой? Боюсь я не смогу дойти сама..",176031,null],[176039,"2026-08-27T23:36:58",41,"— Значит вы местная. Можем ли мы с вами поговорить, когда вы отдохнете?",167805,null],[176040,"2026-08-27T23:37:05",53,"так вот как называются те существа...",176029,null],[176041,"2026-08-27T23:38:25",11,"— Что бы вы хотели узнать? Я и так должна вам за помощь, спрашивайте",176039,null],[176042,"2026-08-27T23:38:38",53,"я сделаю все возможное дабы вы вновь могли здравствовать.",176032,null],[176043,"2026-08-27T23:39:39",17,"Фауст принес хворост и складывает костер неподалеку",167805,null],[176044,"2026-08-27T23:40:25",17,"\"Кто она? Откуда? Цель пребывания здесь? Что она знает о других разумных в этом лесу? Где выход из чаши? Уже все узнали?\"",167805,null],[176045,"2026-08-27T23:40:35",22,"Венус грустно жевала шашлык, слушая диалог.",167805,null],[176046,"2026-08-27T23:41:10",41,"— только приступаем",176044,null],[176047,"2026-08-27T23:41:35",11,"// неплохой на вкус тащемта",176045,null],[176048,"2026-08-27T23:42:42",11,"Эльфийка вопросительно посмотрела на эладрина\n\n— Это ваше полагаю — она протянет к тебе руку с платком",176044,null],[176049,"2026-08-27T23:43:34",22,"- Как давно вы живёте в лесу и как называете свой народ?",167805,null],[176050,"2026-08-27T23:43:35",53,"мясо \"аризонозаврыв\"(с заметным акцентом и затруднением произнес слово) сьедобно?",176041,null],[176051,"2026-08-27T23:45:08",17,"Он подходит и молча кивает ей забирая своё.",176048,null],[176052,"2026-08-27T23:45:24",53,"*после вопроса протягиваю ей водоросли и сам тоже ем*",176050,null],[176053,"2026-08-27T23:45:44",17,"Потом возвращается к костру, зажигает его. Вставляет рогатины и вешает котелок на жердочку",167805,null],[176054,"2026-08-27T23:46:08",11,"— Как давно? — она ненадолго задумалась — Честно говоря я никогда не задавалась таким вопросом. Я родилась и жила всю жизнь в родном городке неподалёку отсюда. Как и мои родители. А ещё.. мне не доводилось видеть никого подобного на вас раньше, отец лишь рассказывал о том что есть другие расы, а мы зовёмся лорендроу",176049,null],[176055,"2026-08-27T23:47:14",11,"— Эм.. Мы не пробовали готовить их раньше, как вы могли заметить охотиться на них может быть трудно, но смею предположить как рыба? Вы любите рыбу?",176050,null],[176056,"2026-08-27T23:50:32",53,"*киваю*",176055,null],[176057,"2026-08-27T23:51:24",53,"Фауст, не мог бы ты найти пару пальмовых листов покрупнее?",176053,null],[176058,"2026-08-27T23:53:25",11,"— Могу ли я рассчитывать на вашу помощь..? — уже более неловко спрашивает она — ночью в джунглях ещё менее безопасно чем днём, а здесь несколько туш и на запах мяса могут прийти другие хищники. Если вам негде остановиться вы могли бы остановиться у меня! У нас чудный город!",167805,null],[176059,"2026-08-27T23:55:39",22,"- Конечно. Мы успеем в город до темноты?",167805,null],[176060,"2026-08-27T23:56:42",11,"— Да, тут не так далеко! — она оценивающе смотрит на небо — к закату должны успеть",167805,null],[176061,"2026-08-27T23:57:18",11,"// но лягушонок ирл спать ушёл",167805,null],[176062,"2026-08-27T23:57:39",17,"Фауст отправил ледяного клона в сторону пальм, потом поменялся с ним местами и срубил несколько листьев. Снова поменялся и передал Цету",176057,null],[176063,"2026-08-27T23:58:48",11,"// чисто ауру фармит",176062,null],[176064,"2026-08-27T23:58:51",53,"благодарю.",176062,null],[176065,"2026-08-27T23:59:55",53,"*используя листы пальмы, две палки и нить для зашивания лишних отверстий в организмах живых существ пытаюсь собрать носилки*",167805,null],[176066,"2026-08-28T00:00:07",41,"Освальд собрал кокосики с упавшей пальмы",167805,null],[176067,"2026-08-28T00:00:10",53,"//что то кидат?",176065,null],[176068,"2026-08-28T00:01:19",11,"//даже не знаю что тут, медицину..? Выживание? Сам выбирай",176067,null],[176070,"2026-08-28T00:03:05",53,"//+0",176069,null],[176071,"2026-08-28T00:03:34",11,"— Это не обязательно — ответила девушка Цету увидев что у него ничего не получается, мне бы трость..",167805,null],[176072,"2026-08-28T00:04:30",22,"- Зачем вы так извращаетесь?\n\nВенус превращается в одного из ящеров, который должен быть достаточно большим для всадника и предлагает девушке на себя взобраться",167805,null],[176073,"2026-08-28T00:06:45",17,"Фауст пока варит суп из тех стейков что нарезали раньше. Кидает туда травы \n\n\"У кого нибудь есть соль?\"",167805,null],[176074,"2026-08-28T00:06:45",11,"// такс, напомни какое по ты щас можешь?",167805,null],[176075,"2026-08-28T00:07:27",22,"//я не знаю как в днд работают размеры, поэтому отыгрываю от патфайндера(это как днд только лучше).\nИдея в том, чтобы стать существом размера L чтобы девушка М могла оседлать и довезти ее",167805,null],[176076,"2026-08-28T00:07:46",22,"/если я ошибаюсь и в днд не так - поправьте меня",167805,null],[176077,"2026-08-28T00:08:17",22,"/тем более что короткий отдых мы точно сделали и ячейки обликов восстартвились",167805,null],[176078,"2026-08-28T00:08:23",41,"освальд подает Соль, а сам натирает кокосы На стружку",176073,null],[176079,"2026-08-28T00:08:48",41,"( я L",176075,null],[176080,"2026-08-28T00:09:04",41,"( и девушка M меня не оседлает(",167805,null],[176081,"2026-08-28T00:09:35",22,"//ну в пф можно ездить на существах которые больше на 1 размер, как в днд хз. Тут даже минус к силе за размер S не дают 😒",167805,null],[176082,"2026-08-28T00:10:22",22,"//мой мастер сказал, что в днд размер ни на что не влияет, так что моя заявка исключительно на усмотрение @Ashenchampion",167805,null],[176083,"2026-08-28T00:10:53",27,"// Аналогичное вроде правило.",176081,null],[176084,"2026-08-28T00:11:51",22,"Все я нашла!!!",167805,null],[176085,"2026-08-28T00:12:01",22,"https://dnd.su/bestiary/329-warhorse/\n\nИГОГОГО!!!!",167805,null],[176086,"2026-08-28T00:12:47",22,"Тыг дыг тыг дык\n\nВенус качает гривой и опускается на колени, приглашая девушку взобраться на нее",167805,null],[176087,"2026-08-28T00:13:18",22,"//простите за флуд, я перенервничала в этот ответственный момент",167805,null],[176088,"2026-08-28T00:14:13",11,"— Так среди вас тоже есть друиды! Благодарю, Венус — она оглядывается на Цета прося помощи взглядом",176086,null],[176089,"2026-08-28T00:14:25",17,"/ А уточните мне, вы собираетесь щас куда то уехать? У меня тут суп...",167805,null],[176090,"2026-08-28T00:15:01",11,"// все в порядке, абсолютно уместные вопросы. Если что в днд все тоже самое на 1 размер больше нужно существо да. А друид может обращаться только в зверей определенных показателей опасности, так как у тебя круг луны то выбор увеличивается на порядок",176087,null],[176091,"2026-08-28T00:15:38",11,"// кушай кушай, лягуху подберём и поедем. Но на сегодня всем спасибо, без Эла двигаться все же дальше не будем",176089,null],[176093,"2026-08-28T00:17:45",53,"*помогаю встать и довожу ее до скакуна*",176088,null],[176098,"2026-08-28T00:21:23",22,"Венус ждет, стукая копытом о землю и с любопытством поглядывая на котелок с супом",167805,null],[176100,"2026-08-28T00:26:00",11,"Девушка с помощью тритона садится на коня Флорена и приобнимает её",167805,null],[176117,"2026-08-28T00:31:05",22,"Венус следует за товарищами и в направлении, куда указывает эльфийка.\n\nСама Венус держится чуть поодать, чтобы защитить девушку, если возникнет опасность.\n\nГрива лошади начинает немного сиять и распускаются цветы",167805,null],[176153,"2026-08-28T01:05:57",41,"Освальд хочет погладить гриву 👉👈🥺",176117,null],[176163,"2026-08-28T09:09:07",5,"// разбудите кто-нибудь лягушонка 🥺",167805,null],[176173,"2026-08-28T10:50:30",17,"Суп с мясом ящеров и специями доваривается в котелке и тонкий запах наваристого бульона распространяется по полянке\n\nНепременно он попал и в ноздри Кварсио\n\n\"Попробуйте, кажется готово.\"",167805,null],[176174,"2026-08-28T10:51:40",41,"— пахнет очень вкусно. Кажется кто-то ещё и талантливый повар) \n\nПробует",167805,null],[176176,"2026-08-28T10:52:06",17,"/r Суп вышел на",167805,null],[176187,"2026-08-28T10:53:32",41,"— Вы молодец, Фауст! Очень вкусно!",167805,null],[176203,"2026-08-28T10:59:45",22,"Лошадь фыркает в плечо Фаусту, выразительно смотря на суп.\n\nДлинным зеленым языком, кобыла облизала парня, взъерошив ему волосы.\n\nДыхание кобылы пахло мхом и свежескошенной травой.",167805,null],[176204,"2026-08-28T11:00:40",17,"\"Это... Интересная реакция.\"",176203,null],[176226,"2026-08-28T12:17:16",5,"Нюх-нюх\n\nЖивот спящего грунга заурчал, а он открыл один глаз.  Потом второй. И наконец встал.\n\n— Запах еды! Я так давно не кушал\n\nВсё ещё сонный К'варсио прыгает к котелку и пробует блюдо.\n\n— Вкусно, вкусно! Квасибо за еду, Фауст!",176173,null],[176361,"2026-08-28T13:13:08",53,"//на 18 из 10 :D",176177,null],[176362,"2026-08-28T13:13:58",41,"Супь",167805,null],[176385,"2026-08-28T13:25:45",11,"// так ну суп съели можно идти?)",167805,null],[176386,"2026-08-28T13:28:38",41,"( агась",167805,null],[176393,"2026-08-28T13:35:21",11,"Вы недолгое время идёте по джунглям, пока солнце понемногу начинает опускаться за горизонт. Олани, по дороге, поведает вам о том что она рыбачка, а у моря всю рыбу выловили ящеры и поэтому она пошла рыбачить к водоёму не ожидая что там тоже поселились аризонозавры\n\nА спустя какое-то время перед взором группы открывается скрытый поселок, раскинувшийся в прибрежных джунглях. Город не разрушает природу, а буквально является её продолжением. Многовековые исполинские деревья с невероятно толстыми стволами и раскидистыми кронами служат естественным фундаментом для изящных деревянных башен и резных многоярусных домов. Жилые постройки эльфов, выполненные из темной древесины, плавно огибают изгибы ветвей. Их остроконечные крыши покрыты слоем мягкого живого мха и вьющихся лиан.\n\nВсе уровни этого вертикального поселения соединены между собой сложной системой подвесных мостов, арок и переходов. Между каменными уступами и корнями деревьев с оглушительным ревом срываются мощные горные водопады. Их хрустальные струи питают бурные речные потоки, протекающие прямо под подвесными конструкциями города. Воздух здесь пропитан влажной свежестью, прохладой и ароматом цветущих джунглей. На каждом ярусе, вдоль перил и у входов в дома, мягким люминесцентным светом сияют грибы. Они рассеивают вечную густую тень лесного навеса и отражаются в быстрых речных водах, рядом с которыми цветут лотосы и расположены рисовые поля.",167805,null],[176399,"2026-08-28T13:43:42",11,"Вы постепенно проходите по мостам подымаясь к месту которое указала девушка. Все жители здесь, подобные ей темнокожие эльфы, проходят мимо вас оглядываясь с удивлением, но Олани цыкает на них.\n\n— Вот и мой дом — говорит она\n\n— Олани? — мужчина сидящий на пороге подымается и обеспокоенно подходит к девушке, а затем вопросительно смотрит на вас",167805,null],[176411,"2026-08-28T14:11:48",22,"Слушая незамысловатый рассказ рыбачки, Венус наслаждалась новым обликом, чувствуя, как мягкая влажная земля приятно пружинит под копытами. Но когда перед глазами распахнулась панорама эльфийского города, Венус в буквальном смысле замерла на месте.\n\nГрохот водопадов, брызги хрустальной воды и сияние светящихся грибов заставили её гриву встать дыбом от нахлынувшего восторга. Лошадь с наслаждением втянула влажный воздух, полный дивных запахов. \n\nКобыла оживленно фыркнула, мотнула головой и сделала пару шагов к краю речного потока. Опустив бархатный нос к водоему, она жадно отпила прохладной воды, а затем повернула морду к спутникам",167805,null],[176415,"2026-08-28T14:20:46",11,"Вода прохладная и освежающая, на вкус как горная",176411,null],[176417,"2026-08-28T14:25:54",41,"Овальд завораженный красотой вросшего в деревья городка проводит рукой по хрустальным, холодным струйкам.\n\nНаверное сюда часто приходят полюбоваться — подумал он, и оставил игрушечного бычка из дерева на камне. Какой-то нуждающийся сможет забрать",167805,null],[176424,"2026-08-28T14:31:24",11,"На другом берегу, напротив вас, девочка на вид лет около 10 чем-то усердно занималась на рисовых грядках. Она была так занята что даже не увидела вас, но стоило вам отойти и Освальд замечает как ребенок идёт к реке помыть руки и видит её игрушку\n\nПробежав мост девочка подошла к камню и с любопытством начала осматривать игрушку взяв её в свои миниатюрные ладошки",176417,null],[176431,"2026-08-28T14:47:12",41,"Освальд с интересом наблюдал издалека. Ему было приятно, что ребенок возможно впервые находит игрушку на улице. Должно быть настоящий подарок судьбы. \n\n— Думаю, тут я уже могу выпустить Рудольфа. \n\nОн заглядывает в мешок\n\n— Рудольф! Не налегай на печенье! \n\nРудольф хрустя печеньками выбирается из мешка и стучит копытами по древесному мосту, благородно поднимая рога над бризом горной воды \n\n— хороший мальчик)",167805,null],[176432,"2026-08-28T14:47:36",41,"( Карпатська джерельна!",176415,null],[176442,"2026-08-28T15:06:22",5,"— Квакое чудесно место! Воздух и квадопады! Я обязательно посижу в них. Но сейчас надо выспаться, ква!\n\nГрунг тронул лапой Цета.\n\n— Цет, у квеликого есть такие квадопады?",176393,null],[176528,"2026-08-28T16:34:21",11,"— Эти люди спасли меня, пап. — девушка рассказывает ему про произошедшее, а затем добавляет — могут ли мои спасители остаться у нас в доме на ночь?\n\nМужчина оценивающе посмотрел на группу, а затем на свое скромное жилье\n\n— Боюсь спальных мест на всех не хватит.. но раз вы помогли моей дочери я постараюсь сделать что смогу, прошу, проходите — он забрал дочь с спины Венус взяв её на руки и вошёл в дом открыв вам дверь\n\n— Вашего оленя вы можете оставить в стайнях.. все равно место моей Сонаты теперь свободно.. — добавила она",167805,null],[176530,"2026-08-28T16:35:39",41,"Освальд вздохнул.\n\n— Вы очень добры, спасибо",167805,null],[176553,"2026-08-28T17:21:57",17,"Фауст осматривал поселение с присущим ему скепсисом и \"нормальной\" паранойей как он это называл. \n\nВсё что на первый взгляд безмятежно выглядит, может скрывать за ширмой ужасные тайны\n\nОн телепатически обратился к девушке Олани\n\n\"Береги себя.\"\n\nПотом к её отцу \n\n\"Спасибо за гостепримство, я могу спать под звёздами, не принципиально. Моё имя Фауст. Что это за место?\"",176528,null],[176733,"2026-08-28T20:02:04",22,"Венус превращается обычно в девушку.\n\n- Я рада, что с вами все хорошо. Меня зовут Венус, я друид, мы с товарищами путешествуем и еще ни разу не были в подобных местах. Расскажите нам о нем?",176528,null],[176746,"2026-08-28T20:04:53",41,"( обычный цветок",167805,null],[176825,"2026-08-28T21:09:28",17,"\"Кварсио, как думаешь, те ящеры были причиной пробуждения леса? Или за ними стоит что то или кто то ещё?\"",176442,null],[177007,"2026-08-29T06:16:54",5,"— Думаю, лес пробудил ящеров. Они обычные хищники, причина должна быть другой",176825,null],[177009,"2026-08-29T06:22:07",17,"\"Может эти люди знают причину. Выведаем и пойдем разберемся.\"",177007,null],[177010,"2026-08-29T06:22:36",5,"— Ква! Сначала поспим!",177009,null],[177116,"2026-08-29T12:28:51",11,"Войдя в дом вас встречает уютная округлая комната, где стены из живого переплетенного дерева плавно переходят в мягкий моховой ковер под ногами. В центре, вокруг невысокого столика, разложены шелковые подушки, а через открытую арку-окно открывается вид на лесную террасу. Комната наполнена мягким мерцанием светлячков и едва слышным журчанием воды доносящимся снаружи\n\nМужчина сажает дочь на одну из подушек, а сам суетится принести ещё что бы хватило всем. Закончив этим он так же приносит угощения: почти невесомые рисовые пирожки, пахнущие ягодами, бережно выложенные на свежий кленовый лист. Рядом, в глиняных кружках, налито что-то напоминающее молоко — однако напиток слегка темноват и от него исходит глубокий, пикантный аромат лесных грибов\n\n— Прошу присаживайтесь. Выглядите вы уставшими.",167805,null],[177117,"2026-08-29T12:29:46",11,"— Все вы, не стоит оставаться на улице.",176553,null],[177124,"2026-08-29T12:40:36",11,"— Приятно познакомиться, Венус. Моё имя Мелиан. Вы попали в Ильварин - наш скромный город принадлежит лесу Ультима, но находится далеко от остальных, так как мы выбрали место недалёкое от побережья для жизни. Основан наш город был не так давно, впрочем, мы с женой начали здесь жить не сразу когда его возвели — он осмотрит вас всех — а как.. вы здесь оказались? Дело в том что мне не доводилось видеть других рас, нигде кроме книг..",176733,null],[177131,"2026-08-29T12:47:52",41,"— Простите, что задержался. Меня зовут Освальд. Я слишком большой, но могу поспать в своем мешке, хохо! \n\nОн позволит Венус ответить на вопрос",177124,null],[177375,"2026-08-29T16:56:46",5,"Лягушонок устроился на мху около стола и сразу начал пить из кружки. Закончив, он сказал.\n\n— Ква-кварсио я. Молоко необычное и вкусное. Но я очень хочу спать!\n\n*зевает*",167805,null],[177376,"2026-08-29T16:57:35",11,"На вкус как.. грибной крем суп..",167805,null],[177377,"2026-08-29T16:58:10",5,"Лягушонок слизнул стекающие остатки",167805,null],[177380,"2026-08-29T17:11:45",11,"Видя как вы устали эльф подымается и открывает дверь в просторную комнату со стенами из живого дерева, где пахнет сушеной лавандой, а у стрельчатого окна обустроен широкий деревянный подоконник с мягкими подушками. Вместо громоздких кроватей здесь стоят два плетеныж из ивовых ветвей ложа, застеленные эльфийским шелком. Комната наполнена теплым полумраком, который рассеивают небольшие ручные фонари из стекла и лозы с живыми светлячками внутри\n\n— Вы можете остановиться здесь, хоть и лож недостаточно, но если у вас есть спальники кто-то мог бы уснуть в нем на полу, а кто-то у окна.\n\n— А Венус, как единственная девушка, может остановиться в моей комнате со мной — добавила Олани",167805,null],[177386,"2026-08-29T17:17:26",5,"— Можно я посплю прямо тут, а мху?",167805,null],[177389,"2026-08-29T17:25:30",11,"— Как вам будет удобно.. — мужчина смутился",167805,null],[177390,"2026-08-29T17:26:02",5,"— Квасибо!\n\nЛягушонок отполз от стола и свернулся клубком в уголке",167805,null],[177391,"2026-08-29T17:26:17",22,"- Честно говоря, мы и сами сейчас в заблуждении. Я точно помню, что засыпала совершенно в другом месте, а очнулась на поляне, среди джунглей и странных птиц...\n\nВенус посмотрела на товарищей, ожидая их реакции.\n\n- Ваш лес невероятно красив и столь же интересен. Я нигде ранее не встречала подобных рептилий и цветов. Спасибо вам за ваше гостеприимство, булочки просто потрясающие.\n\nНе сочтите, пожалуйста, за грубость, но сколько вам лет? И часто ли вы ездите в большой город или же совсем не покидаете свое поселение?\n\nСпасибо, Олани.",177124,null],[177392,"2026-08-29T17:33:28",11,"— Проснулись не там где уснули..? — мужчина серьезно задумался.\n\nЕго дочь просто непонимающе проморгала и ответила на следующий вопрос:\n\n— В последний раз когда они пытались посетить бабулю матушка умерла по дороге.. несчастный случай, но мы больше не хотели покидать дом\n\nНа горький вздох дочери отреагировал отец и приобнял ее\n\n— Мне.. после второй сотни перестал считать точно, думаю двести сорок где-то..?",167805,null],[177393,"2026-08-29T17:43:15",11,"— Что же это я.. — Мужчина вновь засуетился и куда-то убежал, а Олани тем временем протянула банку того самого молока К'варсио и свернула парочку пирогов для Венус — вот, берите \n\n[ Грибное молоко — 1к6+3 временных хитов на день за склянку (выпивать действием) ]\n\n[ Ягодные рисовые пирожки 3шт. 1к4+2 временных хитов на час (можно скушать бонусным) ] \n\nВернувшись мужчина поставил перед вами мешочек с произведениями эльфийского искусства — украшениями.\n\n[ 5 эльфийских драгоценностей с стоимостью 100 зм за штуку ]\n\n— Вот, у нас много украшений жены осталось, а вы заслужили награду за спасение жизни моего главного сокровища",167805,null],[177394,"2026-08-29T17:44:53",11,"// опити на сне скажу",167805,null],[177397,"2026-08-29T17:49:52",5,"— Квасибо, молочко отличное... ква...",177393,null],[177399,"2026-08-29T17:53:13",17,"Фауст вставил трубочку в суп и себе между нитей в рот\n\nС усилием втянул кремсупчик\n\n\"Вкусненько, благодарю.\"",177376,null],[177401,"2026-08-29T17:54:10",17,"Эладрин кивнул и вытащив спальник устроился на полу в нем",177380,null],[177402,"2026-08-29T17:55:41",17,"/ По моему опыту если не разделишь никто не возьмёт)",177393,null],[177403,"2026-08-29T17:56:52",17,"\"Оставьте память о вашей супруге при себе. Побрякушки мы вытащим из логова злодеев если попадутся на пути. Эти драгоценности для вас ценее золота. Я уверен. Ваша дочка ещё наденет их сама. Нужно лишь время\"",167805,null],[177404,"2026-08-29T18:02:40",41,"— Спасибо вам за ужин. Прошу, Фауст прав — мы не можем взять такие бесценные вещи, лучше ваша дочь возьмет их как будет готова.",177393,null],[177407,"2026-08-29T18:16:38",11,"// справедливо, ладно тогда все по сотке формально:)",177402,null],[177411,"2026-08-29T18:19:09",11,"Он качает головой\n\n— Не переживайте за нас, мы не бедствуем \n\n// Поотказывались для приличия и хватит:3 награда за день игровой заслуженная",177403,null],[177429,"2026-08-29T18:43:42",11,"// Всем по 500 опитов, а Эле за то что инициировала квест с поиском оленя ещё 50 сверху",167805,null],[177438,"2026-08-29T18:45:15",5,"/ истощение исчезает?",167805,null],[177441,"2026-08-29T18:46:10",11,"// да, Лонг рест же",167805,null],[177443,"2026-08-29T18:46:54",41,"( спасиба!!!",167805,null],[177445,"2026-08-29T18:48:29",11,"// а теперь о делах насущных. Ребят, все молодцы, все отыграли персов своих хорошо. Но пятерых мне все таки тяжело тянуть особенно учитывая что у вас разные уровни\nЕсть идеи?",167805,null],[177499,"2026-08-29T19:27:36",17,"/ Ну я как и говорил тогда покину вас. Мне очень понравилось с вами играть. Спасибо за квест",167805,null],[177500,"2026-08-29T19:28:09",41,"( тебе тоже спасибо",177499,null],[177508,"2026-08-29T19:45:46",22,"Спасибо тебе /",177499,null],[177521,"2026-08-29T21:01:32",11,"// спасибо за игру и за понимание, надеюсь ещё как-то поиграем вместе🤝",177499,null],[177545,"2026-08-29T21:12:29",11,"Фауст просыпается утром в своей постели. На улице привычный пейзаж, знакомые звуки, обычный утренний свет. Все твои вещи лежат там, где ты их оставил. Оружие, одежда, сумка — всё на месте, но присмотревшись ты обнаруживаешь что-то новое: женское украшение ручной работы эльфов..",167805,null],[177552,"2026-08-29T21:22:23",41,"( ого, у него есть крыша … иногда",167805,null],[177582,"2026-08-29T21:41:17",11,"// @dunchev чуть не забыла, за квест же тоже экспа даётся, так как не фулл совсем то 100 всего накину сверху, всё же ты играл и первый день закрыл. В общем 600 тебе.",167805,null],[177665,"2026-08-29T22:33:31",22,"- Пока мы еще не легли отдыхать, давайте узнаем друг друга получше? Олани, чем ты любишь заниматься, кроме рыбалки? У тебя была близкая подруга, которая погибла, защищая тебя, ты идешь по пути следопытов? \n\nОсвальд, твои фигурки и все твое поведение говорит о том, что ты очень добрый и заботливый. Чем ты занимался до попадания сюда? У тебя была своя мастерская?\n\nЦет, К\"варсио, а вы я смотрю сильные воины. Вас наверное больше всего обрадовало это приключение? Ведь кто как не вы, сможете продемонстрировать свою силу и доблесть!\n\nГлаза Венус горели в ожидании интересных историй от своих подневольных товарищей.",167805,null],[177670,"2026-08-29T22:36:10",41,"— у меня есть моя мастерская прямо в мешке. Я простой дедушка, который делает детям игрушки в свободное время. Живу я за счет небольшого магазинчика в Элазии, которые покупают сделанную мной мебель. Вы угадали с моей добродушностью, но я хочу сделать как можно больше взрослых и детей счастливыми. Не вижу смысла бороться злом со злом",167805,null],[177675,"2026-08-29T22:38:24",11,"// если что Фауст до ночи ещё с вами",177665,null],[177678,"2026-08-29T22:42:08",11,"— На самом деле рыбалку я люблю и сама. Это не просто работа — она мечтательно вздохнула — разве океан не чудесен? Здесь неподалёку есть дивные лагуны и разнообразные пляжи, а как я люблю косы посреди глубины! А реки, вам доводилось в них плавать? Кристально чистая вода и такая освежающе прохладная, но больше всего я люблю в них тропических рыбок! Вам стоит увидеть их \n\nНа этих словах Олани хотела было сорваться с места, но поняла что сама не сможет встать. Отец сочувственно погладил ее по спине и помог приподняться\n\n— У меня живёт несколько! Давайте я вам покажу",177665,null],[177741,"2026-08-29T23:21:22",11,"Мужчина находит тросточку для девушки и помогает ей пройти в другую комнату приглашая вас с ними. Сама комната напоминает предыдущие.. Но кое-что бросается в глаза и именно это вам спешит показать девушка: с нежностью она касается кончиками пальцев стекла аквариума. Ближайшие рыбки тут же устремляются к её руке, словно узнавая свою хозяйку. Эльфийка оборачивается к вам с гордой, но тёплой улыбкой\n\n — Этот аквариум - моё личное сокровище. Каждую из этих крох я отлавливала сама. Позвольте мне рассказать, откуда они здесь.**\n\nПрежде чем рассказать о рыбках она показывает каждую из них\n\n— Перламутровые стражи (Рыбы-ангелы) - этих величественных красавцев, похожих на парящие серебряные диски с длинными шёлковыми лентами вместо плавников, я выслеживала в тёплых, затенённых заводях местных тропических рек. Мне пришлось три дня сидеть в засаде среди гигантских кувшинок, чтобы поймать их, не повредив эти тончайшие, похожие на кометные хвосты плавники. А это - огненные коралловые шуты (Рыбы-клоуны) - за ними мне пришлось спуститься на дно океана, к коралловым рифам. Эти бесстрашные малютки с яркими, оранжево-белыми полосами живут прямо среди жгучих щупалец ядовитых актиний. Пришлось проявить немалую ловкость рук, чтобы выманить их оттуда вкусной приманкой и не получить ожог. А вот бойцовая синяя искра (Петушок) - они одиночки, так что тяжело их выследить, я нашла его на затопленном рисовом поле. Их бархатные тела переливаются глубоким ультрамарином, а в темноте края плавников вспыхивают неоном. У этого парня истинно драконий нрав - он бросился на собственное отражение в моей ловушке — Она хихикнула рассказывая это и проводя пальцем, а рыбка последовала за ним — а здесь золотохвостые мантии (Гуппи) - эти суетливые крохи с пышными хвостами, которые переливаются золотом и оставляют в воде шлейф из искрящейся пыльцы, заполонили небольшие пресные озёра в глубине джунглей. Ловить их было сплошным удовольствием — они такие любопытные и жизнерадостные, что сами заплывали в сплетённый мной сачок. А вот последние мои милашки - живые бирюзовые молнии (Голубые неоны) - эти крошечные рыбки держатся огромными стаями в глухих, «чёрных» участках тропических рек, где вода темна от опавших листьев. Они вспыхивают неоновым светом все одновременно, ослепляя хищников, я не была исключением!",167805,null],[177745,"2026-08-29T23:22:04",11,"// давайте сделаем вид что у нее древесная кожа, у меня просто лимит закончился:D",167805,null],[177760,"2026-08-29T23:27:33",11,"// я имела ввиду древесного цвета, но пойдет)",167805,null],[177762,"2026-08-29T23:28:00",22,"- Ваши рыбки просто потрясающи! Как и истории об их поимках! Правда, Фауст? А вам нравятся рыбки или у вас другие увлечения?",167805,null],[177767,"2026-08-29T23:28:48",41,"У меня так сделал",167805,null],[177769,"2026-08-29T23:29:11",11,"// спасибо:3",167805,null],[177771,"2026-08-29T23:29:26",41,":3",167805,null],[177773,"2026-08-29T23:30:27",41,"— столько прекрасных рыб, целый аквариум, и такой чистый...заглядение. Я будто на дне морском, хохо",167805,null],[177778,"2026-08-29T23:32:16",11,"— Дно у нас тут прелестное, рифы вокруг создают такой вид под водой! Загляденье!",167805,null],[177943,"2026-08-30T11:24:06",5,"Почти спящий К'варсио отвечал:\n\n— Я рыцарь моей кваспожи... Лес жаркий, неприятный... Но кваспожа поручили узнать, что с ним не так. Я ничего не ква-демонстрирую, лишь служу моей... Ква!",177665,null],[177947,"2026-08-30T11:28:03",22,"Венус подошла к Освальду и тихо зашептала на ухо.\n\n- Так у тебя мастерская всегда с собой?! Обалдеть! Ты сможешь сделать красивый домик для рыбок для Олани?",167805,null],[177948,"2026-08-30T11:29:40",41,"Освальд прошепчет\n\n— Это прекрасная идея! Но мне понадобится ваша помощь. Я очень хорош в работе по дереву, но для расширения аквариума и подводных украшений мне нужно больше рук! Поможете?",177947,null],[177997,"2026-08-30T12:22:53",22,"- Конечно!",177948,null],[179544,"2026-08-30T17:21:18",41,"( Мы ща пойдем пойдем искать красивые камушки? :3",167805,null],[179564,"2026-08-30T17:26:07",11,"// а что конкретно хотите? Извините, я сегодня час спала и не в силах буду вести да и охота самой поиграть",179544,null],[179569,"2026-08-30T17:27:16",41,"( Давай тогда позже, мне ща тоже немного сложно вести и играть",179564,null],[183777,"2026-09-01T09:50:02",41,"( такс, готова продолжить",167805,null],[183778,"2026-09-01T09:50:07",41,"( Как вы ?",167805,null],[183779,"2026-09-01T09:53:10",11,"// на Освальде?",183777,null],[183780,"2026-09-01T09:53:32",41,"( пока да, аквариум хочеца доделать",183779,null],[183785,"2026-09-01T09:58:39",11,"Вечер незаметно перетекает в глубокую ночь, а на вас накатывает усталость долгого и тяжелого дня. В комнате воцаряется полумрак, разбавляемый лишь теплым сиянием затухающих светлячков в лампах. Кто-то из вас опускается на ивовые постели, другие же устраиваются прямо на полу, зарываясь в свои походные спальники. \n\nУтро наступает внезапно. Тонкие лучи рассветного солнца пробиваются сквозь щели в плотно закрытых ставнях, расчерчивая комнаты золотистыми полосами. Но просыпаетесь вы не от ласкового света. Сонную тишину бесцеремонно разбивает нарастающий гул за дверью. Сквозь толщу дерева доносятся взволнованные, приглушенные голоса, суетливые шаги и обрывки громких, почти панических споров. Из коридора тянет сквозняком, а тревожная суматоха снаружи явно намекает на то, что новый день начнется совсем не с мирного завтрака.",167805,null],[183802,"2026-09-01T10:18:44",41,"Вечером Освальд и Венус вышли на самую сложную для приключенца охоту — охоту за красивыми камнями. Первым местом, которое бросилось им на ум был водопад. \n\nУ Водопада их было несомненно много, да и Венус очень хотелось побыть рядом с обволакивающим бризом. Пока Освальд горбатился и собирал каждый камушек, Венус давала ему свое экспертное мнение о том, насколько он эстетичный. \n\nСледующим местом стал поиск рядом с садами других жителей. Они несомненно заметили то как двое приключенцев шурудели между их домами и поинтересовались, что происходит. \n\n«Мы ищем красивые камушки для аквариума леди Олани» \n\nЭтой фразы хватило чтоб уже пол района присоединилось к поискам. Никто не понимал, что происходит, но в конце у Освальда было очень много образцов, что хватит на несколько разных замков. \n\nЭтим он и занялся. У него были хорошие стеклянные пластины для более высокого и прочного аквариума, а так же деревянные балки чтоб поддерживать его вес. В скором времени основа была готова и дедушка приступил к работе с постройкой замка. Без клея — на натуральных материалах он вылепил новый замок, даже несколько чтоб красиво поставить во двор остальные. \n\nКогда Освальд закончил, с его лица стекал пот. Венус уже спала, хоть и хорошо поработала . Он посильнее укрыл её одеялком и тихо закончил ставить все украшения в доме и у него. \n\nТолько тогда он ушел и провалился в сон",167805,null],[183833,"2026-09-01T10:48:39",11,"И так К'варсио и Цет просыпаются в комнате где засыпали вчетвером.. теперь кого-то явно не хватает. Добрый дедушка фирболг и эладрин исчезли будто их и не было\n\nВенус же просыпается и видит перед собой результат их общей с Освальдом работы. Рыбки оценивают новое украшение аквариума - завораживающее зрелище",167805,null],[183851,"2026-09-01T11:39:34",5,"— Ква, что за шум?\n\nК'варсио немного валяется по мху, а затем встаёт на лапки и осматривается",167805,null],[183852,"2026-09-01T11:43:39",11,"Определенно разговоры",167805,null],[183902,"2026-09-01T12:52:03",5,"Лягушонок задумался, куда пропали ещё два спутника, но потяпал к двери отпирать.  \n\n— Ктво тут спать не даёт?",167805,null],[183906,"2026-09-01T12:55:32",11,"Толпа лорендроу что вломилась в дом семьи с самого утра смотрит на тебя как на восьмое чудо света, но не с радостью",167805,null],[183907,"2026-09-01T12:56:23",5,"Грунг замер при виде такой толпы и квакнул от страха",167805,null],[183908,"2026-09-01T12:57:11",11,"— Вчера вы привели их сюда, а сегодня происходит это! — причитает какая-то разъяренная женщина \n\n— Она права, если не они, то кто? — добавляет мужчина из толпы",167805,null],[183909,"2026-09-01T12:59:15",11,"Цет тоже слышал разговор, Венус только громкую фразу женщины",167805,null],[183910,"2026-09-01T12:59:22",5,"— Ква?",167805,null],[183911,"2026-09-01T12:59:47",11,"Недовольный гомон толпы",183910,null],[183912,"2026-09-01T13:01:02",5,"— Что... случилось?\n\nЛягушонок очень напуган",167805,null],[183913,"2026-09-01T13:04:41",11,"— но они спасли мою дочь.. — Мелиан заслоняет К'варсио собой \n\n— А вы так уверены в этом? — все та же женщина явно настроена негативно \n\n— К тому же двое из них ночью рыскали в поисках чего-то, я видела это из окна — говорит ещё один эльф \n\n— Они сказали что хотят сделать подарок Олани — отвечает тот кто помогал Освальду и Венус ночью\n\n— А я видел как они сами ходили в водопаду откуда и течет река!",167805,null],[183914,"2026-09-01T13:05:28",11,"К'варсио видит как Мелиан вставший на его защиту уже начинает колебаться",167805,null],[183926,"2026-09-01T13:09:27",5,"Лягушонок растерянно хлопает глазами. \n\n— Я спал всю ночь, ква...",167805,null],[183931,"2026-09-01T13:10:33",22,"- Что случилось? Мы туда ходили да, но мы были не одни.\n\nВенус вглядывается в толпу и указывает пальцем.\n\n- Ты, ты и вот ты, точно были с нами!",167805,null],[183940,"2026-09-01T13:13:58",11,"// ну судя по описанию помогали вам только в городе, так что либо отредачь либо кидай на обман с помехой ибо жители явно больше верить своим будут",167805,null],[183942,"2026-09-01T13:15:31",11,"— И правда, что происходит? — С открытой Венус дверью выглядывает сонная Олани",167805,null],[183943,"2026-09-01T13:15:52",11,"— Воды больше нет! Река иссохла!",167805,null],[183946,"2026-09-01T13:18:32",5,"— И жара снаружи?",183943,null],[183948,"2026-09-01T13:19:34",11,"— Здесь всегда тепло, мы живём в джунглях! — отвечают из толпы",183946,null],[183967,"2026-09-01T13:22:07",5,"— Значит, тепло квак всегда? Я думал, лес пробудился...",167805,null],[183992,"2026-09-01T13:26:10",11,"— Я не понимаю о чем ты говоришь \n\n// Представь это голосом Вити:3",167805,null],[183993,"2026-09-01T13:27:57",5,"— Вчера мы встретили больших зверей, от них было ужасно жарко",167805,null],[183994,"2026-09-01T13:28:32",11,"// ну анализ кинь",167805,null],[183997,"2026-09-01T13:34:20",5,"/r -1",167805,null],[183999,"2026-09-01T13:35:30",11,"Да, твоя прошлая идея звучит логично",167805,null],[184000,"2026-09-01T13:36:04",11,"Теперь уже Олани смотрит на тебя с недоверием",167805,null],[184011,"2026-09-01T13:38:51",5,"— Река иссохла из-за них. Нельзя подпускать этих зверей кводе!",167805,null],[184035,"2026-09-01T13:42:13",11,"— Вы их убили, К'варсио.. — говорит Олани",167805,null],[184072,"2026-09-01T13:49:45",5,"— Лес пробудил новых. Что-то в джунглях делает ящеров огненными",167805,null],[184081,"2026-09-01T13:56:27",11,"— У тебя есть доказательства?\n\nВнезапно среди толпы показывается немолодая и невысокая эльфийка. Все расступаются перед ней, а она спокойно проходит на передний план постукивая посохом. На ее плече вы замечаете крупного такого иссиня черного попугая (?)",167805,null],[184082,"2026-09-01T13:56:57",11,"Она говорит абсолютно спокойно в отличие от остальных",167805,null],[184084,"2026-09-01T13:57:41",5,"— Ква, Олани видела ящеров!",167805,null],[184096,"2026-09-01T14:01:21",11,"Эльфийка что только что пришла переводит взгляд на Олани\n\n— Дитя, скажи мне - это правда?\n\nДевушка кивает",167805,null],[184101,"2026-09-01T14:02:08",11,"— Значит необычные динозавры появились с приходом этих людей..",167805,null],[184106,"2026-09-01T14:04:16",11,"— Вам есть что сказать в свое оправдание, молодые люди?",167805,null],[184107,"2026-09-01T14:04:35",5,"— Моя кваспожа сказала, лес пробуждается! Я ищу причины этого",167805,null],[184114,"2026-09-01T14:07:10",11,"Толпа вновь недовольно зашумела, но остановилась лишь одного взмаха руки пожилой эльфийки\n\n— Я дам вам шанс найти причины — говорит она, а на вытянутую руку спрыгивает ее птица, женщина подтягивает руку к себе и ласково гладит питомца",167805,null],[184129,"2026-09-01T14:18:05",5,"— Ква-шанс? Я уже ищу ответы, ты знаешь, где искать?",167805,null],[184131,"2026-09-01T14:18:53",11,"// ты же следопыт, бро, где твой азарт расследования",167805,null],[184135,"2026-09-01T14:21:01",11,"— Новых зверей у нас в поселение не появлялось, причина кроется не в городе — отвечает женщина — люди думают что виной всему вы",167805,null],[184160,"2026-09-01T14:37:44",11,"// нас осталось трое, предлагаю о времени договориться и поиграть нормально, когда вам будет удобно?",167805,null],[184163,"2026-09-01T14:39:38",5,"/ днём и вечером",167805,null],[184385,"2026-09-01T16:44:46",22,"- Малыш птичка говорил нам что-то о страшных птицах, что живут высоко в скалах, может нам стоит туда слазать и поискать ответы?",167805,null],[184543,"2026-09-01T17:30:05",11,"— Вы имеете ввиду Кетцалькоатлей? Лучше держаться от них подальше, они могут поднять вас в небо и сбросить вниз. — отвечает женщина",167805,null],[184554,"2026-09-01T17:34:48",22,"- Как они ведут себя в последнее время? И в целом как ведет себя местное зверье?\n\n*Венус описывает странности, которые с ними произошли за время путешествия по лесу*\n\n- Это нормальное поведение или... что-то не так?",184543,null],[184709,"2026-09-01T18:29:22",11,"Старушка рассмеялась когда ты рассказала про птиц ограбивших вас\n\n— Да это абсолютно нормально для них \n\nКогда же ты рассказала про последний бой она нахмурилась\n\n— Мутировавшие особи иногда встречаются, но что-то влияющее на температуру, магическое..? — она задумалась — за всю мою не короткую жизнь не доводилось слышать о подобном",167805,null],[184720,"2026-09-01T18:36:23",11,"— Признаться честно я знала о их приходе — она обратилась к жителям, а затем вновь обернулась к вам — но вот пришли ли вы вредить или помочь решать вам. Это всё что мне известно \n\nСтарушка подняла посох, а ее питомец вспорхнул с руки\n\n— Расходитесь, они не виноваты в исчезнувшей воде\n\nТолпа послушно убралась из дома, а Олани с отцом озадаченно уставились на вас\n\n— Теперь можем поговорить нормально. Мелиан, будь добр, приготовь нам завтрак. А ты, Олани, не беспокойся, тебе нужно отдохнуть — сказав это женщина закрыла дверь в комнату девушки и дождалась пока мужчина уйдет на кухню",167805,null],[184819,"2026-09-01T19:27:31",22,"Венус осталась возле старушки, ожидая своих товарищей.",167805,null],[185196,"2026-09-02T10:58:08",22,"//мне пока удобно в любое время, просто тегните когда соберетесь",184160,null],[185199,"2026-09-02T11:04:37",53,"благодарю за дивные угощения.\n*делаю небольшой поклон которому нехватает только подсветки с небп и фанфарной музыки для паладинской торжественности*",177116,null],[185200,"2026-09-02T11:05:11",53,"//древний серега пробудился и начал постепенно отвечать на сообщения",167805,null],[185201,"2026-09-02T11:05:18",5,"// давай давай ура",167805,null],[185202,"2026-09-02T11:06:45",53,"имя мне - Цет. попал я сюда... проснувшись после самого обычного дня. пологаю мои товарищи оказались здесь при тех же обстоятельствах.",177124,null],[185203,"2026-09-02T11:07:48",5,"Напуганный лягушонок уселся на мох и слушает Мелиан.\n\n— А меня зовут Ква-К'варсио",167805,null],[185205,"2026-09-02T11:10:09",5,"— Огненные ящеры, квоворю же. Они греют джунгли",184709,null],[185207,"2026-09-02T11:10:35",53,"*с аппетитом ем*",177376,null],[185208,"2026-09-02T11:12:02",53,"благодарю за гостеприимство. \n*еще один поклон*",177380,null],[185210,"2026-09-02T11:15:46",53,"что вы, не стоит. помогать раненым и заблудшим - наш долг.",177393,null],[185211,"2026-09-02T11:18:41",53,"тебе тоже спасибо. и удачного пути фаусту.//",177499,null],[185212,"2026-09-02T11:19:46",5,"Грунг оглянулся.\n\n— А куда исчезли Освальд и Фауст? Они ночью были здесь. С ними всё в кварядке?",167805,null],[185213,"2026-09-02T11:23:15",53,"доблесть не в показной силе, а в намеринии творить добро. да и не так уж я силен, как могло бы показатся. я лекарь, а не воин, пусть и вооружение мое хорошо. \n\n\n//ебать я чет сегодня паладинисто говорю",177665,null],[185236,"2026-09-02T11:29:34",53,"родом я из дальних морей. воды в них и правда прекрасны, но в шторма они и столь же опасны.",177678,null],[185239,"2026-09-02T11:30:11",53,"следует быть предельно аккуратными оказываясь в новых водах",185236,null],[185246,"2026-09-02T11:34:11",11,"// давай давай продолжай так гляди и дойдешь до последних сообщений когда-то и дальше продвинемся",185239,null],[185335,"2026-09-02T14:26:01",11,"// Сергей @elsio28 @lady_godzilla \nГотовы продолжать? Могу прямо сейчас",167805,null],[185341,"2026-09-02T14:31:34",11,"// так вот, котята, возвращаемся к разговору",167805,null],[185348,"2026-09-02T14:38:49",11,"Не успела глава ответить вам (проницательные герои ведь поняли что кого попало все горожане слушаться не будут?) как в дом семьи влетает ещё один эльф\n\n— Госпожа Анис! — он выглядит так будто бежал в спешке и говорит с отдышкой — пастухи ушедшие на рассвете вернулись без скота! Они потеряли почти всех пекарей и коров..! \n\n— Стой, успокойся — женщина останавливает его — Давай по порядку, что случилось?",167805,null],[185349,"2026-09-02T14:39:19",5,"— Ква-ква-кваровы...",167805,null],[185350,"2026-09-02T14:40:18",11,"— Почти все стадо — он останавливается что бы подышать, стоя хватаясь за колени, а затем вновь подымает голову — убежало в лес потому что эти лентяи уснули!",167805,null],[185351,"2026-09-02T14:40:26",53,"*достаю уже подготовленный комплект целителя*\nим требуется какая либо помощь?",185348,null],[185352,"2026-09-02T14:42:45",11,"Из-за входной двери доносится ещё чей-то голос, тот эльф так же прерывается на отдышаться\n\n— Да мы не виноваты, госпожа Анис, честно! Просто в какой-то момент всех нас одновременно потянуло в сон.. \n\nВторой эльф так же заваливается в дом, отец семейства уже явно недоволен происходящим проходным двором в своем жилье\n\nВсе выглядят здоровыми (для Сереги)",167805,null],[185353,"2026-09-02T14:43:14",11,"// жду вашего участия в разговоре, всех вас:3",167805,null],[185354,"2026-09-02T14:44:12",5,"— Сон? Я вот проснулся, а как заснул не помню, когда попал в это место",185352,null],[185355,"2026-09-02T14:45:28",11,"Пожилая эльфийка хватается за голову, на беднягу явно навалило много дел за один день",167805,null],[185357,"2026-09-02T14:45:51",5,"— Кворите, они убежали в лес? Я могу сходить за ними, вдруг кворовы пробудились!",167805,null],[185361,"2026-09-02T14:46:48",11,"— При всем моем уважение, лягушонок, я бы не хотела что бы твои лапки касались коров, нам они ещё живыми нужны — отвечает женщина намекая на твой яд",167805,null],[185362,"2026-09-02T14:47:18",53,"*подношу ей настойку от головных болей*\nбыть может пред тем как погрузится в сон вы узрели что то необычное?(не главе)\nвыпейте, это поможет от болей в голове(главе)",185355,null],[185363,"2026-09-02T14:47:28",11,"— Но он прав! Сон точно странный был, не могли же мы уснуть все одновременно просто так.. — добавляет пастух",167805,null],[185364,"2026-09-02T14:47:34",5,"— Не хотите квак хотите!\n\nЛягушонок надулся (буквально) и сидит на мхе, смотрит на остальных",167805,null],[185365,"2026-09-02T14:47:39",53,"//а как же перчатки?",185361,null],[185366,"2026-09-02T14:49:37",11,"— Благодарю — отвечает женщина, но не пьет, зелёное сияние исходящее с ее рук освещает бутылку на мгновение и только после этого она улыбается и делает пару глотков, возвращая тебе её",185362,null],[185367,"2026-09-02T14:49:58",11,"// а это не для вас квест\nТак что не квакайте тут",185365,null],[185372,"2026-09-02T14:52:22",53,"*убираю бутылек место*",185366,null],[185373,"2026-09-02T14:52:36",53,"//и больше его никто никогда не видел",185372,null],[185374,"2026-09-02T14:52:48",11,"— Хм.. если так подумать.. — пастух сделал глубокий выдох-вдох — да.. мы проходили мимо роз..\n\nАнис выглядит явно удивленной\n\n— Вот! Мы тоже удивились, тут розы обычно не растут.. вот мы и остановились у них, а затем как-то так в сон склонило.. не заметили как уснули — он пожимает плечами и огорчённо вздыхает \n\n// @lady_godzilla",185362,null],[185375,"2026-09-02T14:53:07",11,"// если не понял что она делала можешь кинуть анализ",185372,null],[185377,"2026-09-02T14:54:17",11,"— Значит почти все стадо пропало так ещё и воды нет.. У меня нет выбора кроме как просить помощи у вас, чужестранцы — Анис обращается к вам",167805,null],[185378,"2026-09-02T14:54:22",53,"//не, есть предположения, так что не буду",185375,null],[185380,"2026-09-02T14:54:40",11,"// ну мало ли, озвучь проверь) как хочешь",185378,null],[185381,"2026-09-02T14:55:05",53,"хмм...\n*вспоминает как их подруга поросла розами*",185374,null],[185384,"2026-09-02T14:55:36",11,"— А когда проснулись роз не было, представляете? — сказав это его взгляд упал на флорена — вот! Точно такие же розы как у неё!",185374,null],[185386,"2026-09-02T14:56:01",11,"// а вы что думаете я зря про преды спрашивала:3",167805,null],[185388,"2026-09-02T14:56:42",5,"— С водой помочь легко. Надо найти исток и отогнать огненных ящеров оттуда",185377,null],[185389,"2026-09-02T14:57:06",53,"мы будем рады вам помочь.",185377,null],[185391,"2026-09-02T14:57:27",53,"//если коровы вернутся забинтоваными  я не виноват",167805,null],[185393,"2026-09-02T14:58:30",11,"— Сможете справиться с этим? — спрашивает женщина водных созданий и косо смотрит на флорен",185388,null],[185396,"2026-09-02T14:58:59",5,"— Смогу, ква!",167805,null],[185406,"2026-09-02T15:01:17",11,"— Тогда удачи вам и если справитесь обещаю отблагодарить чем сможем \n\nЛюбопытный птенец госпожи Анис делает круг вокруг вас и возвращается с ней",167805,null],[185408,"2026-09-02T15:01:34",11,"// такс ну на этом предлагаю вам двоим выйти, а с Полиной мы продолжим позже",167805,null],[185410,"2026-09-02T15:03:03",5,"К'варсио выскакивает на улицу.\n\n— А где река?",167805,null],[185411,"2026-09-02T15:03:32",11,"К'варсио и Цет выходят на улицу. Солнце уже давно встало, но пока утро — жара ещё не донимает. Перед вами всё тот же вид, но менее красивый — вместо водопадов лишь каменные пороги. А остатки воды понемногу высыхают на камнях",167805,null],[185412,"2026-09-02T15:03:50",11,"// с чего же герои начнут свое расследование",167805,null],[185413,"2026-09-02T15:04:49",5,"— Цет? Я думаю надо идти вдоль реки, что-то поймём",167805,null],[185414,"2026-09-02T15:05:25",11,"Пороги выглядят крупными, ведут вверх, но лягушонок присмотревшись оценит что прыгать он сможет без труда по ним",167805,null],[185418,"2026-09-02T15:06:13",5,"/ жду цета",167805,null],[185424,"2026-09-02T15:08:17",53,"хмм.. думается мне это может сработать, однакож стато бежало в лес.",185413,null],[185425,"2026-09-02T15:09:02",11,"// вы не стадо ищете, братан",167805,null],[185426,"2026-09-02T15:09:26",5,"— Мы идём не за стадом, а за водой\n\nС этими словами грунг запрыгнул на первый порог",167805,null],[185428,"2026-09-02T15:10:02",53,"//пельмкешки пытались доказать обратное",185425,null],[185429,"2026-09-02T15:10:04",11,"Лягушонок смотрит на тритона сверху вниз. Высота здесь повыше его головы, но руками к порогу дотянется, остальные примерно такие же +-",167805,null],[185430,"2026-09-02T15:10:16",11,"// за это я их накажу тем что сьем",185428,null],[185432,"2026-09-02T15:10:26",53,"поддерживаю//",185430,null],[185433,"2026-09-02T15:13:04",53,"помнится мне, там где был тот огненый зверь была вода. можем опробовать сыскать ее там",185429,null],[185434,"2026-09-02T15:13:48",11,"// кинь анализ",185433,null],[185436,"2026-09-02T15:14:02",53,"//+0 :D",167805,null],[185437,"2026-09-02T15:14:08",11,"Да звучит как отличная идея, Цет в это верит",185435,null],[185438,"2026-09-02T15:14:11",5,"— Но кводу нужно привести сюда!",185433,null],[185439,"2026-09-02T15:15:11",53,"хмм... это осложняет дело. \n*выпиваю какую то настоечку для благоразумия*",185438,null],[185441,"2026-09-02T15:15:38",22,"- Всех потянуло в сон..\n\nВенус задумалась.\n\n- Подскажите, какие запахи вы слышали перед сном? Что последнее вам особенно запомнилось?\n\nВенус долждалась их ответа и продолжила.\n\n- Розы значит.. Они  были похожи... На эти?\n\nДевушка слегка разводит подолы верхнего платья в стороны, демонстрируя россыпь ароматных роз, которые начали на ней цвести со вчерашнего дня.\n\n- Странно, но мои товарищи не засыпали от их аромата, а когда я прибыла в ваш лес, роз на мне еще не было. Послушайте! Последние запахи были.. такими?\n\nВенус предлагает один из цветков со своего платья. Она не отрывает его, ножка цветка удлинилась, до ее ладони.",185352,null],[185442,"2026-09-02T15:15:59",22,"//я если пропадаю - не теряйте меня, реакция будет на все 👌",167805,null],[185443,"2026-09-02T15:16:17",11,"Вы слишком долго держались на одном месте и привлекли внимание птицы похожей на фламинго, пока Цет рылся в поисках своих скляночек птица клюкнула его в ногу будучи привлеченной запахом рыбы",167805,null],[185444,"2026-09-02T15:17:01",5,"— Цет, сзади! Беги!",185443,null],[185445,"2026-09-02T15:17:47",11,"Пастух кивает и нерешительно, но с одобрительным кивком Анис принюхивается\n\n— Угу.. очень похожий, но более резкий запах был..",185441,null],[185447,"2026-09-02T15:18:08",11,"// а чё он зевает 1 урона ему сразу колющий что бы быстрее реагировал 😡",185444,null],[185448,"2026-09-02T15:18:58",53,"нгх.. \n*отскакиваю от птицы, одежда трансформируется в доспех*",185443,null],[185449,"2026-09-02T15:19:32",11,"Птица с испугом улетает, рыбы поесть не удалось, разочарование",167805,null],[185450,"2026-09-02T15:19:43",5,"Лягушонок запрыгивает на следующий порог, подальше от фламинго",167805,null],[185451,"2026-09-02T15:20:07",53,"не припомнишь ли ты случаем, такие птицы обитают не у воды?",167805,null],[185452,"2026-09-02T15:20:21",11,"вы оба таких птиц раньше не видели",167805,null],[185453,"2026-09-02T15:20:25",53,"//что за пороги 🤔",185450,null],[185456,"2026-09-02T15:20:40",5,"— Нет, таких не знаю. Беги от неё!",167805,null],[185459,"2026-09-02T15:21:09",11,"Вот арт города с водой, водопадики видишь? Там сейчас сухо и только камни по которым вода текла остались",185453,null],[185461,"2026-09-02T15:22:04",53,"//аа, теперь поняф",167805,null],[185462,"2026-09-02T15:22:12",53,"что же, в путь.",167805,null],[185463,"2026-09-02T15:22:31",53,"//ну тогда да, надо бы сгонять к началу реки",185461,null],[185465,"2026-09-02T15:23:16",11,"Лягушонок уже на ступеньку вперёд впереди тебя, как забираться будешь?",185462,null],[185472,"2026-09-02T15:27:04",53,"сможешь удержать меня коли подам веревку?",185465,null],[185473,"2026-09-02T15:27:48",5,"— Смогу, я сильный рыцарь!",167805,null],[185474,"2026-09-02T15:27:56",53,"*подаю веревку*",185473,null],[185475,"2026-09-02T15:28:10",5,"Грунг крепко держит её",167805,null],[185477,"2026-09-02T15:28:20",11,"// бросок силы/атлетики",167805,null],[185478,"2026-09-02T15:28:28",53,"*взбираюсь по веревке*",185475,null],[185479,"2026-09-02T15:28:44",5,"/r +5",167805,null],[185481,"2026-09-02T15:29:03",11,"Веревка выскользает из лапок",167805,null],[185483,"2026-09-02T15:29:47",11,"А Цет приземляется на копчик обратно \n\nЗдесь не высоко, так что не так больно, сколько обидно",167805,null],[185484,"2026-09-02T15:30:29",53,"*броня погнулась*",185483,null],[185485,"2026-09-02T15:30:40",5,"— Прости! Я знаю другой способ!",167805,null],[185486,"2026-09-02T15:31:12",53,"не беспокойся, друг.  что же за способ ты знаешь?",185485,null],[185488,"2026-09-02T15:31:37",5,"Лягушонок скидывает Цету копьё.\n\n— Держи его крепко и прыгай. Я магически усилю твой прыжок\n\n/ хочу дать возвратному копью команду вернуться и дёрнуть цета вверх так",167805,null],[185489,"2026-09-02T15:32:02",11,"// прикольно давай",167805,null],[185490,"2026-09-02T15:32:10",5,"\"Копьё возврата\"\n(Необычный магический предмет, требует настройки)\n\nДлинное копъе с дополнительным свойством \"Метательное 40/120\".\n\nЕсли вы настроенны на предмет его можно вернуть его в руку \"бонусным действием\" если между вам нет неприодолимой преграды.\n\nЕсли противник держит копьё когда вы пытаетесь его вернуть он должен совершить проверку атлетики сл 16, при провале он не удерживает копьё и его толкает на 5 футов в вашем направлении.",167805,null],[185492,"2026-09-02T15:32:15",53,"*прыгаю держась за копье*",185488,null],[185493,"2026-09-02T15:32:44",53,"//вот так и летают ведьмы на метлах",167805,null],[185494,"2026-09-02T15:32:45",5,"Грунг двигает лапками, тиара на голове сверкает и Цета сильно дёргает в сторону грунга",167805,null],[185495,"2026-09-02T15:33:02",11,"Смекалкой лягушонка вы оба добираетесь наверх где дно реки становится ровным и по нему можно спокойно идти, на уровень ниже вас стоит один житель и крутит у виска\n\n— Мосты здесь для кого..",167805,null],[185496,"2026-09-02T15:33:35",53,"//для адекватных",185495,null],[185497,"2026-09-02T15:34:00",53,"идем же, кварсио.",185495,null],[185498,"2026-09-02T15:34:29",53,"*двигаюсь вперед внимательно оглядываясь по сторонам и сверкая свой погнутой в районе копчика броней*",167805,null],[185500,"2026-09-02T15:34:34",11,"// напомни мне потом, Эл, тебе +10 опыта за нестандартный подъем накинуть \nЗа смекалку",167805,null],[185501,"2026-09-02T15:34:47",5,"Следопыт идёт вдоль реки, внимательно ища следы на земле",167805,null],[185503,"2026-09-02T15:35:21",53,"//быть может какой то бобр-гоблин построил плотину 🤔",167805,null],[185504,"2026-09-02T15:35:46",11,"Солнце подымается, а вместе с ним возвращается и жара. Вы идете по дну реки которое начало высыхать из-за палящего солнца, теперь здесь вместо воды лишь потрескавшийся ил и высыхающие водоросли. Это была определенно полноводная река, теперь же - глиняная тропа, петляющую среди гигантских папоротников и переплетенных корней. Воздух пахнет прелой листвой и гниющей рыбой, которую вы видели по дороге, застрявшую в пересыхающих лужах. \n\nВскоре впереди начинает нарастать странный, глухой гул.",167805,null],[185505,"2026-09-02T15:36:19",5,"— Ил съедобный? Я помню, ты собирал!",167805,null],[185506,"2026-09-02T15:36:43",11,"// ил это земля, водоросли тут не морские так что не знаю знает ли он",167805,null],[185507,"2026-09-02T15:37:23",53,"не знаю, водоросли тут незнакомы мне. однакож...\n*срезаю несколько водорослей собирая образцы*",185505,null],[185510,"2026-09-02T15:38:56",11,"// хм..",167805,null],[185511,"2026-09-02T15:39:03",11,"// брось ка д100",167805,null],[185512,"2026-09-02T15:39:05",53,"раз уж путь наш будет долог, поговорим о прошлом?",185505,null],[185516,"2026-09-02T15:39:29",11,"Повезло, не ядовитые",167805,null],[185517,"2026-09-02T15:39:31",53,"аль о грядущем?",185512,null],[185520,"2026-09-02T15:39:42",5,"— Мы можем, но вот я уже сохну!\n\nЛягушонок из бурдюка поливает себя водой",185512,null],[185521,"2026-09-02T15:39:47",11,"Свойства как и свойства тех листьев что у тебя в сумке ты не знаешь",167805,null],[185522,"2026-09-02T15:39:54",53,"*поняв что птицы нас не атакуют одежда вновь становистя врачебной*",167805,null],[185524,"2026-09-02T15:40:29",5,"— Ещё этот звук!\n\n*прислушивается к гулу*",167805,null],[185528,"2026-09-02T15:40:46",53,"//в водоеме была преснач или соленая вода? там где горячая пара была",185521,null],[185530,"2026-09-02T15:40:58",11,"// поболтайте, я не тороплю, а на звук можете кинуть анализ с низкой сл",167805,null],[185533,"2026-09-02T15:41:22",11,"// солёная",185528,null],[185536,"2026-09-02T15:41:37",5,"/r -1",185530,null],[185544,"2026-09-02T15:42:09",53,"*протягиваю флягу*\nесть эта вода. однакож она солена и многим будет не по вкусу.",185536,null],[185545,"2026-09-02T15:43:13",5,"— Что с этой кводой? У меня ещё осталась вкусная в бурдюке",185520,null],[185546,"2026-09-02T15:43:23",11,"Очень похоже на тот звук что издавали вчерашние водопадики, только громче. К'варсио делает вывод: «падает вода»",185538,null],[185547,"2026-09-02T15:43:50",11,"// а ещё ты следы искал да.. как следопыт можешь кинуть с преимуществом выживание",167805,null],[185549,"2026-09-02T15:44:09",5,"— Я слышу воду! Кводопад, как у твоего квеликого!",167805,null],[185550,"2026-09-02T15:44:55",5,"/r +d20+3",185547,null],[185552,"2026-09-02T15:45:51",53,"великолепно, нам следует идти туда.",185549,null],[185553,"2026-09-02T15:45:57",53,"впрочем...",185552,null],[185554,"2026-09-02T15:46:12",53,"//умные мысли приследовали меня, но я был быстрее",185553,null],[185556,"2026-09-02T15:46:29",53,"//извините если пиздец сильно туплю",167805,null],[185557,"2026-09-02T15:46:35",11,"Лягушонок обращает внимание на кучку водорослей, их слегка что-то примяло.. будто бы наступил на них кто\n\nПрисмотревшись ближе ты видишь следы очень похожие на твои собственные, но ты ведь тут не топтал..?",167805,null],[185559,"2026-09-02T15:47:47",5,"К'варсио склонился над водорослями.\n\n— Следы как у меня. Возможно здесь есть мои сородичи! Надо быть начеку, они часто дикие",167805,null],[185561,"2026-09-02T15:48:09",11,"// и так идете дальше вдоль реки или по следам?",167805,null],[185563,"2026-09-02T15:48:40",5,"— Давай проверим следы сначала!",167805,null],[185567,"2026-09-02T15:49:40",53,"*на всякий случай пометил след пахучей мазью яркого цвета*",185559,null],[185568,"2026-09-02T15:49:53",53,"*киваю и иду за пытателем следов*",185563,null],[185569,"2026-09-02T15:50:20",5,"К'варсио идёт по лягушачьи следам",167805,null],[185571,"2026-09-02T15:50:27",53,"//типо красный штрих шириной в два палтца",185567,null],[185578,"2026-09-02T15:52:50",11,"Как идете?",167805,null],[185581,"2026-09-02T15:53:54",5,"Настороженно, оба меча в руках",167805,null],[185582,"2026-09-02T15:54:04",11,"// кто спереди кто сзади?\n\nВ паровозике",167805,null],[185583,"2026-09-02T15:54:14",5,"Спереди лягушка",167805,null],[185585,"2026-09-02T15:57:05",11,"К'варсио выслеживает цепочку странных перепончатых лап.\n\nгрунг, идущий впереди уверенно прорубает путь сквозь плотную стену зелени. Его влажная кожа поблескивает в редких лучах солнца, пробивающихся сквозь кроны, а трехпалые лапы то и дело мягко отодвигают массивные, сочные листья папоротников, которые периодически прилетают Цету в лицо.",167805,null],[185587,"2026-09-02T15:58:44",11,"Его товарищ сосредоточен на цепочке загадочных следов.\n\nШум водопада и пение птиц начало разбавляться ещё каким-то звуком.. тоже гулом, но таким писклявым, неприятным..",167805,null],[185588,"2026-09-02T15:59:21",11,"Вы начинаете ощущать кровососов на себе, но ведь где эти насекомые там и вода, верно?",167805,null],[185590,"2026-09-02T16:00:34",11,"Так, спустя пару минут, вы начинаете чувствовать воду под ногами, прямо тут, посреди зарослей джунглей..\n\nСледы теряются в ней, но отодвинув ещё один папоротник К'варсио видит деревья посреди воды",167805,null],[185591,"2026-09-02T16:00:51",11,"Судя по всему тот кто шел сюда плыл",167805,null],[185593,"2026-09-02T16:01:34",5,"Без сомнений К'варсио плюхается в воду",167805,null],[185594,"2026-09-02T16:01:53",5,"/ большая... Лужа?",167805,null],[185595,"2026-09-02T16:02:17",11,"Мутно, много зарослей, мало что видно",167805,null],[185596,"2026-09-02T16:02:24",11,"// Сергей что делаешь?",167805,null],[185600,"2026-09-02T16:04:05",5,"— Он плавает, как и я! Следы должны продолжится где-то на суше. Подожди меня минуту!\n\nК'варсио плывёт по воде в том же направлении, что шёл раньше. В течение минуты",167805,null],[185622,"2026-09-02T16:13:48",53,"//я позади",185582,null],[185629,"2026-09-02T16:15:09",11,"Так и что делаешь",185622,null],[185632,"2026-09-02T16:16:35",53,"вот мы и нашли воду.",185593,null],[185633,"2026-09-02T16:16:58",11,"Эл, ты под водой плывешь или над?",167805,null],[185634,"2026-09-02T16:16:58",5,"— Да, но как починить реку?",185632,null],[185636,"2026-09-02T16:17:10",53,"*ныряю за лягушенком и уже более своболно оглядываюсь в то время как мой костюм претерпевает изменения*",185596,null],[185637,"2026-09-02T16:17:12",5,"Над",185633,null],[185638,"2026-09-02T16:17:21",53,"//а я под",185637,null],[185639,"2026-09-02T16:17:33",11,"Прежде чем нырнуть ты чувствуешь укол в пятку..",185636,null],[185641,"2026-09-02T16:17:52",53,"*смотрю что меня кольнуло*",185639,null],[185643,"2026-09-02T16:18:00",11,"Спас тела",167805,null],[185646,"2026-09-02T16:18:19",5,"/ комары...",185641,null],[185648,"2026-09-02T16:18:21",11,"червь что пытается заползти в землю под мутной водой",185641,null],[185652,"2026-09-02T16:19:15",53,"+0 //",185651,null],[185656,"2026-09-02T16:19:26",11,"Червь почему-то начинает двоится в глазах Цета.. да и голова как-то кружится\n\nТебе истощение+отравление",167805,null],[185659,"2026-09-02T16:19:38",11,"/roll d6+1",167805,null],[185661,"2026-09-02T16:19:49",11,"// и 2 урона один колющий 1 ядом",167805,null],[185662,"2026-09-02T16:20:11",53,"сс... что тоту укусило ме..ня.. *голос постепенно замедляется*",185648,null],[185663,"2026-09-02T16:20:34",11,"// кроме этих состояний ничего если что) просто нарративно описала",185656,null],[185664,"2026-09-02T16:20:55",5,"К'варсио бьёт лапками по воде.\n\n— Всплывай, тут слишком мутно!",167805,null],[185665,"2026-09-02T16:21:07",11,"// а это недалеко от суши ещё было, у тебя все ок) возможно",167805,null],[185666,"2026-09-02T16:21:40",11,"К'варсио чувствует как возле него под водой что-то проплыло",167805,null],[185667,"2026-09-02T16:22:41",5,"*пытаюсь по силе вибраций воды определить размер существа*",185666,null],[185670,"2026-09-02T16:23:00",53,"*мое плаванье стало чуть кривее, а голова то и дело начала задевать линию воды*",185663,null],[185671,"2026-09-02T16:23:32",11,"// анализ с преимуществом",185667,null],[185672,"2026-09-02T16:24:01",5,"/r +d20-1",167805,null],[185674,"2026-09-02T16:24:17",11,"Твой размер, ты это чувствуешь",167805,null],[185675,"2026-09-02T16:24:50",22,"//я так переживаю за вас 😨",167805,null],[185676,"2026-09-02T16:25:14",11,"// а кто будет переживать за тебя 😈",167805,null],[185678,"2026-09-02T16:25:43",5,"— Цет, высунь голову на секунду из воды...",167805,null],[185679,"2026-09-02T16:25:48",11,"// червя атаковать не пытаетесь?",167805,null],[185680,"2026-09-02T16:26:29",5,"Дождавшись, когда Тритон послушается, к'варсио прикасается к тиаре на голове.\n\nВ метре воды под ним создаётся оглушающий раскат грома.\n\n/ Чудотворство",167805,null],[185681,"2026-09-02T16:26:45",11,"// оно урон наносит? Или только звук",167805,null],[185682,"2026-09-02T16:27:12",5,"/ нет, звук",167805,null],[185683,"2026-09-02T16:27:25",11,"// ахахахах как же я угораю с этой ситуации..",167805,null],[185695,"2026-09-02T16:30:54",11,"Лягушонок касается тиары, она светится, а из под воды звучит заглушенный ее толщью звук\n\nРядом плавает дурно себя чувствующий тритон\n\nИ..\n\nИз под воды выныривает оглушенная, но дико злая..",167805,null],[185697,"2026-09-02T16:30:58",11,"// как думаете что?",167805,null],[185699,"2026-09-02T16:31:16",5,"/ жаба",167805,null],[185702,"2026-09-02T16:32:07",53,"*голова ненадолго выныривает*",185678,null],[185704,"2026-09-02T16:32:31",11,"Утка!",167805,null],[185706,"2026-09-02T16:32:37",53,"//а может и тонет XD",185695,null],[185707,"2026-09-02T16:32:39",11,"Спас харизмы с обоих",167805,null],[185710,"2026-09-02T16:33:00",53,"+3//",167805,null],[185711,"2026-09-02T16:33:03",11,"И следом инициативу😁",167805,null],[185712,"2026-09-02T16:33:03",53,"//18",167805,null],[185713,"2026-09-02T16:33:13",53,"//а, и я отравлен же?",185711,null],[185716,"2026-09-02T16:33:22",53,"//тогда вот помеха",185715,null],[185717,"2026-09-02T16:33:23",11,"// на 24 часа, друг мой",185713,null],[185718,"2026-09-02T16:33:32",5,"/r",167805,null],[185722,"2026-09-02T16:33:41",5,"/r +2",185711,null],[185724,"2026-09-02T16:34:21",5,"/ отравление не влияет на спасы",185716,null],[185725,"2026-09-02T16:34:43",53,"а, оке//",185724,null],[185726,"2026-09-02T16:34:47",53,"//тогда 18 :3",167805,null],[185727,"2026-09-02T16:34:47",11,"Грозная утка-пингвин, размером с К'варсио выныривает из воды пулей, вы полностью видите её размер и так же размер ее немалых когтей\n\nОна приземляется обратно в воду и всплывает как подобает утке\n\nВас это приводит в УЖАС (на ход)",167805,null],[185730,"2026-09-02T16:35:16",53,"//и иня тогда 2",167805,null],[185733,"2026-09-02T16:35:46",11,"Порядок:\n\nК'варсио \nБейпяозавр\nЦет",167805,null],[185735,"2026-09-02T16:36:19",11,"И ходит испуганный лягушонок. Уточка впереди тебя, в 10 футах, Цет сзади в 10 и вы все на плаву",167805,null],[185738,"2026-09-02T16:37:06",5,"/ нееет, я не хочу бить бейпи(",167805,null],[185739,"2026-09-02T16:37:22",11,"// это должна была быть просто случайная встреча, но ты сам его напугал) впрочем вы волны делать что хотите, я просто угораю с ситуации",185738,null],[185740,"2026-09-02T16:38:38",5,"— Ящер-чудище! Кваааа!\n\nПаникующий лягушонок плывёт от бейпика зигзагами, иногда подныривая в воду.\n\n/ отплыл назад на 15 футов из-за траектории, уклонение",167805,null],[185741,"2026-09-02T16:38:48",5,"/ ход",167805,null],[185743,"2026-09-02T16:40:33",11,"Злая утка ныряет под воду и плывёт следом за убегающим, но между вами всё то же расстояние.. он медленный😢",167805,null],[185744,"2026-09-02T16:41:09",11,"// в пяти футах от Цета, под водой\n\nНу и ход Цета соответственно",167805,null],[185752,"2026-09-02T16:51:27",53,"//пиздец меня ирл ебошит щас",167805,null],[185753,"2026-09-02T16:51:39",5,"/ что с тобой(",185752,null],[185754,"2026-09-02T16:51:54",53,"//да рубит жестко",185753,null],[185755,"2026-09-02T16:52:04",53,"//поел и после этого началось",185754,null],[185760,"2026-09-02T16:53:50",11,"// ладно отбой, малютка спать идёт",167805,null],[187466,"2026-09-03T15:32:46",11,"// @lady_godzilla занята сейчас? Давай перейдём к тебе?",167805,null],[187474,"2026-09-03T15:35:24",22,"|я готова",187466,null],[187478,"2026-09-03T15:36:48",11,"— Судя по всему вы леди.. как я могу вас называть..? — обращается к тебе пожилая эльфийка",167805,null],[187480,"2026-09-03T15:37:27",22,"- Венус, просто Венус.\n\nУлыбнулась флорен, чуть сжав руками подол платья.",187478,null],[187491,"2026-09-03T15:40:00",11,"— Приятно познакомиться, Венус, я - Анис — женщина поклонилась тебе в ответ — старшая и единственный друид в этом отдаленном городе. Так вот на счёт роз.. Они обычно не растут в наших джунглях, вам что-то известно о них?",167805,null],[187496,"2026-09-03T15:42:43",22,"- Нет, я сама была приятно удивлена, когда они на мне расцвели. Они так прекрасны и так дивно пахнут! Раньше на мне были только колючки и грибы. Я не могла и мечтать о том, что на мне могут быть розы!\n\nВенус искренне улыбалась.\n\n- Вы так спрашиваете.. С этими цветами что-то не так?\n\nВенус нахмурилась и чуть погрустнела.",167805,null],[187497,"2026-09-03T15:45:03",11,"— Нет-нет, они чудесны.. просто это необычное явление, а то что они исчезли когда пастухи проснулись.. — она вздохнула и погладила своего фамильяра — я не могу покинуть город, но вы.. вы ведь тоже друид, я чувствую это, не могли бы вы исследовать это необычное природное явление?",167805,null],[187513,"2026-09-03T15:50:03",22,"- Да, конечно, я очень люблю природу и хочу познавать ее тайны и дальше. Вы расскажете мне подробнее?",167805,null],[187520,"2026-09-03T15:52:10",11,"— Я могу рассказать вам по дороге — отозвался стоящий сзади эльф-пастух — и показать место где мы уснули\n\nОн немного успокоился отдышавшись, но выглядел обеспокоенным, терять скот ему явно не хотелось",167805,null],[187585,"2026-09-03T16:11:13",22,"- Да, отлично, давайте все внимательно осмотрим.\n\nГлаза Венус зажглись любопытством.\n\n- А такое часто происходит? Всегда одна и та же реакция - сон? Или цветы приносят разные эффекты?",167805,null],[187670,"2026-09-03T16:44:57",11,"Вы выходите на улицу вместе с эльфом-пастухом, молодым на вид, он ведёт тебя куда-то, но по пути ты видишь что реки действительно пересохли\n\n— А? Нет, мы впервые увидели розы в лесу, поэтому и удивились.. — он разводит руками оборачиваясь к тебе — это был вот такой воот куст! Большой, да. Прямо посреди поляны по которой мы каждый день проходим, представляете? Откуда он там мог взяться за день? \n\nОн вновь обернулся и пошел прямо.\n\nПуть был лёгкий, никаких веток и папоротников закрывающих обзор, все облагорожено и вытоптано, видно что тут действительно ходят часто\n\n— И вот мы решили взглянуть.. эм, может это была плохая идея? Но любопытство взяло свое. Розы пахли приторно, а перед тем как потерять сознание я почувствовал такой, знаете.. странный запах, будто метала\n\nОн снова останавливается и протягивает тебе руку. Видно что на пальце след от укола.\n\n— У всех у нас были вот такие вот следы, будто мы укололись шипами роз, не только у меня! Так что это точно не совпадение, я уверен — и эльф немного подуспокоив свой торопливый тон вновь пошел по пути — надеюсь ничего не забыл, вы спрашивайте если ещё что интересно",167805,null],[187687,"2026-09-03T17:16:22",22,"- Ого... как интересно..\n\nВенус внимательно изучает укол и сравнивает его с уколом от обычной розы.",167805,null],[187689,"2026-09-03T17:16:27",22,"/r +5",167805,null],[187694,"2026-09-03T17:17:42",22,"Потом она осматривает то место, где до этого росли розы.\n\nФлорен попускается на колени, будто бы зарываясь в землю, закрывает глаза и пытается почувствовать корни куста, а также корни других растений, которые обплетают тут все вокруг.",167805,null],[187695,"2026-09-03T17:17:45",11,"// а чего конкретно бросок? Характеристики",167805,null],[187697,"2026-09-03T17:17:59",22,"//восприятие",187695,null],[187704,"2026-09-03T17:18:54",22,"/r +5 Выживание",187694,null],[187710,"2026-09-03T17:19:26",22,"- Тут так много жизни! Что дух захватывает!",167805,null],[187711,"2026-09-03T17:20:20",11,"На первый взгляд просто обычная царапина, но если всмотреться точно можно определить что укол шипом, а ещё.. тебе показалось что вены на пальце эльфа внезапно стали пурпурными будто бы в них что-то протекло..?",187697,null],[187719,"2026-09-03T17:25:47",11,"— Вот это место — эльф указывает на место возле двух деревьев на краю полянки \n\nОсмотрев его, тебе кажется что там ничего не обычного, ни следа, но.. в момент сверху на тебя что-то падает, лёгкое, ты даже не услышала, только едва почувствовала",187694,null],[187722,"2026-09-03T17:27:57",22,"- Ох, кажется эти цвета ядовиты не только своей пыльцой...\n\nФлорен с жалостью посмотрела на пастуха.\n\n- Пожалуйста, будьте осторожны! Я вижу, что следы яда еще у вас остались, если вам будет нездоровиться - позовите меня, я осмотрю вас тщательнее. Обычно розы так себя не ведут. Это неправильные розы!\n\nВозмущенно воскликнула девушка.\n\n- Мне кажется, что этот странный куст был лишь приманкой для вас! И возможно, что другое растение, как-то выкачало всю воду своими корнями... Нужно исследовать русло реки..\n\n- А?!\n\nИспуганно воскликнула девушка и обернулась, когда почувствовала касание.",167805,null],[187743,"2026-09-03T17:38:56",11,"Эльф что-то отвечал тебе стоя где-то сбоку, но вмиг он и пение птиц затихло\n\nСтоило тебе обернуться и то что коснулось тебя упало наземь, под твои ноги. Это был крупный лепесток розы, багровый, с тонкими пульсирующими прожилками уже знакомого тебе пурпурного цвета",187722,null],[187764,"2026-09-03T18:26:02",22,"- Красивый...\n\nВенус наклонилась и подняла его.",167805,null],[187771,"2026-09-03T18:45:23",11,"Подняв лепесток ты чувствуешь что в привычном зелёном своде джунглей что-то сильно изменилось. Как будто сама ткань пространства.. А так же Венус чувствует на себе незримый, удушающе тяжёлый и величественный взор чего-то знакомого..",187764,null],[187780,"2026-09-03T18:47:25",22,"- Невероятно...\n\nБережно прижав лепесток к груди, девушка осмотрелась. Она внимательно посмотрела на место, где был ранее куст и направилась в сторону джунглей, словно завороженная.",167805,null],[187810,"2026-09-03T19:12:56",11,"Небо над поляной окрасилось в глубокий, тревожный багряно-пурпурный цвет, но такой знакомый тебе.. Это не просто смена погоды — это материальное воплощение гнева и страсти.\n\nПастух лежит у дерева, его оплетает лоза\n\nСтоит тебе сделать шаг на выход как ты ощущаешь лозы под своими ногами, что-то не даёт тебе уйти и в этот же миг кора дерева напротив тебя как будто бы расступается жидкими волнами, а из них появляется большой бутон: он распускается и увядает, пока из него вытягиваясь является дриада. Сквозь глубокие трещины в её древесине бешено пульсируют ядовито-пурпурные магические прожилки, а в щелях, на месте глаз, пылает пурпурное пламя.\n\n— Я ждала встречи с тобой, Венус, так вот как выглядит та кто заменила меня в саду её величества.. — дриада выходит из померкшей розы",187780,null],[187913,"2026-09-03T19:38:06",22,"- Приветствую, но боюсь, твоего имени я не знаю.\n\nВенус мягко улыбнулась.\n\n- Как видишь, теперь заменили и меня. Любовь госпожи переменчива, словно ветер. Твои розы... И ты сама.. так прекрасны... И опасны... Почему ты вредишь этим людям? Они тебя чем-то расстроили?\n\nПурпурный свет, заливающий всё вокруг, отозвался в жилах Венус знакомой, пьянящей магией мира фей. Она опустила взгляд на оплетённого лозой пастуха, а затем снова, с еще большим восхищением, посмотрела на дриаду - прямо в щели, откуда пылало пурпурное пламя.\n\nФлорен тихо выдохнула и сделала шаг навстречу и позволив лозам лишь слегка прикоснуться к её голеням.\nЕё голос звучал бархатисто и неторопливо. Венус медленно поднесла руку к собственной груди, где под бледной зелёной кожей бьётся то же самое фейское естество.\n\n- Я чувствую тебя, я слышу твой гнев... Он пахнет так ярко и прекрасно: приторная сладость и железистые нотки крови. Ох, право, это самый прекрасный и ядовитый аромат, который я встречала за все свои скитания.",167805,null],[187962,"2026-09-03T19:51:51",11,"// кинь на убеждение",187913,null],[188034,"2026-09-03T20:11:54",22,"/r",187962,null],[188037,"2026-09-03T20:12:15",22,"/не будет у меня подружки дриады😭",167805,null],[188059,"2026-09-03T20:17:33",11,"— Заменили? — она с сомнением посмотрела на тебя и не отводя взгляд добавила — он спит, эльфы меня не интересуют и её тем более.. \n\nДриада отвернулась и сделала несколько шагов в другом направлении, пытаясь выйти с поляны как и Венус, но её корнистые ноги так же оплели тернии\n\n— Она наблюдает за этой поляной, ты ведь тоже ощущаешь это \n\nШелестом листьев раздался женский величественный смех\n\n— Мое имя - Сериче. Я поклялась на верность Королеве человеческими веками назад и я буду делать всё что бы удовлетворить её желание",187913,null],[188063,"2026-09-03T20:18:34",11,"Сериче делает шаги обратно и шипастые лозы отпускают её\n\n— Я буду драться с тобой не используя ту же магию что на эльфов. \n\n// Инициатива",167805,null],[188239,"2026-09-03T21:10:48",11,"// Поль, кинь инициативу и скажи когда завтра днём тебе будет удобно отыграть бой активно, просто с перерывами ходить я так не могу.. мне это не нравится и социалку я ещё могу терпеть, без интереса к игре, но вот бой без динамики это будет нечто",167805,null],[188393,"2026-09-03T21:44:10",22,"//сорри, я по вечерам частично доступна, по факту только в отражениях боевку кидала, а социалку специально оставляла на момент, когда смогу вдумчиво описать действия. Жаль заромансить не получилось дриаду",188239,null],[188394,"2026-09-03T21:44:18",22,"/r +2",188063,null],[188401,"2026-09-03T21:45:19",22,"- Мне жаль, что нам придется сражаться, Сериче, а ведь мы... Мы могли вырастить свой собственный сад.\n\nВенус грустно покачала головой и стала обращаться медведицей.",188059,null],[188406,"2026-09-03T21:47:26",11,"// да Эля говорила что ты более днями активна, поэтому и предлагаю перенести на завтра и отыграть бой активно.",188393,null],[188408,"2026-09-03T21:47:57",11,"// где-то после 12 тебе нормально будет?",167805,null],[188419,"2026-09-03T21:50:17",22,"/да отлично",188408,null],[189030,"2026-09-04T11:24:44",11,"// напомни свой КД пожалуйста в форме медведя и твой ход",188419,null],[189033,"2026-09-04T11:25:35",11,"// поле боя",167805,null],[189034,"2026-09-04T11:26:36",22,"ХП 34\nКБ 11\nМультиатака. Две атаки: одну укусом, и одну когтями.\nУкус. +6, . Попадание: Кол урон 8 (1к8 + 4).\nКогти. +6, Попадание: Руб урон 11 (2к6 + 4).",189030,null],[189035,"2026-09-04T11:27:22",22,"- Я правда не хочу этого делать..\n\nВенус превращается в цветущую медведицу и нападает на явно агрессивную дриаду.",167805,null],[189036,"2026-09-04T11:28:05",22,"/r +6 укус\n/r d8+4\n/r +6 царапа\n/r 2d6+4",167805,null],[189038,"2026-09-04T11:28:12",22,"/ход",167805,null],[189041,"2026-09-04T11:29:01",11,"первая атака медведя попадает в плечо, наносит урон, но как только ты пытаешься убрать лапу, напоследок тебя пронизывают шипы",189037,null],[189043,"2026-09-04T11:29:24",11,"/roll d6 урона ядом реакцией",167805,null],[189047,"2026-09-04T11:29:54",11,"В лапку мишки попадает всё тот же пурпурный яд",167805,null],[189048,"2026-09-04T11:31:07",11,"/roll d20 \n/roll d20",167805,null],[189051,"2026-09-04T11:31:41",11,"В свой ход дриада делает две атаки, попадает так же только одна",167805,null],[189052,"2026-09-04T11:32:53",11,"/roll 2d6 колющего\n/roll d6 ядом (у тебя от расы уменьшение урона ядом, так что хоть в мишке и меняются статы, но резист оставить разрешаю)",167805,null],[189055,"2026-09-04T11:33:21",22,"/это половина урона проходит, верно?",167805,null],[189056,"2026-09-04T11:33:31",11,"// 9 колющего и 10 ядом",167805,null],[189058,"2026-09-04T11:34:14",22,"Венус рычит и продолжает свою атаку не смотря на боль.\n\n20/34",167805,null],[189059,"2026-09-04T11:34:26",22,"/r +6 укус\n/r d8+4\n/r +6 царапа\n/r 2d6+4",167805,null],[189061,"2026-09-04T11:34:51",22,"/ход",167805,null],[189062,"2026-09-04T11:35:09",11,"и вновь первая атака попадает сталкиваясь с ядовитыми шипами",167805,null],[189063,"2026-09-04T11:35:15",11,"/roll d6",167805,null],[189065,"2026-09-04T11:36:29",11,"Полученный урон пока не сильно ее беспокоит и она вновь делает 2 взмаха шипастыми корнистыми руками",167805,null],[189066,"2026-09-04T11:36:37",11,"/roll d20\n/roll d20",167805,null],[189068,"2026-09-04T11:37:18",11,"/roll 2d6+3 колющий \n/roll 2d6+3 колющий\n/roll d6 ядом",167805,null],[189071,"2026-09-04T11:38:50",11,"Тело медведя больше не в силах выдержать урон и Венус возвращается в истинную форму получив 18 урона за мишку и 8 как Венус",167805,null],[189072,"2026-09-04T11:39:41",11,"Дриада улыбается, а небо мигает будто незримый наблюдатель заворожен такой жестокостью",167805,null],[189074,"2026-09-04T11:41:27",11,"// анализ если что свободным",167805,null],[189075,"2026-09-04T11:42:25",22,"В момент атаки, когти дриады срываются обличие медведя и оставляют длинные порезы на лице девушки. \n\n18/26",167805,null],[189076,"2026-09-04T11:43:00",22,"/r",189074,null],[189078,"2026-09-04T11:43:33",11,"«Дерево должно хорошо гореть» — думает Венус",167805,null],[189079,"2026-09-04T11:44:26",22,"Ну ладони девушки вырастает гриб, она сжимает его и сдувает споры прямо в лицо дриаде.\n\nОгонь фей, спас ловкость 13",167805,null],[189080,"2026-09-04T11:45:01",11,"/roll +d20",167805,null],[189082,"2026-09-04T11:45:13",11,"// бонус не пишу, но прошла",167805,null],[189083,"2026-09-04T11:45:50",11,"Венус видит что колдунья Королевы мстительных роз хорошо справляется с заклинаниями направленными на неё лично",167805,null],[189084,"2026-09-04T11:47:00",22,"Наверное дерево будет хорошо гореть, подумала Венус, но сразу же оборвала себя. Сила природы не столько в магии, сколько в не когтях и клыках!\n\nГлаза Венус наливаются жёлтым светом и она становится волчицей.",167805,null],[189085,"2026-09-04T11:47:02",22,"ХП 37\nКБ 14\nУкус. +5, Попадание: Кол урон 10 (2к6 + 3). Цель существо - спас Силы Сл 13, иначе будет сбита с ног.",167805,null],[189086,"2026-09-04T11:47:06",22,"/ход",167805,null],[189087,"2026-09-04T11:48:39",11,"Дриада не останавливается, сдув пыльцу на траву она делает новые два взмаха",167805,null],[189088,"2026-09-04T11:48:48",11,"/roll d20\n/roll d20",167805,null],[189090,"2026-09-04T11:49:23",11,"/roll 2d6+3 колющий\n/roll 2d6+3 колющий \n/roll d6 ядом",167805,null],[189092,"2026-09-04T11:49:38",11,"// что с кубами жесть😳",189091,null],[189093,"2026-09-04T11:50:07",11,"Волчица чувствует себя явно не лучшим образом, Дриада же ранена, но пока не так страшно",167805,null],[189094,"2026-09-04T11:50:07",22,"/венус+кубы=❤️",167805,null],[189095,"2026-09-04T11:50:22",11,"// у тебя если что есть хил за ячейки в форме зверя бонусным",167805,null],[189096,"2026-09-04T11:52:38",11,"// можешь глянуть что у тебя есть в снаряжении и подумать, я не тороплю",167805,null],[189100,"2026-09-04T11:54:56",22,"Венус закрывает глаза и шумно выдыхает, ее цветы распустились и воздух наполнился кисло-сладким ароматом",167805,null],[189101,"2026-09-04T11:54:56",22,"/r 2d8",167805,null],[189112,"2026-09-04T11:56:20",11,"// более того в форме зверя ты не можешь обычные заклинания использовать, можешь отменить это если хочешь",167805,null],[189114,"2026-09-04T11:56:32",22,"Набравшись сил, Венус прыгает на противницу, надеясь повалить ее своим весом.\n\n11/37",167805,null],[189115,"2026-09-04T11:56:32",22,"/r +5 \n/r 2d6+3",167805,null],[189117,"2026-09-04T11:56:35",11,"// ну или скажем что ты потратила ячейку 1 круга на 4 хила от д8 бонусного",167805,null],[189121,"2026-09-04T11:58:50",11,"Дриада ловко уклоняется от атак, но они были близко, даже очень\n\nВ свой ход она понимает твое положение и говорит:\n\n— Добить тебя сразу будет слишком скучно, Ей нужно шоу\n\nОна отходит от тебя и растворяется в дереве (отход)",189116,null],[189122,"2026-09-04T11:59:59",11,"// твои действия?",167805,null],[189124,"2026-09-04T12:00:17",22,"Венус убегает, жалобно поскуливая. Найдя какую-то низину в корнях, она забирается туда и зализывает раны.\n\n//короткий отдых, я снова готова к бою!",167805,null],[189125,"2026-09-04T12:00:37",11,"// нет) это все ещё бой",167805,null],[189128,"2026-09-04T12:01:26",22,"/r 3d8",167805,null],[189130,"2026-09-04T12:01:32",22,"Ааа(",167805,null],[189132,"2026-09-04T12:02:29",22,"Тогда Венус отбегает на полную скорость и зализывает раны.\n\nБонус 2 ячейка",167805,null],[189134,"2026-09-04T12:02:46",22,"/roll 2d8",167805,null],[189136,"2026-09-04T12:03:00",11,"// нарисуй на карте куда отбежала, с поляны тебя не выпустят, только по ней",167805,null],[189139,"2026-09-04T12:06:37",22,"Ближе к камню",167805,null],[189141,"2026-09-04T12:06:59",22,"Если можно, то я бы осн потратила на лечение, вместо бонусного, чтобы 2 лечения сделать за хож/",167805,null],[189147,"2026-09-04T12:07:49",11,"// в форме зверя ты можешь восстановить д8 здоровья зверя за ячейку, за 2 круг будет 2д8 и тд, в своей форме можешь обычные заклинания использовать только и на свое здоровье (Венус)\n\nВ форме зверья нельзя касты использовать",167805,null],[189149,"2026-09-04T12:09:48",22,"Добежал до камня, волчица выдохнула и потянулась корнями к земле. Она мысленно взмолилась всем зеленым богами дать ей сил.",167805,null],[189150,"2026-09-04T12:11:00",22,"/немного запуталась, у меня есть лечение ран 2 круг, я на себя не могу наложить, в форме только за счёт траты ячейки. Грубо говоря лечение ран ещё +3 от мудрости даст, а в форме не могу его использовать, верно же?",167805,null],[189152,"2026-09-04T12:11:21",11,"// сейчас в флуде объясню",189150,null],[189161,"2026-09-04T12:19:14",22,"Боги напомнили Венус, о вкусняшках в сумке. Волчица дернула зубами, разрывая сверток и стала жадно ласкать грибной молоко",189149,null],[189163,"2026-09-04T12:19:38",22,"/r 1d6+3",167805,null],[189165,"2026-09-04T12:19:49",11,"**Дриада выходит с дерева напротив тебя и видит что ты не в ее зоне досягаемости, а потому подходит лишь на",167805,null],[189167,"2026-09-04T12:20:30",11,"10 футов",167805,null],[189170,"2026-09-04T12:22:33",22,"Венус смотрит на дриаду и жалобный скулеж псинки, становится грозным рыком.\n\nМолочко дало девушке ту силу и отвагу, которых ей так не хватало.\n\nВстряхнув шерстью, волчица пускает по своему телу последнюю мощную\nЦелебную волну и прыгает на дриаду, надеясь сбить ту с ног \n\n\n38/45 с учётом лечения",167805,null],[189171,"2026-09-04T12:23:15",22,"/r 2d8 лечение за 2 круг\n/r +5 укус и попытка сбить с ног\n/r 2d6+3",167805,null],[189174,"2026-09-04T12:24:18",11,"// последнее это урон?",167805,null],[189175,"2026-09-04T12:25:28",22,"/с дриады спас силы 13",167805,null],[189176,"2026-09-04T12:25:36",11,"/roll d20 дриада сопротивляется опрокидыванию",167805,null],[189180,"2026-09-04T12:27:10",11,"— Хитрый ход! — говорит она едва сдерживая натиск волчицы\n\nОднако укус ранил её, теперь она выглядит не так свежо",167805,null],[189184,"2026-09-04T12:28:00",11,"/roll d20",167805,null],[189186,"2026-09-04T12:28:12",11,"/roll 2d8+3",167805,null],[189188,"2026-09-04T12:28:24",11,"/roll d8 яд",167805,null],[189190,"2026-09-04T12:29:07",11,"Дриада царапает тебя свободной рукой, во вторую же ты вцепилась\n\n— Отпусти! — грозный древесный голос с ноткой паники",167805,null],[189191,"2026-09-04T12:29:14",11,"// твой ход",167805,null],[189193,"2026-09-04T12:30:01",22,"Более лёгкая волна лечения проносится по телу волчицы и сама флорен усилила наттиск\n\n29/45",167805,null],[189195,"2026-09-04T12:30:59",22,"/r 1d8 лечение последнее\n/r +5 укус и попытка сбить с ног\n/r 2d6+3",167805,null],[189197,"2026-09-04T12:31:53",11,"// давай с преимуществом за счёт того что ты и так держишь ее руку в пасти",167805,null],[189198,"2026-09-04T12:32:11",22,"/r +5 укус и попытка сбить с ног\n/r 2d6+3",167805,null],[189202,"2026-09-04T12:32:28",22,"/мисклик",167805,null],[189204,"2026-09-04T12:33:40",11,"Мощная пасть прокусывает дерево и рука остаётся в ней, а дриада освобождается получая моральную травму\n\n— Да как ты.. смеешь! — Кричит она и вновь замахивается на тебя целой рукой",167805,null],[189205,"2026-09-04T12:33:57",11,"/roll d20",167805,null],[189207,"2026-09-04T12:34:14",11,"/roll 2d6+3\n/roll d8 яд",167805,null],[189210,"2026-09-04T12:35:08",11,"// твой ход",167805,null],[189213,"2026-09-04T12:37:07",22,"Волчица давит на дриаду, раз за разом пытаясь повалить ту на землю.\nСила, сл 13\n\n7/45",167805,null],[189214,"2026-09-04T12:37:13",22,"/r +5 укус и попытка сбить с ног\n/r 2d6+3",167805,null],[189219,"2026-09-04T12:39:04",11,"Дриада на земле",167805,null],[189220,"2026-09-04T12:40:12",11,"выглядит крайне побитой, без руки, но ещё не на грани",167805,null],[189222,"2026-09-04T12:41:01",11,"Огонь в её глазах всё так же пылает яростью, но теперь и паникой, она ползет отходом к дереву и растворяется в нем вновь\n\n// Твой ход",167805,null],[189226,"2026-09-04T12:43:02",11,"/roll d6 урона ядом за последний укус реакция",167805,null],[189231,"2026-09-04T12:43:32",22,"Венус принюхивается, пытаясь найти дриаду по ее ярком запаху",167805,null],[189233,"2026-09-04T12:44:55",11,"Запах от дерева, она растворилась в нём",167805,null],[189235,"2026-09-04T12:45:24",22,"Волчица рычит и пытается поцарапать и погрызть это дерево",167805,null],[189236,"2026-09-04T12:45:46",22,"/r +5 грызет дерево\n/r 2d6+3",167805,null],[189238,"2026-09-04T12:46:18",22,"Волчица в яростном прыжке летит в дерево и попадает прямо в дупло.",167805,null],[189239,"2026-09-04T12:46:23",11,"В пасть попала заноза, кажется это больно",189237,null],[189241,"2026-09-04T12:46:31",11,"/roll d4 колющий",167805,null],[189243,"2026-09-04T12:46:38",22,"//как лисонька в снег прыгает, так волчица в дупло",167805,null],[189252,"2026-09-04T12:48:20",11,"Дриада появляется с обратной стороны, переведя дух в дереве она успокаивает свою панику и берет себя в руки, а затем накидывается на тебя сзади",167805,null],[189255,"2026-09-04T12:48:42",11,"/roll d20\n/roll d20 мультиатака последней рукой",167805,null],[189257,"2026-09-04T12:49:07",11,"/roll 2d6+3 колющий \n/roll d6 яд",167805,null],[189259,"2026-09-04T12:49:41",11,"Первая атака не попала, но второй она атаковала прицельнее",167805,null],[189267,"2026-09-04T12:52:01",22,"Волчицу больно дернули за хвостик. Поскуливая, она обернулась и снова набросилась на противницу, пытаясь повалить ту на землю.\n\n4/45",167805,null],[189268,"2026-09-04T12:52:11",22,"/r +5 Кусь!\n/r 2d6+3",167805,null],[189271,"2026-09-04T12:52:35",11,"// лежит",167805,null],[189272,"2026-09-04T12:53:20",11,"Но тратит половину скорости и скидывает тебя с себя😅",167805,null],[189273,"2026-09-04T12:53:59",11,"— Бой оказался более равным чем мне казалось изначально.. признаю — говорит дриада, выглядите вы примерно одинаково побитыми",167805,null],[189274,"2026-09-04T12:54:03",22,"И все же, я уложу тебя, паршивка.\n\nПодумала волчица и зарычала.",167805,null],[189275,"2026-09-04T12:54:23",11,"/roll d20\n/roll d20 мультиатака",167805,null],[189277,"2026-09-04T12:54:39",22,"//пора расчехлять скимитар и щит",167805,null],[189278,"2026-09-04T12:55:22",11,"Ярость переполняет дриаду, она знает что вы обе близки и либо ты либо она",167805,null],[189280,"2026-09-04T12:56:22",11,"/roll 4d6+3 пурпурное пламя в глазах дриады искрами срывается и боль кажется обжигающей..",167805,null],[189282,"2026-09-04T12:56:45",11,"// 4 урона волчице, 13 Венус",167805,null],[189283,"2026-09-04T12:57:08",11,"/roll 2d6 вторая атака попадает тоже, даже щит не помог",167805,null],[189285,"2026-09-04T12:57:32",11,"// или помог..?",167805,null],[189287,"2026-09-04T12:57:45",22,"//момент",167805,null],[189288,"2026-09-04T12:58:21",22,"/помог, кд 14 со щитом",189285,null],[189289,"2026-09-04T12:58:24",11,"Внезапно розы на теле Венус защищают её от второй атаки, впиваясь шипами в руку дриады, а Венус слышит знакомый смех в голове, однако шипы наносят урон и тебе",167805,null],[189290,"2026-09-04T12:58:36",11,"// я не пишу модификатор просто",189288,null],[189292,"2026-09-04T12:59:29",11,"/roll d6 урона колющими шипами Венус \n/roll 2d6 урона дриаде",167805,null],[189294,"2026-09-04T13:00:40",11,"/roll d6 ядом от первой атаки однако Венус почувствовала",167805,null],[189296,"2026-09-04T13:00:44",11,"// ход",167805,null],[189297,"2026-09-04T13:01:02",11,"Вас обеих оплетает лоза твоих роз, они будто смотрят на вас",167805,null],[189298,"2026-09-04T13:01:43",22,"Венус уже едва стоит на ногах, однако решимость ее не покинула.\n\nЛовким движением, флорен закидывает себе в рот один пирожок.\n\n7/32",167805,null],[189299,"2026-09-04T13:01:53",22,"/r 1d4+2 пирожок ам",167805,null],[189302,"2026-09-04T13:02:54",11,"Дриада как твое отражение — побитая и оплетенная",167805,null],[189303,"2026-09-04T13:03:24",22,"Флорен прижимается к дриаде так близко, что та, чувствует дыхание Венус на своем лице. Свежескошенная трава и мох.\n\nСкимитар вонзается дриаде в живот.",167805,null],[189304,"2026-09-04T13:03:43",22,"/r +4\n/r d6+2",167805,null],[189306,"2026-09-04T13:04:09",11,"// и ещё",167805,null],[189307,"2026-09-04T13:04:27",22,"Венус прижимается к дриаде еще ближе и впивается в ее губы поцелуем.\n\nСкимитар в ране делает поворот.",189305,null],[189308,"2026-09-04T13:04:31",22,"/r d6+2",167805,null],[189310,"2026-09-04T13:04:59",22,"//это должна была быть эпичная шестерка а не единица!",167805,null],[189318,"2026-09-04T13:07:19",11,"— Отлично-отлично! — голос раздается шелестом листьев, а лозы все сильнее оплетают вас — последние два удара от вас обоих были прекрасны, я довольна, слуги мои! \n\nТы чувствуешь что лозы оплетают твою голову, у дриады видишь тоже самое, а затем.. дриада падает наземь, где под вами вместо травы уже лежат лепестки роз\n\n«Хотя дриаде оставалось мало, но это не от моего удара» — последнее о чем думает флорен прежде чем и сама упадёт на лепестки роз без сознания",167805,null],[189319,"2026-09-04T13:07:34",11,"// конец боя:3 а теперь нам нужно доиграть ветку ребят что бы вернуться к тебе",167805,null],[189321,"2026-09-04T13:07:44",22,"//ветка потрясающая!",167805,null],[189323,"2026-09-04T13:08:19",11,"// оставь отзыв пожалуйста в поиске квестов, если что заранее скажу что концовка - ничья, буквально:3",167805,null],[189597,"2026-09-04T16:46:25",11,"// и так возвращаемся к парочке рыбных палочек \n\nНапоминаю обстановку: вы в воде, К'варсио сагрил злую утку. Цет хп свое надеюсь помнит, а так же отравлен и имеет степень истощения \n\nУтка в 5 футах напротив Цета, в воде, он над водой\nК'варсио позади в 15 футах \n\nХод цета",167805,null],[189598,"2026-09-04T16:50:44",53,"обожди, обожди, мы не причиним тебе вреда.  *полняв руки пытаюсь донести до утки добрые намерения*",189597,null],[189600,"2026-09-04T16:51:21",11,"// убеждение и уход за животными даже так",167805,null],[189603,"2026-09-04T16:52:04",53,"//на каждый отдельно или вместе прокинуть?",189600,null],[189604,"2026-09-04T16:53:03",11,"// отдельно два броска",189603,null],[189609,"2026-09-04T16:55:23",53,"убеждение 18, уход за животными 4//",189605,null],[189610,"2026-09-04T16:55:42",53,"//ну и если дышит под водой, то\nПосланник моря. У водных животных есть исключительная близость к вашему народу.\n\nВы можете передавать простые идеи животным, которые могут дышать под водой. Они могут понимать значение ваших слов, хотя у вас нет никакой специальной способности понять их в ответ.",167805,null],[189611,"2026-09-04T16:55:43",11,"// ты зачем мне тыщу кубов кидаешь давай нормально",167805,null],[189612,"2026-09-04T16:55:52",11,"https://youtube.com/shorts/qrxna77PLb8?si=6bayE20FOWU80kW-\n\n// Вот с кем вы связались думайте",167805,null],[189614,"2026-09-04T16:56:02",53,"//с помехой изза отравления на одно, с помехой изза отравления на второе",189611,null],[189616,"2026-09-04T16:57:10",11,"// ладно \n\nУтёнок игнорирует тебя, но лягушку которая потревожила его мирный покой он хочет РЕЗАТЬ",189610,null],[189617,"2026-09-04T16:57:29",11,"// двигаешься куда-то или конец хода?",167805,null],[189620,"2026-09-04T16:59:56",11,"// Серёга, вы вдвоем играете, давай как нить быстрее)) это не тяжело",167805,null],[189621,"2026-09-04T17:00:00",53,"*отплываю дальше и кричу кварсио: осторожно*",189616,null],[189622,"2026-09-04T17:00:06",53,"//мне впн мозгу ипет",189620,null],[189623,"2026-09-04T17:00:14",11,"// я вместе с ним буду",189622,null],[189624,"2026-09-04T17:00:25",11,"// @elsio28",167805,null],[189625,"2026-09-04T17:01:17",5,"К'варсио, громко квакая, удирает от бейпика в сторону ближайшей суши\n\n// Рывок",167805,null],[189626,"2026-09-04T17:01:29",53,"//щас раздуплюс(ну или отрублюсь изза того что поел) и норм будет",189621,null],[189627,"2026-09-04T17:01:37",5,"— Уплывай от него, я отвлеку!",189621,null],[189630,"2026-09-04T17:02:48",11,"Лапки лягушенка касаются противоположного берега, но на мелководье тебя постигает та же участь что и Цета\n\n// Спас просить не буду от яда ибо иммун, но 1 урона колющего и состояние истощения 1 степень \n\nнедовольный тем что его побеспокоили червь вертится в иле в попытках заползти обратно в землю",189625,null],[189631,"2026-09-04T17:02:52",53,"я не могу оставить тебя здесь, мой долг оберегать всех существ и помогать им встретится с богом. уплывай ты, а я попробую договорится!",189627,null],[189632,"2026-09-04T17:03:22",11,"// щас я вам организую встречу с богом",189631,null],[189633,"2026-09-04T17:03:28",5,"— Если что, встретимся у реки!",189631,null],[189634,"2026-09-04T17:03:31",5,"/ ход",167805,null],[189638,"2026-09-04T17:03:50",53,"*киваю*",189633,null],[189640,"2026-09-04T17:05:06",53,"обожди, о создание великого, быть может я поделюсь с стобой остатками еды что у меня есть и излечу раны коли таковы имеются?(заврику)",189638,null],[189641,"2026-09-04T17:05:20",11,"Злой утёнок делает рывок вслед за лягушкой и выскакивает на берег показательно махая на К'варсио когтистыми лапами и шипя, а его перья на голове пугающе подымаются",167805,null],[189643,"2026-09-04T17:06:11",11,"Сам К'варсио обнаруживает себя на противоположном берегу. Здесь все так же хорошо слышно водопад, вы недалеко от него, но река с другой стороны водоема - либо обходить, либо плыть",167805,null],[189644,"2026-09-04T17:07:07",11,"— Я здесь охочусь на червей, а лягушка потревожил покой меня великого! Он за это поплатиться или покинет мой новый дом!",189640,null],[189645,"2026-09-04T17:07:40",11,"— И ты проваливай, черви здесь - мои",167805,null],[189646,"2026-09-04T17:08:48",5,"— Он с тобой говорит!?",167805,null],[189647,"2026-09-04T17:09:04",11,"Утка разворачивается в твою сторону и снова шипит",167805,null],[189648,"2026-09-04T17:09:17",11,"А Цету он что-то вычирикивает",167805,null],[189652,"2026-09-04T17:10:10",53,"хорошо. он покинет его, ты согласен на это?",189645,null],[189654,"2026-09-04T17:10:19",53,"и я покину.",189646,null],[189655,"2026-09-04T17:10:38",11,"— Пусть ловит червя мне раз расшумелся тут и я так уж и быть прощу вас",167805,null],[189656,"2026-09-04T17:11:22",11,"// червь ещё возле лягушки, ходите без ини раз избежали боя",189630,null],[189657,"2026-09-04T17:11:24",53,"*киваю и говорю кварсио о просьбе утки*\n\nон требует добыть ему червя в замен за то что мы потревожили его.",189655,null],[189659,"2026-09-04T17:12:00",5,"— Червя? Легко, ква!\n\nЛягушка достаёт короткий меч и пытается проколоть червя",167805,null],[189660,"2026-09-04T17:12:24",11,"Вот червь такой",167805,null],[189663,"2026-09-04T17:12:48",11,"Червезмей",167805,null],[189664,"2026-09-04T17:13:09",5,"Прыгаю за ним, присев",167805,null],[189668,"2026-09-04T17:14:25",11,"// атака с помехой. Червь в иле, особенность его такая",167805,null],[189669,"2026-09-04T17:14:53",5,"/r -d20+6",167805,null],[189677,"2026-09-04T17:16:29",11,"— Бесполезный-бесполезный! — слышит Цет\n\nНеразборчивые птичьи звуки — для К'варсио \n\nУтёнок бросается к вам и хватает клювом червя, ныряет с ним в воду, затем выныривает, отряхивается от воды, глотает добычу и говорит:\n\n— Проваливайте",167805,null],[189681,"2026-09-04T17:17:18",5,"— Какой вредный ящер! Зато разговаривает. Мистер ящер, как ты умеешь говорить?",167805,null],[189684,"2026-09-04T17:17:38",11,"// ты его не понимаешь",167805,null],[189685,"2026-09-04T17:17:44",5,"Грунг машет лапкой Цету\n\n— Плыви сюда",167805,null],[189686,"2026-09-04T17:17:49",5,"/ а..",189684,null],[189688,"2026-09-04T17:18:14",11,"// для тебя это неразборчивые звуки, а Цет понимает водных тварей, хотя только морских на самом деле, но допустим)",167805,null],[189696,"2026-09-04T17:19:33",53,"*плыву к кварсио* он говорит уходить.",189685,null],[189698,"2026-09-04T17:20:11",5,"— Пойдём к реке вдоль водоёма",167805,null],[189700,"2026-09-04T17:20:24",11,"Недовольная утка провожает вас взглядом",167805,null],[189701,"2026-09-04T17:20:44",11,"// если пойдете обратной дорогой выживание с того кто ведёт",167805,null],[189703,"2026-09-04T17:21:38",53,"*киваю*\nдруг мой, ты тоже ощущаешь эту тошноту и недомоганье?",189698,null],[189704,"2026-09-04T17:21:46",5,"/ можно ли считать эту местность болотом?",167805,null],[189706,"2026-09-04T17:22:05",5,"— Да, этот червь меня квуснул",189703,null],[189709,"2026-09-04T17:22:43",5,"— А у этого злого ящера лапки квак у меня",167805,null],[189710,"2026-09-04T17:22:46",11,"// это все ещё джунгли",189704,null],[189711,"2026-09-04T17:23:04",11,"// он не ящер, где ты ящерицу увидел, у него перья, лапки просто перепончатые",189709,null],[189712,"2026-09-04T17:23:07",5,"/r +3 веду",167805,null],[189714,"2026-09-04T17:23:11",53,"я помогу, на что хватит сил, но слелует вывести яд.\n*подходу ближе когла мы уже отошли от утки и начинаю целительстврватт рану мазью*",189706,null],[189715,"2026-09-04T17:23:42",5,"— Квак вывести? Он уже внутри",189714,null],[189719,"2026-09-04T17:23:50",5,"/ помеха, 8",189717,null],[189720,"2026-09-04T17:24:35",11,"Не по своим шагам конечно, но вы выбираетесь к высохшей реке. За это время солнце поднялось сильнее и вам уже становится жарковато, благо то что вы были в воде спасает",189713,null],[189721,"2026-09-04T17:24:55",11,"// аы ладно будем считать что тебе Цет помог..",189719,null],[189723,"2026-09-04T17:26:36",11,"Всё та же обстановка, звуки водопада за углом, только глина засохнуть успела на дне реки",167805,null],[189725,"2026-09-04T17:27:50",5,"/ ?",189714,null],[189934,"2026-09-04T20:52:05",53,"правильным питанием и лечебныеми процедурами и средствами",189715,null],[189938,"2026-09-04T20:55:04",5,"— Правильным питанием?\n\nЛягушонок задумался.\n\n— У меня есть что-то правильное!\n\nОн достал  бутылочку с грибным молоком и отпил. Потом предложил Цету.\n\n— Хочешь? Тебя ведь тоже ранило",189934,null],[189939,"2026-09-04T20:55:16",5,"/r d6+3 тхп",167805,null],[189941,"2026-09-04T20:56:08",53,"//загрузило меня в магазине",167805,null],[189962,"2026-09-04T21:15:29",11,"// ну и что товарищи делают дальше? Обстановка все та же",167805,null],[189963,"2026-09-04T21:23:00",53,"*покашливая от ядов в организме и соглашаюсь с мыслью товарища и тоже выпиваю немного грибного молока*\n\nты прав, рыцарь.",189938,null],[189965,"2026-09-04T21:23:16",53,"6 тхп//",189964,null],[189966,"2026-09-04T21:24:07",11,"// просто интересно где вы все молоко взяли учитывая что я его давала только К'варсио, но так уж и быть пейте, но после этого вы обязаны будете спасти коров))",167805,null],[189967,"2026-09-04T21:24:14",53,"//а есть какие то отличия у высохшей области и у области с водой помимо наличия воды и жизни?",189720,null],[189968,"2026-09-04T21:24:36",11,"//?",189967,null],[189969,"2026-09-04T21:24:42",5,"— Теперь мы можем идти к кводопаду",189963,null],[189970,"2026-09-04T21:25:21",53,"//?",189968,null],[189971,"2026-09-04T21:25:38",53,"нам следует быть осторожнее в этот раз.",189969,null],[189972,"2026-09-04T21:26:48",5,"— Мы были квасторожны! Птица плавала под нами!",167805,null],[189973,"2026-09-04T21:27:37",53,"мы были недостаточно внимательны.",189972,null],[189974,"2026-09-04T21:28:31",5,"— Кварошо. Пойдём, ты смотри в оба!",189973,null],[189975,"2026-09-04T21:29:48",53,"и не должны ли мы сообщить старице о том что нашли воду там?",189974,null],[189976,"2026-09-04T21:30:13",11,"Что-ж вы сворачивание за очередное ответвление реки и видите перед собой огромную дамбу из корней ила и обломков камней, сквозь нее не просачивается ни капли воды, очевидно что именно она препятствует течению реки",167805,null],[189977,"2026-09-04T21:31:08",53,"пологаю это и есмь причина отсутствия воды.",189976,null],[189978,"2026-09-04T21:31:25",11,"А за дамбой вас встречает довольно крупного вида озеро у водопада. Из-за того что вода не впадает в реку озеро стало сильнее крупнее затопив соседние участки джунглей",167805,null],[189979,"2026-09-04T21:32:10",53,"думается мне стоит сей час же сообщить старице об этом.",189978,null],[189980,"2026-09-04T21:32:35",5,"— Зачем? Они и так знают, что вода есть в других местах",189975,null],[189981,"2026-09-04T21:33:25",53,"//все еще чутка туплю",189980,null],[189982,"2026-09-04T21:33:29",5,"— Смотри, кто-то построил дамбу за ночь. Вот в чём дело!",189978,null],[189983,"2026-09-04T21:33:56",5,"— Можем сообщить, а может разберемся с самой дамбой?",167805,null],[189984,"2026-09-04T21:34:09",53,"быть может и не за ночь, прлсто за ночь она достигла высоты, сто не пускает воду в реку",189982,null],[189985,"2026-09-04T21:34:29",53,"ежели мы так поступим деревню может смыть по нашей вине",189983,null],[189987,"2026-09-04T21:36:17",5,"— Квачем им дамба, им нужна вода",167805,null],[189988,"2026-09-04T21:36:34",5,"/ а не так прочитал хд",167805,null],[189989,"2026-09-04T21:37:03",11,"// никто не мешает вам бросать проверки на анализ если хотите что-то узнать:3",167805,null],[189990,"2026-09-04T21:37:09",5,"— Тогда надо узнать, была ли здесь дамба раньше",189985,null],[189991,"2026-09-04T21:37:15",5,"— Может её надо убрать!",167805,null],[189992,"2026-09-04T21:37:37",53,"*киваю*",189990,null],[189993,"2026-09-04T21:37:58",53,"что же, в путь, покуда не приключилось новых бед",167805,null],[189994,"2026-09-04T21:38:20",5,"— Пойдём поскорее, солнце печёт!",189993,null],[189995,"2026-09-04T21:39:10",5,"Направляемся назад в деревню",167805,null],[189996,"2026-09-04T21:40:11",53,"//сколько у тебя скорость?",189995,null],[189997,"2026-09-04T21:40:17",5,"/ 25",167805,null],[189998,"2026-09-04T21:40:41",53,"//я смогу тебя нести без потери скорости? 🤔",189997,null],[189999,"2026-09-04T21:40:58",5,"/ мастеру решать",189998,null],[190000,"2026-09-04T21:42:01",53,"//ну тодя ждем мастера",189999,null],[190001,"2026-09-04T21:43:08",11,"Рыба несёт жабу, жаба ядовитая, вы идете так какое-то время и бросаете спас от истощения на жаре",167805,null],[190002,"2026-09-04T21:43:23",5,"/r -d20+3",167805,null],[190005,"2026-09-04T21:43:45",53,"//ну хуже уже не будет XD",190004,null],[190006,"2026-09-04T21:44:28",5,"— Цет, моя кожа плавится! Давай остановимся в деревне до вечера",167805,null],[190007,"2026-09-04T21:44:31",11,"А хуже стало, сразу 2 истощения, дальше жабу не несёт..",167805,null],[190008,"2026-09-04T21:45:53",53,"*рыбаф как то усох и замедлиься за время носки*\nвсе... больше не могу нести...",167805,null],[190009,"2026-09-04T21:46:37",53,"//имел ввиду хуже еденицы уде не будет :3",190007,null],[190010,"2026-09-04T21:46:50",5,"Лягушонок смотрит сочувственно.\n\n— И ты совсем плох. Скорее, найдём укрытие в деревне!",190008,null],[190011,"2026-09-04T21:46:53",53,"//0 не выбью",190009,null],[190012,"2026-09-04T21:47:07",53,"*киваю поправляя маску*",190010,null],[190013,"2026-09-04T21:47:16",11,"И так два потрепанных жизнью путника(даже без боя) возвращаются в город, и слышат как шушукаются жители. Атмосфера напряжённая, люди паникуют\n\nВы идете к дому Олани, там вас встречает она с тростью и приглашает войти вновь. Внутри уже ждёт обеспокоенная Аниса. Пожилая эльфийка перебирает пальцами в неторопливом ожидании и с надеждой в глазах смотрит на вас",167805,null],[190014,"2026-09-04T21:47:40",11,"Вот кстати она, только без рыбовых",167805,null],[190015,"2026-09-04T21:47:40",5,"— Жарко, квужас!",190013,null],[190016,"2026-09-04T21:48:34",53,"кхык... здравы будьте, леди оланья",190013,null],[190017,"2026-09-04T21:48:46",53,"*звуки засохшего кашля*",190016,null],[190018,"2026-09-04T21:49:08",5,"— Мы нашли кводу. Она за дамбой",167805,null],[190019,"2026-09-04T21:49:53",53,"озеро за ней начинает выходить из берегов изза дамбы.",167805,null],[190020,"2026-09-04T21:49:59",11,"Олани приносит вам воды",167805,null],[190021,"2026-09-04T21:50:18",11,"— Дамбой? — женщина удивляется — ох позвольте вам помочь, а вы пока расскажите о чем вы говорите..",190018,null],[190022,"2026-09-04T21:50:19",53,"благодарю.",190020,null],[190023,"2026-09-04T21:50:19",5,"Лягушонок пьёт, а потом умывает мордочку",190020,null],[190024,"2026-09-04T21:50:43",11,"Женщина подходит и подымает над вами руки, от ее теплой зелёной магии вы чувствуете себя немного лучше",167805,null],[190025,"2026-09-04T21:50:51",53,"*приподняв маску быстро выпиваю воду, часть проливается под одежду*",190022,null],[190026,"2026-09-04T21:50:52",11,"/roll 1d4+5",167805,null],[190028,"2026-09-04T21:51:03",11,"// нормальный хил для обоих",167805,null],[190029,"2026-09-04T21:51:25",53,"//хп у нас вроде почти целое было 🤔",190028,null],[190030,"2026-09-04T21:51:41",11,"// у тебя нет, тхп никуда не делось впрочем",167805,null],[190031,"2026-09-04T21:51:57",11,"// я помню что наносила 1 колющего, потом ещё 1, потом ядом побольше, К'варсио только 1 колющего",167805,null],[190032,"2026-09-04T21:52:12",5,"— Там дамба посреди реки. Из травы!",190021,null],[190033,"2026-09-04T21:52:28",11,"// травы там не было брат:_)",167805,null],[190034,"2026-09-04T21:52:53",11,"/",189976,null],[190035,"2026-09-04T21:53:08",11,"— Дамба из травы, как же это возможно..?",167805,null],[190036,"2026-09-04T21:53:31",53,"это были корни деревьев...",190032,null],[190037,"2026-09-04T21:53:41",53,"и камни.",167805,null],[190038,"2026-09-04T21:53:52",53,"чем то они и правда похожи на траву \n*задумался*",190036,null],[190039,"2026-09-04T21:54:10",5,"/ Кварсио её так видит",190034,null],[190040,"2026-09-04T21:54:15",53,"особенно со всем илом там.",190038,null],[190041,"2026-09-04T21:54:52",5,"— Ква-квамешки тоже были!",190037,null],[190042,"2026-09-04T21:56:12",53,"дамба была огромна, за ней кркпное озеро и боюсь если ее сломать сразу, деревню может снести поток буйной воды. поэтому мы и вернулись. есть ли у вас мастера воды, али те кто умеют управлятся с дамбами?",167805,null],[190043,"2026-09-04T21:56:54",11,"— Корни деревьев.. и камни.. — женщина задумалась — возможно обрушилась часть скалы или звери что-то учудили, но всего за ночь.. \n\nСтарушка подошла к балкону посмотреть на иссохшую реку\n\n— Вы молодцы, я отправлю ребят разобраться с этим, а вам бы проверить как дела обстоят у вашей подруги — женщина обернулась к вам вновь — она ушла вскоре после вас и до сих пор не вернулась как и тот юнец..",167805,null],[190044,"2026-09-04T21:57:14",5,"— Это вы построили дамбу?",167805,null],[190045,"2026-09-04T21:57:28",11,"— Зачем же нам лишать себя воды, дитя?",167805,null],[190046,"2026-09-04T21:57:51",5,"— Значит лес пробудился и вырастил дамбу",167805,null],[190047,"2026-09-04T21:58:05",53,"юнец?",190043,null],[190048,"2026-09-04T21:58:41",11,"— Девушка по имени Венус ушла вместе с молодым пастухом исследовать те странные розы и вернуть скот",167805,null],[190049,"2026-09-04T21:58:44",53,"возможно там живет что то, что постепенно строило дамбу, пока она не перекрыла всю воду.",190046,null],[190050,"2026-09-04T21:59:09",11,"— Там..? У вас есть предположения?",190049,null],[190051,"2026-09-04T21:59:14",5,"— Квозможно. Или лес пробудил это существо, чтобы дамба выросла сейчас",190049,null],[190052,"2026-09-04T21:59:19",53,"//например бобры или птице-бобры",190049,null],[190053,"2026-09-04T21:59:42",53,"не могу знать что здесь обитает.",190050,null],[190054,"2026-09-04T22:00:03",11,"— Ох, надеюсь вы не правы..",190051,null],[190055,"2026-09-04T22:00:10",53,"так или иначе беда может повтоиится.",190051,null],[190056,"2026-09-04T22:00:49",53,"ведь ежели есть то - что возводит дамбы - оно вероятно возведет их вновь.",190055,null],[190057,"2026-09-04T22:01:07",5,"— Вы видели ещё признаки пробуждения?",190054,null],[190058,"2026-09-04T22:01:24",5,"— Кверно. Значит надо искать причину",190056,null],[190059,"2026-09-04T22:02:39",53,"всегда важно находить причину, но и симптомы стоит исцелять, ведь можно и не дожить до исцеления причины ежели не лечить симптом.",167805,null],[190060,"2026-09-04T22:02:41",11,"Старушка задумалась на какое-то время, а потом с ясными глазами сказала\n\n— Может и так. Он сказал что вы разберётесь с этим, я в вас верю",167805,null],[190061,"2026-09-04T22:03:07",53,"Он?..",190060,null],[190062,"2026-09-04T22:03:32",5,"— Это слова квеликого?",190059,null],[190063,"2026-09-04T22:03:37",11,"— Вам не положено знать, дети, иначе вы не сможете так просто покинуть это место",167805,null],[190064,"2026-09-04T22:03:51",11,"Старушка улыбнулась",190062,null],[190065,"2026-09-04T22:04:38",53,"*киваю*\nвеликий поведал нашему ордену эту мудрость.",190062,null],[190066,"2026-09-04T22:05:31",11,"— Ступайте же, проверьте в порядке ли Венус и Иллан. Чует моё сердце что что-то приключилось, ох-ох",167805,null],[190067,"2026-09-04T22:05:58",53,"куда держать нам путь?",190066,null],[190068,"2026-09-04T22:05:59",5,"— Возможно ваш покровитель похож на мою кваспожу! Она послала меня разобраться",190060,null],[190069,"2026-09-04T22:06:25",53,"//собрались как то три культиста в одной комнате...",167805,null],[190070,"2026-09-04T22:09:50",11,"— Я велю позвать Морвена, он тоже был там утром, покажет вам дорогу\n\nСтарушка даёт печенье своему фамильяру и описывает ему кого нужно найти. Птенец съедает угощение и вылетает сквозь балкон\n\n— Есть ли у вас вопросы ко мне пока у нас есть время ?",167805,null],[190071,"2026-09-04T22:10:25",53,"поппо?//",190070,null],[190072,"2026-09-04T22:10:47",53,"как зовут вашего питомца?",190070,null],[190073,"2026-09-04T22:11:35",11,"— Веспер — отвечает старушка — он микрораптор",167805,null],[190074,"2026-09-04T22:11:35",5,"— Мы встретили плавающую птицу размером с меня. Кто это?",190070,null],[190075,"2026-09-04T22:12:09",11,"— А плавающая птица.. а как она выглядела?",167805,null],[190076,"2026-09-04T22:12:36",5,"— Она страшно кричала, размером с меня и следы такие же",167805,null],[190077,"2026-09-04T22:13:22",53,"он ел ядовитых червей прячущихся в иле.",167805,null],[190078,"2026-09-04T22:13:46",11,"— Перепончатые лапки? Должно быть это бейпяозавр, они обычно довольно спокойны если их не трогать, но если побеспокоить могут оставить с парой шрамов на всю жизнь..",167805,null],[190079,"2026-09-04T22:14:07",5,"— Я думал его напугать, он плавал под нами",167805,null],[190080,"2026-09-04T22:14:22",11,"— У них замедленный метаболизм, они проще переносят яды",190077,null],[190081,"2026-09-04T22:14:51",11,"— Зачем же? Вряд ли он как-то мешал вам",190079,null],[190082,"2026-09-04T22:15:32",5,"— Я испугался",167805,null],[190083,"2026-09-04T22:16:11",53,"нас ужалил тот червь. *показываю рану на своей ноге*",190080,null],[190084,"2026-09-04T22:16:47",11,"Старушка засмеялась\n\n— Да, они могут устрашать. Скажите они живут возле образовавшейся дамбы? Мне нужна любая информация что бы предупредить тех кто будет разбираться с ней",167805,null],[190085,"2026-09-04T22:16:58",11,"— Даже если дамба вернётся городу нужна вода сейчас..",167805,null],[190086,"2026-09-04T22:17:15",5,"— Ква, этот водоём в джунглях недалеко. А квода там из-за дамбы",167805,null],[190087,"2026-09-04T22:17:59",11,"Анис поправляет очки и присматривается\n\n— Тяжело сказать что бы это могло быть.. в джунглях водится много ядовитых созданий, можете описать влияние яда?",190083,null],[190088,"2026-09-04T22:18:06",53,"*рассказываю по какому пути мы добрались до реки*",190084,null],[190089,"2026-09-04T22:18:28",11,"— Значит не возле дамбы, хорошо, спасибо за информацию, К'варсио",190086,null],[190090,"2026-09-04T22:18:51",53,"//он меня только отравление или истощение наложил?",190087,null],[190091,"2026-09-04T22:19:00",11,"// и истощение",167805,null],[190092,"2026-09-04T22:19:30",53,"кожа усохла, тяжесть во всем теле и общее недомогание.",190090,null],[190093,"2026-09-04T22:20:10",11,"— А как ваше общее состояние, нет онемения в ужаленной конечности?",167805,null],[190094,"2026-09-04T22:20:29",53,"//нет онемения?",190093,null],[190095,"2026-09-04T22:20:52",53,"*прислушиваюсь к ощущениям*",190093,null],[190096,"2026-09-04T22:21:18",53,"не чувствую онемения.\nчервь был похож на змею с лапами.",190093,null],[190097,"2026-09-04T22:23:48",11,"— Не похоже что это какой-то опасный для жизни яд, увы я не сталкивалась с такими случаями — женщина качает головой — но вам бы не помешал постельный режим.. \n\nВ дверь стучат, хозяин дома открывает и вы видите как входит прям юный на вид эльф, мальчишка лет 14, с темными волосами. На его плече сидит не менее иссиня темный Веспер",167805,null],[190098,"2026-09-04T22:23:58",11,"— Вот и ваш проводник, господа",167805,null],[190099,"2026-09-04T22:24:13",11,"Веспер взлетает и возвращается к хозяйке",167805,null],[190100,"2026-09-04T22:24:31",5,"— Надо найти пропавших и поскорее вернуться отжохнуть",167805,null],[190101,"2026-09-04T22:24:50",11,"— Морвен, будь добр, проводи гостей к той поляне.. Иллиан так и не вернулся до сих пор",167805,null],[190102,"2026-09-04T22:25:10",11,"Парень молча кивнул и стоит ждёт вас у дверей",167805,null],[190103,"2026-09-04T22:26:35",5,"К'варсио следует за парнем",167805,null],[190104,"2026-09-04T22:26:38",53,"*с трудом и хрустом кожи поднииаюсь опираясь на стул и иду к двери*",190102,null],[190105,"2026-09-04T22:27:00",53,"*а затем следую за товарищами*",167805,null],[190106,"2026-09-04T22:27:10",11,"Старушка осторожно касается руки Цета\n\n— Не хотели бы вы остаться и отдохнуть? Выглядите вы явно хуже чем ваш товарищ — ты видишь искреннее беспокойство в глазах Анис",167805,null],[190107,"2026-09-04T22:28:17",53,"я обязан помогать своим товарищам.",190106,null],[190108,"2026-09-04T22:28:48",53,"это мой долг, как бы велика не была угроза или моя тяжесть.",190107,null],[190109,"2026-09-04T22:29:12",11,"Она отпускает руку\n\n— Берегите себя и найдите Венус и Иллиана, пожалуйста, а так же наш скот — говорит она на последок и остаётся стоять у двери смотря как вы удаляетесь",167805,null],[190110,"2026-09-04T22:30:12",53,"*киваю удаляясь за рыцарем и дроу*",190109,null],[190111,"2026-09-04T22:30:29",5,"— Держись за мной, Цет. Я ещё могу сражаться",190108,null],[190112,"2026-09-04T22:30:45",11,"Молодой дроу ведёт вас по тому же пути что совсем недавно шла Венус с Иллианом, он не спешит начинать разговор сам",167805,null],[190113,"2026-09-04T22:31:15",5,"— Ква-ква",167805,null],[190114,"2026-09-04T22:31:18",11,"Тропа по которой вы идёте выглядит протоптанной и путь идёт куда быстрее за счёт того что вам не нужно прорубаться сквозь джунгли",167805,null],[190116,"2026-09-04T22:31:35",11,"он вздрагивает и оборачивается с испуганными глазами \n\n— ..?",190113,null],[190120,"2026-09-04T22:32:27",5,"К'варсио прыгает дальше по тропе и квакает",190116,null],[190121,"2026-09-04T22:32:46",11,"— Морвен, подожди! — не успели вы отойти далеко от города как вас кто-то нагоняет, вы слышите громкие шаги",167805,null],[190122,"2026-09-04T22:33:19",53,"//со мной на конце догнать нас легко",190121,null],[190123,"2026-09-04T22:33:52",5,"/ У меня скорость 12 футов если что",167805,null],[190124,"2026-09-04T22:34:15",11,"// кстати пост фактом скажу что встреча с бейпи была ответвлением доп мини событием на которое Эл сам выбрал выйти:3",167805,null],[190125,"2026-09-04T22:34:45",11,"// так что обернетесь посмотреть кто позади?",190123,null],[190126,"2026-09-04T22:35:16",53,"а, так ты тож провалил спас...//",190123,null],[190127,"2026-09-04T22:35:29",53,"*оборачивсь*",190125,null],[190128,"2026-09-04T22:35:34",5,"Грунг остановился и обернулся \n\n— Кто там квакает?",167805,null],[190129,"2026-09-04T22:38:28",11,"— Мама? \n\nВы видите эльфийку внешне очень похожую на пастуха который ведёт вас. Она сидит верхом на майазавре, а рядом с ней идёт особь поменьше \n\n— Я пойду с тобой, вдруг Иллиану и той девушке нужна будет помощь, везти их верхом будет проще чем нести",167805,null],[190130,"2026-09-04T22:39:12",5,"Грунг обдумывает кто тут \"мама\"",167805,null],[190131,"2026-09-04T22:39:40",11,"// вот на такой зверюге она сидит. Огромная тень огромной зверины закрывает Цета от солнца",167805,null],[190132,"2026-09-04T22:40:43",11,"— Я видела как эти господа едва плетутся.. простите меня, как я могу к вам обращаться..? — говорит женщина спускаясь с седла",167805,null],[190133,"2026-09-04T22:40:59",11,"— Ну мам.. я и сам бы мог.. — отвечает подросток",167805,null],[190134,"2026-09-04T22:41:48",5,"— Я ква-кварсио. Вы подвезёте нас?",167805,null],[190135,"2026-09-04T22:42:26",11,"— Да, прошу, садитесь, К'варсио— она приглашает тебя жестом",167805,null],[190136,"2026-09-04T22:42:30",53,"имя мне цет, паладин ордена красного креста. можете использовать любую из частей моего звания или имени, либо же просто звать лекарем, целителем или путником.",190132,null],[190137,"2026-09-04T22:42:50",53,"*во время слов сухо кашляю прерывачсь изза этого*",190136,null],[190138,"2026-09-04T22:42:52",5,"К'варсио делает большой прыжок прямо на спину завра",167805,null],[190139,"2026-09-04T22:43:05",11,"женщина рассмеялась, а темный подросток уже раскраснелся бы, хорошо что цвет кожи мешает",190136,null],[190140,"2026-09-04T22:43:54",11,"Женщина удивлённо подымает бровь, но взбирается обратно\n\n— Морвен, помоги господину \"паладину ордену красного креста\"",190138,null],[190141,"2026-09-04T22:44:47",5,"Лапкой в перчатке гладит бок майязавра",167805,null],[190142,"2026-09-04T22:45:02",11,"Недовольный подросток забирается в седло и подводит маунта к тебе\n\n— Садись — он подаёт тебе руку. Темные глаза смотрят на тебя сверху вниз не особо выражая какие-то эмоции",167805,null],[190143,"2026-09-04T22:46:21",11,"Майя издаёт напоминающий трубу (музыкальный инструмент) звук, звучит безобидно, но так громко что хочется закрыть уши, а птицы сидящие на ветках над вами внезапно вспорхнули и улетели",190141,null],[190144,"2026-09-04T22:46:27",53,"благодарю.\n*взяв его за руку с тяжестью поднимаюсь на заврика*",190142,null],[190145,"2026-09-04T22:47:35",11,"Вас рысью, с ветерком, прокатывают по просторному пути джунглей. На земле видны следы копыт скота, видно здесь их гоняют часто",167805,null],[190146,"2026-09-04T22:48:07",11,"// едете молча?",167805,null],[190147,"2026-09-04T22:48:41",53,"*стараюсь удержатся и высматриваю угрозы на пути*",190146,null],[190148,"2026-09-04T22:48:44",5,"/ могу чудотворством в три раза увеличить громкость? ( По правилам оно только на себя)",190143,null],[190149,"2026-09-04T22:48:47",53,"//дя",190146,null],[190150,"2026-09-04T22:48:58",11,"// прикола ради да",190148,null],[190151,"2026-09-04T22:49:40",5,"К'варсио делает жесть руками и теперь этот и так громкий звук слышали все джунгли",167805,null],[190152,"2026-09-04T22:49:49",53,"//\n-от чего вы умерли?\n-я от хохоту\n-я от холоду\n-мы от усиленного звука динозавра",167805,null],[190153,"2026-09-04T22:50:09",53,"//весь китай знает что вы здесь",190151,null],[190154,"2026-09-04T22:52:06",11,"К'варсио получает урон звуком \n\nЭльфийка сидящая спереди него в шоке\n\n— Я конечно привыкла уже, но не к такому же",190151,null],[190155,"2026-09-04T22:52:29",11,"// давай д8 кинь)",167805,null],[190156,"2026-09-04T22:53:01",5,"— Извините, я никогда не слышал такого, поэтому делюсь со всеми, кто бродит в лесах. Может это замедлит пробуждение",167805,null],[190157,"2026-09-04T22:53:07",5,"/r d8",167805,null],[190159,"2026-09-04T22:53:17",5,"/ броня не пробита",167805,null],[190160,"2026-09-04T22:53:33",11,"Сама майазавра от себя в шоке издает другой звук - судя по всему испуга и порывается убежать, но",167805,null],[190161,"2026-09-04T22:53:42",11,"/roll +d20",167805,null],[190163,"2026-09-04T22:54:03",11,"Хозяйка пытается ее остановить, но зверь несётся вперёд встав на две лапы",167805,null],[190164,"2026-09-04T22:54:35",5,"К'варсио держится крепко, ободряюще хлопая лапой по боку",190163,null],[190165,"2026-09-04T22:54:41",11,"Удивленный сын немного повтыкав пытается догнать вас",167805,null],[190166,"2026-09-04T22:55:07",53,"*я уже прикидываю чем можно успокоить зверя из моих трав*",190165,null],[190167,"2026-09-04T22:55:51",5,"Улучив удобный момент, лягушонок достаёт длинное копье и выставляет его вперёд как заправский рыцарь",167805,null],[190168,"2026-09-04T22:55:52",53,"//вот так и выглядит кража велосипеда",190164,null],[190169,"2026-09-04T22:56:14",11,"К'варсио с матушкой эльфийкой первый влетает на необходимую поляну, но проносится дальше вперёд, впрочем кучу лепестков роз вместо травы тяжело не заметить",167805,null],[190170,"2026-09-04T22:57:18",5,"Во время скачки смотрит, что впереди и кричит.\n\n— Тут лепестки роз как у квенус, ква!",190169,null],[190171,"2026-09-04T22:57:19",11,"Женщина тоже заметила это и с дополнительными усилиями всё же останавливает маечку пару десятков метров спустя",167805,null],[190172,"2026-09-04T22:58:25",11,"— Фух! — женщина тяжело дышит и ложится на своего верного скакуна приобнимая ту — не знаю с каких пор она научилась так громко говорить что даже сама себя пугается..",167805,null],[190173,"2026-09-04T22:59:19",11,"Тем временем Морвен останавливается на поляне\n\n— Лепестки роз, те самые что были утром! — его взгляд тут же цепляется за лежащего у дерева эльфа — А вот и Иллиан!",167805,null],[190174,"2026-09-04T22:59:27",5,"К'варсио убирает копьё и спрыгивает на поляну. Затем треплет Майю по боку.\n\n— Умничка",167805,null],[190175,"2026-09-04T22:59:50",11,"Она перебирая копытообразными лапками фыркает на тебя",190174,null],[190176,"2026-09-04T23:00:17",53,"*с невиданной для чела с третьим истощением силой и скоростью срываюсь с динозавра и подбегаю к телу осматривая его на раны, травмы и так далее*",190173,null],[190177,"2026-09-04T23:00:39",11,"Впрочем Венус нигде не видно",167805,null],[190178,"2026-09-04T23:01:14",53,"//он дышит? сердце бьется?",190176,null],[190179,"2026-09-04T23:01:15",11,"— А..? — от пробуждающих тормошений просыпается эльф, он выглядит совершенно здоровым, просто спал здесь..",190176,null],[190180,"2026-09-04T23:01:35",11,"зев прямо перед Цетом",167805,null],[190181,"2026-09-04T23:01:48",53,"вы целы? не ранены? ощущаете недомогание, боль, слабость?",190179,null],[190184,"2026-09-04T23:02:43",11,"— Я.. — он ощупывает себя — всё на месте! Погодите.. я что снова уснул..? \n\nПарень резко приподнимается, чувствует он себя явно бодрее чем сам Цет\n\n— А где та девушка? Она в порядке?",167805,null],[190185,"2026-09-04T23:02:56",5,"— Где же Венус?\n\nГрунг прыгает по поляне, ища следы",167805,null],[190186,"2026-09-04T23:03:06",11,"Лягушонок медленно идёт назад, пока майя идёт за ним и дышит в спину",167805,null],[190187,"2026-09-04T23:03:18",53,"*пока он говорит глаза осматривают полость рта и галаза эльфа*",190184,null],[190188,"2026-09-04T23:03:51",5,"— Я ей понравился. Что ест это сильное создание?\n\nК'варсио копается в рюкзаке",190186,null],[190189,"2026-09-04T23:03:58",11,"— Со мной всё в порядке, лучше скажите где Венус?",167805,null],[190190,"2026-09-04T23:04:19",11,"она снова фыркает, на вид не особо довольно",190188,null],[190192,"2026-09-04T23:04:59",11,"— Она травоядная, но особенно любит есть цветы с клумб.. — отвечает женщина и вы выходите на поляну",167805,null],[190193,"2026-09-04T23:05:11",53,"мы прибыли выяснить это и найти вас.",190189,null],[190194,"2026-09-04T23:05:35",11,"Майя тут же отвлекается на лепестки роз и начинает щипать их как лопатой зачерпывая их своими большими губами",167805,null],[190195,"2026-09-04T23:05:47",5,"Чудотворством К'варсио отвечает звуком (создаёт), что ранее был им усилен. Но в этот раз звук гораздо тише.",167805,null],[190196,"2026-09-04T23:06:09",11,"// кинь д20 чистое",167805,null],[190197,"2026-09-04T23:06:15",5,"/roll@roll_bot",167805,null],[190199,"2026-09-04T23:06:37",11,"Майя оборачивается в поисках источника звука, а затем подозрительно смотрит на тебя",167805,null],[190201,"2026-09-04T23:06:49",11,"Женщина тем временем спускается",167805,null],[190202,"2026-09-04T23:06:56",53,"что последнее вы помните?",190189,null],[190203,"2026-09-04T23:07:01",5,"— Значит, я соберу цветы на случай повторной встречи",190192,null],[190204,"2026-09-04T23:07:15",5,"К'варсио квакает",190199,null],[190205,"2026-09-04T23:07:33",11,"— Я рассказывал ей как мы попали сюда и про странные розы.. КАК ЖЕ МНОГО ЗДЕСЬ ЛЕПЕСТКОВ",190202,null],[190206,"2026-09-04T23:07:50",5,"Затем грунг всё-таки возвращается к поиску следов Венус",167805,null],[190207,"2026-09-04T23:07:59",11,"Незаинтересванно продолжает щипать лепестки",190204,null],[190208,"2026-09-04T23:08:11",11,"// кидай выживание",167805,null],[190209,"2026-09-04T23:08:18",53,"*беру леписток и пробую его на вкус*",190207,null],[190210,"2026-09-04T23:08:36",5,"/r -d20+3",167805,null],[190212,"2026-09-04T23:08:37",11,"обычный лепесток розы",190209,null],[190213,"2026-09-04T23:08:47",11,"// на первый взгляд, кинь тоже д20",190212,null],[190215,"2026-09-04T23:09:49",11,"// а теперь д4",167805,null],[190218,"2026-09-04T23:11:25",11,"Твой нос учуял запах вкуснейшего яблочного пирога, он исходит от листьев которые лежат кучкой..\n\nК'варсио тоже обращает внимание на то что в одном месте листьев как будто бы больше",167805,null],[190219,"2026-09-04T23:12:04",53,"*вспомнил как венус заворачивали такой и отправился к куче листвы*",190218,null],[190220,"2026-09-04T23:12:19",5,"К'варсио за Цетом",167805,null],[190221,"2026-09-04T23:13:06",53,"*акууратно разгребя листву осматриваю что под ней*",190220,null],[190222,"2026-09-04T23:13:06",11,"тебя прям манит этот запах\n\nИ так вы оба подходите, но майя оказывается быстрее вас и съедает листья прямо перед вашими глазами открывая скрытое под лепестками роз — знакомую вам девушку",190219,null],[190223,"2026-09-04T23:13:35",11,"Цет очарован Венус на минуту кстати\n\n// Своеобразный эффект найтарового озорства в подарок от архифеи за съеденную розу",167805,null],[190224,"2026-09-04T23:13:54",5,"Собираю листья вокруг и подношу к Майе удобной стопкой",190222,null],[190225,"2026-09-04T23:13:55",53,"а не лягухом?//",190223,null],[190226,"2026-09-04T23:14:12",53,"//оке",190225,null],[190227,"2026-09-04T23:14:21",5,"— Венус тут! Что с ней?",167805,null],[190228,"2026-09-04T23:14:32",11,"Дышит",167805,null],[190229,"2026-09-04T23:14:56",11,"невозмутимо ест, касаясь мордой тела девушки\n\n// @lady_godzilla просыпается Венус",190224,null],[190230,"2026-09-04T23:15:19",53,"*начинаю лечение и попытки возвращения к жизни тела, обмазываю мазями и настойками (прыщи венус преследывать кажется более не будут как и сухость коди XD)*",190223,null],[190231,"2026-09-04T23:15:31",53,"//ну и лечение конечно же :3",167805,null],[190233,"2026-09-04T23:15:54",11,"// она получила эффект короткого отдыха лёжа там, но допустим)",167805,null],[190234,"2026-09-04T23:15:57",53,"5 хп лечения, а сколько костей хп у нее для аолучения тхп не знаю//",190232,null],[190235,"2026-09-04T23:16:24",5,"— Кажется, Квенус в порядке! Привет!\n\nЛягушонок машет лапой",167805,null],[190236,"2026-09-04T23:16:34",11,"Разгребая листья рядом с девушкой вы обнаруживаете коряги.. нет, это что-то другое, похожее на тело — дриаду, она тоже без сознания",167805,null],[190237,"2026-09-04T23:16:49",5,"— Цет, тут ещё кто-то!",167805,null],[190238,"2026-09-04T23:17:36",53,"*ее тоже на всякий случай подлечим*",190236,null],[190239,"2026-09-04T23:17:38",5,"К'варсио тщательно разгребает листья вокруг дриады и собирает в кучки",167805,null],[190241,"2026-09-04T23:18:04",11,"Эльфы тоже собираются помочь вам разгребать листву, а маечки просто пасутся\n\n// ну а продолжим мы уже с Полиной",167805,null],[190242,"2026-09-04T23:18:14",53,"//почти добил первый набор целителя :D 2 юза осталось :3",167805,null],[190243,"2026-09-04T23:19:03",11,"// можете пока отзыв оставить оба в поиске квестов на сегодняшнюю сессию и в целом \n@sweetkittywitch ты тоже кстати, если ещё не оставляла, если я забыла извини тогда😅",167805,null],[190244,"2026-09-04T23:20:05",5,"Грунг просит их собирать в аккуратные кучки, чтобы потом накормить Майю, а часть сложить в рюкзак на потом",190241,null],[190245,"2026-09-04T23:20:56",5,"/ как будто тут пока недостаточно событий было, сорри",190243,null],[190246,"2026-09-04T23:21:39",53,"//ей понравилось помню",190243,null],[190247,"2026-09-04T23:21:53",11,"// а подробнее",190245,null],[190249,"2026-09-04T23:22:32",53,"//мне понравилось, но что мы ищем я понял только когда мы уже нашли дамбу, впрочем это уже скорее моя вина",167805,null],[190250,"2026-09-04T23:23:53",5,"/ бейпик понравился. А так нашли дамбу, ушли от дамбы",190247,null],[190251,"2026-09-04T23:24:13",11,"// я просила все таки в поиск квестов и основательно описать там отвечу",190250,null],[190258,"2026-09-04T23:34:07",11,"Венус с дриадой лежат посреди роз лицом друг к другу. На их головах два одинаковых терновых венца, раньше вы такого у нее точно не видели, она так же ощущает его на себе",167805,null],[190259,"2026-09-04T23:34:13",11,"Как и связь с дриадой",167805,null],[190261,"2026-09-04T23:39:27",22,"- А? С-сериче? О, какая ты красавица, кто ты?\n\nВенус ошеломленно поднимается, ее взгляд блуждает. Флорен замечает Майю и тянет к ней руки.\nОперевшись одной рукой назад, Венус находит что-то мягкое.\n\n- Сериче!\n\nВоскрикнула девушка, и стала освобождать девушку от листвы, параллельно пытаясь понять как она и как дриада себя чувствуют.",190229,null],[190262,"2026-09-04T23:40:53",5,".",190235,null],[190263,"2026-09-04T23:41:21",5,"Лягушонок собирает пачки листьев и скармливает Майе, пытается погладить по носу",167805,null],[190266,"2026-09-04T23:42:35",22,"3",190234,null],[190267,"2026-09-04T23:43:16",22,"/roll 3d8 короткий отдых",167805,null],[190270,"2026-09-04T23:43:59",11,"// к каждой кости хитов ещё добавь бонус телосложения, а ещё сверху пусть Серёга скажет сколько тебе отхилиь",190268,null],[190271,"2026-09-04T23:44:13",22,"//тогда в фулах",167805,null],[190272,"2026-09-04T23:45:00",11,"Чувствуешь себя отдохнувшей, Сериче постепенно приходит в себя и молча тянется к голове\n\n— У тебя.. такой же",190261,null],[190273,"2026-09-04T23:46:41",53,"//5 хп и тх сколько у нее максимум костей хитов",190270,null],[190274,"2026-09-04T23:47:12",11,"Спас мудрости от К'варсио и Цета",167805,null],[190277,"2026-09-04T23:47:54",53,"//сколько + не помню",190276,null],[190278,"2026-09-04T23:48:08",53,"//дриаде столько же кстати",190273,null],[190279,"2026-09-04T23:49:30",22,"- Что это з-значит? Я раньше не встречала такие украшения.. В Саду были венки, но они выглядели совершенно иначе..",190272,null],[190280,"2026-09-04T23:49:44",5,"/r +2",167805,null],[190282,"2026-09-04T23:49:59",5,"Майя меня игнорирует?",190263,null],[190283,"2026-09-04T23:50:53",11,"Стоило дриаде оглянуться и увидеть лишних зрителей как тут же все кроме нее и Венус попадали сном на землю\n\nВпрочем майя удивлено тыкается мордой в спящего лягушенка, спустя пару мгновений его это разбудит",167805,null],[190284,"2026-09-04T23:51:07",11,"— Это дар.. от неё",190279,null],[190285,"2026-09-04T23:51:47",11,"— Но я пока не понимаю что он делает — дриада подымается — впрочем нам больше не обязательно драться.. \n\nОна подаёт руку Венус",167805,null],[190286,"2026-09-04T23:51:55",5,"— Я заснул!?\n\nОн обернётся к Цету и растолкает его. А потом продолжит кормить завра.",167805,null],[190287,"2026-09-04T23:53:00",5,"/ я на этом пойду спать",167805,null],[190288,"2026-09-04T23:53:10",53,"оке//",190287,null],[190289,"2026-09-04T23:53:53",11,"// небольшую сценку с Венус отыграем и вернёмся к сюжету в след раз тогда",167805,null],[190290,"2026-09-04T23:55:59",22,"Венус принимает руку и встает.",190285,null],[190291,"2026-09-04T23:56:40",22,"- Дар? От Госпожи?\n\nНа глазах у девушки наворачиваются слезы. Она любила и любит свою госпожу всем сердцем, как дитя любит свою мать. Ведь она ее создательница",167805,null],[190292,"2026-09-04T23:59:49",11,"Ты чувствуешь что Сериче чувствует тоже самое. Чувствуешь так будто бы можешь читать ее эмоции, или они передаются тебе?\n\nДриада вытирает слезу с твоей щеки\n\n— Да. Я тоже её люблю",167805,null],[190293,"2026-09-05T00:04:41",22,"- Какой потрясающий эффект.\n\nВенус дотрагивается до своего венка.\n\n- Ты тоже.. чувствуешь меня? Это так непривычно, раньше у меня была такая связь только с животными, но гораздо слабее и поверхностней. Это же.. невероятно.. \n\nВенус с восхищением смотрит на Сериче.",167805,null],[190294,"2026-09-05T00:08:07",11,"Дриада тоже восхищается, как и всегда, чудеса созданные Королевой Роз поражают воображение слуг \n\n— Лягушка приходит в себя — ты чувствуешь ее тревогу когда она увидела как за твоей спиной майазавра разбудила К'варсио",167805,null],[190295,"2026-09-05T00:16:54",22,"- Ребята, вы как? Тут такое произошло, вы не поверите! Ах да, это Сериче! Сериче,познакомься: К'варсио и Цет!\n\nВенус начала щебетать, рассказывая о своих приключениях и одновременно с этими прислушалась к ощущениям дриады. Флорен старалась выражаться аккуратно, чтобы не ранить чувства девушки, прекрасно понимая, кто поставил ее в такое положение.",167805,null],[190296,"2026-09-05T00:17:55",11,"Дриада прячется за деревом пока рыбки приходят в себя",167805,null],[190348,"2026-09-05T10:20:43",22,"Венус попыталась мысленно к ней обратиться и послала эмоциональную волну успокоения и дружелюбия.\n\n🧠Давай я познакомлю тебя со своими друзьями? Они добрые и не обидят тебя.",167805,null],[190355,"2026-09-05T10:59:31",11,"— ..? — Дриада удивлённо выглянула из-за дерева \n\n«Похоже у нас есть телепатическая связь.. Любопытно. Если ты говоришь что эти странные не лесные создания твои друзья.. Что-ж, я могу подсказать куда делся скот, эльфы ведь ищут его?» \n\nОна нырнула в дерево\n\n«Только разбудите их и отправьте обратно пожалуйста, я бы не хотела являться перед ними»",190348,null],[190358,"2026-09-05T11:09:12",22,"//она милашка, ждем тогда ребят @elsio28 Сергей",167805,null],[190359,"2026-09-05T11:09:51",11,"// венец - предмет уникальный, но свойства его будешь понемногу узнавать) полное описание в конце квеста дам\n\nВпрочем как ты уже поняла одно из них связь с Сериче",190358,null],[190398,"2026-09-05T12:11:59",22,"- Ребята, познакомьтесь с Сериче, она дриада и поможет нам найти пропавший скот. Сериче, покажись, пожалуйста",167805,null],[190400,"2026-09-05T12:12:33",11,"Дриада явно надменно смотрит на лягушку и тритона",167805,null],[190403,"2026-09-05T12:14:39",5,"К'варсио продолжает кормить Майю, но поворачивается.\n\n— Я К'варсио! А ты пробуждение создание леса?",167805,null],[190411,"2026-09-05T12:21:50",11,"Венус чувствует удивление дриады. А ее лиственные брови больше не хмурятся\n\n— Откуда тебе известно про пробужденного?",167805,null],[190426,"2026-09-05T12:32:07",5,"— Пробужденного?\n\nК'варсио задумался.\n\n— Значит, лес не просто пробудился, есть кто-то виновный в этом! Моя кваспожа рассказала про пробуждение леса и поручила найти причину. Ты можешь направить нас?",167805,null],[190428,"2026-09-05T12:33:31",22,"Венус подошла к дриаде, успокаивающе сжала ее руку и улыбнулась.",167805,null],[190431,"2026-09-05T12:35:49",11,"/ давай на убеждение",190428,null],[190606,"2026-09-05T14:05:23",22,"/roll",190431,null],[190611,"2026-09-05T14:06:34",11,"Дриада сомневается и указывает на лягуху \n\n— От него веет благим двором, ты уверена что хочешь иметь дело с этим?",167805,null],[190749,"2026-09-05T14:55:48",22,"- Но он же такой миленький! Смотри какие щечки!",167805,null],[190760,"2026-09-05T15:00:03",11,"Скептический взгляд",167805,null],[190882,"2026-09-05T15:21:44",22,"- Ну ты же с ним еще не общалась! Меня вот вчера сильно поклевали птицы, а этот отважный лягушонок прогнал их прочь и помог мне подлатать ранки. Я сужу о существах лишь по их поступкам, а не по внешности и расе!\n\nВенус нахмурилась.\n\n- Этот мир так чудесен и интересен! Мы не знаем, сколько нам здесь отведено, так зачем же тратить время на дрязги и предрассудки?",167805,null],[191006,"2026-09-05T15:41:34",11,"— Мне нет дела до его расы, его покровитель из благого двора, ты же знаешь что они соперничают с нашей госпожой? — раздается голос дриады у тебя в голове",190882,null],[191172,"2026-09-05T16:03:42",22,"Венус тяжело вздохнула. Конечно она знала, но Кварсио оказался очень хорошим и ничего злого не сделал для Венус, которая как новорожденный ребенок искренне не понимала, почему она должна ненавидеть милейшее существо.",167805,null],[191235,"2026-09-05T16:13:39",11,"Дриада чувствуя твое смятение сдаётся\n\n«Раз уж ты доверяешь им.. только не разочаруй Госпожу прошу тебя»",167805,null],[191243,"2026-09-05T16:14:59",11,"// я позже опишу что она расскажет",167805,null],[192265,"2026-09-05T19:13:46",11,"«Он прав. В лесу пробудился хранитель — древний энт. Я давно здесь.. с тех пор как меня сослала госпожа со своего двора» \n\nПоследние слова были наполнены горечью\n\n«Эльфы в последнее время слишком сильно расширили город, ему это не нравится, поэтому он пытается их прогнать.»",167805,null],[192413,"2026-09-05T19:46:12",22,"- Хм.. наверное он охраняет что-то важное или просто привык, что это его территория. Я думаю, что нужно найти его и попробовать все объяснить, мы должны попробовать договориться.",167805,null],[192704,"2026-09-05T21:40:31",11,"— Возможно — она решила говорить вслух — Но стоит ли эльфам об этом знать\n\nЖестом руки дриада указала на лежащих на земле, спящих эльфов",167805,null],[192707,"2026-09-05T21:41:20",5,"— Ква-ква. Так кого найти?",167805,null],[192717,"2026-09-05T21:43:03",22,"- Конечно стоит! Мы им все расскажем и попробуем договориться с энтом. Можем для него важно какое-то определенное место и они смогут с эльфами и дальше жить в синергии.\n\nВенус чуть задумалась.\n\n- Кварсио, у нас в лесу пробудился энт и он недоволен эльфами. Мне кажется, что лучше эльфам все рассказать и попробовать договориться с энтом, а ты что думаешь?",167805,null],[192720,"2026-09-05T21:43:47",5,"— Энт пробуждает лес? Где его искать? И почему недоволен?",192717,null],[192725,"2026-09-05T21:45:16",22,"- Мне кажется, что эльфы зашли на его территорию и потревожили, их поселение растет и места им нужно больше..",167805,null],[192811,"2026-09-05T22:20:08",5,"— Эльфы добры к нам. Мы должны отправиться к энту и узнать, добрый ли он",167805,null],[192812,"2026-09-05T22:22:26",11,"— Делайте как считаете нужным — говорит дриада — Но если будете говорить с эльфами я пожалуй предпочту избежать их внимания. Я обитаю здесь давно и старалась не показываться им раньше. Не могли бы вы сказать им что сонные розы тоже дело рук энта?",167805,null],[192823,"2026-09-05T22:33:28",5,"— Квачем врать?",192812,null],[192824,"2026-09-05T22:36:23",11,"Дриада игнорируя представиля вражеской фракции просто растворяется в дереве, на последок показывая в какую сторону ушел скот\n\n— Вам лучше поторопиться. Я видела там стайку голодных хищников",167805,null],[192830,"2026-09-05T23:41:13",22,"- Она очень стеснительная, Кварсио, ее розы были так прекрасны, что если эльф узнают о том, от кого они, то они замучают дриаду своим вниманием. \n\nЯ думаю, что будет достаточно сказать им, что плохие розы их больше не потревожат, мы уладили эту проблему.",192823,null],[192831,"2026-09-05T23:41:56",22,"- Давайте направимся к эльфам, Сериче права, не стоит долго тут оставаться.\n\nВенус испуганно осмотрелась.",167805,null],[192834,"2026-09-05T23:43:59",11,"«Сперва верните скот, а затем разбудите этих эльфов» — раздается у тебя в голове — «Или наоборот»",167805,null],[192838,"2026-09-05T23:46:15",22,"- Ой! Нам же нужно вернуть скот как можно скорее! А Сериче сказала, что тут много хищников. Давайте сперва разъём их, пока не случилось непоправимое.\n\nВенус стала более внимательно осматривать местность, надеясь, что сможет найти следы животных и ей не потребуется выслеживать их по запаху.",167805,null],[192839,"2026-09-05T23:46:47",22,"/roll +5 Выживание, ищем сломанные ветки и примятую траву",167805,null],[192845,"2026-09-05T23:49:36",11,"С подсказками дриады и собственной внимательностью ты легко находишь самые свежие следы копыт. Видно что животные шли не спеша. Похоже когда пастухи уснули, стадо просто разбрелось по округе пастись\n\nТем временем майазавры прерываются от щипания лепестков обеспокоенные тем что хозяины без сознания\n\n— Фрр — доносится с их стороны. Это должно разбудить эльфов",167805,null],[192885,"2026-09-06T00:23:58",22,"Дождавшись товарищей, Венус вместе с ними постаралась собрать стадо и отвести пастухам.",167805,null],[192898,"2026-09-06T00:28:17",11,"// а что со стадом так сказать узнаем в следующей серии когда все соберутся",167805,null],[193095,"2026-09-06T10:47:05",5,"— Правда? Кварошо, давай скажем, что розы больше не будут мешать. Винить энта я не хочу",192830,null],[193098,"2026-09-06T10:47:45",5,"— Пойдём по следам!",167805,null],[195443,"2026-09-07T12:43:54",53,"//через пол часа после 3 пары свободен",167805,null],[195444,"2026-09-07T12:49:10",53,"это через 2 с половиной часа +-//",195443,null],[195735,"2026-09-07T15:38:32",53,"//и вот я дома",167805,null],[195765,"2026-09-07T15:51:55",22,"Венус задержалась, чтобы послушать, что скажет лягушонок, а после отправилась по находке дриады",167805,null],[195789,"2026-09-07T15:59:59",22,"- Как интересно. \n\nГоворит девушка и принюхивается.",167805,null],[195792,"2026-09-07T16:01:44",22,"/r +5",167805,null],[195795,"2026-09-07T16:01:55",22,"Венус очень громко чихнула",167805,null],[195797,"2026-09-07T16:02:08",53,"*наконец полность отошедший ото сна спрашиваю*\nудалось обнаружить что-то?",195789,null],[195798,"2026-09-07T16:02:09",5,"Грунг беззаботно прыгает по следам, всматриваясь в них\n\n— Будь здорова!",167805,null],[195799,"2026-09-07T16:02:13",22,"//ну понеслась душа в рай",167805,null],[195800,"2026-09-07T16:02:27",53,"будь здорова",195795,null],[195801,"2026-09-07T16:02:30",22,"- Спасибо!\nШмыг шмыг",195798,null],[195804,"2026-09-07T16:03:14",5,"— Цет, майязавры очень любят лепестки цветов. Квакни, если увидишь их. Мне нужен запас корма!",195797,null],[195811,"2026-09-07T16:04:02",53,"*киваю, а после слегка зеваю*\nа собственно куда мы идем?",195804,null],[195826,"2026-09-07T16:05:02",5,"— Следы крови... Что-то напало на бедных животных? Скорее сюда!",167805,null],[195828,"2026-09-07T16:05:15",22,"Венус бежит",167805,null],[195830,"2026-09-07T16:05:27",53,"*подбегаю к лягуху*",195826,null],[195834,"2026-09-07T16:06:18",22,"-Давайте осмотримся, может найдем ещё следы",167805,null],[195838,"2026-09-07T16:06:48",22,"Перехватив щит, Венус заглядывает",167805,null],[195842,"2026-09-07T16:07:20",5,"К'варсио не отставая запрыгивает туда (за кусты, не в корову)",167805,null],[195850,"2026-09-07T16:08:53",53,"*цет еще из-за спины девушки увидев корову несется к ней и проверяет есть ли у нее признаки жизни*",195842,null],[195851,"2026-09-07T16:08:58",22,"- Ого.. что это такое..\n\nВенус аккуратно отодвигается края раны скимитаром и пытается понять, почему из раны растут грибы. Это заражение или же сама корова наполовину гриб.",167805,null],[195852,"2026-09-07T16:09:00",5,"— Грибной зверь? Квакой ужас!\n\nГрунг осматривает раны",167805,null],[195856,"2026-09-07T16:09:40",22,"/r +5 уход за животными",167805,null],[195865,"2026-09-07T16:11:20",53,"полагаю это их молоко нам давали.",195852,null],[195884,"2026-09-07T16:14:09",22,"- Точно! А я думала, что они его смешивают с грибами, чтобы получить такой интересный вкус.",195865,null],[195886,"2026-09-07T16:14:37",22,"Венус поспешила за прытким товарищем",167805,null],[195920,"2026-09-07T16:20:20",5,"/ хищники рванули куда?",167805,null],[195941,"2026-09-07T16:23:15",53,"(5 хп исцелил ему + тхп в размере его костей хп)",195938,null],[195949,"2026-09-07T16:23:40",5,"/ а я без черты просто набор трачу)",167805,null],[195966,"2026-09-07T16:26:49",5,"/ 10 минут без концентрации",167805,null],[195977,"2026-09-07T16:29:08",5,"— Ква, спокойнее пожалуйста. Мы ищем других зверей. Хотим помочь!",167805,null],[195993,"2026-09-07T16:32:40",5,"— Кабанчик жалуется, что все бросили его, а он медленный",167805,null],[195997,"2026-09-07T16:33:25",5,"— Но остальные вон там, куда он побежал",167805,null],[196003,"2026-09-07T16:33:43",53,"мы тоже медленные..",195993,null],[196004,"2026-09-07T16:34:09",5,"К'варсио совершенно точно и в самой понятной для кабана форме задал вопросы ему",167805,null],[196039,"2026-09-07T16:37:44",22,"//сорян, Венус работу работала, сейчас все опишу",167805,null],[196063,"2026-09-07T16:41:15",22,"- Я думаю, что нам нужно не за хищниками гнаться, а искать дальше животных. Хищников тут много, не стоит тратить на них время.\n\nВенус посмотрела на кабанчика. \n\n- Какой ты миленький! Давай я помогу.\n\nМагией друидов Венус попробовала сплести рюкзак-переноску из лоз.",167805,null],[196077,"2026-09-07T16:43:06",5,"— Квенус, понесешь его? Ты самая быстрая из нас, мы выдохлись от жары...",196063,null],[196083,"2026-09-07T16:43:57",22,"Венус поправила лямки и рюкзак и подогнала под мелвежью форму. Теперь можно будет скинуть в одно движение рюкзак.",167805,null],[196088,"2026-09-07T16:44:56",5,"К'варсио показывает куда говорит кабанчик",195997,null],[196089,"2026-09-07T16:44:59",22,"Венус становится медведем, и зубами закидывает на себя рюкзак. \n\nОна большая, наверное на ней поместится ещё кто-то, но скорость станет пониже, но все лучше, чем топать уставшим, верно?",167805,null],[196092,"2026-09-07T16:45:35",22,"Медведица приглашающе наклонилась",167805,null],[196094,"2026-09-07T16:45:51",5,"К'варсио запрыгнул прямо на спину",167805,null],[196095,"2026-09-07T16:45:57",22,"Формы: \n\nМедведь\nХП 34\nКБ 11\nМультиатака. Две атаки: одну укусом, и одну когтями.\nУкус. +6, . Попадание: Кол урон 8 (1к8 + 4).\nКогти. +6, Попадание: Руб урон 11 (2к6 + 4).\n\nНавыки Восприятие +3\nЧувства пассивное Восприятие 13\nТонкий нюх. Медведь совершает с преимуществом проверки Мудрости (Восприятие), полагающиеся на обоняние.\n\nЛютоволк\nХП 37\nКБ 14\nУкус. +5, Попадание: Кол урон 10 (2к6 + 3). Цель существо - спас Силы Сл 13, иначе будет сбита с ног.\n\nНавыки: Восприятие +3, Скрытность +4\nЧувства пассивное Восприятие 13\nОстрый слух и тонкий нюх. Волк совершает с преимуществом проверки Мудрости (Восприятие), полагающиеся на слух и обоняние.\nТактика стаи. Волк совершает с преимуществом броски атаки по существу, если в пределах 5 футов от этого существа находится как минимум один дееспособный союзник волка.",167805,null],[196096,"2026-09-07T16:45:58",5,"— Спасибо, Квенус!",167805,null],[196097,"2026-09-07T16:46:07",22,"Напоминаю внешность формы, есть за что цепляться/",167805,null],[196100,"2026-09-07T16:47:33",22,"Венус двинулась в сторону за хищниками, куда указали товарищи",167805,null],[196106,"2026-09-07T16:49:21",53,"*аккурратно взбираюс за лягухом*",196092,null],[196119,"2026-09-07T16:51:03",22,"Нормально",167805,null],[196120,"2026-09-07T16:51:14",22,"/рывок опасно, скрытность долго",167805,null],[196121,"2026-09-07T16:51:38",53,"благодарю, сами бы мы млжнт и не дорьпорстит6",196095,null],[196138,"2026-09-07T16:56:35",5,"К'варсио удобно устроился на спине, держится за ветку и смотрит вокруг",167805,null],[196192,"2026-09-07T17:05:45",5,"/r +2",167805,null],[196225,"2026-09-07T17:09:47",5,"/ интересно, что мы шли как раз чтобы разговор с животными кончился)",167805,null],[196232,"2026-09-07T17:11:01",22,"/r +2",167805,null],[196304,"2026-09-07T17:22:12",22,"Венус дождалась, пока товарищи с нее слезут и сняла кабанчика. Рваться в бой вместе с ними было опасно для всех.",167805,null],[196307,"2026-09-07T17:22:37",22,"После этого она побежала прямо на ближайшего раптора по центру",167805,null],[196308,"2026-09-07T17:22:46",22,"/r +6 укус\n/r d8+4\n/r +6 царап\n/r 2d6+4",167805,null],[196311,"2026-09-07T17:23:12",22,"/ход",167805,null],[196312,"2026-09-07T17:23:16",5,"— Ква, вот и стадо! И хищники!\n\nГрунг погладил кабанчика на удачу, прежде чем он убежал",167805,null],[196360,"2026-09-07T17:29:28",22,"//кубы меня ненавидят",167805,null],[196365,"2026-09-07T17:30:15",22,"/го, впитываем!",167805,null],[196375,"2026-09-07T17:31:34",22,"//стоим! 8/34",167805,null],[196414,"2026-09-07T17:36:35",5,"// окей",167805,null],[196415,"2026-09-07T17:36:40",5,"// мне пока не ходить?",167805,null],[196468,"2026-09-07T17:45:03",5,"К'варсио квакает:\n\n— Квенус, не дай себя окружить!\n\nТиара на голове сверкает, наполняя лапки силой. \n\n// бонусным удар зефира",167805,null],[196472,"2026-09-07T17:45:17",5,"// со скоростью 12 я не дойду до венус?",167805,null],[196475,"2026-09-07T17:45:22",5,"// хочу за спиной встать",167805,null],[196479,"2026-09-07T17:46:16",5,"Лягушонок прыгает со всех ног в направлении Венус...",167805,null],[196487,"2026-09-07T17:47:40",5,"Затем тиара вновь сверкает и посреди стаи рапторов раздаётся рёв майязавра, что лягушонок слышал ранее.\n\n/ чудотворство",167805,null],[196489,"2026-09-07T17:48:08",5,"// ход",167805,null],[196511,"2026-09-07T17:50:45",5,"/r",167805,null],[196534,"2026-09-07T17:53:36",5,"/ далеко Венус?",167805,null],[196570,"2026-09-07T18:00:17",5,"/ кидай спасы тела от яда сл 12 сколько считаешь нужным",167805,null],[196629,"2026-09-07T18:10:48",5,"/ какой урон в итоге?",167805,null],[196636,"2026-09-07T18:12:22",5,"/ отравленные с помехой делают всё",167805,null],[196643,"2026-09-07T18:13:21",5,"/r 4d20 ради интереса спасы концентрации",167805,null],[196645,"2026-09-07T18:13:35",5,"/ ого, там былобольше 4 попаданий?",167805,null],[196651,"2026-09-07T18:14:29",53,"//что в белом кругу?",167805,null],[196653,"2026-09-07T18:14:38",53,"большом//",196651,null],[196654,"2026-09-07T18:14:45",5,"/roll@roll_bot",167805,null],[196656,"2026-09-07T18:14:50",5,"/r +3",167805,null],[196657,"2026-09-07T18:15:00",5,"/roll +3",167805,null],[196661,"2026-09-07T18:15:20",5,"/ вот на этом провалил да",196658,null],[196663,"2026-09-07T18:15:36",5,"/r d4 благословение",167805,null],[196674,"2026-09-07T18:18:43",5,"— Птица была размером как я, эти больше",167805,null],[196678,"2026-09-07T18:19:18",53,"я про тех водных, что еще прожарили нас когда мы были в лесу.",196674,null],[196679,"2026-09-07T18:19:27",53,"//где сейчас ближайший раптор?",167805,null],[196684,"2026-09-07T18:20:42",5,"К'варсио вспоминает, как кричали те водные",196678,null],[196693,"2026-09-07T18:21:33",5,"/r -1",167805,null],[196730,"2026-09-07T18:24:33",53,"+1//",167805,null],[196753,"2026-09-07T18:27:00",53,"//вот теперь ход, ежели кварсио согласен то +к4 эллектричеству атакам его мечем",167805,null],[196770,"2026-09-07T18:28:47",5,"Лягушонок тянет меч согласно\n\n— Сила квеликого в нем?",167805,null],[196792,"2026-09-07T18:31:22",53,"*киваю*",196770,null],[196867,"2026-09-07T18:42:14",22,"Венус задумалась и улыбнулась, конечно, она могла бы попробовать стать одним из больших ящеров, но ее умений явно не хватает, поэтому девушка принимает облик гигантской гиены и начинает драть мелочь",167805,null],[196874,"2026-09-07T18:43:00",22,"/r +5 Гиена нападает на ближайшего мелкого \n/r 2d6+3",167805,null],[196990,"2026-09-07T18:57:49",5,"— Их квак много!",167805,null],[196997,"2026-09-07T19:01:35",5,"/roll@roll_bot",167805,null],[197000,"2026-09-07T19:02:17",5,"/ тогда действие на чудотворство не потратил?",167805,null],[197007,"2026-09-07T19:04:24",5,"Чудотворством лягушонок создаёт рык мощных морских завров посреди стаи рапторов",167805,null],[197015,"2026-09-07T19:05:45",22,"Если съела, то буйством атакую другого.\n\n\n// сорри я орала на администраторшу, которая \"забыла\" предупредить меня что она отменила мою запись на маниюкр. Я злая как черт",167805,null],[197017,"2026-09-07T19:06:00",5,"/ то есть не получилось ни голосом ни чудотворством? значит без действия",167805,null],[197038,"2026-09-07T19:09:08",5,"К'варсио растворяется в облаке тумана, а само облако расплывается по земле, пробуждая растительность под ногами рапторов.\n\n/ можно бонусным туманный шаг, действием опутывание?",167805,null],[197075,"2026-09-07T19:12:54",5,"/ спас силы сл 11",167805,null],[197128,"2026-09-07T19:18:00",5,"— Животные кусаются больно, что мне делать!",167805,null],[197243,"2026-09-07T19:31:24",5,"/ Сериче ударь провоцированной 😭",167805,null],[197251,"2026-09-07T19:33:01",53,"//через 6 минут впн отрубит, хз смогу ли перезапустить ибо продлить не получается",167805,null],[197281,"2026-09-07T19:38:23",5,"Грунг смотрит на атаке по Венус и от страха тыкает одного раптора мечом, перед этим проведя лезвием по своей коже\n\n/ реакция стража",167805,null],[197287,"2026-09-07T19:40:01",5,"/r +6\n/r d6+2d4+4",167805,null],[197294,"2026-09-07T19:40:54",5,"/ кстати прокинула спасы от яда кусающим?",167805,null],[197300,"2026-09-07T19:43:26",5,"/r 2d4 ядом",167805,null],[197302,"2026-09-07T19:44:07",5,"/ урон ядом по тому кого тыкнул. Я запутался немного сорри",197288,null],[197316,"2026-09-07T19:47:26",5,"/ все рапторы выпутались?",167805,null],[197323,"2026-09-07T19:48:13",5,"Корни отпускают бедных животных, как только грунг замечает, что от них нет смысла",167805,null],[197324,"2026-09-07T19:48:19",5,"/ скинул концентрацию",167805,null],[197353,"2026-09-07T19:55:18",22,"Гиена грозно рычит, она хотела сожрать вначале мелочь, но увидела, как обижают Кварси и готова бросится на сильного альфа-врага, предварительно запустив волну исцеления.\n\n16/50",167805,null],[197395,"2026-09-07T20:05:30",53,"//а дриада все там же где стояла?",167805,null],[197401,"2026-09-07T20:06:59",53,"*поудобнее перехватив алебарлу наношу размашистый уда по тварюке в стороне лриады и в этот моменты пытаюсь обтечь жтого врага переместившись к дриаде*",167805,null],[197403,"2026-09-07T20:07:43",53,"//5 на попадание",197402,null],[197406,"2026-09-07T20:10:20",53,"*алебарда начинает лететь в сторону существа, но двоящаяся фигура резким движением разделяется на три, улебарда влетает в среднюю, а тем временем сам раптор с легкостью уходит от довольно тяжелой алебарды просто отклонив голову. алебарда же вылетает из слабой хватки цета и улетает в даль в сторону кварсио и венус*",167805,null],[197453,"2026-09-07T20:23:38",53,"//спас тела или мудрости (не помню какой..)",167805,null],[197455,"2026-09-07T20:24:01",53,"//при провале отлетает на 10 фт и получает 2к8, при успехе не отлетает и получает только половину",167805,null],[197474,"2026-09-07T20:29:37",53,"гхыг!\n*получив удар по спине прорывающий броню как бумагу (даже не знаю почему, дааа.. ведь не как бумага же оно на прочьность *невинный свист*) падю на земь у ног дриады, а тело испускает энергетический импульс бьющий в тело раптора, к сожалению тот успевает сдвинутся и получить лишь малую долю возможного урона*\nо великий.....\n*тем временем в мыслях идет молитва*\n\"о великий... великий ктулху, защити лекаря, верно служащего учению твоему и дозволь поразить врага силою твоей.. и да защитит длань твоя братьев моих, да товарещей....\"\n\n*как и голос мысли медленнно начинают затихать а сознание гаснуть*",167805,null],[197476,"2026-09-07T20:30:10",22,"/r 2d8",167805,null],[197478,"2026-09-07T20:31:08",22,"Венус попробует проглотить альфу, либо сжать его зубами так, чтобы он не мог двигаться\n\n31/55",167805,null],[197480,"2026-09-07T20:31:18",22,"/r +5\n/r 2d6+3",167805,null],[197488,"2026-09-07T20:31:46",22,"/ход, невовремя кубы подвели",167805,null],[197490,"2026-09-07T20:32:07",22,"/одна, вторая только если кого-то добью",167805,null],[197498,"2026-09-07T20:34:14",53,"//могу на своем ходу вместе со спасом от смерти на религию прокинуть?",197474,null],[197501,"2026-09-07T20:34:38",5,"— Цет! Держись, я тебя вынесу! Кваа!",197474,null],[197513,"2026-09-07T20:37:37",5,"Лягушонок пытается защитить Венус и тыкает одного из рапторов мечом",167805,null],[197515,"2026-09-07T20:37:49",5,"/r +6",167805,null],[197532,"2026-09-07T20:39:53",53,"//могу аль нет?",197498,null],[197533,"2026-09-07T20:40:09",5,"/r d6+2d4+4 урон",167805,null],[197536,"2026-09-07T20:40:20",53,"//и насчет обоих бросков вопрос: с помехой аль без?",197532,null],[197545,"2026-09-07T20:42:27",5,"— Квааа!\n\nОтчаянно квакая, грунг наносит первую атаку по альфе",167805,null],[197548,"2026-09-07T20:42:39",22,"//сорри, только до дома дошла, теперь тут полноценно",167805,null],[197553,"2026-09-07T20:43:07",5,"А затем тыкает вторым мечом",167805,null],[197558,"2026-09-07T20:43:22",5,"/ оно опутано? окей",167805,null],[197562,"2026-09-07T20:43:34",5,"/r d20+6+d4",167805,null],[197568,"2026-09-07T20:44:05",5,"/ и спас от яда",167805,null],[197574,"2026-09-07T20:44:19",5,"/r 2d4 урон",167805,null],[197577,"2026-09-07T20:44:27",5,"/ живое?",167805,null],[197591,"2026-09-07T20:46:12",5,"Клинок глубоко ранил раптора, но тот стоял на ногах и был готов ответить укусом. Однако через секунду что-то распространилось по венам зверя, изо рта пошла слюна и он повис в пасти гиены бессильно",167805,null],[197598,"2026-09-07T20:47:20",22,"/r +5\n/r 2d6+3",167805,null],[197600,"2026-09-07T20:47:23",5,"/ могу бонусным снова крикнуть как ящер?",167805,null],[197612,"2026-09-07T20:50:08",5,"/r выступаю",167805,null],[197623,"2026-09-07T20:51:26",22,"\"ммм... полынь.. моя любимая..\"",167805,null],[197625,"2026-09-07T20:51:57",5,"Пристыженный лягушонок прячется за гиену /если можно без прокаций",167805,null],[197651,"2026-09-07T20:54:32",5,"К'варсио с бинтами тут же попрыгал к Цету",167805,null],[197653,"2026-09-07T20:54:52",5,"Сначала обвязывает кровавые места, затем всё тело как мумию",167805,null],[197655,"2026-09-07T20:55:27",5,"— Квеликий, не оставь своего отважного воина!",167805,null],[197672,"2026-09-07T20:58:22",22,"Венус оборачивается, проверяя товарищей. Видя, что Кварсио уже оказывает первую помощь, девушка погналась за стадом, сгоняя его в кучу на полянке, словно пастушья собака, а не гиена.",167805,null],[197888,"2026-09-07T21:37:30",5,"— Ква!!! Квачем ты их пугаешь!\n\nК'варсио прыгает за стадом и говорит на их языке.\n\n/ Разговор за ячейку\n\n— Стойте! Стойте! Мы пришли вернуть вас домой! Там уже готова еда и... Лепестки роз!\n\nОн достал один пучок лепестков из рюкзак и помахал животным",167805,null],[197898,"2026-09-07T21:41:01",22,"Гиена села на попку и чешет задней лапой ухо.",167805,null],[197899,"2026-09-07T21:41:23",22,"//если у вас вдруг были сомнения о том, которая я из гиен, так вот - самая придурковатая явно",167805,null],[197900,"2026-09-07T21:41:47",5,"/r +2 помеха от истощения",167805,null],[197906,"2026-09-07T21:43:50",5,"— Дома есть всё, что вы едите. Я кважу эльфам, что вы хотите?",167805,null],[197962,"2026-09-07T21:52:24",5,"— Квенус! Перестань их пугать пожалуйста!",167805,null],[197984,"2026-09-07T21:54:47",22,"Венус придурковато склонила голову на бок и мило-мило замурчала.",167805,null],[197995,"2026-09-07T21:55:43",5,"— Ква-ква, стань обычной, Квенус!",167805,null],[198012,"2026-09-07T21:57:20",5,"К'варсио берёт его сильными лягушачьими лапками",167805,null],[198019,"2026-09-07T21:58:26",5,"Ведём к эльфам",167805,null],[198041,"2026-09-07T22:03:44",22,"Венус сбрасывает облик гиены и лечит Цета",167805,null],[198044,"2026-09-07T22:04:06",22,"/r d8+3",167805,null],[198097,"2026-09-07T22:11:37",53,"//фуловый и 2 тхп",198091,null],[198133,"2026-09-07T22:17:39",53,"*встряхнув головой оглядываю окружающийх*",198097,null],[198155,"2026-09-07T22:22:05",22,"Кварсио, давай я и тебя немного подлатаю, пока ведем стадо",167805,null],[198189,"2026-09-07T22:31:40",5,"— Квасибо!\n\nЛягушонок всё ещё выглядит не очень",167805,null],[198192,"2026-09-07T22:32:11",53,"*пошатываясь так же подхожу к кварсио и оглядываю его (раны есть?)*",198189,null],[198204,"2026-09-07T22:34:42",5,"Ран немало",198192,null],[198210,"2026-09-07T22:36:16",5,"— Ква, погоди! Я обещал животным, что сегодня их пустят на поля. Иначе бы они не вернулись сюда",167805,null],[198216,"2026-09-07T22:37:16",22,"*Лучи добра, любви и благодарности*",167805,null],[198251,"2026-09-07T22:44:06",53,"*заматываю раны и обеззараживаю их*",198204,null],[198256,"2026-09-07T22:44:30",53,"//6 хп отхиль еще и 2 тхп получи (кварсио)",198253,null],[198273,"2026-09-07T22:47:59",5,"— Странно-странно",167805,null],[198274,"2026-09-07T22:48:08",5,"Грунг поскакал к остальным",167805,null],[198341,"2026-09-07T22:59:45",22,"Венус хотела было помедитировать немного, но ее отвлек шум.\n\nДевушка подошла и увидела много раненых.\n\n- Я могу исцелять, кому нужна помощь прежде всего?",167805,null],[198349,"2026-09-07T23:01:23",5,"Товарищ квакает где-то под окном",167805,null],[198354,"2026-09-07T23:02:15",22,"- Он отдыхает. Я вижу у вас тут очень много работы, давайте помогу.\n\nВенус присоединяется к помощи раненым.",167805,null],[198355,"2026-09-07T23:02:28",5,"/ а как меня видят? где я?",167805,null],[198384,"2026-09-07T23:06:09",5,"— Ква! Извините, я потерялся!",167805,null],[198388,"2026-09-07T23:06:50",22,"/r +5 медицина",167805,null],[198390,"2026-09-07T23:06:53",5,"— Вы не видели, куда ушёл тритон и девушка похожая на куст?",167805,null],[198394,"2026-09-07T23:07:30",22,"Венус благодарно кивнула",167805,null],[198415,"2026-09-07T23:10:34",53,"*спешно бинтую раненых*\n\nрыцарь, мне необходимы те наборы, что я передал тебе и твоя помощь.",167805,null],[198420,"2026-09-07T23:10:51",53,"(мы же слышим его голос?)",198415,null],[198442,"2026-09-07T23:13:05",53,"рыцарь\n*подзываю головой к себе*",198415,null],[198443,"2026-09-07T23:13:21",5,"— Я помогу!",167805,null],[198446,"2026-09-07T23:13:45",5,"Лягушонок под руководством Цета помогает обрабатывать раны",167805,null],[198458,"2026-09-07T23:15:04",5,"Поднимает лапки над головой",167805,null],[198502,"2026-09-07T23:19:47",5,"— Сначала поможем, а потом обсудим, что мы узнали про пробуждение",167805,null],[198507,"2026-09-07T23:20:14",53,"ах да, когда меня ранили, я слышал глас...",167805,null],[198513,"2026-09-07T23:20:31",53,"*продолжаю заливать микстуры и обеззораживать раны*",167805,null],[198520,"2026-09-07T23:20:59",53,"не можете ль вы знать чей это был глас?",198507,null],[198557,"2026-09-07T23:27:56",5,"Лягушка поскакала за старушкой",167805,null],[198565,"2026-09-07T23:28:36",22,"Венус оборачивается на звук плача",167805,null],[198583,"2026-09-07T23:31:02",22,"Подхожу к плачущей девушке",167805,null],[198586,"2026-09-07T23:32:13",5,"— Он тоже был у дамбы?",167805,null],[198598,"2026-09-07T23:37:04",22,"- Его тело нашли?\n\nТихо спросила Венус",167805,null],[198604,"2026-09-07T23:41:49",22,"Венус грустно промолчала.",167805,null],[198631,"2026-09-07T23:57:33",5,"/ извините, пойду спать. Ничего толкового уже не выдам",167805,null],[198634,"2026-09-07T23:58:13",53,"//сладких снов",198631,null],[198639,"2026-09-08T00:00:05",53,"//и тута предлогаю дождатся элса",167805,null],[198903,"2026-09-08T11:16:29",11,"// и тут почистилось, авв :(\n\nОпыт 370 Элу и Серёге \n670 Полине\n\nПост перепишу позже😓",167805,null],[200406,"2026-09-08T21:17:53",11,"Войдя в таверну вы сразу же почувствовали ароматный запах знакомых и не знакомых вам ингредиентов.\n\nУслышав шум открывающейся двери из кухни вышла эльфийка в фартуке с белыми волосами собранными в косу. В ее, на вид, слабых руках, был поднос с тремя порциями ароматнейшего рагу, запах которого доносился до вас.\n\nПоставив рагу на стол она поинтересовалась где Госпожа Анис, узнав же что вы пообещали забрать еду для Олани сами она кивнула и вернулась на кухню\n\nОтужинав сытного рагу с рисом, мясом пекари, и чудных эльфийских грибов К'варсио тут же сморило в сон. Эльф, похожий на прошлую эльфийку как две капли воды, унёс вашего спутника-лягушенка отдыхать. \n\nНа Венус и Цете же осталась задача. Но добравшись до дома девушки вы обнаружили ее спящей на кровати отца с засохшими ручейками соли на щеках",167805,null],[200514,"2026-09-08T22:28:55",22,"Венус накрывает девушку пледом.\n\nЕду она оставит рядом, накрыв, чтобы та не заветрилась. Уже уходя, Венус обернулась и с грустной улыбкой вырастила несколько лилий из ножек кровати.",167805,null],[207811,"2026-09-13T01:18:48",11,"// когда будете готовы продолжить? Собраться что бы всем вместе",167805,null],[207812,"2026-09-13T01:20:34",5,"/ когда остальные будут",167805,null],[207872,"2026-09-13T02:08:14",22,"/завтра свободна с 11 утра",167805,null]]);
